INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kizzz/eleon-client/angular-capacitor-patterns', 'community', 'kizzz', 'eleon-client', 'kizzz/eleon-client', 'angular-capacitor-patterns', 0, 0, 42, '2026-03-08T01:57:15.331Z', '2026-03-08T02:03:13.328Z', '4375b2cf6f2a71b582f1b9d888fa1354651a07f7f6825f168bb880e1dd48fee7', '{"id":"kizzz/eleon-client/angular-capacitor-patterns","name":"angular-capacitor-patterns","description":{"en":"angular-capacitor-patterns provides specialized architectural patterns for hybrid mobile apps using Angular Standalone Components, Capacitor 6, and offline-first strategies. It benefits developers building optimized mobile applications.","zh":"Angular + Capacitor移动应用开发模式，用于构建高性能的混合移动应用","ja":"Angular + Capacitorモバイルアプリ開発パターンは、ハイブリッドモバイルアプリを構築するために使用されます","ko":"Angular + Capacitor 모바일 애플리케이션 개발 패턴은 고성능 하이브리드 모바일 애플리케이션을 구축하는 데 사용됩니다","es":"Patrones arquitectónicos especializados para aplicaciones móviles híbridas con Angular y Capacitor","fr":"Modèles architecturaux spécialisés pour les applications mobiles hybrides avec Angular et Capacitor","de":"Spezialisierte Architekturmuster für hybride Mobile-Anwendungen mit Angular und Capacitor","pt":"O angular-capacitor-patterns é um conjunto de padrões arquitetônicos para aplicativos móveis híbridos usando Angular e Capacitor.","ru":"Angular + Capacitor - это набор архитектурных шаблонов для гибридных мобильных приложений, использующих Angular и Capacitor с ИИ Агентами","ar":"angular-capacitor-patterns هو مجموعة من الأنماط المعمارية لتطبيقات الجوال الهجينة باستخدام Angular و Capacitor مع أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"angular-capacitor-patterns: Mobile App Development Best P...","zh":"Angular + Capacitor移动应用开发最佳实践","ja":"Angular + Capacitorモバイルアプリ開発ガイド","ko":"Angular + Capacitor 모바일 애플리케이션 개발 패턴","es":"Guía de configuración de patrones de Angular + Capacitor ...","fr":"Guide de mise en place des modèles Angular + Capacitor po...","de":"Einrichtungsleitfaden für Angular + Capacitor-Muster in m...","pt":"Guia de Configuração do Angular + Capacitor: Melhores Prá...","ru":"Настройка Angular + Capacitor: Лучшие практики для гибрид...","ar":"دليل إعداد Angular + Capacitor: أفضل الممارسات لبرامج الج..."},"description":{"en":"Unlock efficient mobile app development with angular-capacitor-patterns. Learn how to implement offline-first sync, Capacitor plugins, and GSAP animations. G...","zh":"使用Angular Standalone Components、Capacitor 6和离线优先策略，构建高性能的混合移动应用","ja":"Angular Standalone Components、Capacitor 6、オフラインファースト戦略を使用して、高パフォーマンスのハイブリッドモバイルアプリを構築する","ko":"Angular Standalone Components, Capacitor 6 및 오프라인 우선 전략을 사용하여 고성능 하이브리드 모바일 애플리케이션을 구축합니다","es":"Aprende a crear aplicaciones móviles híbridas con Angular Standalone Components, Capacitor 6 y estrategias offline-first","fr":"Découvrez comment créer des applications mobiles hybrides avec des composants Angular Standalone, Capacitor 6 et des stratégies offline-first","de":"Erfahren Sie, wie Sie hybride Mobile-Anwendungen mit Angular-Standalone-Komponenten, Capacitor 6 und Offline-First-Strategien erstellen","pt":"Aprenda a criar aplicativos móveis híbridos otimizados com Angular Standalone Components, Capacitor 6 e estratégias offline-first","ru":"Узнайте, как создавать оптимизированные гибридные мобильные приложения с Angular Standalone Components, Capacitor 6 и стратегиями offline-first с помощью ИИ ...","ar":"تعلم كيفية إنشاء تطبيقات الجوال الهجينة المُحسّنة باستخدام Angular Standalone Components و Capacitor 6 و استراتيجيات العمل دون اتصال بالإنترنت مع أدوات الذكا..."},"definition":{"en":"angular-capacitor-patterns is a set of specialized architectural patterns for building hybrid mobile applications using Angular, Capacitor, and offline-first strategies.","zh":"Angular + Capacitor移动应用开发模式是一种用于构建高性能的混合移动应用的架构模式","ja":"Angular + Capacitorモバイルアプリ開発パターンは、ハイブリッドモバイルアプリを構築するためのアーキテクチャパターンです","ko":"Angular + Capacitor 모바일 애플리케이션 개발 패턴은 고성능 하이브리드 모바일 애플리케이션을 구축하는 데 사용되는 아키텍처 패턴입니다","es":"Patrones de diseño para aplicaciones móviles híbridas que combinan Angular y Capacitor","fr":"Modèles de conception pour les applications mobiles hybrides qui combinent Angular et Capacitor","de":"Entwurfsmuster für hybride Mobile-Anwendungen, die Angular und Capacitor kombinieren","pt":"Angular + Capacitor é um conjunto de padrões para desenvolver aplicativos móveis híbridos com Angular e Capacitor","ru":"Angular + Capacitor - это набор шаблонов для разработки гибридных мобильных приложений с использованием Angular и Capacitor","ar":"Angular + Capacitor هو مجموعة من القوالب لإنشاء تطبيقات الجوال الهجينة باستخدام Angular و Capacitor"},"features":{"en":["Implements offline-first synchronization with Supabase","Integrates Capacitor plugins such as Notifications, Storage, and Camera","Configures GSAP animations for gamification","Structures features with NgRx Signals","Optimizes mobile components for touch using Angular Standalone Components"],"zh":["使用Angular Standalone Components构建移动组件","实现离线优先的同步功能","集成Capacitor插件（Notifications、Storage、Camera）","配置GSAP动画以实现游戏化","使用NgRx Signals结构化功能"],"ja":["Angular Standalone Componentsを使用してモバイルコンポーネントを構築する","オフラインファーストの同期機能を実装する","Capacitorプラグイン（Notifications、Storage、Camera）を統合する","GSAPアニメーションを設定してゲーム化を実現する","NgRx Signalsを使用して機能を構造化する"],"ko":["Angular Standalone Components를 사용하여 모바일 컴포넌트를 구축합니다","오프라인 우선의 동기화 기능을 구현합니다","Capacitor 플러그인（Notifications、Storage、Camera）을 통합합니다","GSAP 애니메이션을 설정하여 게임화를 구현합니다","NgRx Signals를 사용하여 기능을 구조화합니다"],"es":["Creación de componentes móviles optimizados para touch","Implementación de sincronización offline-first con Supabase","Integración de plugins de Capacitor como Notificaciones, Storage y Camera","Configuración de animaciones GSAP para gamificación","Estructuración de características con NgRx Signals"],"fr":["Création de composants mobiles optimisés pour le touch","Mise en œuvre de la synchronisation offline-first avec Supabase","Intégration de plugins Capacitor tels que Notifications, Stockage et Appareil photo","Configuration d''animations GSAP pour la gamification","Structuration de fonctionnalités avec NgRx Signals"],"de":["Erstellung von mobilen Komponenten, die für Touch optimiert sind","Implementierung der Offline-First-Synchronisierung mit Supabase","Integration von Capacitor-Plugins wie Benachrichtigungen, Speicher und Kamera","Konfiguration von GSAP-Animationen für Gamification","Strukturierung von Funktionen mit NgRx Signals"],"pt":["Otimização de componentes móveis para touch","Implementação de sincronização offline-first com Supabase","Integração de plugins de Capacitor (Notifications, Storage, Camera)","Configuração de animações GSAP para gamificação","Estruturação de features com NgRx Signals"],"ru":["Оптимизация мобильных компонентов для сенсорных экранов","Реализация синхронизации offline-first с Supabase","Интеграция плагинов Capacitor (Notifications, Storage, Camera)","Настройка анимаций GSAP для геймификации","Структуризация функций с помощью NgRx Signals"],"ar":["تحسين المكونات الجوالة للاستخدام باللمس","تنفيذ التزامن دون اتصال بالإنترنت مع Supabase","دمج ملحقات Capacitor (Notifications, Storage, Camera)","تكوين الرسوم المتحركة GSAP للتحفيز","هيكلة الميزات باستخدام NgRx Signals"]},"keywords":{"en":["how to use angular-capacitor-patterns","angular-capacitor-patterns tutorial","angular-capacitor-patterns vs ionic","angular-capacitor-patterns install","angular-capacitor-patterns setup guide","what is angular-capacitor-patterns","angular-capacitor-patterns alternative","angular-capacitor-patterns mobile app development"],"zh":["Angular移动应用开发","Capacitor移动应用开发","离线优先开发","GSAP动画","NgRx Signals","AIエージェント","移动应用开发最佳实践"],"ja":["Angularモバイルアプリ開発","Capacitorモバイルアプリ開発","オフラインファースト開発","GSAPアニメーション","NgRx Signals","AIエージェント","モバイルアプリ開発ガイド"],"ko":["Angular 모바일 애플리케이션 개발","Capacitor 모바일 애플리케이션 개발","오프라인 우선 개발","GSAP 애니메이션","NgRx Signals","AI 에이전트","모바일 애플리케이션 개발 패턴"],"es":["patrones de angular","capacitor para móviles","aplicaciones móviles híbridas","desarrollo de aplicaciones móviles","angular standalone components","capacitor 6","estrategias offline-first","supabase para móviles"],"fr":["modèles angular","capacitor pour mobiles","applications mobiles hybrides","développement d''applications mobiles","composants angular standalone","capacitor 6","stratégies offline-first","supabase pour mobiles"],"de":["angular-muster","capacitor für mobile anwendungen","hybride mobile-anwendungen","entwicklung von mobilen anwendungen","angular-standalone-komponenten","capacitor 6","offline-first-strategien","supabase für mobile anwendungen"],"pt":["angular capacitor","aplicativos móveis híbridos","angular standalone components","capacitor 6","estratégias offline-first","supabase","gsap","ngrx signals"],"ru":["angular capacitor","гибридные мобильные приложения","angular standalone components","capacitor 6","стратегии offline-first","supabase","gsap","ngrx signals","ИИ Агенты"],"ar":["angular capacitor","تطبيقات الجوال الهجينة","angular standalone components","capacitor 6","استراتيجيات العمل دون اتصال بالإنترنت","supabase","gsap","ngrx signals","أدوات الذكاء الاصطناعي"]}},"owner":"kizzz","repo":"eleon-client","repoPath":"kizzz/eleon-client","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.331Z","topics":[],"category":"community","skillMd":{"name":"angular-capacitor-patterns","description":"Arquitectura y patrones para apps móviles con Angular 18+, Capacitor 6, PrimeNG y GSAP. Úsalo cuando construyas componentes móviles, implementes sincronización offline, o integres plugins de Capacitor.","bodyPreview":"# Angular + Capacitor Mobile Patterns\n\nPatrones arquitectónicos especializados para aplicaciones móviles híbridas usando Angular Standalone Components, Capacitor 6, y estrategias offline-first.\n\n## Cuándo Usar Esta Skill\n\n- Crear componentes móviles optimizados para touch\n- Implementar sincronización offline-first con Supabase\n- Integrar plugins de Capacitor (Notifications, Storage, Camera)\n- Configurar animaciones GSAP para gamificación\n- Estructurar features con NgRx Signals\n\n## Principios Fun","body":"# Angular + Capacitor Mobile Patterns\n\nPatrones arquitectónicos especializados para aplicaciones móviles híbridas usando Angular Standalone Components, Capacitor 6, y estrategias offline-first.\n\n## Cuándo Usar Esta Skill\n\n- Crear componentes móviles optimizados para touch\n- Implementar sincronización offline-first con Supabase\n- Integrar plugins de Capacitor (Notifications, Storage, Camera)\n- Configurar animaciones GSAP para gamificación\n- Estructurar features con NgRx Signals\n\n## Principios Fundamentales\n\n### 1. Mobile-First Architecture\n\nTodos los componentes deben:\n- Usar `ChangeDetectionStrategy.OnPush` obligatorio\n- Implementar gestos touch-friendly (min 44x44px)\n- Considerar keyboard virtual (bottom padding dinámico)\n- Optimizar para 3G/4G (lazy loading agresivo)\n\n```typescript\n@Component({\n  selector: ''app-block-card'',\n  standalone: true,\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  host: {\n    ''[style.min-height.px]'': ''88'', // 2x touch target\n    ''[class.ios]'': ''platform.is(\"ios\")'',\n    ''[class.android]'': ''platform.is(\"android\")''\n  }\n})\nexport class BlockCardComponent {}\n```\n\n### 2. Offline-First Data Flow\n\n```\n┌─────────────────────────────────────────────┐\n│ User Action (Complete Block)               │\n└───────────────┬─────────────────────────────┘\n                │\n                ▼\n┌───────────────────────────────────────────┐\n│ 1. Write to Local SQLite FIRST            │\n│    (Instant UI update via signals)        │\n└───────────────┬───────────────────────────┘\n                │\n                ▼\n┌───────────────────────────────────────────┐\n│ 2. Queue Sync Operation                   │\n│    (Background service)                   │\n└───────────────┬───────────────────────────┘\n                │\n                ▼\n         ┌──────┴───────┐\n         │ Online?      │\n         └──┬────────┬──┘\n           YES      NO\n            │        │\n            │        └─> Store in sync_queue\n            │            (retry on reconnect)\n            ▼\n┌───────────────────────────────────────────┐\n│ 3. Push to Supabase                       │\n│    (Last-write-wins conflict resolution)  │\n└───────────────┬───────────────────────────┘\n                │\n                ▼\n┌───────────────────────────────────────────┐\n│ 4. Update Local with server response      │\n│    (Reconcile timestamps)                 │\n└───────────────────────────────────────────┘\n```\n\n### 3. NgRx Signals State Management\n\n**NUNCA usar NgRx Store clásico**. Siempre Signals:\n\n```typescript\n// ✅ CORRECTO: Signal Store con computeds\nimport { signalStore, withState, withComputed, withMethods } from ''@ngrx/signals'';\n\ninterface BlocksState {\n  blocks: DailyBlock[];\n  selectedDate: string;\n  loading: boolean;\n}\n\nexport const BlocksStore = signalStore(\n  { providedIn: ''root'' },\n  withState<BlocksState>({\n    blocks: [],\n    selectedDate: new Date().toISOString().split(''T'')[0],\n    loading: false\n  }),\n  \n  withComputed(({ blocks, selectedDate }) => ({\n    todayBlocks: computed(() => \n      blocks().filter(b => b.date === selectedDate())\n    ),\n    completedCount: computed(() => \n      blocks().filter(b => b.status === ''completed'').length\n    ),\n    completionRate: computed(() => {\n      const total = blocks().length;\n      const completed = blocks().filter(b => b.status === ''completed'').length;\n      return total > 0 ? (completed / total) * 100 : 0;\n    })\n  })),\n  \n  withMethods((store, blocksRepo = inject(BlocksRepository)) => ({\n    async loadBlocks(userId: string, date: string) {\n      patchState(store, { loading: true });\n      try {\n        const blocks = await blocksRepo.getDailyBlocks(userId, date);\n        patchState(store, { blocks, selectedDate: date, loading: false });\n      } catch (error) {\n        console.error(''Failed to load blocks'', error);\n        patchState(store, { loading: false });\n      }\n    },\n    \n    async completeBlock(blockId: string, note?: string) {\n      // Optimistic update\n      const updatedBlocks = store.blocks().map(b => \n        b.id === blockId \n          ? { ...b, status: ''completed'' as const, completion_note: note }\n          : b\n      );\n      patchState(store, { blocks: updatedBlocks });\n      \n      // Background sync\n      try {\n        await blocksRepo.completeBlock(blockId, note);\n      } catch (error) {\n        // Rollback on failure\n        patchState(store, { blocks: store.blocks() });\n        throw error;\n      }\n    }\n  }))\n);\n```\n\n## Capacitor Integration Patterns\n\n### Plugin Initialization\n\n```typescript\n// src/app/core/capacitor/capacitor.service.ts\nimport { Injectable, inject } from ''@angular/core'';\nimport { Platform } from ''@angular/cdk/platform'';\nimport { App } from ''@capacitor/app'';\nimport { StatusBar, Style } from ''@capacitor/status-bar'';\nimport { SplashScreen } from ''@capacitor/splash-screen'';\n\n@Injectable({ providedIn: ''root'' })\nexport class CapacitorService {\n  private platform = inject(Platform);\n  \n  async initialize() {\n    if (!this.platform.isBrowser) {\n      await this.setupStatusBar();\n      await this.setupAppListeners();\n      await SplashScreen.hide();\n    }\n  }\n  \n  private async setupStatusBar() {\n    if (this.platform.IOS) {\n      await StatusBar.setStyle({ style: Style.Dark });\n    } else if (this.platform.ANDROID) {\n      await StatusBar.setBackgroundColor({ color: ''#1a202c'' });\n    }\n  }\n  \n  private async setupAppListeners() {\n    App.addListener(''appStateChange'', ({ isActive }) => {\n      if (isActive) {\n        // Resume sync cuando app vuelve a foreground\n        inject(SyncService).resumeSync();\n      }\n    });\n    \n    App.addListener(''backButton'', ({ canGoBack }) => {\n      if (!canGoBack) {\n        App.exitApp();\n      }\n    });\n  }\n}\n```\n\n### Local Notifications Pattern\n\n```typescript\n// src/app/core/notifications/notification.service.ts\nimport { LocalNotifications, ScheduleOptions } from ''@capacitor/local-notifications'';\nimport { Haptics, ImpactStyle } from ''@capacitor/haptics'';\n\n@Injectable({ providedIn: ''root'' })\nexport class NotificationService {\n  private hasPermissions = signal(false);\n  \n  async init() {\n    const result = await LocalNotifications.requestPermissions();\n    this.hasPermissions.set(result.display === ''granted'');\n  }\n  \n  async scheduleBlockReminder(block: DailyBlock, minutesBefore: number = 5) {\n    if (!this.hasPermissions()) return;\n    \n    const reminderTime = new Date(block.start_time);\n    reminderTime.setMinutes(reminderTime.getMinutes() - minutesBefore);\n    \n    await LocalNotifications.schedule({\n      notifications: [{\n        id: this.generateNotificationId(block.id),\n        title: `Próximo: ${block.name}`,\n        body: `Comienza en ${minutesBefore} minutos`,\n        schedule: { at: reminderTime },\n        actionTypeId: ''BLOCK_REMINDER'',\n        extra: { blockId: block.id, blockName: block.name }\n      }]\n    });\n  }\n  \n  // Cancelar todas las notificaciones de un día específico\n  async cancelDayNotifications(date: string) {\n    const pending = await LocalNotifications.getPending();\n    const idsToCancel = pending.notifications\n      .filter(n => n.extra?.date === date)\n      .map(n => n.id);\n    \n    if (idsToCancel.length > 0) {\n      await LocalNotifications.cancel({ notifications: idsToCancel.map(id => ({ id })) });\n    }\n  }\n  \n  // Haptic feedback para confirmaciones\n  async triggerSuccess() {\n    await Haptics.impact({ style: ImpactStyle.Medium });\n  }\n  \n  async triggerError() {\n    await Haptics.notification({ type: NotificationType.Error });\n  }\n  \n  private generateNotificationId(blockId: string): number {\n    // Convertir UUID a número único (primeros 8 chars en hex)\n    return parseInt(blockId.slice(0, 8), 16);\n  }\n}\n```\n\n## PrimeNG Mobile Optimizations\n\n### Touch-Optimized Dialog\n\n```typescript\n// Wrapper component para dialogs móviles\n@Component({\n  selector: ''app-mobile-dialog'',\n  standalone: true,\n  imports: [DialogModule],\n  template: `\n    <p-dialog\n      [(visible)]=\"visible\"\n      [modal]=\"true\"\n      [dismissableMask]=\"true\"\n      [blockScroll]=\"true\"\n      [styleClass]=\"''mobile-dialog''\"\n      [position]=\"position()\"\n      [breakpoints]=\"{ ''960px'': ''90vw'', ''640px'': ''100vw'' }\"\n    >\n      <ng-content></ng-content>\n    </p-dialog>\n  `,\n  styles: [`\n    :host ::ng-deep .mobile-dialog {\n      .p-dialog-content {\n        padding: var(--spacing-lg);\n        max-height: 70vh;\n        overflow-y: auto;\n        -webkit-overflow-scrolling: touch;\n      }\n      \n      // iOS safe area\n      @supports (padding: env(safe-area-inset-bottom)) {\n        .p-dialog-footer {\n          padding-bottom: calc(var(--spacing-md) + env(safe-area-inset-bottom));\n        }\n      }\n    }\n  `]\n})\nexport class MobileDialogComponent {\n  visible = model<boolean>(false);\n  \n  private platform = inject(Platform);\n  \n  position = computed(() => \n    this.platform.IOS ? ''bottom'' : ''center''\n  );\n}\n```\n\n### Infinite Scroll con DataView\n\n```typescript\n@Component({\n  selector: ''app-habit-history'',\n  standalone: true,\n  imports: [DataViewModule, ScrollerModule],\n  template: `\n    <p-dataView\n      [value]=\"visibleItems()\"\n      [layout]=\"''list''\"\n      [lazy]=\"true\"\n      (onLazyLoad)=\"loadMore($event)\"\n    >\n      <ng-template let-item pTemplate=\"listItem\">\n        <app-habit-card [habit]=\"item\" />\n      </ng-template>\n    </p-dataView>\n  `\n})\nexport class HabitHistoryComponent {\n  private habitsStore = inject(HabitsStore);\n  \n  visibleItems = computed(() => \n    this.habitsStore.habits().slice(0, this.pageSize() * this.currentPage())\n  );\n  \n  private pageSize = signal(20);\n  private currentPage = signal(1);\n  \n  loadMore(event: any) {\n    this.currentPage.update(p => p + 1);\n  }\n}\n```\n\n## GSAP Animation Patterns\n\n### Streak Celebration Animation\n\n```typescript\n// src/app/shared/animations/streak.animations.ts\nimport gsap from ''gsap'';\n\nexport class StreakAnimations {\n  static playStreakComplete(element: HTMLElement, days: number) {\n    const tl = gsap.timeline();\n    \n    // Scale + Rotation\n    tl.to(element, {\n      scale: 1.3,\n      rotation: 360,\n      duration: 0.6,\n      ease: ''back.out(2)'',\n      onStart: () => {\n        element.classList.add(''celebrating'');\n      }\n    });\n    \n    // Bounce back\n    tl.to(element, {\n      scale: 1,\n      duration: 0.3,\n      ease: ''elastic.out(1, 0.5)''\n    });\n    \n    // Milestone confetti\n    if ([7, 30, 100].includes(days)) {\n      this.playConfetti(element.parentElement!);\n    }\n  }\n  \n  static playStreakLost(element: HTMLElement) {\n    const tl = gsap.timeline();\n    \n    // Shake violently\n    tl.to(element, {\n      x: -10,\n      duration: 0.05,\n      repeat: 5,\n      yoyo: true\n    });\n    \n    // Fade out and shrink\n    tl.to(element, {\n      opacity: 0,\n      scale: 0.5,\n      duration: 0.4,\n      ease: ''power2.in'',\n      onComplete: () => {\n        gsap.set(element, { opacity: 1, scale: 1, x: 0 });\n      }\n    });\n  }\n  \n  private static playConfetti(container: HTMLElement) {\n    // Crear partículas\n    const colors = [''#6366f1'', ''#10b981'', ''#f59e0b'', ''#ef4444''];\n    const particleCount = 30;\n    \n    for (let i = 0; i < particleCount; i++) {\n      const particle = document.createElement(''div'');\n      particle.className = ''confetti-particle'';\n      particle.style.backgroundColor = colors[Math.floor(Math.random() * colors.length)];\n      container.appendChild(particle);\n      \n      gsap.fromTo(particle, \n        {\n          x: 0,\n          y: 0,\n          opacity: 1,\n          scale: 1\n        },\n        {\n          x: (Math.random() - 0.5) * 300,\n          y: -200 + Math.random() * 100,\n          opacity: 0,\n          scale: 0,\n          duration: 1.5,\n          ease: ''power2.out'',\n          onComplete: () => particle.remove()\n        }\n      );\n    }\n  }\n}\n```\n\n### Page Transition Animation\n\n```typescript\n// src/app/core/animations/route-animations.ts\nimport { trigger, transition, style, animate, query } from ''@angular/animations'';\n\nexport const slideInAnimation = trigger(''routeAnimations'', [\n  transition(''* <=> *'', [\n    query('':enter, :leave'', [\n      style({\n        position: ''absolute'',\n        width: ''100%'',\n        transform: ''translateX(0)'',\n        opacity: 1\n      })\n    ], { optional: true }),\n    \n    query('':enter'', [\n      style({ transform: ''translateX(100%)'', opacity: 0 })\n    ], { optional: true }),\n    \n    query('':leave'', [\n      animate(''300ms ease-out'', style({ \n        transform: ''translateX(-100%)'',\n        opacity: 0 \n      }))\n    ], { optional: true }),\n    \n    query('':enter'', [\n      animate(''300ms 150ms ease-out'', style({ \n        transform: ''translateX(0)'',\n        opacity: 1 \n      }))\n    ], { optional: true })\n  ])\n]);\n```\n\n## Offline Sync Patterns\n\n### SQLite Repository\n\n```typescript\n// src/app/core/database/sqlite.service.ts\nimport { CapacitorSQLite, SQLiteConnection, SQLiteDBConnection } from ''@capacitor-community/sqlite'';\n\n@Injectable({ providedIn: ''root'' })\nexport class SQLiteService {\n  private sqlite: SQLiteConnection;\n  private db!: SQLiteDBConnection;\n  \n  async init() {\n    this.sqlite = new SQLiteConnection(CapacitorSQLite);\n    \n    this.db = await this.sqlite.createConnection(\n      ''lifeblocks'',\n      false,\n      ''no-encryption'',\n      1,\n      false\n    );\n    \n    await this.db.open();\n    await this.createTables();\n  }\n  \n  private async createTables() {\n    const schema = `\n      CREATE TABLE IF NOT EXISTS daily_blocks (\n        id TEXT PRIMARY KEY,\n        user_id TEXT NOT NULL,\n        date TEXT NOT NULL,\n        name TEXT NOT NULL,\n        start_time TEXT NOT NULL,\n        end_time TEXT NOT NULL,\n        status TEXT DEFAULT ''pending'',\n        completion_note TEXT,\n        completed_at TEXT,\n        synced INTEGER DEFAULT 0,\n        updated_at TEXT DEFAULT CURRENT_TIMESTAMP\n      );\n      \n      CREATE INDEX IF NOT EXISTS idx_blocks_date ON daily_blocks(date);\n      CREATE INDEX IF NOT EXISTS idx_blocks_sync ON daily_blocks(synced);\n      \n      CREATE TABLE IF NOT EXISTS sync_queue (\n        id INTEGER PRIMARY KEY AUTOINCREMENT,\n        operation TEXT NOT NULL,\n        table_name TEXT NOT NULL,\n        record_id TEXT NOT NULL,\n        payload TEXT NOT NULL,\n        created_at TEXT DEFAULT CURRENT_TIMESTAMP\n      );\n    `;\n    \n    await this.db.execute(schema);\n  }\n  \n  async getUnsyncedBlocks(): Promise<DailyBlock[]> {\n    const result = await this.db.query(\n      ''SELECT * FROM daily_blocks WHERE synced = 0''\n    );\n    return result.values || [];\n  }\n  \n  async markAsSynced(blockId: string) {\n    await this.db.run(\n      ''UPDATE daily_blocks SET synced = 1 WHERE id = ?'',\n      [blockId]\n    );\n  }\n}\n```\n\n### Background Sync Service\n\n```typescript\n// src/app/core/sync/background-sync.service.ts\n@Injectable({ providedIn: ''root'' })\nexport class BackgroundSyncService {\n  private sqlite = inject(SQLiteService);\n  private supabase = inject(SupabaseService);\n  private network = inject(NetworkService);\n  \n  private syncInterval$ = interval(30000); // 30 segundos\n  \n  startAutoSync() {\n    this.syncInterval$\n      .pipe(\n        filter(() => this.network.isOnline()),\n        switchMap(() => this.syncPendingChanges()),\n        catchError(error => {\n          console.error(''Sync failed'', error);\n          return of(null);\n        })\n      )\n      .subscribe();\n  }\n  \n  async syncPendingChanges() {\n    const unsynced = await this.sqlite.getUnsyncedBlocks();\n    \n    for (const block of unsynced) {\n      try {\n        await this.supabase\n          .from(''daily_blocks'')\n          .upsert(block, { onConflict: ''id'' });\n        \n        await this.sqlite.markAsSynced(block.id);\n      } catch (error) {\n        console.error(`Failed to sync block ${block.id}`, error);\n        // Continuar con el siguiente\n      }\n    }\n  }\n}\n```\n\n## Performance Optimization\n\n### Virtual Scrolling for Long Lists\n\n```typescript\n@Component({\n  selector: ''app-inventory-list'',\n  standalone: true,\n  imports: [ScrollingModule, VirtualScrollerModule],\n  template: `\n    <cdk-virtual-scroll-viewport itemSize=\"72\" class=\"viewport\">\n      <app-inventory-item\n        *cdkVirtualFor=\"let item of items(); trackBy: trackById\"\n        [item]=\"item\"\n      />\n    </cdk-virtual-scroll-viewport>\n  `\n})\nexport class InventoryListComponent {\n  items = input.required<InventoryItem[]>();\n  \n  trackById(index: number, item: InventoryItem) {\n    return item.id;\n  }\n}\n```\n\n### Image Loading Strategy\n\n```typescript\n// Directiva para lazy loading de imágenes\n@Directive({\n  selector: ''img[appLazyLoad]'',\n  standalone: true\n})\nexport class LazyLoadDirective implements OnInit {\n  @Input() src!: string;\n  private el = inject(ElementRef<HTMLImageElement>);\n  \n  ngOnInit() {\n    if (''IntersectionObserver'' in window) {\n      const observer = new IntersectionObserver((entries) => {\n        entries.forEach(entry => {\n          if (entry.isIntersecting) {\n            this.loadImage();\n            observer.disconnect();\n          }\n        });\n      });\n      \n      observer.observe(this.el.nativeElement);\n    } else {\n      this.loadImage();\n    }\n  }\n  \n  private loadImage() {\n    this.el.nativeElement.src = this.src;\n  }\n}\n```\n\n## Testing Patterns\n\n### Component Testing with Signals\n\n```typescript\nimport { ComponentFixture, TestBed } from ''@angular/core/testing'';\nimport { signal } from ''@angular/core'';\n\ndescribe(''BlockCardComponent'', () => {\n  let component: BlockCardComponent;\n  let fixture: ComponentFixture<BlockCardComponent>;\n  \n  beforeEach(async () => {\n    await TestBed.configureTestingModule({\n      imports: [BlockCardComponent]\n    }).compileComponents();\n    \n    fixture = TestBed.createComponent(BlockCardComponent);\n    component = fixture.componentInstance;\n  });\n  \n  it(''should update completion status when confirmed'', async () => {\n    const mockBlock = {\n      id: ''1'',\n      name: ''Deep Work'',\n      status: ''pending'' as const\n    };\n    \n    fixture.componentRef.setInput(''block'', mockBlock);\n    fixture.detectChanges();\n    \n    // Simular confirmación\n    await component.confirmCompletion(''Terminé el módulo de auth'');\n    \n    expect(component.block().status).toBe(''completed'');\n  });\n});\n```\n\n### Service Testing with Mocks\n\n```typescript\ndescribe(''BlocksRepository'', () => {\n  let repo: BlocksRepository;\n  let mockSupabase: jasmine.SpyObj<SupabaseClient>;\n  \n  beforeEach(() => {\n    mockSupabase = jasmine.createSpyObj(''SupabaseClient'', [''from'']);\n    \n    TestBed.configureTestingModule({\n      providers: [\n        BlocksRepository,\n        { provide: SupabaseService, useValue: { client: mockSupabase } }\n      ]\n    });\n    \n    repo = TestBed.inject(BlocksRepository);\n  });\n  \n  it(''should fetch daily blocks'', async () => {\n    const mockData = [{ id: ''1'', name: ''Gym'' }];\n    mockSupabase.from.and.returnValue({\n      select: () => ({\n        eq: () => ({\n          eq: () => Promise.resolve({ data: mockData, error: null })\n        })\n      })\n    } as any);\n    \n    const result = await repo.getDailyBlocks(''user-1'', ''2025-01-30'');\n    \n    expect(result).toEqual(mockData);\n  });\n});\n```\n\n## Troubleshooting Common Issues\n\n### Issue: Notificaciones no aparecen en iOS\n\n**Causa**: Permisos no solicitados correctamente\n\n**Solución**:\n```typescript\n// Solicitar permisos DESPUÉS de que el usuario interactúe\nasync requestNotificationPermissions() {\n  const result = await LocalNotifications.requestPermissions();\n  \n  if (result.display !== ''granted'') {\n    // Mostrar dialog explicando por qué son necesarias\n    this.showPermissionsExplanation();\n  }\n}\n```\n\n### Issue: App se congela en sincronización\n\n**Causa**: Operaciones síncronas en main thread\n\n**Solución**: Usar Web Workers\n```typescript\n// sync.worker.ts\naddEventListener(''message'', async (e) => {\n  const { blocks } = e.data;\n  \n  // Procesamiento pesado aquí\n  const processed = await heavySync(blocks);\n  \n  postMessage({ result: processed });\n});\n```\n\n### Issue: Memoria creciente en listas largas\n\n**Causa**: No usar virtual scrolling\n\n**Solución**: Implementar `cdk-virtual-scroll-viewport` (ver sección Performance)\n\n---\n\n## Scripts de Automatización\n\n### Generar Componente Mobile-Ready\n\n```bash\n#!/bin/bash\n# scripts/generate-mobile-component.sh\n\nCOMPONENT_NAME=$1\n\nng generate component \"features/${COMPONENT_NAME}\" \\\n  --standalone=true \\\n  --change-detection=OnPush \\\n  --skip-tests=false \\\n  --style=scss\n\necho \"✅ Componente mobile-ready creado en features/${COMPONENT_NAME}\"\n```\n\n### Sincronizar Tipos de Supabase\n\n```bash\n#!/bin/bash\n# scripts/sync-supabase-types.sh\n\nnpx supabase gen types typescript \\\n  --project-id $SUPABASE_PROJECT_ID \\\n  > src/app/core/supabase/database.types.ts\n\necho \"✅ Tipos de Supabase actualizados\"\n```\n\n---\n\n## Checklist de Code Review\n\nAntes de merge, verificar:\n\n- [ ] Todos los componentes usan `ChangeDetectionStrategy.OnPush`\n- [ ] State management usa NgRx Signals (no NgRx Store)\n- [ ] Sincronización escribe primero a SQLite, luego a Supabase\n- [ ] Notificaciones tienen haptic feedback\n- [ ] Touch targets mínimo 44x44px\n- [ ] Animaciones GSAP optimizadas (`willChange` usado correctamente)\n- [ ] Tests cubren casos offline y online\n- [ ] Safe area insets considerados para iOS\n\n**Related skills:** [angular-primeng](angular-primeng/SKILL.md), [angular-best-practices-primeng](angular-best-practices-primeng/SKILL.md) (PrimeNG); [angular](angular/SKILL.md) (Signals, Standalone).\n\n---\n\n**Versión**: 1.0.0  \n**Última actualización**: 2025-01-30  \n**Compatibilidad**: Angular 18+, Capacitor 6+, PrimeNG 18+\n"},"lastSynced":"2026-03-08T02:03:13.328Z","agentAnalysis":{"suitability":{"en":"Perfect for Mobile App Agents needing specialized architectural patterns for hybrid mobile apps using Angular Standalone Components and Capacitor 6.","zh":"非常适合需要为混合移动应用程序使用 Angular Standalone Components 和 Capacitor 6 提供专用架构模式的移动应用程序代理。","ja":"Angular Standalone Components と Capacitor 6 を使用したハイブリッド モバイル アプリケーション向けの専用アーキテクチャ パターンを必要とするモバイル アプリ エージェントに最適です。","ko":"Angular Standalone Components와 Capacitor 6를 사용하는 하이브리드 모바일 애플리케이션을 위한 전문 아키텍처 패턴이 필요한 모바일 애플리케이션 에이전트에 적합합니다.","es":"Perfecto para Agentes de Aplicaciones Móviles que necesitan patrones arquitectónicos especializados para aplicaciones móviles híbridas que utilizan Angular Standalone Components y Capacitor 6.","fr":"Parfait pour les Agents d''Applications Mobiles ayant besoin de modèles d''architecture spécialisés pour les applications mobiles hybrides utilisant Angular Standalone Components et Capacitor 6.","de":"Perfekt für Mobile App-Agents, die spezielle Architekturmuster für hybride Mobile Apps benötigen, die Angular Standalone Components und Capacitor 6 verwenden.","pt":"Perfeito para Agentes de Aplicativos Móveis que precisam de padrões arquiteturais especializados para aplicativos móveis híbridos que usam Angular Standalone Components e Capacitor 6.","ru":"Идеально подходит для агентов мобильных приложений, нуждающихся в специализированных архитектурных шаблонах для гибридных мобильных приложений, использующих Angular Standalone Components и Capacitor 6.","ar":"مثالي لعميل تطبيقات الجوال الذين يحتاجون إلى أنماط معمارية متخصصة لتطبيقات الجوال الهجين التي تستخدم Angular Standalone Components و Capacitor 6."},"recommendation":{"en":"Empowers agents to implement offline-first strategies, integrate Capacitor plugins like Notifications and Storage, and configure GSAP animations for gamification, all while structuring features with NgRx Signals and utilizing Supabase for synchronization.","zh":"赋予代理实现离线优先策略、集成诸如通知和存储的 Capacitor 插件、为游戏化配置 GSAP 动画的能力，并在此过程中使用 NgRx Signals 结构化功能、利用 Supabase 进行同步。","ja":"エージェントがオフライン優先戦略を実装し、通知やストレージなどの Capacitor プラグインを統合し、ゲーム化のために GSAP アニメーションを構成し、NgRx Signals で機能を構造化し、Supabase を使用して同期することを可能にします。","ko":"에이전트가 오프라인 우선 전략을 구현하고, 알림 및 저장소와 같은 Capacitor 플러그인을 통합하고, 게임화에 대한 GSAP 애니메이션을 구성하며, NgRx Signals로 기능을 구조화하고, Supabase를 사용하여 동기화를 수행할 수 있도록 합니다.","es":"Permite a los agentes implementar estrategias de offline-first, integrar plugins de Capacitor como Notificaciones y Almacenamiento, y configurar animaciones GSAP para gamificación, todo mientras estructuran características con NgRx Signals y utilizan Supabase para la sincronización.","fr":"Permet aux agents de mettre en œuvre des stratégies de offline-first, d''intégrer des plugins Capacitor tels que les Notifications et le Stockage, et de configurer des animations GSAP pour des éléments de gamification interactifs, le tout en structurant les fonctionnalités avec NgRx Signals et en utilisant Supabase pour la synchronisation.","de":"Ermöglicht es den Agenten, Offline-First-Strategien umzusetzen, Capacitor-Plugins wie Benachrichtigungen und Speicherung zu integrieren und GSAP-Animationen für Gamification zu konfigurieren, während sie Funktionen mit NgRx Signals strukturieren und Supabase für die Synchronisierung verwenden.","pt":"Habilita os agentes a implementar estratégias offline-first, integrar plugins do Capacitor, como Notificações e Armazenamento, e configurar animações GSAP para gamificação, tudo isso enquanto estruturam recursos com NgRx Signals e utilizam Supabase para sincronização.","ru":"Позволяет агентам реализовывать стратегии offline-first, интегрировать плагины Capacitor, такие как Уведомления и Хранилище, и настраивать анимации GSAP для геймификации, все это при структурировании функций с помощью NgRx Signals и использовании Supabase для синхронизации.","ar":"يسمح للوكلاء بتنفيذ استراتيجيات عدم الاتصال أولًا، وتكامل إضافات Capacitor مثل الإشعارات والتخزين، وتكوين animations GSAP للتحفيز، كل ذلك أثناء هيكلة الميزات مع NgRx Signals واستخدام Supabase للتنسيق."},"useCases":{"en":["Implementing offline-first synchronization with Supabase","Integrating Capacitor plugins for enhanced mobile functionality","Configuring GSAP animations for interactive gamification elements","Structuring mobile app features with NgRx Signals for improved state management"],"zh":["使用 Supabase 实现离线优先同步","集成 Capacitor 插件以增强移动功能","为交互式游戏化元素配置 GSAP 动画","使用 NgRx Signals 结构化移动应用功能以改善状态管理"],"ja":["Supabase を使用したオフライン優先同期の実装","Capacitor プラグインの統合によるモバイル機能の強化","インタラクティブなゲーム化要素用の GSAP アニメーションの構成","NgRx Signals を使用したモバイル アプリ機能の構造化と状態管理の改善"],"ko":["Supabase를 사용한 오프라인 우선 동기화 구현","Capacitor 플러그인의 통합을 통한 모바일 기능 강화","인터랙티브 게임화 요소용 GSAP 애니메이션 구성","NgRx Signals를 사용한 모바일 애플리케이션 기능 구조화 및 상태 관리 개선"],"es":["Implementar la sincronización de offline-first con Supabase","Integrar plugins de Capacitor para una funcionalidad móvil mejorada","Configurar animaciones GSAP para elementos de gamificación interactivos","Estructurar características de aplicaciones móviles con NgRx Signals para una mejor gestión de estado"],"fr":["Mettre en œuvre la synchronisation de offline-first avec Supabase","Intégrer des plugins Capacitor pour une fonctionnalité mobile améliorée","Configurer des animations GSAP pour des éléments de gamification interactifs","Structurer les fonctionnalités des applications mobiles avec NgRx Signals pour une meilleure gestion d''état"],"de":["Implementierung der Offline-First-Synchronisierung mit Supabase","Integration von Capacitor-Plugins für eine verbesserte mobile Funktionalität","Konfiguration von GSAP-Animationen für interaktive Gamification-Elemente","Strukturierung von Mobile-App-Funktionen mit NgRx Signals für eine verbesserte Zustandsverwaltung"],"pt":["Implementação da sincronização offline-first com Supabase","Integração de plugins do Capacitor para funcionalidade móvel aprimorada","Configuração de animações GSAP para elementos de gamificação interativos","Estruturação de recursos de aplicativos móveis com NgRx Signals para gerenciamento de estado aprimorado"],"ru":["Реализация синхронизации offline-first с помощью Supabase","Интеграция плагинов Capacitor для расширенной мобильной функциональности","Настройка анимаций GSAP для интерактивных элементов геймификации","Структурирование функций мобильных приложений с помощью NgRx Signals для улучшения управления состоянием"],"ar":["تنفيذ التزامن عدم الاتصال أولًا مع Supabase","تكامل إضافات Capacitor للوظائف المتنقلة المتقدمة","تكوين animations GSAP للعناصر التفاعلية للتحفيز","هيكلة ميزات تطبيقات الجوال مع NgRx Signals لتحسين إدارة الحالة"]},"limitations":{"en":["Requires Angular Standalone Components and Capacitor 6","Offline-first strategies may require additional setup and configuration","Supabase integration necessary for offline synchronization"],"zh":["需要 Angular Standalone Components 和 Capacitor 6","离线优先策略可能需要额外的设置和配置","需要 Supabase 集成以实现离线同步"],"ja":["Angular Standalone Components と Capacitor 6 が必要","オフライン優先戦略には追加の設定と構成が必要になる可能性がある","オフライン同期を実現するために Supabase の統合が必要"],"ko":["Angular Standalone Components와 Capacitor 6가 필요","오프라인 우선 전략은 추가 설정 및 구성이 필요할 수 있음","오프라인 동기화를 수행하기 위해 Supabase 통합이 필요"],"es":["Requiere Angular Standalone Components y Capacitor 6","Las estrategias de offline-first pueden requerir una configuración y setup adicionales","La integración de Supabase es necesaria para la sincronización de offline"],"fr":["Nécessite Angular Standalone Components et Capacitor 6","Les stratégies de offline-first peuvent nécessiter une configuration et un setup supplémentaires","L''intégration de Supabase est nécessaire pour la synchronisation de offline"],"de":["Benötigt Angular Standalone Components und Capacitor 6","Offline-First-Strategien können eine zusätzliche Konfiguration und Einrichtung erfordern","Die Integration von Supabase ist für die Offline-Synchronisierung erforderlich"],"pt":["Exige Angular Standalone Components e Capacitor 6","Estratégias offline-first podem exigir configuração e instalação adicionais","Integração com Supabase necessária para sincronização offline"],"ru":["Требует Angular Standalone Components и Capacitor 6","Стратегии offline-first могут требовать дополнительной настройки и конфигурации","Интеграция с Supabase необходима для синхронизации offline"],"ar":["يتطلب Angular Standalone Components و Capacitor 6"," قد تتطلب استراتيجيات عدم الاتصال أولًا إعدادًا وتكوينًا إضافيًا","التكامل مع Supabase ضروري للتنسيق غير المتصلة"]},"version":4},"contentHash":"4375b2cf6f2a71b582f1b9d888fa1354651a07f7f6825f168bb880e1dd48fee7","qualityScore":42}');
