INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kizzz/eleon-client/angular-capacitor-patterns', 'angular-capacitor-patterns', 'kizzz', 'eleon-client', 'community', 'angular-capacitor-patterns kizzz eleon-client community angular-capacitor-patterns provides specialized architectural patterns for hybrid mobile apps using Angular Standalone Components, Capacitor 6, and offline-first strategies. It benefits developers building optimized mobile applications. Angular + Capacitor移动应用开发模式，用于构建高性能的混合移动应用 Angular + Capacitorモバイルアプリ開発パターンは、ハイブリッドモバイルアプリを構築するために使用されます Angular + Capacitor 모바일 애플리케이션 개발 패턴은 고성능 하이브리드 모바일 애플리케이션을 구축하는 데 사용됩니다 Patrones arquitectónicos especializados para aplicaciones móviles híbridas con Angular y Capacitor Modèles architecturaux spécialisés pour les applications mobiles hybrides avec Angular et Capacitor Spezialisierte Architekturmuster für hybride Mobile-Anwendungen mit Angular und Capacitor O angular-capacitor-patterns é um conjunto de padrões arquitetônicos para aplicativos móveis híbridos usando Angular e Capacitor. Angular + Capacitor - это набор архитектурных шаблонов для гибридных мобильных приложений, использующих Angular и Capacitor с ИИ Агентами angular-capacitor-patterns هو مجموعة من الأنماط المعمارية لتطبيقات الجوال الهجينة باستخدام Angular و Capacitor مع أدوات الذكاء الاصطناعي how to use angular-capacitor-patterns angular-capacitor-patterns tutorial angular-capacitor-patterns vs ionic angular-capacitor-patterns install angular-capacitor-patterns setup guide what is angular-capacitor-patterns angular-capacitor-patterns alternative angular-capacitor-patterns mobile app development Angular移动应用开发 Capacitor移动应用开发 离线优先开发 GSAP动画 NgRx Signals AIエージェント 移动应用开发最佳实践 Implements offline-first synchronization with Supabase Integrates Capacitor plugins such as Notifications, Storage, and Camera Configures GSAP animations for gamification Structures features with NgRx Signals Optimizes mobile components for touch using Angular Standalone Components angular-capacitor-patterns is a set of specialized architectural patterns for building hybrid mobile applications using Angular, Capacitor, and offline-first strategies.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('EpicenterHQ/epicenter/documentation', 'community', 'EpicenterHQ', 'epicenter', 'EpicenterHQ/epicenter', 'documentation', 0, 0, 42, '2026-03-08T01:57:15.337Z', '2026-03-08T02:03:20.097Z', '3bde9a18824c6aba5de728c80c6971f0ec9de88042c912447d6ea96b8501b6ee', '{"id":"EpicenterHQ/epicenter/documentation","name":"documentation","description":{"en":"The documentation skill helps developers explain the reasoning behind their code, creating informative folder READMEs with ASCII art diagrams and overviews of key exports.","zh":"AI AgentSkill文档生成工具，帮助开发者快速创建高质量文档，提高开发效率","ja":"AIエージェントを使用したドキュメント生成ツールは、開発者が迅速に高品質なドキュメントを作成するのに役立ちます","ko":"AI 에이전트를 활용한 문서 생성 도구는 개발자가 효율적으로 높은 품질의 문서를 생성할 수 있도록 도와줍니다","es":"La documentación explica el porqué, no el qué. Aprende a crear documentación efectiva para tu proyecto de desarrollo","fr":"La documentation explique le pourquoi, pas le quoi. Apprenez à créer une documentation efficace pour votre projet de développement","de":"Die Dokumentation erklärt das Warum, nicht das Was. Erfahren Sie, wie Sie effektive Dokumentation für Ihr Entwicklungsprojekt erstellen","pt":"A documentação explica o porquê, não o que. Ela inclui ASCII art e modelos mentais para ajudar os usuários a entenderem o código","ru":"Документация объясняет почему, а не что. Она включает в себя ASCII-искусство и ментальные модели, чтобы помочь пользователям понять код","ar":"التوثيق يشرح لماذا، لا ما. يتضمن فن ASCII والنماذج العقلية لمساعدة المستخدمين على فهم الكود"},"seo":{"title":{"en":"Documentation: Setup Guide for AI Agents | AI Agent Skill","zh":"文档生成工具：使用AI AgentSkill进行高效文档编写","ja":"AIエージェントを使用したドキュメントの作成ガイド","ko":"문서 작성 가이드: AI 에이전트를 활용한 효율적인 문서 생성","es":"Guía de configuración de documentación para desarrolladores","fr":"Guide de mise en place de la documentation pour les dével...","de":"Einrichtungsleitfaden für Dokumentation für Entwickler","pt":"Guia de Configuração de Documentação para Agentes de IA","ru":"Настройка документации для ИИ Агентов: Лучшие Практики","ar":"دليل إعداد التوثيق لعميل الذكاء الاصطناعي"},"description":{"en":"Discover how to effectively use documentation with AI agents. Learn to explain the ''why'' behind your code and create informative folder READMEs with ASCII ar...","zh":"了解如何使用AI AgentSkill进行文档生成，提高开发效率，实现高质量文档编写","ja":"AIエージェントを使用してドキュメントを作成する方法を学び、開発効率を向上させましょう","ko":"AI 에이전트를 사용하여 문서 생성을 자동화하고 개발 효율성을 높이는 방법을 알아보세요","es":"Aprende a crear documentación efectiva con ASCII art y explicaciones claras para tu proyecto de desarrollo","fr":"Découvrez comment créer une documentation efficace avec des diagrammes ASCII et des explications claires pour votre projet de développement","de":"Erfahren Sie, wie Sie effektive Dokumentation mit ASCII-Kunst und klaren Erklärungen für Ihr Entwicklungsprojekt erstellen","pt":"Aprenda a criar documentação eficaz para agentes de IA, incluindo explicações de ASCII art e modelos mentais","ru":"Узнайте, как создать эффективную документацию для ИИ Агентов, включая объяснения ASCII-искусства и ментальных моделей","ar":"تعرف على كيفية إنشاء توثيق فعال لعميل الذكاء الاصطناعي، بما في ذلك شرح الفن ASCII والنماذج العقلية"},"definition":{"en":"Documentation is a process of explaining the ''why'' behind code, providing context and mental models for users to understand the reasoning and relationships between different components.","zh":"文档生成工具是指使用AI AgentSkill自动创建文档的技术","ja":"ドキュメント生成ツールとは、AIエージェントを使用してドキュメントを作成する技術です","ko":"문서 생성 도구는 AI 에이전트를 사용하여 문서를 자동으로 생성하는 기술입니다","es":"La documentación es el proceso de explicar el razonamiento detrás de un proyecto de desarrollo","fr":"La documentation est le processus d''explication de la logique derrière un projet de développement","de":"Die Dokumentation ist der Prozess der Erklärung der Argumentation hinter einem Entwicklungsprojekt","pt":"Documentação é a explicação do porquê do código, incluindo modelos mentais e ASCII art para ajudar os usuários a entenderem","ru":"Документация - это объяснение почему кода, включая ментальные модели и ASCII-искусство, чтобы помочь пользователям понять","ar":"التوثيق هو شرح لماذا الكود، بما في ذلك النماذج العقلية وفن ASCII لمساعدة المستخدمين على الفهم"},"features":{"en":["Explains the ''why'' behind code, not just the ''what''","Creates informative folder READMEs with ASCII art diagrams","Provides overviews of key exports and entry points","Includes brief file descriptions for added context","Supports relationships to other folders for better understanding"],"zh":["支持ASCII艺术图表","提供文件夹README模板","支持文件描述和关键导出","提供关系图和概述","支持多语言文档生成","集成writing-voice风格指南"],"ja":["ASCIIアート図表のサポート","フォルダREADMEテンプレートの提供","ファイルの説明と主要エクスポートのサポート","関係図と概要の提供","多言語ドキュメント生成のサポート","writing-voiceスタイルガイドの統合"],"ko":["ASCII 아트 다이어그램 지원","폴더 README 템플릿 제공","파일 설명 및 주요 내보내기 지원","관계도 및 개요 제공","다국어 문서 생성 지원","writing-voice 스타일 가이드 통합"],"es":["Uso de diagramas ASCII para explicar relaciones complejas","Explicaciones claras del modelo mental detrás de cada carpeta","Resumen de puntos de entrada y exportaciones clave","Descripciones breves de archivos para agregar contexto","Relaciones con otras carpetas para una comprensión más profunda"],"fr":["Utilisation de diagrammes ASCII pour expliquer des relations complexes","Explications claires du modèle mental derrière chaque dossier","Résumé des points d''entrée et des exportations clés","Descriptions brèves de fichiers pour ajouter du contexte","Relations avec d''autres dossiers pour une compréhension plus approfondie"],"de":["Verwendung von ASCII-Kunst für die Erklärung komplexer Beziehungen","Klare Erklärungen des mentalen Modells hinter jedem Ordner","Zusammenfassung der Einstiegspunkte und wichtigen Exporte","Kurze Beschreibungen von Dateien für zusätzlichen Kontext","Beziehungen zu anderen Ordnern für ein tieferes Verständnis"],"pt":["Explicações de ASCII art para relações complexas","Visão geral de exports e pontos de entrada principais","Descrições breves de arquivos que adicionam contexto","Relacionamentos com pastas e modelos mentais","Suporte a aplicativos de código aberto e local-first"],"ru":["Объяснения ASCII-искусства для сложных отношений","Обзор основных экспортов и точек входа","Краткие описания файлов, добавляющих контекст","Связи с папками и ментальными моделями","Поддержка открытого кода и локально-ориентированных приложений"],"ar":["شرح فن ASCII للعلاقات المعقدة","نظرة عامة على الصادرات والنقاط الرئيسية للدخول","وصف موجز للملفات التي تضيف السياق","العلاقات مع المجلدات والنماذج العقلية","دعم التطبيقات المفتوحة والمحلية أولاً"]},"keywords":{"en":["how to use documentation","what is documentation","documentation setup guide","documentation best practices","documentation alternative","documentation vs github wiki","documentation install","folder READMEs tutorial","ASCII art diagrams in documentation","documentation for AI agents"],"zh":["AI AgentSkill","文档生成工具","开发效率","高质量文档","ASCII艺术图表","writing-voice风格指南","多语言文档生成","文档自动化"],"ja":["AIエージェント","ドキュメント生成ツール","開発効率","高品質ドキュメント","ASCIIアート図表","writing-voiceスタイルガイド","多言語ドキュメント生成","ドキュメント自動化"],"ko":["AI 에이전트","문서 생성 도구","개발 효율성","높은 품질 문서","ASCII 아트 다이어그램","writing-voice 스타일 가이드","다국어 문서 생성","문서 자동화"],"es":["documentación para desarrolladores","creación de documentación","ASCII art en documentación","explicaciones claras en documentación","modelos mentales en documentación","herramientas de documentación para desarrollo","mejores prácticas de documentación"],"fr":["documentation pour les développeurs","création de documentation","art ASCII dans la documentation","explications claires dans la documentation","modèles mentaux dans la documentation","outils de documentation pour le développement","meilleures pratiques de documentation"],"de":["Dokumentation für Entwickler","Erstellung von Dokumentation","ASCII-Kunst in der Dokumentation","klare Erklärungen in der Dokumentation","mentale Modelle in der Dokumentation","Dokumentationswerkzeuge für die Entwicklung","Best-Practices für Dokumentation"],"pt":["documentação de agentes de IA","guias de configuração de documentação","melhores práticas de documentação","ASCII art em documentação","modelos mentais em programação","desenvolvimento de aplicativos de código aberto","técnicas de documentação para desenvolvedores"],"ru":["документация ИИ Агентов","руководства по настройке документации","лучшие практики документации","ASCII-искусство в документации","ментальные модели в программировании","разработка открытых приложений","техники документации для разработчиков"],"ar":["توثيق عميل الذكاء الاصطناعي","دليل إعداد التوثيق","أفضل ممارسات التوثيق","فن ASCII في التوثيق","نماذج عقلية في البرمجة","تطوير تطبيقات مفتوحة","تقنيات التوثيق للمطورين"]}},"owner":"EpicenterHQ","repo":"epicenter","repoPath":"EpicenterHQ/epicenter","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.337Z","topics":[],"category":"community","skillMd":{"name":"documentation","description":"In-code documentation, folder READMEs, and code comments. Use when writing README.md files, JSDoc comments, or explaining code organization.","bodyPreview":"# Documentation\n\nFollow [writing-voice](../writing-voice/SKILL.md) for tone.\n\nDocumentation explains **why**, not **what**. Users can read code to see what it does. They need you to explain the reasoning.\n\n## Folder READMEs\n\nPrimary job: explain **why** this folder exists and the mental model.\n\n### Can Include\n\n- ASCII art diagrams for complex relationships\n- Overview of key exports or entry points\n- Brief file descriptions IF they add context beyond the filename\n- Relationships to other folders","body":"# Documentation\n\nFollow [writing-voice](../writing-voice/SKILL.md) for tone.\n\nDocumentation explains **why**, not **what**. Users can read code to see what it does. They need you to explain the reasoning.\n\n## Folder READMEs\n\nPrimary job: explain **why** this folder exists and the mental model.\n\n### Can Include\n\n- ASCII art diagrams for complex relationships\n- Overview of key exports or entry points\n- Brief file descriptions IF they add context beyond the filename\n- Relationships to other folders\n\n### Avoid\n\n- Exhaustive file listings that just duplicate `ls`\n- Descriptions that repeat the filename (\"auth.ts - authentication\")\n- Implementation details better expressed in code\n\n### Good\n\n````markdown\n# Converters\n\nTransform field schemas into format-specific representations.\n\n```\n┌─────────────┐     ┌──────────────┐\n│ Field Schema│────▶│  to-arktype  │────▶ Runtime validation\n└─────────────┘     ├──────────────┤\n                    │  to-drizzle  │────▶ SQLite columns\n                    └──────────────┘\n```\n\nField schemas are pure JSON Schema objects with `x-component` hints. Each converter takes the same input and produces output for a specific consumer.\n````\n\n### Bad\n\n```markdown\n# Converters\n\n- `to-arktype.ts` - Converts to ArkType\n- `to-drizzle.ts` - Converts to Drizzle\n- `index.ts` - Exports\n```\n\nThe bad example just lists files without explaining the pattern or when to add new converters.\n\n## JSDoc Comments\n\nJSDoc explains **when and why** to use something, not just what it does.\n\n### Good\n\n````typescript\n/**\n * Get all table helpers as an array.\n *\n * Useful for providers and indexes that need to iterate over all tables.\n * Returns only the table helpers, excluding utility methods like `clearAll`.\n *\n * @example\n * ```typescript\n * for (const table of tables.defined()) {\n *   console.log(table.name, table.count());\n * }\n * ```\n */\ndefined() { ... }\n````\n\n### Bad\n\n```typescript\n/** Returns all table helpers as an array. */\ndefined() { ... }\n```\n\n### Rules\n\n- Include `@example` blocks with realistic usage\n- Explain WHEN to use it, not just WHAT it does\n- Document non-obvious behavior or edge cases\n- Public APIs get detailed docs; internal helpers can be minimal\n\n## Code Comments\n\nComments explain **why**, not **what**.\n\n### Good\n\n```typescript\n// Y.Doc clientIDs are random 32-bit integers, so we can''t rely on ordering.\n// Use timestamps from the entries themselves for deterministic sorting.\nconst sorted = entries.sort((a, b) => a.timestamp - b.timestamp);\n```\n\n### Bad\n\n```typescript\n// Sort the entries\nconst sorted = entries.sort((a, b) => a.timestamp - b.timestamp);\n```\n\n### Rules\n\n- If the code is clear, don''t comment it\n- Comment the \"why\" when it''s not obvious\n- Comment workarounds with links to issues/docs\n- Delete commented-out code; that''s what git is for\n"},"lastSynced":"2026-03-08T02:03:20.097Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents needing advanced documentation capabilities to explain complex code relationships.","zh":"适用于需要高级文档功能来解释复杂代码关系的代码分析代理。","ja":"コード分析エージェントが複雑なコード関係を説明するための高度なドキュメント機能を必要とする場合に最適です。","ko":"복잡한 코드 관계를 설명하는 고급 문서 기능이 필요한 코드 분석 에이전트에게 적합합니다.","es":"Perfecto para agentes de análisis de código que necesitan capacidades de documentación avanzadas para explicar relaciones de código complejas.","fr":"Parfait pour les agents d''analyse de code nécessitant des capacités de documentation avancées pour expliquer des relations de code complexes.","de":"Perfekt für Code-Analyse-Agents, die erweiterte Dokumentationsfunktionen benötigen, um komplexe Code-Beziehungen zu erklären.","pt":"Perfeito para Agentes de Análise de Código que precisam de capacidades de documentação avançadas para explicar relacionamentos de código complexos.","ru":"Идеально для агентов анализа кода, которым требуются расширенные возможности документации для объяснения сложных связей кода.","ar":"مثالي لعمليات تحليل الشفرة التي تحتاج إلى إمكانيات توثيق متقدمة لشرح علاقات الشفرة المعقدة."},"recommendation":{"en":"Empowers agents to generate informative READMEs with ASCII art diagrams, overviews of key exports, and brief file descriptions, providing context beyond filenames using Markdown formatting and folder structure analysis.","zh":"启用代理生成包含ASCII艺术图表、关键导出概述和简要文件描述的信息丰富的README，提供超出文件名的上下文，使用Markdown格式和文件夹结构分析。","ja":"エージェントがASCIIアート図、主要エクスポートの概要、簡潔なファイル説明を含む情報豊富なREADMEを生成できるようにし、ファイル名を超えたコンテキストを提供し、Markdown形式とフォルダ構造分析を使用します。","ko":"에이전트가 ASCII 아트 다이어그램, 주요 내보내기 개요 및 간단한 파일 설명을 포함하는 정보가 풍부한 README를 생성할 수 있도록 하여 파일 이름을 넘어서는 컨텍스트를 제공하고 Markdown 형식 및 폴더 구조 분석을 사용합니다.","es":"Habilita a los agentes a generar READMEs informativos con diagramas de arte ASCII, resúmenes de exportaciones clave y descripciones de archivos breves, proporcionando contexto más allá de los nombres de archivo utilizando la formación Markdown y el análisis de la estructura de carpetas.","fr":"Permet aux agents de générer des READMEs informatifs avec des diagrammes d''art ASCII, des aperçus des exportations clés et des descriptions de fichiers brèves, fournissant un contexte au-delà des noms de fichier en utilisant la mise en forme Markdown et l''analyse de la structure des dossiers.","de":"Ermächtigt Agents, informative README-Dateien mit ASCII-Kunstdiagrammen, Übersichten über wichtige Exporte und kurze Dateibeschreibungen zu erstellen, wodurch ein Kontext jenseits der Dateinamen mithilfe der Markdown-Formatierung und der Analyse der Ordnerstruktur bereitgestellt wird.","pt":"Permite que os agentes gerem READMEs informativos com diagramas de arte ASCII, visões gerais das exportações principais e descrições breves de arquivos, fornecendo contexto além dos nomes dos arquivos usando formatação Markdown e análise da estrutura de pastas.","ru":"Позволяет агентам генерировать информативные README с диаграммами ASCII-искусства, обзорами ключевых экспортов и краткими описаниями файлов, предоставляя контекст за пределами имен файлов с использованием форматирования Markdown и анализа структуры папок.","ar":"تمكن العميل من إنشاء ملفات README إعلامية تحتوي على رسومات ASCII وملخصات للمفاخر الرئيسية ووصفًا موجزًا للملفات، وتقديم السياق ما وراء أسماء الملفات باستخدام تنسيق Markdown وتحليل هيكل المجلدات."},"useCases":{"en":["Generating folder READMEs with ASCII art diagrams","Creating informative overviews of key exports","Debugging code relationships using documentation"],"zh":["生成包含ASCII艺术图表的文件夹README","创建关键导出的信息丰富的概述","使用文档调试代码关系"],"ja":["ASCIIアート図を含むフォルダREADMEを生成する","主要エクスポートの情報豊富な概要を作成する","ドキュメントを使用してコード関係をデバッグする"],"ko":["ASCII 아트 다이어그램을 포함하는 폴더 README 생성","주요 내보내기의 정보가 풍부한 개요 생성","문서를 사용하여 코드 관계 디버깅"],"es":["Generación de READMEs de carpetas con diagramas de arte ASCII","Creación de resúmenes informativos de exportaciones clave","Depuración de relaciones de código utilizando la documentación"],"fr":["Génération de READMEs de dossiers avec des diagrammes d''art ASCII","Création d''aperçus informatifs des exportations clés","Débogage des relations de code en utilisant la documentation"],"de":["Erstellung von Ordner-README-Dateien mit ASCII-Kunstdiagrammen","Erstellung von informativen Übersichten über wichtige Exporte","Fehlerbehebung von Code-Beziehungen unter Verwendung der Dokumentation"],"pt":["Geração de READMEs de pastas com diagramas de arte ASCII","Criação de visões gerais informativas das exportações principais","Depuração de relacionamentos de código usando documentação"],"ru":["Генерация README папок с диаграммами ASCII-искусства","Создание информативных обзоров ключевых экспортов","Отладка связей кода с помощью документации"],"ar":["إنشاء ملفات README لمجلدات تحتوي على رسومات ASCII","إنشاء نظرة عامة إعلامية للمفاخر الرئيسية","تصحيح أخطاء العلاقات بين الشفرات باستخدام الوثائق"]},"limitations":{"en":["Requires understanding of writing voice and tone guidelines","Limited to explaining why, not what, the code does"],"zh":["需要了解书写声音和语气指南","仅限于解释代码为什么这样做，而不是代码做什么"],"ja":["書き言葉と口調のガイドラインを理解する必要がある","コードが何をするかではなく、コードがなぜそうするかを説明することのみに限られる"],"ko":["쓰기 목소리 및 тон 지침을 이해해야 함","코드가 무엇을 하는지ではなく 코드가 왜那样 하는지 설명하는 것만으로 제한됨"],"es":["Requiere comprensión de las pautas de voz y tono de escritura","Limitado a explicar por qué, no qué, hace el código"],"fr":["Nécessite une compréhension des directives de voix et de ton d''écriture","Limité à expliquer pourquoi, et non ce que fait le code"],"de":["Benötigt Verständnis für Richtlinien zu Schreibstimme und -ton","Begrenzt auf die Erklärung, warum, nicht was, der Code tut"],"pt":["Exige compreensão das diretrizes de voz e tom de escrita","Limitado a explicar por que, e não o que, o código faz"],"ru":["Требует понимания руководств по голосу и тону письма","Ограничен объяснением почему, а не что, делает код"],"ar":["يتطلب فهم إرشادات صوت وطريقة الكتابة","محدود بتوضيح لماذا وليس ما الذي يفعله الكود"]},"version":4},"contentHash":"3bde9a18824c6aba5de728c80c6971f0ec9de88042c912447d6ea96b8501b6ee","qualityScore":42}');
