INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('EpicenterHQ/epicenter/documentation', 'documentation', 'EpicenterHQ', 'epicenter', 'community', 'documentation EpicenterHQ epicenter community The documentation skill helps developers explain the reasoning behind their code, creating informative folder READMEs with ASCII art diagrams and overviews of key exports. AI AgentSkill文档生成工具，帮助开发者快速创建高质量文档，提高开发效率 AIエージェントを使用したドキュメント生成ツールは、開発者が迅速に高品質なドキュメントを作成するのに役立ちます AI 에이전트를 활용한 문서 생성 도구는 개발자가 효율적으로 높은 품질의 문서를 생성할 수 있도록 도와줍니다 La documentación explica el porqué, no el qué. Aprende a crear documentación efectiva para tu proyecto de desarrollo La documentation explique le pourquoi, pas le quoi. Apprenez à créer une documentation efficace pour votre projet de développement Die Dokumentation erklärt das Warum, nicht das Was. Erfahren Sie, wie Sie effektive Dokumentation für Ihr Entwicklungsprojekt erstellen A documentação explica o porquê, não o que. Ela inclui ASCII art e modelos mentais para ajudar os usuários a entenderem o código Документация объясняет почему, а не что. Она включает в себя ASCII-искусство и ментальные модели, чтобы помочь пользователям понять код التوثيق يشرح لماذا، لا ما. يتضمن فن ASCII والنماذج العقلية لمساعدة المستخدمين على فهم الكود how to use documentation what is documentation documentation setup guide documentation best practices documentation alternative documentation vs github wiki documentation install folder READMEs tutorial ASCII art diagrams in documentation documentation for AI agents AI AgentSkill 文档生成工具 开发效率 高质量文档 ASCII艺术图表 writing-voice风格指南 多语言文档生成 文档自动化 Explains the ''why'' behind code, not just the ''what'' Creates informative folder READMEs with ASCII art diagrams Provides overviews of key exports and entry points Includes brief file descriptions for added context Supports relationships to other folders for better understanding Documentation is a process of explaining the ''why'' behind code, providing context and mental models for users to understand the reasoning and relationships between different components.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('thesampaton/durable-streams-reference/m13-domain-error', 'community', 'thesampaton', 'durable-streams-reference', 'thesampaton/durable-streams-reference', 'm13-domain-error', 0, 0, 42, '2026-03-08T01:57:15.339Z', '2026-03-08T02:03:24.371Z', '5e87ba8162af9e34e6a6afe6f50e7e708bc5363216f7d691870d25965cafa1d3', '{"id":"thesampaton/durable-streams-reference/m13-domain-error","name":"m13-domain-error","description":{"en":"The m13-domain-error skill provides a reference implementation of the Durable Streams protocol in Rust, supporting streaming reads and producer idempotency. It benefits developers working with axum and tokio.","zh":"m13-domain-error 是一个使用 Rust、axum 和 tokio 实现的 Durable Streams 协议参考实现，支持流式读取、生产者幂等性、JSON 批处理和 TTL","ja":"m13-domain-error は、Rust、axum、tokio で実装された Durable Streams プロトコルのリファレンス実装です。ストリーミング読み取り、プロデューサー冪等性、JSON バッチモード、TTL をサポートします","ko":"m13-domain-error는 Rust, axum 및 tokio로 구현된 Durable Streams 프로토콜의 참조 구현입니다. 스트리밍 읽기, 프로듀서 멱등성, JSON 배치 모드 및 TTL을 지원합니다","es":"m13-domain-error es una implementación de referencia del protocolo Durable Streams en Rust, construida con axum y tokio","fr":"m13-domain-error est une implémentation de référence du protocole Durable Streams en Rust, construite avec axum et tokio","de":"m13-domain-error ist eine Referenzimplementierung des Durable Streams-Protokolls in Rust, erstellt mit axum und tokio","pt":"O m13-domain-error é uma implementação de referência do protocolo Durable Streams em Rust, construída com axum e tokio, que suporta leituras de streaming e idempotência do produtor","ru":"m13-domain-error - это эталонная реализация протокола Durable Streams в Rust, построенная с использованием axum и tokio, которая поддерживает потоковые чтения и идемпотентность производителя","ar":"م13-دомен-خطأ هو تنفيذ مرجعي لبروتوكول Durable Streams في روست، مبني على أكسوم وتوكio، يدعم قراءات التدفق وإمكانية إعادة الإنتاج"},"seo":{"title":{"en":"m13-domain-error: Error Handling Setup Guide | AI Agent","zh":"m13-domain-error 错误处理设置指南","ja":"m13-domain-error エラー処理のベストプラクティス - AIエージェント","ko":"m13-domain-error 오류 처리 설정 가이드 - AI 도구","es":"Guía de configuración de m13-domain-error para manejo de ...","fr":"Guide de mise en œuvre de m13-domain-error pour la gestio...","de":"Einrichtungsleitfaden für m13-domain-error zur Fehlerbeha...","pt":"Guia de Implementação m13-domain-error: Tratamento de Err...","ru":"ИИ Агенты: m13-domain-error - Руководство по обработке ош...","ar":"دليل م13-دомен-خطأ: معالجة الأخطاء في روست مع أكسوم وتوكio"},"description":{"en":"Discover how m13-domain-error simplifies error handling with axum and tokio. Learn to implement idempotent producers and streaming reads with our expert guide.","zh":"了解 m13-domain-error 的错误处理机制，包括错误分类、恢复和调试，使用 Rust、axum 和 tokio","ja":"m13-domain-error のエラー処理メカニズムを学びましょう。エラーカテゴライズ、回復、デバッグを Rust、axum、tokio で実現します","ko":"m13-domain-error의 오류 처리 메커니즘을 알아보세요. 오류 분류, 복구 및 디버깅을 Rust, axum 및 tokio에서 구현합니다","es":"Aprende a implementar m13-domain-error con Rust, axum y tokio para un manejo de errores eficaz","fr":"Découvrez comment mettre en œuvre m13-domain-error avec Rust, axum et tokio pour une gestion des erreurs efficace","de":"Erfahren Sie, wie Sie m13-domain-error mit Rust, axum und tokio für eine effiziente Fehlerbehandlung implementieren","pt":"Aprenda a implementar o protocolo Durable Streams em Rust com axum e tokio, incluindo leituras de streaming e idempotência do produtor","ru":"Изучите реализацию протокола Durable Streams в Rust с использованием axum и tokio, включая потоковые чтения и идемпотентность производителя","ar":"تعرف على كيفية تنفيذ بروتوكول Durable Streams في روست مع أكسوم وتوكio، بما في ذلك قراءات التدفق وإمكانية إعادة الإنتاج"},"definition":{"en":"m13-domain-error is a Rust-based implementation of the Durable Streams protocol, offering features like streaming reads, idempotent producers, and JSON batch mode.","zh":"m13-domain-error 是一个错误处理机制，用于处理 Durable Streams 协议中的错误","ja":"m13-domain-error は、Durable Streams プロトコルにおけるエラーを処理するエラーハンドリングメカニズムです","ko":"m13-domain-error는 Durable Streams 프로토콜에서 발생하는 오류를 처리하는 오류 처리 메커니즘입니다","es":"m13-domain-error es un agente de errores que maneja errores de dominio en aplicaciones","fr":"m13-domain-error est un agent d''erreurs qui gère les erreurs de domaine dans les applications","de":"m13-domain-error ist ein Fehleragent, der Domänenfehler in Anwendungen handhabt","pt":"O m13-domain-error é uma estratégia de tratamento de erros para aplicações em Rust, focada em erros de domínio e recuperação","ru":"m13-domain-error - это стратегия обработки ошибок для приложений на Rust, ориентированная на ошибки домена и восстановление","ar":"م13-دомен-خطأ هو استراتيجية لمعالجة الأخطاء للتطبيقات في روست، تركز على أخطاء الدومين وإمكانية الاستعادة"},"features":{"en":["Supports streaming reads via long-poll and SSE","Provides producer idempotency for reliable data processing","Offers JSON batch mode for efficient data handling","Utilizes axum and tokio for building robust applications","Includes TTL support for timed data processing","Enables debugging with context-aware error handling"],"zh":["错误分类和恢复","支持流式读取和生产者幂等性","JSON 批处理和 TTL 支持","使用 Rust、axum 和 tokio 实现","长轮询和 SSE 支持"],"ja":["エラーカテゴライズと回復","ストリーミング読み取りとプロデューサー冪等性のサポート","JSON バッチモードと TTL のサポート","Rust、axum、tokio で実装","長いポーリングと SSE のサポート"],"ko":["오류 분류 및 복구","스트리밍 읽기 및 프로듀서 멱등성 지원","JSON 배치 모드 및 TTL 지원","Rust, axum 및 tokio로 구현","장시간 폴링 및 SSE 지원"],"es":["Soporte para lecturas de streaming (long-poll, SSE)","Idempotencia del productor","Modo de lote JSON","TTL (Time To Live)","Implementación con Rust, axum y tokio"],"fr":["Prise en charge des lectures de streaming (long-poll, SSE)","Idempotence du producteur","Mode batch JSON","TTL (Time To Live)","Implémentation avec Rust, axum et tokio"],"de":["Unterstützung für Streaming-Lesevorgänge (long-poll, SSE)","Idempotenz des Produzenten","JSON-Batch-Modus","TTL (Time To Live)","Implementierung mit Rust, axum und tokio"],"pt":["Suporte a leituras de streaming (long-poll, SSE)","Idempotência do produtor","Modo de lote JSON","TTL (Time To Live) para mensagens","Implementação do protocolo Durable Streams em Rust","Construído com axum e tokio"],"ru":["Поддержка потоковых чтений (long-poll, SSE)","Идемпотентность производителя","Режим пакетной передачи JSON","TTL (Time To Live) для сообщений","Реализация протокола Durable Streams в Rust","Построен с использованием axum и tokio"],"ar":["دعم قراءات التدفق (طويل-استطلاع، SSE)","إمكانية إعادة الإنتاج","وضع البتاجة JSON","TTL (زمن الحياة) للرسائل","تنفيذ بروتوكول Durable Streams في روست","مبني على أكسوم وتوكio"]},"keywords":{"en":["how to use m13-domain-error","m13-domain-error setup guide","error handling with axum and tokio","m13-domain-error alternative","m13-domain-error vs other error handling libraries","what is m13-domain-error","m13-domain-error install","m13-domain-error tutorial","m13-domain-error documentation","m13-domain-error examples"],"zh":["m13-domain-error","错误处理","Durable Streams","Rust","axum","tokio","流式读取","生产者幂等性","JSON 批处理","TTL"],"ja":["m13-domain-error","エラー処理","Durable Streams","Rust","axum","tokio","ストリーミング読み取り","プロデューサー冪等性","JSON バッチモード","TTL","AIエージェント"],"ko":["m13-domain-error","오류 처리","Durable Streams","Rust","axum","tokio","스트리밍 읽기","프로듀서 멱등성","JSON 배치 모드","TTL","AI 도구"],"es":["m13-domain-error","errores de dominio","Rust","axum","tokio","Durable Streams","manejo de errores","agentes de errores","Herramientas de IA para desarrolladores"],"fr":["m13-domain-error","erreurs de domaine","Rust","axum","tokio","Durable Streams","gestion des erreurs","agents d''erreurs","Outils d''IA pour les développeurs"],"de":["m13-domain-error","Domänenfehler","Rust","axum","tokio","Durable Streams","Fehlerbehandlung","Fehleragenten","KI-Tools für Entwickler"],"pt":["m13-domain-error","tratamento de erros em Rust","protocolo Durable Streams","axum","tokio","leituras de streaming","idempotência do produtor","modo de lote JSON","TTL"],"ru":["m13-domain-error","обработка ошибок в Rust","протокол Durable Streams","axum","tokio","потоковые чтения","идемпотентность производителя","режим пакетной передачи JSON","TTL"],"ar":["م13-دомен-خطأ","معالجة الأخطاء في روست","بروتوكول Durable Streams","اكسوم","توكio","قراءات التدفق","إمكانية إعادة الإنتاج","وضع البتاجة JSON","TTL"]}},"owner":"thesampaton","repo":"durable-streams-reference","repoPath":"thesampaton/durable-streams-reference","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.339Z","topics":[],"category":"community","skillMd":{"name":"m13-domain-error","description":"Use when designing domain error handling. Keywords: domain error, error categorization, recovery strategy, retry, fallback, domain error hierarchy, user-facing vs internal errors, error code design, circuit breaker, graceful degradation, resilience, error context, backoff, retry with backoff, error recovery, transient vs permanent error, 领域错误, 错误分类, 恢复策略, 重试, 熔断器, 优雅降级","bodyPreview":"# Domain Error Strategy\n\n> **Layer 2: Design Choices**\n\n## Core Question\n\n**Who needs to handle this error, and how should they recover?**\n\nBefore designing error types:\n- Is this user-facing or internal?\n- Is recovery possible?\n- What context is needed for debugging?\n\n---\n\n## Error Categorization\n\n| Error Type | Audience | Recovery | Example |\n|------------|----------|----------|---------|\n| User-facing | End users | Guide action | `InvalidEmail`, `NotFound` |\n| Internal | Developers | Debug in","body":"# Domain Error Strategy\n\n> **Layer 2: Design Choices**\n\n## Core Question\n\n**Who needs to handle this error, and how should they recover?**\n\nBefore designing error types:\n- Is this user-facing or internal?\n- Is recovery possible?\n- What context is needed for debugging?\n\n---\n\n## Error Categorization\n\n| Error Type | Audience | Recovery | Example |\n|------------|----------|----------|---------|\n| User-facing | End users | Guide action | `InvalidEmail`, `NotFound` |\n| Internal | Developers | Debug info | `DatabaseError`, `ParseError` |\n| System | Ops/SRE | Monitor/alert | `ConnectionTimeout`, `RateLimited` |\n| Transient | Automation | Retry | `NetworkError`, `ServiceUnavailable` |\n| Permanent | Human | Investigate | `ConfigInvalid`, `DataCorrupted` |\n\n---\n\n## Thinking Prompt\n\nBefore designing error types:\n\n1. **Who sees this error?**\n   - End user → friendly message, actionable\n   - Developer → detailed, debuggable\n   - Ops → structured, alertable\n\n2. **Can we recover?**\n   - Transient → retry with backoff\n   - Degradable → fallback value\n   - Permanent → fail fast, alert\n\n3. **What context is needed?**\n   - Call chain → anyhow::Context\n   - Request ID → structured logging\n   - Input data → error payload\n\n---\n\n## Trace Up ↑\n\nTo domain constraints (Layer 3):\n\n```\n\"How should I handle payment failures?\"\n    ↑ Ask: What are the business rules for retries?\n    ↑ Check: domain-web or project requirements\n    ↑ Check: SLA (availability requirements)\n```\n\n| Question | Trace To | Ask |\n|----------|----------|-----|\n| Retry policy | domain-web | What''s acceptable latency for retry? |\n| User experience | domain-web | What message should users see? |\n| Compliance | Project requirements | What must be logged for audit? |\n\n---\n\n## Trace Down ↓\n\nTo implementation (Layer 1):\n\n```\n\"Need typed errors\"\n    ↓ m06-error-handling: thiserror for library\n    ↓ m04-zero-cost: Error enum design\n\n\"Need error context\"\n    ↓ m06-error-handling: anyhow::Context\n    ↓ Logging: tracing with fields\n\n\"Need retry logic\"\n    ↓ m07-concurrency: async retry patterns\n    ↓ Crates: tokio-retry, backoff\n```\n\n---\n\n## Quick Reference\n\n| Recovery Pattern | When | Implementation |\n|------------------|------|----------------|\n| Retry | Transient failures | exponential backoff |\n| Fallback | Degraded mode | cached/default value |\n| Circuit Breaker | Cascading failures | failsafe-rs |\n| Timeout | Slow operations | `tokio::time::timeout` |\n| Bulkhead | Isolation | separate thread pools |\n\n## Error Hierarchy\n\n```rust\n#[derive(thiserror::Error, Debug)]\npub enum AppError {\n    // User-facing\n    #[error(\"Invalid input: {0}\")]\n    Validation(String),\n\n    // Transient (retryable)\n    #[error(\"Service temporarily unavailable\")]\n    ServiceUnavailable(#[source] reqwest::Error),\n\n    // Internal (log details, show generic)\n    #[error(\"Internal error\")]\n    Internal(#[source] anyhow::Error),\n}\n\nimpl AppError {\n    pub fn is_retryable(&self) -> bool {\n        matches!(self, Self::ServiceUnavailable(_))\n    }\n}\n```\n\n## Retry Pattern\n\n```rust\nuse tokio_retry::{Retry, strategy::ExponentialBackoff};\n\nasync fn with_retry<F, Fut, T, E>(f: F) -> Result<T, E>\nwhere\n    F: Fn() -> Fut,\n    Fut: Future<Output = Result<T, E>>,\n    E: std::fmt::Debug,\n{\n    let strategy = ExponentialBackoff::from_millis(100)\n        .max_delay(Duration::from_secs(10))\n        .take(5);\n\n    Retry::spawn(strategy, || f()).await\n}\n```\n\n---\n\n## Common Mistakes\n\n| Mistake | Why Wrong | Better |\n|---------|-----------|--------|\n| Same error for all | No actionability | Categorize by audience |\n| Retry everything | Wasted resources | Only transient errors |\n| Infinite retry | DoS self | Max attempts + backoff |\n| Expose internal errors | Security risk | User-friendly messages |\n| No context | Hard to debug | .context() everywhere |\n\n---\n\n## Anti-Patterns\n\n| Anti-Pattern | Why Bad | Better |\n|--------------|---------|--------|\n| String errors | No structure | thiserror types |\n| panic! for recoverable | Bad UX | Result with context |\n| Ignore errors | Silent failures | Log or propagate |\n| Box<dyn Error> everywhere | Lost type info | thiserror |\n| Error in happy path | Performance | Early validation |\n\n---\n\n## Related Skills\n\n| When | See |\n|------|-----|\n| Error handling basics | m06-error-handling |\n| Retry implementation | m07-concurrency |\n| Domain modeling | m09-domain |\n| User-facing APIs | domain-web |\n"},"lastSynced":"2026-03-08T02:03:24.371Z","agentAnalysis":{"suitability":{"en":"Ideal for Rust-based AI Agents requiring robust error handling and streaming capabilities with axum and tokio.","zh":"适用于需要使用 axum 和 tokio 实现强大的错误处理和流媒体功能的 Rust 基础 AI 代理。","ja":"axum と tokio を使用して強力なエラーハンドリングとストリーミング機能を実装する必要がある Rust ベースの AI エージェントに適しています。","ko":"axum과 tokio를 사용하여 강력한 오류 처리 및 스트리밍 기능을 구현해야 하는 Rust 기반 AI 에이전트에 적합합니다.","es":"Ideal para agentes de IA basados en Rust que requieren un control de errores robusto y capacidades de transmisión con axum y tokio.","fr":"Idéal pour les agents d''IA basés sur Rust nécessitant une gestion d''erreurs robuste et des capacités de diffusion avec axum et tokio.","de":"Ideal für auf Rust basierende KI-Agents, die eine robuste Fehlerbehandlung und Streaming-Funktionen mit axum und tokio erfordern.","pt":"Ideal para Agentes de IA baseados em Rust que exigem tratamento de erros robusto e capacidades de transmissão com axum e tokio.","ru":"Идеально для агентов ИИ на основе Rust, требующих надежной обработки ошибок и возможностей потоковой передачи с axum и tokio.","ar":"مثالي للوكلاء الذكاء الاصطناعي المستندة إلى Rust التي تتطلب معالجة الخطأ المتينة والقدرات التدفق مع axum و tokio."},"recommendation":{"en":"Empowers agents to implement idempotent producer streams and handle domain-specific errors using the Durable Streams protocol, facilitating debugging and recovery with Rust.","zh":"赋予代理实现幂等的生产者流并使用 Durable Streams 协议处理特定于域的错误，从而使用 Rust 方便调试和恢复。","ja":"Durable Streams プロトコルを使用して特定のドメイン エラーを処理し、idempotent プロデューサ ストリームを実装することで、Rust を使用してデバッグと回復を容易に行えるエージェントを実現します。","ko":"Durable Streams 프로토콜을 사용하여 특정 도메인 오류를 처리하고 idempotent 프로듀서 스트림을 구현하여 Rust를 사용하여 디버깅 및 복구를 용이하게 하는 에이전트를 구현합니다.","es":"Permite a los agentes implementar flujos de productores idempotentes y controlar errores específicos del dominio utilizando el protocolo Durable Streams, lo que facilita la depuración y la recuperación con Rust.","fr":"Permet aux agents de mettre en œuvre des flux de producteurs idempotents et de gérer des erreurs spécifiques au domaine en utilisant le protocole Durable Streams, ce qui facilite le débogage et la récupération avec Rust.","de":"Ermöglicht es Agents, idempotente Producer-Streams zu implementieren und domänen-spezifische Fehler mithilfe des Durable Streams-Protokolls zu handhaben, was das Debuggen und die Wiederherstellung mit Rust erleichtert.","pt":"Habilita os agentes a implementar streams de produtores idempotentes e lidar com erros específicos do domínio usando o protocolo Durable Streams, facilitando a depuração e recuperação com Rust.","ru":"Предоставляет агентам возможность реализовать идемпотентные потоки производителей и обрабатывать ошибки, специфичные для области применения, используя протокол Durable Streams, что облегчает отладку и восстановление с помощью Rust.","ar":"يمنح الوكلاء القدرة على تنفيذ تدفقات المنتجين المتطابقة ومعالجة الأخطاء المحددة للنطاق باستخدام بروتوكول Durable Streams، مما يسهل التصحيح والاستعادة باستخدام Rust."},"useCases":{"en":["Implementing error categorization for user-facing and internal errors","Designing recovery strategies for domain-specific errors","Integrating streaming reads with producer idempotency using axum and tokio"],"zh":["为用户面向和内部错误实现错误分类","为特定于域的错误设计恢复策略","使用 axum 和 tokio 实现生产者幂等的流媒体读取"],"ja":["ユーザー向けおよび内部エラーのエラーカテゴライズの実装","特定のドメイン エラーのための復旧戦略の設計","axum と tokio を使用したプロデューサーの冪等性を使用したストリーミング リードの統合"],"ko":["사용자 중심 및 내부 오류에 대한 오류 분류 구현","특정 도메인 오류에 대한 복구 전략 설계","axum 및 tokio를 사용하여 프로듀서 idempotency와 스트리밍 읽기 통합"],"es":["Implementar la categorización de errores para errores de cara al usuario y errores internos","Diseñar estrategias de recuperación para errores específicos del dominio","Integrar lecturas de transmisión con idempotencia del productor utilizan