INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('thesampaton/durable-streams-reference/m13-domain-error', 'm13-domain-error', 'thesampaton', 'durable-streams-reference', 'community', 'm13-domain-error thesampaton durable-streams-reference community The m13-domain-error skill provides a reference implementation of the Durable Streams protocol in Rust, supporting streaming reads and producer idempotency. It benefits developers working with axum and tokio. m13-domain-error 是一个使用 Rust、axum 和 tokio 实现的 Durable Streams 协议参考实现，支持流式读取、生产者幂等性、JSON 批处理和 TTL m13-domain-error は、Rust、axum、tokio で実装された Durable Streams プロトコルのリファレンス実装です。ストリーミング読み取り、プロデューサー冪等性、JSON バッチモード、TTL をサポートします m13-domain-error는 Rust, axum 및 tokio로 구현된 Durable Streams 프로토콜의 참조 구현입니다. 스트리밍 읽기, 프로듀서 멱등성, JSON 배치 모드 및 TTL을 지원합니다 m13-domain-error es una implementación de referencia del protocolo Durable Streams en Rust, construida con axum y tokio m13-domain-error est une implémentation de référence du protocole Durable Streams en Rust, construite avec axum et tokio m13-domain-error ist eine Referenzimplementierung des Durable Streams-Protokolls in Rust, erstellt mit axum und tokio O m13-domain-error é uma implementação de referência do protocolo Durable Streams em Rust, construída com axum e tokio, que suporta leituras de streaming e idempotência do produtor m13-domain-error - это эталонная реализация протокола Durable Streams в Rust, построенная с использованием axum и tokio, которая поддерживает потоковые чтения и идемпотентность производителя م13-دомен-خطأ هو تنفيذ مرجعي لبروتوكول Durable Streams في روست، مبني على أكسوم وتوكio، يدعم قراءات التدفق وإمكانية إعادة الإنتاج how to use m13-domain-error m13-domain-error setup guide error handling with axum and tokio m13-domain-error alternative m13-domain-error vs other error handling libraries what is m13-domain-error m13-domain-error install m13-domain-error tutorial m13-domain-error documentation m13-domain-error examples m13-domain-error 错误处理 Durable Streams Rust axum tokio 流式读取 生产者幂等性 JSON 批处理 TTL Supports streaming reads via long-poll and SSE Provides producer idempotency for reliable data processing Offers JSON batch mode for efficient data handling Utilizes axum and tokio for building robust applications Includes TTL support for timed data processing Enables debugging with context-aware error handling m13-domain-error is a Rust-based implementation of the Durable Streams protocol, offering features like streaming reads, idempotent producers, and JSON batch mode.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('1wos/sdkhackthon/moru-python', 'community', '1wos', 'sdkhackthon', '1wos/sdkhackthon', 'moru-python', 0, 0, 42, '2026-03-08T01:57:15.340Z', '2026-03-08T02:03:25.888Z', '444051efa79ead5fe6c01305a54e740413ee1a5ba5a2896cf930671d39651270', '{"id":"1wos/sdkhackthon/moru-python","name":"moru-python","description":{"en":"The moru-python skill provides a Python SDK for creating and managing sandboxes, allowing developers to run commands and interact with files. It benefits AI agent developers and users.","zh":"Moru Python SDK 提供了便捷的沙盒创建、命令运行和文件读写功能","ja":"Moru Python SDK はサンドボックスの作成、コマンドの実行、ファイルの読み書きを容易に行えるようにします","ko":"Moru Python SDK는 샌드박스 생성, 명령 실행 및 파일 읽기/쓰기 기능을 제공합니다","es":"Moru-python es un SDK de Python que permite a los desarrolladores crear sandbox y ejecutar comandos de manera segura y eficiente","fr":"Moru-python est un SDK Python qui permet aux développeurs de créer des sandbox et d''exécuter des commandes de manière sécurisée et efficace","de":"Moru-python ist ein Python-SDK, das es Entwicklern ermöglicht, Sandbox zu erstellen und Befehle sicher und effizient auszuführen","pt":"O Moru Python SDK é uma ferramenta para criar sandboxes e executar comandos Python. Instale com pip e comece a usar.","ru":"Moru Python SDK - это инструмент для создания песочниц и выполнения команд Python. Установите с помощью pip и начните использовать - ИИ Агенты","ar":"Moru Python SDK هي أداة لإنشاء sandboxes وتنفيذ أوامر Python. ثبّت مع pip وابدأ في الاستخدام - أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"moru-python: Python SDK Setup Guide | AI Agent Skill","zh":"Moru Python SDK 安装与配置指南","ja":"Moru Python SDK の設定と使い方 - AIエージェント","ko":"Moru Python SDK 설정 및 사용 방법 - AI 도구","es":"Guía de configuración de moru-python para desarrolladores","fr":"Guide de démarrage rapide pour moru-python","de":"Schnellstart-Anleitung für moru-python-Entwickler","pt":"Guia de Configuração do Moru Python SDK","ru":"Установка и Настройка Moru Python SDK - ИИ Агенты","ar":"دليل إعداد Moru Python SDK - أدوات الذكاء الاصطناعي"},"description":{"en":"Unlock the power of moru-python with our expert guide. Learn how to install and use the moru-python SDK for AI agents and discover its capabilities.","zh":"使用 Moru Python SDK 进行沙盒创建、命令运行和文件读写，了解如何安装和配置","ja":"Moru Python SDK を使用してサンドボックスを作成し、コマンドを実行し、ファイルを読み書きする方法を学ぶ - AIエージェント","ko":"Moru Python SDK를 사용하여 샌드박스를 생성하고 명령을 실행하며 파일을 읽고 쓰는 방법을 알아보세요 - AI 도구","es":"Aprende a utilizar moru-python con nuestro SDK de Python y descubre cómo crear sandbox y ejecutar comandos de manera efectiva","fr":"Découvrez comment utiliser moru-python avec notre SDK Python et apprenez à créer des sandbox et à exécuter des commandes avec efficacité","de":"Erfahren Sie, wie Sie moru-python mit unserem Python-SDK verwenden und entdecken Sie, wie Sie Sandbox erstellen und Befehle effektiv ausführen","pt":"Aprenda a instalar e usar o Moru Python SDK com nosso guia passo a passo. Crie sandboxes e execute comandos com facilidade.","ru":"Узнайте, как установить и использовать Moru Python SDK с нашей пошаговой инструкцией. Создавайте песочницы и выполняйте команды с легкостью - ИИ Агенты","ar":"تعلم كيفية تثبيت واستخدام Moru Python SDK مع دليلنا الخطوة بخطوة. انشئ sandboxes واكتب أوامر بسهولة - أدوات الذكاء الاصطناعي"},"definition":{"en":"moru-python is a Python SDK for creating and managing sandboxes, providing a simple way to run commands and interact with files.","zh":"Moru Python SDK 是一个 Python 库，用于创建沙盒、运行命令和读写文件","ja":"Moru Python SDK は、サンドボックスを作成し、コマンドを実行し、ファイルを読み書きするための Python ライブラリです","ko":"Moru Python SDK는 샌드박스를 생성하고 명령을 실행하며 파일을 읽고 쓰는 데 사용되는 Python 라이브러리입니다","es":"Moru-python es un conjunto de herramientas de AI que permite a los desarrolladores crear entornos de prueba seguros","fr":"Moru-python est un ensemble d''outils d''IA qui permet aux développeurs de créer des environnements de test sécurisés","de":"Moru-python ist ein Satz von AI-Tools, der es Entwicklern ermöglicht, sichere Testumgebungen zu erstellen","pt":"O que é Moru Python SDK? É uma biblioteca Python para criar ambientes de teste isolados.","ru":"Что такое Moru Python SDK? Это библиотека Python для создания изолированных тестовых сред - ИИ Агенты","ar":"ما هو Moru Python SDK? هو مكتبة Python لإنشاء بيئات اختبار معزولة - أدوات الذكاء الاصطناعي"},"features":{"en":["Creates sandboxes using the `Sandbox.create()` command","Runs commands within the sandbox using `sbx.commands.run()`","Supports file writing and reading using `sbx.files.write()` and `sbx.files.r`","Automatically kills the sandbox after use","Installs via pip using `pip install moru`"],"zh":["沙盒创建：使用 `Sandbox.create()` 方法创建沙盒","命令运行：使用 `sbx.commands.run()` 方法运行命令","文件读写：使用 `sbx.files.write()` 和 `sbx.files.read()` 方法读写文件","自动沙盒销毁：沙盒会在使用完毕后自动销毁","支持模板：使用 `Sandbox.create(''template'')` 方法创建模板化沙盒"],"ja":["サンドボックスの作成：`Sandbox.create()` メソッドを使用してサンドボックスを作成","コマンドの実行：`sbx.commands.run()` メソッドを使用してコマンドを実行","ファイルの読み書き：`sbx.files.write()` と `sbx.files.read()` メソッドを使用してファイルを読み書き","自動サンドボックス破棄：サンドボックスは使用完了後に自動的に破棄される","テンプレートのサポート：`Sandbox.create(''template'')` メソッドを使用してテンプレート化サンドボックスを作成"],"ko":["샌드박스 생성：`Sandbox.create()` 메서드를 사용하여 샌드박스를 생성","명령 실행：`sbx.commands.run()` 메서드를 사용하여 명령을 실행","파일 읽기/쓰기：`sbx.files.write()` 및 `sbx.files.read()` 메서드를 사용하여 파일을 읽고 쓰기","자동 샌드박스销毁：샌드박스는 사용이 끝나면 자동으로銷毁","템플릿 지원：`Sandbox.create(''template'')` 메서드를 사용하여 템플릿화된 샌드박스를 생성"],"es":["Creación de sandbox con Sandbox.create()","Ejecución de comandos con sbx.commands.run()","Lectura de archivos con sbx.files.read()","Instalación con pip install moru","Compatibilidad con Python 3"],"fr":["Création de sandbox avec Sandbox.create()","Exécution de commandes avec sbx.commands.run()","Lecture de fichiers avec sbx.files.read()","Installation avec pip install moru","Compatibilité avec Python 3"],"de":["Erstellung von Sandbox mit Sandbox.create()","Ausführung von Befehlen mit sbx.commands.run()","Lesen von Dateien mit sbx.files.read()","Installation mit pip install moru","Kompatibilität mit Python 3"],"pt":["Crie sandboxes com facilidade","Execute comandos Python dentro das sandboxes","Leia e escreva arquivos dentro das sandboxes","Use o método Sandbox.create() para criar ambientes de teste","Use o método sbx.commands.run() para executar comandos"],"ru":["Создавайте песочницы с легкостью","Выполняйте команды Python внутри песочниц","Читайте и записывайте файлы внутри песочниц","Используйте метод Sandbox.create() для создания тестовых сред","Используйте метод sbx.commands.run() для выполнения команд - ИИ Агенты"],"ar":["انشئ sandboxes بسهولة","اكتب أوامر Python داخل sandboxes","اقرأ واكتب ملفات داخل sandboxes","استخدم طريقة Sandbox.create() لإنشاء بيئات اختبار","استخدم طريقة sbx.commands.run() لتنفيذ أوامر - أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use moru-python","moru-python alternative","moru-python install","what is moru-python","moru-python vs docker","moru-python setup guide","moru-python python sdk","moru-python sandbox creation"],"zh":["Moru Python SDK","Python 库","沙盒创建","命令运行","文件读写","自动沙盒销毁","模板支持","AI开发","Python开发"],"ja":["Moru Python SDK","Python ライブラリ","サンドボックスの作成","コマンドの実行","ファイルの読み書き","自動サンドボックス破棄","テンプレートのサポート","AIエージェント","Python開発"],"ko":["Moru Python SDK","Python 라이브러리","샌드박스 생성","명령 실행","파일 읽기/쓰기","자동 샌드박스销毁","템플릿 지원","AI 도구","Python開発"],"es":["moru-python","SDK de Python","creación de sandbox","ejecución de comandos","lectura de archivos","pip install moru","desarrollo de aplicaciones","herramientas de AI","entornos de prueba seguros"],"fr":["moru-python","SDK Python","création de sandbox","exécution de commandes","lecture de fichiers","pip install moru","développement d''applications","outils d''IA","environnements de test sécurisés"],"de":["moru-python","Python-SDK","Erstellung von Sandbox","Ausführung von Befehlen","Lesen von Dateien","pip install moru","Anwendungsentwicklung","AI-Tools","sichere Testumgebungen"],"pt":["Moru Python SDK","sandboxes Python","executar comandos Python","leitura e escrita de arquivos","bibliotecas Python","desenvolvimento de software","testes de unidade"],"ru":["Moru Python SDK","песочницы Python","выполнение команд Python","чтение и запись файлов","библиотеки Python","разработка программного обеспечения","юнит-тесты","ИИ Агенты"],"ar":["Moru Python SDK","sandboxes Python","تنفيذ أوامر Python","قراءة وكتابة الملفات","مكتبات Python","تطوير البرمجيات","اختبارات الوحدة","أدوات الذكاء الاصطناعي"]}},"owner":"1wos","repo":"sdkhackthon","repoPath":"1wos/sdkhackthon","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.340Z","topics":[],"category":"community","skillMd":{"name":"moru-python","description":"Use this skill when writing Python code that interacts with Moru cloud sandboxes. This includes: creating sandboxes with `Sandbox.create()`, running commands with `sbx.commands.run()`, reading and writing files with `sbx.files.read()` and `sbx.files.write()`, working with persistent volumes using the `Volume` class, building custom templates with the `Template` builder, handling background processes, streaming command output, and async operations with `AsyncSandbox`. The skill covers the complete Python SDK API including error handling with `TimeoutException`, `CommandExitException`, `AuthenticationException`, and other exceptions from `moru.exceptions`. Use this skill whenever users want to: execute code safely in isolated environments, build AI agents that run untrusted code, create data processing pipelines, run web scrapers, set up development environments, or any Python automation involving Moru sandboxes. Triggers on: moru python, from moru import, Sandbox.create, pip install moru, moru sdk python, python sandbox, AsyncSandbox, Volume.create, Template.build, or any Python code that needs to run in isolated cloud environments. Do NOT use this skill for JavaScript/TypeScript code - use moru-javascript instead.","bodyPreview":"# Moru Python SDK\n\n```bash\npip install moru\n```\n\n## Quick Start\n\n```python\nfrom moru import Sandbox\n\nwith Sandbox.create() as sbx:\n    sbx.files.write(\"/app/script.py\", \"print(''Hello from Moru!'')\")\n    result = sbx.commands.run(\"python3 /app/script.py\")\n    print(result.stdout)\n# Sandbox auto-killed\n```\n\n## Quick Reference\n\n| Task | Code |\n|------|------|\n| Create sandbox | `Sandbox.create()` or `Sandbox.create(\"template\")` |\n| Run command | `sbx.commands.run(\"cmd\")` |\n| Read file | `sbx.files.r","body":"# Moru Python SDK\n\n```bash\npip install moru\n```\n\n## Quick Start\n\n```python\nfrom moru import Sandbox\n\nwith Sandbox.create() as sbx:\n    sbx.files.write(\"/app/script.py\", \"print(''Hello from Moru!'')\")\n    result = sbx.commands.run(\"python3 /app/script.py\")\n    print(result.stdout)\n# Sandbox auto-killed\n```\n\n## Quick Reference\n\n| Task | Code |\n|------|------|\n| Create sandbox | `Sandbox.create()` or `Sandbox.create(\"template\")` |\n| Run command | `sbx.commands.run(\"cmd\")` |\n| Read file | `sbx.files.read(\"/path\")` |\n| Write file | `sbx.files.write(\"/path\", \"content\")` |\n| Background process | `sbx.commands.run(\"cmd\", background=True)` |\n| Set timeout | `Sandbox.create(timeout=600)` or `sbx.set_timeout(600)` |\n| Use volume | `Sandbox.create(volume_id=vol.volume_id, volume_mount_path=\"/workspace\")` |\n\n---\n\n## Sandbox Lifecycle\n\n### Create\n```python\nfrom moru import Sandbox\n\n# Default template\nsbx = Sandbox.create()\n\n# Specific template\nsbx = Sandbox.create(\"python\")\n\n# With options\nsbx = Sandbox.create(\n    template=\"python\",\n    timeout=600,                    # seconds (default: 300)\n    metadata={\"project\": \"myapp\"},\n    envs={\"API_KEY\": \"secret\"},\n    volume_id=\"vol_xxx\",\n    volume_mount_path=\"/workspace\",\n    allow_internet_access=True,\n)\n```\n\n### Context Manager (Recommended)\n```python\nwith Sandbox.create() as sbx:\n    result = sbx.commands.run(\"echo hello\")\n# Auto-killed on exit\n```\n\n### Connect to Existing\n```python\nsbx = Sandbox.connect(\"sbx_abc123\")\nif sbx.is_running():\n    result = sbx.commands.run(\"echo still alive\")\n```\n\n### Kill\n```python\nsbx.kill()\n# or\nSandbox.kill(\"sbx_abc123\")\n```\n\n### List All\n```python\nfor info in Sandbox.list():\n    print(f\"{info.sandbox_id}: {info.state}\")\n```\n\n---\n\n## Running Commands\n\n### Basic\n```python\nresult = sbx.commands.run(\"echo hello\")\nprint(result.stdout)      # \"hello\\n\"\nprint(result.stderr)      # \"\"\nprint(result.exit_code)   # 0\n```\n\n### With Options\n```python\nresult = sbx.commands.run(\n    \"python3 script.py\",\n    cwd=\"/app\",                         # Working directory\n    user=\"root\",                        # Run as root\n    envs={\"DEBUG\": \"1\"},               # Environment variables\n    timeout=120,                        # Command timeout (seconds)\n    on_stdout=lambda d: print(d, end=\"\"),  # Stream stdout\n    on_stderr=lambda d: print(d, end=\"\"),  # Stream stderr\n)\n```\n\n### Background Process\n```python\nhandle = sbx.commands.run(\"python3 server.py\", background=True)\n\n# Get public URL\nurl = sbx.get_host(8080)\nprint(f\"Server at: {url}\")\n\n# Send input\nhandle.send_stdin(\"quit\\n\")\n\n# Wait for completion\nresult = handle.wait()\n\n# Or kill it\nhandle.kill()\n```\n\n### Process Management\n```python\n# List running processes\nfor proc in sbx.commands.list():\n    print(f\"PID {proc.pid}: {proc.command}\")\n\n# Kill by PID\nsbx.commands.kill(1234)\n```\n\n---\n\n## Working with Files\n\n### Read/Write\n```python\n# Write\nsbx.files.write(\"/app/config.json\", ''{\"key\": \"value\"}'')\n\n# Read\ncontent = sbx.files.read(\"/app/config.json\")\n\n# Binary\ndata = sbx.files.read(\"/app/image.png\", format=\"bytes\")\nsbx.files.write(\"/app/output.bin\", binary_data)\n\n# Stream large files\nfor chunk in sbx.files.read(\"/app/large.bin\", format=\"stream\"):\n    process(chunk)\n```\n\n### Multiple Files\n```python\nsbx.files.write_files([\n    {\"path\": \"/app/file1.txt\", \"data\": \"content1\"},\n    {\"path\": \"/app/file2.txt\", \"data\": \"content2\"},\n])\n```\n\n### Directory Operations\n```python\n# Check existence\nif sbx.files.exists(\"/app/config.json\"):\n    config = sbx.files.read(\"/app/config.json\")\n\n# List directory\nfor entry in sbx.files.list(\"/app\"):\n    print(f\"{entry.type}: {entry.name} ({entry.size} bytes)\")\n\n# Recursive list\nentries = sbx.files.list(\"/app\", depth=5)\n\n# Get info\ninfo = sbx.files.get_info(\"/app/file.txt\")\nprint(f\"Size: {info.size}, Modified: {info.modified_time}\")\n\n# Create directory\nsbx.files.make_dir(\"/app/data\")\n\n# Delete\nsbx.files.remove(\"/app/old_file.txt\")\n\n# Rename/Move\nsbx.files.rename(\"/app/old.txt\", \"/app/new.txt\")\n```\n\n### Watch for Changes\n```python\nhandle = sbx.files.watch_dir(\"/app\")\nfor event in handle.events():\n    print(f\"{event.type}: {event.name}\")\nhandle.stop()\n```\n\n---\n\n## Volumes (Persistent Storage)\n\n```python\nfrom moru import Sandbox, Volume\n\n# Create volume (idempotent)\nvol = Volume.create(name=\"my-workspace\")\n\n# Attach to sandbox\nsbx = Sandbox.create(\n    volume_id=vol.volume_id,\n    volume_mount_path=\"/workspace\"  # Must be /workspace, /data, /mnt, or /volumes\n)\n\n# Data in /workspace persists after kill\nsbx.commands.run(\"echo ''persistent'' > /workspace/data.txt\")\nsbx.kill()\n\n# Later - data still there\nsbx2 = Sandbox.create(volume_id=vol.volume_id, volume_mount_path=\"/workspace\")\nresult = sbx2.commands.run(\"cat /workspace/data.txt\")\nprint(result.stdout)  # \"persistent\"\n```\n\n### Volume Operations (No Sandbox Needed)\n```python\nvol = Volume.get(\"my-workspace\")\n\n# List files\nfor f in vol.list_files(\"/\"):\n    print(f\"{f.type}: {f.name}\")\n\n# Download/Upload\ncontent = vol.download(\"/data.txt\")\nvol.upload(\"/config.json\", b''{\"key\": \"value\"}'')\n\n# Delete\nvol.delete(\"/old_file.txt\")\n\n# Delete volume (WARNING: permanent)\nvol.delete()\n```\n\n---\n\n## Templates\n\n```python\nfrom moru import Template\nfrom moru.template import wait_for_port\n\n# Define template\ntemplate = (\n    Template()\n    .from_python_image(\"3.11\")\n    .apt_install([\"curl\", \"git\"])\n    .pip_install([\"flask\", \"pandas\", \"requests\"])\n    .copy(\"./app\", \"/app\")\n    .set_workdir(\"/app\")\n    .set_envs({\"FLASK_ENV\": \"production\"})\n    .set_start_cmd(\"python app.py\", wait_for_port(5000))\n)\n\n# Build\ninfo = Template.build(template, alias=\"my-flask-app\")\n\n# Use\nsbx = Sandbox.create(\"my-flask-app\")\n```\n\n### From Dockerfile\n```python\ntemplate = Template().from_dockerfile(\"./Dockerfile\")\nTemplate.build(template, alias=\"my-app\")\n```\n\n### Build Options\n```python\nTemplate.build(\n    template,\n    alias=\"my-app\",\n    cpu_count=4,\n    memory_mb=2048,\n    on_build_logs=lambda entry: print(entry.message),\n)\n\n# Background build\ninfo = Template.build_in_background(template, alias=\"my-app\")\nstatus = Template.get_build_status(info)  # building, success, failed\n```\n\n---\n\n## Async Support\n\n```python\nimport asyncio\nfrom moru import AsyncSandbox\n\nasync def main():\n    async with await AsyncSandbox.create() as sbx:\n        result = await sbx.commands.run(\"echo hello\")\n        print(result.stdout)\n\n        await sbx.files.write(\"/tmp/test.txt\", \"content\")\n        content = await sbx.files.read(\"/tmp/test.txt\")\n\nasyncio.run(main())\n```\n\n---\n\n## Error Handling\n\n```python\nfrom moru import Sandbox\nfrom moru.exceptions import (\n    SandboxException,           # Base\n    TimeoutException,           # Operation timed out\n    NotFoundException,          # Resource not found\n    AuthenticationException,    # Invalid API key\n    NotEnoughSpaceException,    # Disk full\n    CommandExitException,       # Non-zero exit (has exit_code, stdout, stderr)\n)\n\ntry:\n    with Sandbox.create() as sbx:\n        result = sbx.commands.run(\"python3 script.py\", timeout=30)\nexcept TimeoutException:\n    print(\"Command timed out\")\nexcept CommandExitException as e:\n    print(f\"Failed with exit code {e.exit_code}: {e.stderr}\")\nexcept AuthenticationException:\n    print(\"Invalid API key - check MORU_API_KEY\")\n```\n\n---\n\n## Common Pitfalls\n\n### Always cleanup sandboxes\n```python\n# ❌ WRONG\nsbx = Sandbox.create()\nsbx.commands.run(\"echo hello\")\n# Forgot to kill - sandbox keeps running!\n\n# ✅ CORRECT\nwith Sandbox.create() as sbx:\n    sbx.commands.run(\"echo hello\")\n```\n\n### Don''t assume packages exist\n```python\n# ❌ WRONG\nsbx.commands.run(\"python3 -c ''import pandas''\")  # ImportError!\n\n# ✅ CORRECT\nsbx.commands.run(\"pip install pandas\", timeout=120)\nsbx.commands.run(\"python3 -c ''import pandas''\")\n```\n\n### Write to volume path for persistence\n```python\n# ❌ WRONG - lost on kill\nsbx.files.write(\"/home/user/data.txt\", \"important\")\n\n# ✅ CORRECT - persisted\nsbx.files.write(\"/workspace/data.txt\", \"important\")\n```\n\n### Handle command failures\n```python\nresult = sbx.commands.run(\"python3 script.py\")\nif result.exit_code != 0:\n    print(f\"Error: {result.stderr}\")\n```\n"},"lastSynced":"2026-03-08T02:03:25.888Z","agentAnalysis":{"suitability":{"en":"Perfect for Python-based AI Agents needing advanced sandbox management and command execution capabilities.","zh":"适合需要高级沙盒管理和命令执行功能的基于Python的AI代理。","ja":"PythonベースのAIエージェントが高度なサンドボックス管理とコマンド実行機能を必要とする場合に最適です。","ko":"고급 샌드박스 관리 및 명령어 실행 기능이 필요한 파이썬 기반 AI 에이전트에 적합합니다.","es":"Perfecto para Agentes de IA basados en Python que necesitan capacidades de gestión de sandbox avanzadas y ejecución de comandos.","fr":"Parfait pour les agents d''IA basés sur Python nécessitant une gestion de sandbox avancée et des capacités d''exécution de commandes.","de":"Perfekt für Python-basierte KI-Agents, die erweiterte Sandbox-Verwaltungs- und Befehlsausführungsfunktionen benötigen.","pt":"Perfeito para Agentes de IA baseados em Python que necessitam de gerenciamento avançado de sandbox e capacidades de execução de comandos.","ru":"Идеально для агентов ИИ на основе Python, которым необходимы продвинутые возможности управления sandbox и выполнения команд.","ar":"مثالي للوكلاء الذكيين القائمين على Python الذين يحتاجون إلى إدارة محاكاة متقدمة وتنفيذ أوامر متقدم"},"recommendation":{"en":"Empowers agents to create and manage sandboxes, run commands, and interact with files using the moru-python SDK, supporting Python 3 and providing features like automatic sandbox killing.","zh":"赋予代理创建和管理沙盒、运行命令以及使用moru-python SDK与文件交互的能力，支持Python 3，并提供自动沙盒终止等功能。","ja":"エージェントにサンドボックスの作成と管理、コマンドの実行、およびmoru-python SDKを使用したファイルとのやり取りを可能にし、Python 3をサポートし、自動サンドボックス終了などの機能を提供します。","ko":"에이전트가 샌드박스를 생성하고 관리하고, 명령어를 실행하고, moru-python SDK를 사용하여 파일과 상호 작용할 수 있는 기능을 제공하며, 파이썬 3을 지원하며, 자동 샌드박스 종료 등의 기능을 제공합니다.","es":"Habilita a los agentes a crear y gestionar sandboxes, ejecutar comandos e interactuar con archivos utilizando el SDK moru-python, que admite Python 3 y ofrece características como la matanza automática de sandbox.","fr":"Permet aux agents de créer et de gérer des sandboxes, d''exécuter des commandes et d''interagir avec des fichiers à l''aide du SDK moru-python, qui prend en charge Python 3 et offre des fonctionnalités comme la suppression automatique de sandbox.","de":"Ermöglicht es Agents, Sandboxes zu erstellen und zu verwalten, Befehle auszuführen und mit Dateien zu interagieren, indem sie das moru-python-SDK verwenden, das Python 3 unterstützt und Funktionen wie automatisches Sandbox-Beenden bietet.","pt":"Habilita os agentes a criar e gerenciar sandboxes, executar comandos e interagir com arquivos usando o SDK moru-python, suportando Python 3 e fornecendo recursos como matança automática de sandbox.","ru":"Наделяет агентов возможностью создавать и управлять sandbox, запускать команды и взаимодействовать с файлами с помощью SDK moru-python, поддерживающего Python 3 и обеспечивающего функции, такие как автоматическое убийство sandbox.","ar":"يمنح الوكلاء القدرة على إنشاء وإدارة محاكاة وتنفيذ أوامر والتفاعل مع الملفات باستخدام SDK moru-python ، والذي يدعم Python 3 ويوفر ميزات مثل القتل التلقائي للمحاكاة"},"useCases":{"en":["Automating command execution in isolated environments","Generating and managing sandboxed file systems","Debugging Python scripts in secure sandboxes"],"zh":["在隔离环境中自动执行命令","生成和管理沙盒文件系统","在安全沙盒中调试Python脚本"],"ja":["隔離された環境でコマンドを自動実行する","サンドボックス化されたファイルシステムを生成および管理する","セキュアなサンドボックスでPythonスクリプトをデバッグする"],"ko":["격리된 환경에서 명령어를 자동으로 실행하는 것","샌드박스화된 파일 시스템을 생성하고 관리하는 것","보안 샌드박스에서 파이썬 스크립트를 디버깅하는 것"],"es":["Automatización de la ejecución de comandos en entornos aislados","Generación y gestión de sistemas de archivos sandboxeados","Depuración de scripts de Python en sandboxes seguras"],"fr":["Automatisation de l''exécution de commandes dans des environnements isolés","Génération et gestion de systèmes de fichiers sandboxés","Débogage de scripts Python dans des sandboxes sécurisées"],"de":["Automatisierung der Befehlsausführung in isolierten Umgebungen","Erzeugung und Verwaltung von sandbox-basierten Dateisystemen","Fehlersuche in Python-Skripten in sicheren Sandboxes"],"pt":["Automatizar a execução de comandos em ambientes isolados","Gerar e gerenciar sistemas de arquivos em sandbox","Depurar scripts Python em sandboxes seguras"],"ru":["Автоматизация выполнения команд в изолированных средах","Генерация и управление файловыми системами в sandbox","Отладка скриптов Python в безопасных sandbox"],"ar":["تأتمتة تشغيل الأوامر في بيئات معزولة","إنشاء وإدارة أنظمة الملفات في محاكاة","تصحيح أخطاء البرامج النصية Python في محاكاة آمنة"]},"limitations":{"en":["Requires Python 3 installation","Sandbox auto-killing after use"],"zh":["需要Python 3安装","使用后自动终止沙盒"],"ja":["Python 3のインストールが必要","使用後自動的にサンドボックスを終了する"],"ko":["파이썬 3 설치가 필요함","사용 후 자동으로 샌드박스를 종료함"],"es":["Requiere instalación de Python 3","Sandbox auto-matanza después de uso"],"fr":["Nécessite une installation de Python 3","Suppression automatique du sandbox après utilisation"],"de":["Benötigt Python 3-Installation","Sandbox-Auto-Beenden nach Verwendung"],"pt":["Requer instalação do Python 3","Morte automática do sandbox após uso"],"ru":["Требует установку Python 3","Автоматическое убийство sandbox после использования"],"ar":["يتطلب تثبيت Python 3","القتل التلقائي للمحاكاة بعد الاستخدام"]},"version":4},"contentHash":"444051efa79ead5fe6c01305a54e740413ee1a5ba5a2896cf930671d39651270","qualityScore":42}');
