INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('1wos/sdkhackthon/moru-python', 'moru-python', '1wos', 'sdkhackthon', 'community', 'moru-python 1wos sdkhackthon community The moru-python skill provides a Python SDK for creating and managing sandboxes, allowing developers to run commands and interact with files. It benefits AI agent developers and users. Moru Python SDK 提供了便捷的沙盒创建、命令运行和文件读写功能 Moru Python SDK はサンドボックスの作成、コマンドの実行、ファイルの読み書きを容易に行えるようにします Moru Python SDK는 샌드박스 생성, 명령 실행 및 파일 읽기/쓰기 기능을 제공합니다 Moru-python es un SDK de Python que permite a los desarrolladores crear sandbox y ejecutar comandos de manera segura y eficiente Moru-python est un SDK Python qui permet aux développeurs de créer des sandbox et d''exécuter des commandes de manière sécurisée et efficace Moru-python ist ein Python-SDK, das es Entwicklern ermöglicht, Sandbox zu erstellen und Befehle sicher und effizient auszuführen O Moru Python SDK é uma ferramenta para criar sandboxes e executar comandos Python. Instale com pip e comece a usar. Moru Python SDK - это инструмент для создания песочниц и выполнения команд Python. Установите с помощью pip и начните использовать - ИИ Агенты Moru Python SDK هي أداة لإنشاء sandboxes وتنفيذ أوامر Python. ثبّت مع pip وابدأ في الاستخدام - أدوات الذكاء الاصطناعي how to use moru-python moru-python alternative moru-python install what is moru-python moru-python vs docker moru-python setup guide moru-python python sdk moru-python sandbox creation Moru Python SDK Python 库 沙盒创建 命令运行 文件读写 自动沙盒销毁 模板支持 AI开发 Python开发 Creates sandboxes using the `Sandbox.create()` command Runs commands within the sandbox using `sbx.commands.run()` Supports file writing and reading using `sbx.files.write()` and `sbx.files.r` Automatically kills the sandbox after use Installs via pip using `pip install moru` moru-python is a Python SDK for creating and managing sandboxes, providing a simple way to run commands and interact with files.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('toilahuongg/Shopify-Agents-Kit/shopify-metafields', 'community', 'toilahuongg', 'Shopify-Agents-Kit', 'toilahuongg/Shopify-Agents-Kit', 'shopify-metafields', 0, 0, 42, '2026-03-08T01:57:15.345Z', '2026-03-08T02:03:33.719Z', '441022fbededbed02ceebc72f92efc2d15ad1ca2f6484d16fa8256fb2269dfcd', '{"id":"toilahuongg/Shopify-Agents-Kit/shopify-metafields","name":"shopify-metafields","description":{"en":"Shopify-metafields allows developers to store additional data on Shopify resources, enhancing customization and flexibility for e-commerce applications. It benefits developers and businesses seeking to extend Shopify''s default schema.","zh":"Shopify Metafields 允许您在 Shopify 资源上存储额外的数据，包括产品、订单、客户和店铺，通过命名空间、键、类型和所有者实现灵活的数据管理","ja":"Shopify Metafields を使用すると、Shopify リソース（製品、注文、顧客、ショップ）に追加のデータを保存できます。ネームスペース、キー、タイプ、オーナーを使用して柔軟なデータ管理を実現","ko":"Shopify Metafields를 사용하면 Shopify 리소스(제품, 주문, 고객, 상점)에 추가 데이터를 저장할 수 있습니다. 네임스페이스, 키, 유형, 소유자를 사용하여 유연한 데이터 관리를 구현","es":"Los metafields de Shopify permiten almacenar datos adicionales en recursos como productos y clientes. Conoce cómo configurar y utilizar esta función.","fr":"Les metafields Shopify permettent de stocker des données supplémentaires sur les ressources telles que les produits et les clients. Découvrez comment les configurer et les utiliser.","de":"Die Metafields von Shopify ermöglichen die Speicherung von zusätzlichen Daten auf Ressourcen wie Produkten und Kunden. Erfahren Sie, wie Sie diese Funktion einrichten und nutzen.","pt":"Os metafields do Shopify permitem armazenar dados adicionais em recursos como produtos e pedidos","ru":"Метаполя Shopify позволяют хранить дополнительные данные о продуктах, заказах и клиентах","ar":"تتيح الحقول المتخصصة في شوبيفاي تخزين بيانات إضافية حول المنتجات والطلبات"},"seo":{"title":{"en":"Shopify-Metafields: Mastering Custom Data Storage | AI Ag...","zh":"Shopify Metafields Setup Guide - AIエージェント","ja":"Shopify Metafields ベストプラクティス - AIエージェント","ko":"Shopify Metafields 사용자 가이드 - AI 툴","es":"Configuración de Metafields de Shopify: Guía Completa","fr":"Mise en place des Metafields Shopify: Meilleures Pratiques","de":"Shopify Metafields Einrichten: Anleitung und Tipps","pt":"Guia de Configuração de Metafields do Shopify","ru":"ИИ Агенты для Shopify Metafields: Настройка и Применение","ar":"إعداد وحفظ الحقول المتخصصة في شوبيفاي"},"description":{"en":"Unlock the full potential of Shopify with metafields! Learn how to store custom data on products, orders, and customers. Get started with our expert guide an...","zh":"了解 Shopify Metafields 的概念和技术细节，包括命名空间、键、类型和所有者，实现高效的数据存储和管理","ja":"Shopify Metafields の概念と技術的詳細を理解し、ネームスペース、キー、タイプ、オーナーを使用して効率的なデータストレージと管理を実現","ko":"Shopify Metafields의 개념과 기술적 세부 사항을 이해하여 네임스페이스, 키, 유형, 소유자를 사용하여 효율적인 데이터 저장 및 관리를 구현","es":"Aprende a utilizar metafields en Shopify para almacenar datos adicionales en recursos como productos, pedidos y clientes. Herramientas de AI como Agentes de IA","fr":"Découvrez comment utiliser les metafields Shopify pour stocker des données supplémentaires sur les ressources telles que les produits, les commandes et les c...","de":"Erfahren Sie, wie Sie Metafields in Shopify verwenden, um zusätzliche Daten auf Ressourcen wie Produkten, Bestellungen und Kunden zu speichern. AI-Tools wie ...","pt":"Aprenda a usar metafields do Shopify para armazenar dados adicionais em recursos como produtos e pedidos","ru":"Используйте метаполя Shopify для хранения дополнительных данных о продуктах, заказах и клиентах","ar":"تعلم كيفية استخدام الحقول المتخصصة في شوبيفاي لتخزين بيانات إضافية حول المنتجات والطلبات"},"definition":{"en":"Shopify-metafields is a feature enabling the storage of custom data on Shopify resources, such as products, orders, and customers, using namespaces, keys, and data types.","zh":"Shopify Metafields 是一种允许您在 Shopify 资源上存储额外数据的功能，通过命名空间、键、类型和所有者实现数据管理","ja":"Shopify Metafields は、Shopify リソースに追加のデータを保存できる機能で、ネームスペース、キー、タイプ、オーナーを使用してデータ管理を実現","ko":"Shopify Metafields는 Shopify 리소스에 추가 데이터를 저장할 수 있는 기능으로 네임스페이스, 키, 유형, 소유자를 사용하여 데이터 관리를 구현","es":"Metafields de Shopify: campos personalizados para almacenar datos adicionales en recursos como productos y clientes","fr":"Metafields Shopify: champs personnalisés pour stocker des données supplémentaires sur les ressources telles que les produits et les clients","de":"Metafields von Shopify: benutzerdefinierte Felder zur Speicherung von zusätzlichen Daten auf Ressourcen wie Produkten und Kunden","pt":"Metafields são campos personalizados que armazenam dados adicionais em recursos do Shopify","ru":"Метаполя - это пользовательские поля, которые хранят дополнительные данные о ресурсах Shopify","ar":"الحقول المتخصصة هي حقول مخصصة لتخزين بيانات إضافية حول الموارد في شوبيفاي"},"features":{"en":["Utilizes namespaces for organized data storage","Supports various data types, including single_line_text_field and json","Enables custom data attachment to products, orders, and customers","Allows for specific field naming using keys","Stores data on Shopify resources, extending the default schema"],"zh":["支持命名空间（Namespace）","支持键（Key）和类型（Type）","支持所有者（Owner）","可存储单行文本、数字和 JSON 数据","可用于产品、订单、客户和店铺资源"],"ja":["ネームスペース（Namespace）をサポート","キー（Key）とタイプ（Type）をサポート","オーナー（Owner）をサポート","単行テキスト、数字、JSON データを保存可能","製品、注文、顧客、ショップ リソースで使用可能"],"ko":["네임스페이스(Namespace) 지원","키(Key)와 유형(Type) 지원","소유자(Owner) 지원","单行 텍스트, 숫자, JSON 데이터 저장 가능","제품, 주문, 고객, 상점 리소스에서 사용 가능"],"es":["Almacenamiento de datos adicionales en recursos como productos y clientes","Uso de espacios de nombres para organizar los metafields","Tipos de datos personalizados como texto, número y JSON","Asignación de propietarios a los metafields para controlar el acceso"],"fr":["Stockage de données supplémentaires sur les ressources telles que les produits et les clients","Utilisation d''espaces de noms pour organiser les metafields","Types de données personnalisés tels que texte, nombre et JSON","Affectation de propriétaires aux metafields pour contrôler l''accès"],"de":["Speicherung von zusätzlichen Daten auf Ressourcen wie Produkten und Kunden","Verwendung von Namensräumen zur Organisation der Metafields","Benutzerdefinierte Datentypen wie Text, Zahl und JSON","Zuweisung von Besitzern zu den Metafields zur Zugriffssteuerung"],"pt":["Namespace para organizar os metafields","Chaves específicas para cada metafield","Tipos de dados variados (single_line_text_field, number_integer, json)","Proprietário do recurso que anexa os dados","Armazenamento de dados adicionais em produtos e pedidos","Integração com recursos do Shopify"],"ru":["Пространство имен для организации метаполей","Конкретные ключи для каждого метаполя","Различные типы данных (single_line_text_field, number_integer, json)","Владелец ресурса, который присоединяет данные","Хранение дополнительных данных о продуктах и заказах","Интеграция с ресурсами Shopify"],"ar":["مساحة اسم لتنظيم الحقول المتخصصة","مفاتيح محددة لكل حقل متخصص","أنواع بيانات متعددة (single_line_text_field, number_integer, json)","مالك الموارد الذي يرفق البيانات","تخزين بيانات إضافية حول المنتجات والطلبات","التكامل مع موارد شوبيفاي"]},"keywords":{"en":["how to use shopify-metafields","shopify-metafields setup guide","what is shopify-metafields","shopify-metafields vs custom attributes","shopify-metafields install","shopify-metafields namespace examples","shopify-metafields data types","shopify-metafields api documentation"],"zh":["Shopify Metafields","AIエージェント","数据存储","命名空间","键","类型","所有者","Shopify 资源"],"ja":["Shopify Metafields","AIエージェント","データストレージ","ネームスペース","キー","タイプ","オーナー","Shopify リソース"],"ko":["Shopify Metafields","AI 툴","데이터 저장","네임스페이스","키","유형","소유자","Shopify 리소스"],"es":["metafields shopify","configuración de metafields","almacenamiento de datos en shopify","espacios de nombres en shopify","tipos de datos personalizados en shopify","agentes de ia para shopify","herramientas de ia para comercio electrónico"],"fr":["metafields shopify","configuration des metafields","stockage de données sur shopify","espaces de noms sur shopify","types de données personnalisés sur shopify","outils d''ia pour shopify","outils de commerce électronique avec ia"],"de":["metafields shopify","einrichtung von metafields","speicherung von daten in shopify","namensräume in shopify","benutzerdefinierte datentypen in shopify","ki-agenten für shopify","ei-tools für elektronischen handel"],"pt":["metafields shopify","configurar metafields","armazenar dados adicionais","recursos shopify","campos personalizados","namespace metafields","chaves metafields","tipos de dados metafields","proprietário do recurso"],"ru":["метаполя shopify","настройка метаполей","хранение дополнительных данных","ресурсы shopify","пользовательские поля","пространство имен метаполей","ключи метаполей","типы данных метаполей","владелец ресурса"],"ar":["حقول متخصصة شوبيفاي","إعداد الحقول المتخصصة","تخزين بيانات إضافية","موارد شوبيفاي","حقول مخصصة","مساحة اسم الحقول المتخصصة","مفاتيح الحقول المتخصصة","أنواع بيانات الحقول المتخصصة","مالك الموارد"]}},"owner":"toilahuongg","repo":"Shopify-Agents-Kit","repoPath":"toilahuongg/Shopify-Agents-Kit","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.345Z","topics":[],"category":"community","skillMd":{"name":"shopify-metafields","description":"Guide for working with Shopify Metafields. Covers definitions, storing custom data, accessing via Liquid, and GraphQL mutations.","bodyPreview":"# Shopify Metafields\n\nMetafields allow you to store additional data on Shopify resources (Products, Orders, Customers, Shops) that aren''t included in the default schema (e.g., \"washing instructions\" for a product).\n\n## 1. Concepts\n\n-   **Namespace**: Grouping folder (e.g., `my_app`, `global`).\n-   **Key**: Specific field name (e.g., `washing_instructions`).\n-   **Type**: Data type (e.g., `single_line_text_field`, `number_integer`, `json`).\n-   **Owner**: The resource attaching the data (Product","body":"# Shopify Metafields\n\nMetafields allow you to store additional data on Shopify resources (Products, Orders, Customers, Shops) that aren''t included in the default schema (e.g., \"washing instructions\" for a product).\n\n## 1. Concepts\n\n-   **Namespace**: Grouping folder (e.g., `my_app`, `global`).\n-   **Key**: Specific field name (e.g., `washing_instructions`).\n-   **Type**: Data type (e.g., `single_line_text_field`, `number_integer`, `json`).\n-   **Owner**: The resource attaching the data (Product ID, Shop ID).\n\n## 2. Metafield Definitions (Standard)\n\nAlways use **Metafield Definitions** (pinned metafields) when possible. This integrates them into the Admin UI and ensures standard processing.\n\n-   **Create**: Settings > Custom Data > [Resource] > Add definition.\n-   **Access**: `namespace.key`\n\n## 3. Accessing in Liquid\n\nTo display metafield data on the Storefront:\n\n```liquid\n<!-- Accessing a product metafield -->\n<p>Washing: {{ product.metafields.my_app.washing_instructions }}</p>\n\n<!-- Accessing a file/image metafield -->\n{% assign file = product.metafields.my_app.size_chart.value %}\n<img src=\"{{ file | image_url: width: 500 }}\" />\n\n<!-- Checking existence -->\n{% if product.metafields.my_app.instructions != blank %}\n   ...\n{% endif %}\n```\n\n## 4. Reading via API (GraphQL)\n\n```graphql\nquery {\n  product(id: \"gid://shopify/Product/123\") {\n    title\n    metafield(namespace: \"my_app\", key: \"instructions\") {\n      value\n      type\n    }\n  }\n}\n```\n\n## 5. Writing via API (GraphQL)\n\nTo create or update a metafield, use `metafieldsSet`.\n\n```graphql\nmutation metafieldsSet($metafields: [MetafieldsSetInput!]!) {\n  metafieldsSet(metafields: $metafields) {\n    metafields {\n      id\n      namespace\n      key\n      value\n    }\n    userErrors {\n      field\n      message\n    }\n  }\n}\n\n/* Variables */\n{\n  \"metafields\": [\n    {\n      \"ownerId\": \"gid://shopify/Product/123\",\n      \"namespace\": \"my_app\",\n      \"key\": \"instructions\",\n      \"type\": \"single_line_text_field\",\n      \"value\": \"Wash cold, tumble dry.\"\n    }\n  ]\n}\n```\n\n## 6. Private Metafields\n\nIf you want data to be **hidden from other apps** and the storefront, use Private Metafields. Note: These cannot be accessed via Liquid directly.\n\n-   Use `privateMetafield` queries/mutations.\n-   Requires explicit `read_private_metafields` / `write_private_metafields` scope (rarely used now, `app_data` metafields are preferred for app-specific valid storage).\n"},"lastSynced":"2026-03-08T02:03:33.719Z","agentAnalysis":{"suitability":{"en":"Perfect for E-commerce Agents needing advanced Shopify customization and data extension capabilities.","zh":"非常适合需要高级 Shopify 定制和数据扩展功能的电子商务 Agent。","ja":"高度なShopifyカスタマイズとデータ拡張機能を必要とするEコマースAgentに最適です。","ko":"고급 Shopify 사용자 지정 및 데이터 확장 기능이 필요한 전자상거래 Agent에 완벽합니다.","es":"Perfecto para agentes de comercio electrónico que necesitan personalización avanzada de Shopify y capacidades de extensión de datos.","fr":"Parfait pour les agents de commerce électronique ayant besoin d''une personnalisation avancée de Shopify et de capacités d''extension de données.","de":"Perfekt für E-Commerce-Agents, die eine erweiterte Anpassung von Shopify und Daten-Erweiterungsfunktionen benötigen.","pt":"Perfeito para agentes de comércio eletrônico que precisam de personalização avançada do Shopify e capacidades de extensão de dados.","ru":"Идеально подходит для агентов электронной коммерции, которым требуются продвинутые возможности настройки Shopify и расширения данных.","ar":"مثالي لعمال التاجر الإلكتروني الذين يحتاجون إلى تخصيص متقدم لشركة Shopify وقدرات تمديد البيانات."},"recommendation":{"en":"Empowers agents to store and manage additional data on Shopify resources using metafields, enhancing flexibility with namespace, key, and type specifications, and supporting data types like single_line_text_field, number_integer, and json.","zh":"使 Agent 能够使用 metafield 在 Shopify 资源上存储和管理额外数据，通过 namespace、key 和 type 规范增强灵活性，并支持 single_line_text_field、number_integer 和 json 等数据类型。","ja":"Agentがmetafieldを使用してShopifyリソース上で追加データを保存および管理できるようにし、namespace、key、typeの指定による柔軟性を高め、single_line_text_field、number_integer、jsonなどのデータ型をサポートします。","ko":"Agent가 metafield를 사용하여 Shopify 리소스에 추가 데이터를 저장하고 관리할 수 있도록 하여, 네임스페이스, 키 및 유형 사양으로 유연성을 향상시키고 single_line_text_field, number_integer, json과 같은 데이터 유형을 지원합니다.","es":"Habilita a los agentes a almacenar y gestionar datos adicionales en recursos de Shopify utilizando metafields, mejorando la flexibilidad con especificaciones de namespace, clave y tipo, y compatibilidad con tipos de datos como single_line_text_field, number_integer y json.","fr":"Permet aux agents de stocker et de gérer des données supplémentaires sur les ressources Shopify en utilisant des metafields, améliorant la flexibilité avec des spécifications de namespace, de clé et de type, et prenant en charge des types de données tels que single_line_text_field, number_integer et json.","de":"Ermächtigt Agenten, zusätzliche Daten auf Shopify-Ressourcen mithilfe von Metafields zu speichern und zu verwalten, wodurch die Flexibilität mit Namespace-, Schlüssel- und Typspezifikationen verbessert wird und Datenarten wie single_line_text_field, number_integer und json unterstützt werden.","pt":"Habilita os agentes a armazenar e gerenciar dados adicionais em recursos do Shopify usando metafields, melhorando a flexibilidade com especificações de namespace, chave e tipo, e suportando tipos de dados como single_line_text_field, number_integer e json.","ru":"Наделяет агентов возможностью хранить и управлять дополнительными данными в ресурсах Shopify с помощью metafields, повышая гибкость с помощью спецификаций namespace, ключа и типа, и поддерживая типы данных, такие как single_line_text_field, number_integer и json.","ar":"يمنح الوكلاء القدرة على تخزين وإدارة بيانات إضافية في موارد Shopify باستخدام metafields، مما يعزز المرونة مع مواصفات namespace ومفتاح ونوع، ودعم أنواع البيانات مثل single_line_text_field و number_integer و json."},"useCases":{"en":["Extending product information with custom metafields","Automating order processing using metafield data","Generating customer profiles with enhanced metafield attributes"],"zh":["使用自定义 metafield 扩展产品信息","利用 metafield 数据自动化订单处理","使用增强的 metafield 属性生成客户档案"],"ja":["カスタムmetafieldを使用した商品情報の拡張","metafieldデータを使用した注文処理の自動化","拡張されたmetafield属性による顧客プロファイルの生成"],"ko":["사용자 지정 metafield로 제품 정보 확장","metafield 데이터를 사용한 주문 처리 자동화","향상된 metafield 속성으로 고객 프로필 생성"],"es":["Extender la información del producto con metafields personalizados","Automatizar el procesamiento de pedidos con datos de metafields","Generar perfiles de clientes con atributos de metafields mejorados"],"fr":["Étendre les informations sur les produits avec des metafields personnalisés","Automatiser le traitement des commandes à l''aide de données de metafields","Générer des profils de clients avec des attributs de metafields améliorés"],"de":["Erweitern der Produktinformationen mit benutzerdefinierten Metafields","Automatisieren der Auftragsverarbeitung mithilfe von Metafield-Daten","Generieren von Kundenprofilen mit erweiterten Metafield-Attributen"],"pt":["Estender informações de produtos com metafields personalizados","Automatizar o processamento de pedidos usando dados de metafield","Gerar perfis de clientes com atributos de metafield aprimorados"],"ru":["Расширение информации о продуктах с помощью пользовательских metafields","Автоматизация обработки заказов с помощью данных metafield","Генерация профилей клиентов с улучшенными атрибутами metafield"],"ar":["توسيع معلومات المنتج مع metafields مخصصة","التحكم الآلي في معالجة الطلبات باستخدام بيانات metafield","генерация ملفات تعريف العملاء مع سمات metafield المحسنة"]},"limitations":{"en":["Requires Shopify API access","Limited to Shopify resources (Products, Orders, Customers, Shops)","Dependent on metafield namespace and key uniqueness"],"zh":["需要 Shopify API 访问权限","仅限于 Shopify 资源（产品、订单、客户、商店）","依赖于 metafield namespace 和 key 的唯一性"],"ja":["Shopify APIへのアクセスが必要","Shopifyリソース（商品、注文、顧客、ショップ）に限定される","metafieldのnamespaceとkeyの一意性に依存"],"ko":["Shopify API 액세스 필요","Shopify 리소스(제품, 주문, 고객, 상점)로 제한됨","metafield 네임스페이스 및 키 고유성에 의존"],"es":["Requiere acceso a la API de Shopify","Limitado a recursos de Shopify (Productos, Pedidos, Clientes, Tiendas)","Dependiente de la unicidad del namespace y la clave de metafields"],"fr":["Nécessite un accès à l''API Shopify","Limité aux ressources Shopify (Produits, Commandes, Clients, Magasins)","Dépend de l''unicité du namespace et de la clé des metafields"],"de":["Benötigt Zugriff auf die Shopify-API","Begrenzt auf Shopify-Ressourcen (Produkte, Bestellungen, Kunden, Geschäfte)","Abhängig von der Eindeutigkeit des Metafield-Namespace und -Schlüssels"],"pt":["Exige acesso à API do Shopify","Limitado a recursos do Shopify (Produtos, Pedidos, Clientes, Lojas)","Dependente da singularidade do namespace e da chave do metafield"],"ru":["Требует доступа к API Shopify","Ограничен ресурсами Shopify (продукты, заказы, клиенты, магазины)","Зависит от уникальности namespace и ключа metafield"],"ar":["يتطلب الوصول إلى واجهة برمجة تطبيقات Shopify","محدود بموارد Shopify (المنتجات، الطلبات، العملاء، المحلات)","يعتمد على الفردية من namespace ومفتاح metafield"]},"version":4},"contentHash":"441022fbededbed02ceebc72f92efc2d15ad1ca2f6484d16fa8256fb2269dfcd","qualityScore":42}');
