INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('StirlingMarketingGroup/marlin/creating-github-issues', 'creating-github-issues', 'StirlingMarketingGroup', 'marlin', 'community', 'creating-github-issues StirlingMarketingGroup marlin community The creating-github-issues skill helps developers create well-documented GitHub issues with enough context for implementation, using Explore agent or search tools for research 创建GitHub问题时，需要研究代码库和提供清晰的文档。这确保问题得到有效解决 GitHubイシューを作成する際には、コードベースの調査と明確なドキュメントの提供が重要です。問題の解決を効率化しましょう - AIエージェント 깃허브 이슈를 생성할 때 코드베이스를 연구하고 명확한 문서를 제공하는 것이 중요합니다. 이를 통해 문제를 효율적으로 해결할 수 있습니다 Esta habilidad garantiza que las incidencias de GitHub contengan suficiente contexto para que cualquier persona las comprenda e implemente. Se utiliza Tauri y React para la creación de la interfaz Cette compétence garantit que les problèmes GitHub contiennent suffisamment de contexte pour que toute personne les comprenne et les mette en œuvre. Tauri et React sont utilisés pour la création de l''interface Diese Fähigkeit stellt sicher, dass GitHub-Probleme genügend Kontext enthalten, damit jede Person sie verstehen und umsetzen kann. Tauri und React werden für die Erstellung der Schnittstelle verwendet O skill de criar issues no GitHub é uma ferramenta moderna e eficaz para criar issues claras e bem documentadas, utilizando Tauri e React ИИ Агенты для создания issues на GitHub - современный и эффективный инструмент для создания ясных и хорошо документированных issues с помощью Tauri и React عوامل ذكية لإنشاء قضايا على GitHub - أداة حديثة وفعالة لإنشاء قضايا واضحة ومدونة بشكل جيد مع Tauri و React how to create github issues creating-github-issues setup guide github issue best practices creating-github-issues alternative creating-github-issues vs jira github issue template creating-github-issues install what is creating-github-issues creating-github-issues tutorial 创建GitHub问题 代码库研究 清晰文档 Explore agent 搜索工具 数据库表 API端点 UI组件 Researches codebase using Explore agent or search tools Identifies relevant code locations, including file paths and functions Analyzes similar functionality implementation Examines database tables, API endpoints, and UI components Ensures issues contain enough context for easy implementation creating-github-issues is a skill that ensures GitHub issues are well-researched and clearly documented for easy understanding and implementation');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('olegakbarov/ispo-code/tanstack-db', 'community', 'olegakbarov', 'ispo-code', 'olegakbarov/ispo-code', 'tanstack-db', 0, 0, 42, '2026-03-08T01:57:15.349Z', '2026-03-08T02:03:44.915Z', '051a29660b70e0725850ebb970a1bbdcef2596d195a92d8ceb1111266d5a7849', '{"id":"olegakbarov/ispo-code/tanstack-db","name":"tanstack-db","description":{"en":"tanstack-db is a reactive client store for building local-first apps with sub-millisecond queries and optimistic mutations. It benefits developers building real-time applications.","zh":"TanStack DB是一个reactive客户端存储，用于构建本地优先应用。它提供了亚毫秒查询、乐观式变更和实时同步等功能","ja":"TanStack DBは、ローカルファーストアプリを構築するためのリアクティブクライアントストアです。サブミリ秒クエリ、楽観的ミューテーション、リアルタイム同期などの機能を提供します","ko":"TanStack DB는 반응형 클라이언트 저장소로서 본地 우선 애플리케이션을 구축하기 위한 것입니다. 반응형 클라이언트 저장소는 亚毫秒 쿼리, 낙관적 변환 및 실시간 동기화를 제공합니다","es":"TanStack DB es una tienda de clientes reactiva para aplicaciones locales con consultas en milisegundos y sincronización en tiempo real. Ofrece colecciones tipadas y consultas en vivo","fr":"TanStack DB est un magasin de clients réactif pour les applications locales avec des requêtes en millisecondes et une synchronisation en temps réel. Il propose des collections typées et des requêtes en direct","de":"TanStack DB ist ein reaktiver Client-Speicher für lokale Anwendungen mit Abfragen in Millisekunden und Echtzeit-Synchronisation. Es bietet typisierte Sammlungen und Live-Abfragen","pt":"O TanStack DB é uma loja de cliente reativa para criar aplicativos locais com consultas em milissegundos, mutações otimistas e sincronização em tempo real","ru":"TanStack DB - это реактивное хранилище клиента для создания локальных приложений с запросами за миллисегунды, оптимистическими мутациями и синхронизацией в реальном времени","ar":"TanStack DB هو مخزن عميل تفاعلي لإنشاء تطبيقات محلية مع استفسارات في مللي ثانية، وتعديلات متفائلة، وتنسيق في الوقت الفعلي"},"seo":{"title":{"en":"tanstack-db: Reactive Client Store Setup Guide | AI Agent...","zh":"TanStack DB 入门指南 - 了解reactive客户端存储","ja":"TanStack DB 導入ガイド - ローカルファーストアプリのためのリアクティブクライアントストア","ko":"TanStack DB 시작하기 - 반응형 클라이언트 저장소","es":"Guía de configuración de TanStack DB para aplicaciones lo...","fr":"Guide de mise en place de TanStack DB pour les applicatio...","de":"Einrichtungsleitfaden für TanStack DB für lokale Anwendungen","pt":"TanStack DB: Guia de Configuração para Aplicativos em Tem...","ru":"ИИ Агент TanStack DB: Руководство по Настройке для Реальн...","ar":"TanStack DB: دليل الإعداد لتطبيقات الزمن الفعلي"},"description":{"en":"Unlock sub-millisecond queries with tanstack-db. Learn how to build local-first apps with optimistic mutations and real-time sync. Get started now!","zh":"了解TanStack DB的核心概念，包括集合、实时查询和乐观式变更。使用TanStack DB构建具有亚毫秒查询和实时同步的本地优先应用","ja":"TanStack DBのコアコンセプト、コレクション、ライブクエリ、楽観的ミューテーションを学ぶ。サブミリ秒クエリとリアルタイム同期を備えたローカルファーストアプリを構築する","ko":"TanStack DB의 핵심 개념을 알아보세요. 컬렉션, 라이브 쿼리, 낙관적 변화를 포함하여 반응형 클라이언트 저장소로 본地 우선 애플리케이션을 구축합니다.","es":"Aprende a utilizar TanStack DB, una tienda de clientes reactiva para aplicaciones locales con consultas en milisegundos y sincronización en tiempo real","fr":"Découvrez comment utiliser TanStack DB, un magasin de clients réactif pour les applications locales avec des requêtes en millisecondes et une synchronisation...","de":"Erfahren Sie, wie Sie TanStack DB verwenden, einen reaktiven Client-Speicher für lokale Anwendungen mit Abfragen in Millisekunden und Echtzeit-Synchronisation","pt":"Aprenda a configurar o TanStack DB para criar aplicativos locais com consultas em milissegundos, mutações otimistas e sincronização em tempo real","ru":"Узнайте, как настроить TanStack DB для создания локальных приложений с запросами за миллисекунды, оптимистическими мутациями и синхронизацией в реальном времени","ar":"تعلم كيفية تكوين TanStack DB لإنشاء تطبيقات محلية مع استفسارات في مللي ثانية، وتعديلات متفائلة، وتنسيق في الوقت الفعلي"},"definition":{"en":"tanstack-db is a reactive client store for building local-first apps with features like typed collections and live queries.","zh":"TanStack DB是一种reactive客户端存储，用于构建本地优先应用，提供亚毫秒查询和实时同步","ja":"TanStack DBは、ローカルファーストアプリを構築するためのリアクティブクライアントストアであり、サブミリ秒クエリとリアルタイム同期を提供する","ko":"TanStack DB는 반응형 클라이언트 저장소로서 본地 우선 애플리케이션을 구축하기 위한 것입니다. 亚毫秒 쿼리 및 실시간 동기화를 제공합니다","es":"TanStack DB es una tienda de clientes reactiva para aplicaciones locales","fr":"TanStack DB est un magasin de clients réactif pour les applications locales","de":"TanStack DB ist ein reaktiver Client-Speicher für lokale Anwendungen","pt":"O que é TanStack DB? Uma loja de cliente reativa para aplicativos locais","ru":"Что такое TanStack DB? Реактивное хранилище клиента для локальных приложений","ar":"ما هو TanStack DB؟ مخزن عميل تفاعلي لتطبيقات محلية"},"features":{"en":["Typed set of objects via Collections","Reactive query updates with Live Query","Instant local writes with Optimistic Mutation","Real-time sync for collaborative applications","Sub-millisecond queries for fast data retrieval","Incremental updates for efficient data management"],"zh":["集合：类型化的对象集","实时查询：反应式查询，增量更新","乐观式变更：即时的本地写入，后台同步","亚毫秒查询：快速的数据检索","实时同步：数据的实时更新"],"ja":["コレクション：型付けされたオブジェクトのセット","ライブクエリ：反応型クエリ、インクリメンタル更新","楽観的ミューテーション：即時のローカル書き込み、バックグラウンド同期","サブミリ秒クエリ：高速のデータ取得","リアルタイム同期：データのリアルタイム更新"],"ko":["컬렉션：타입화된 객체의 집합","라이브 쿼리：반응형 쿼리, 증분 업데이트","낙관적 변환：즉시 로컬 쓰기, 백그라운드 동기화","亚毫秒 쿼리：高速의 데이터 조회","실시간 동기화：데이터의 실시간 업데이트"],"es":["Colecciones tipadas para objetos","Consultas en vivo que se actualizan de forma incremental","Mutaciones optimistas para escrituras locales instantáneas","Sincronización en tiempo real","Abfragen en milisegundos"],"fr":["Collections typées pour les objets","Requêtes en direct qui se mettent à jour de manière incrémentale","Mutations optimistes pour des écritures locales instantanées","Synchronisation en temps réel","Requêtes en millisecondes"],"de":["Typisierte Sammlungen für Objekte","Live-Abfragen, die inkremental aktualisiert werden","Optimistische Mutationen für instantane lokale Schreibvorgänge","Echtzeit-Synchronisation","Abfragen in Millisekunden"],"pt":["Coleções tipadas de objetos","Consultas ao vivo que atualizam incrementalmente","Mutações otimistas com escrita local instantânea","Sincronização em tempo real","Suporte a aplicativos locais com sub-milissegundos de consulta"],"ru":["Типизированные коллекции объектов","Живые запросы, которые обновляются инкрементально","Оптимистические мутации с мгновенной локальной записью","Синхронизация в реальном времени","Поддержка локальных приложений с запросами за миллисекунды"],"ar":["مجموعات من النوع كائن","استفسارات حية تحدث تحديثات متتالية","تعديلات متفائلة مع كتابة محلية فورية","تنسيق في الوقت الفعلي","دعم تطبيقات محلية مع استفسارات في مللي ثانية"]},"keywords":{"en":["how to use tanstack-db","tanstack-db alternative","tanstack-db setup guide","what is tanstack-db","tanstack-db vs redux","tanstack-db install","tanstack-db reactive client store","tanstack-db local-first apps","tanstack-db real-time sync"],"zh":["TanStack DB","reactive客户端存储","本地优先应用","亚毫秒查询","实时同步","乐观式变更","集合","实时查询"],"ja":["TanStack DB","リアクティブクライアントストア","ローカルファーストアプリ","サブミリ秒クエリ","リアルタイム同期","楽観的ミューテーション","コレクション","ライブクエリ"],"ko":["TanStack DB","반응형 클라이언트 저장소","본地 우선 애플리케이션","亚毫秒 쿼리","실시간 동기화","낙관적 변환","컬렉션","라이브 쿼리"],"es":["TanStack DB","aplicaciones locales","tienda de clientes reactiva","consultas en milisegundos","sincronización en tiempo real","colecciones tipadas","consultas en vivo","mutaciones optimistas"],"fr":["TanStack DB","applications locales","magasin de clients réactif","requêtes en millisecondes","synchronisation en temps réel","collections typées","requêtes en direct","mutations optimistes"],"de":["TanStack DB","lokale Anwendungen","reaktiver Client-Speicher","Abfragen in Millisekunden","Echtzeit-Synchronisation","typisierte Sammlungen","Live-Abfragen","optimistische Mutationen"],"pt":["TanStack DB","aplicativos locais","consultas em milissegundos","mutações otimistas","sincronização em tempo real","loja de cliente reativa","desenvolvimento de aplicativos","tecnologias de banco de dados"],"ru":["TanStack DB","ИИ Агенты","локальные приложения","запросы за миллисегунды","оптимистические мутации","синхронизация в реальном времени","реактивное хранилище клиента","разработка приложений","технологии баз данных"],"ar":["TanStack DB","أدوات الذكاء الاصطناعي","تطبيقات محلية","استفسارات في مللي ثانية","تعديلات متفائلة","تنسيق في الوقت الفعلي","مخزن عميل تفاعلي","تطوير التطبيقات","تقنيات قواعد البيانات"]}},"owner":"olegakbarov","repo":"ispo-code","repoPath":"olegakbarov/ispo-code","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.349Z","topics":[],"category":"community","skillMd":{"name":"tanstack-db","description":"Expert guidance for TanStack DB reactive client-side database with collections, live queries, optimistic mutations, and sync engines (ElectricSQL, RxDB, PowerSync). Use when user says tanstack db, /tanstack-db, local-first, live query, collection, optimistic mutation, electric, sync engine, or asks about reactive data, offline-first, or real-time sync.","bodyPreview":"# TanStack DB Skill\n\nExpert guidance for TanStack DB - the reactive client store for building local-first apps with sub-millisecond queries, optimistic mutations, and real-time sync.\n\n**Note:** TanStack DB is currently in BETA.\n\n## Quick Reference\n\n### Core Concepts\n\n| Concept | Purpose |\n|---------|---------|\n| **Collection** | Typed set of objects (like a DB table) |\n| **Live Query** | Reactive query that updates incrementally |\n| **Optimistic Mutation** | Instant local write, synced in backgr","body":"# TanStack DB Skill\n\nExpert guidance for TanStack DB - the reactive client store for building local-first apps with sub-millisecond queries, optimistic mutations, and real-time sync.\n\n**Note:** TanStack DB is currently in BETA.\n\n## Quick Reference\n\n### Core Concepts\n\n| Concept | Purpose |\n|---------|---------|\n| **Collection** | Typed set of objects (like a DB table) |\n| **Live Query** | Reactive query that updates incrementally |\n| **Optimistic Mutation** | Instant local write, synced in background |\n| **Sync Engine** | Real-time data sync (Electric, RxDB, PowerSync) |\n\n### Project Structure\n\n```\nsrc/\n├── collections/\n│   ├── todos.ts         # Todo collection definition\n│   ├── users.ts         # User collection\n│   └── index.ts         # Export all collections\n├── queries/\n│   └── hooks.ts         # Custom live query hooks\n└── lib/\n    └── db.ts            # DB setup & QueryClient\n```\n\n## Installation\n\n```bash\n# Core + React\nnpm install @tanstack/react-db @tanstack/db\n\n# With TanStack Query (REST APIs)\nnpm install @tanstack/query-db-collection @tanstack/react-query\n\n# With ElectricSQL (Postgres sync)\nnpm install @tanstack/electric-db-collection\n\n# With RxDB (offline-first)\nnpm install @tanstack/rxdb-db-collection rxdb\n```\n\n## Collections\n\n### Query Collection (REST API)\n\n```typescript\n// src/collections/todos.ts\nimport { createCollection } from \"@tanstack/react-db\"\nimport { queryCollectionOptions } from \"@tanstack/query-db-collection\"\nimport { queryClient } from \"@/lib/db\"\n\nexport interface Todo {\n  id: string\n  text: string\n  completed: boolean\n  createdAt: string\n}\n\nexport const todosCollection = createCollection(\n  queryCollectionOptions({\n    queryKey: [\"todos\"],\n    queryFn: async () => {\n      const res = await fetch(\"/api/todos\")\n      return res.json() as Promise<Todo[]>\n    },\n    queryClient,\n    getKey: (item) => item.id,\n\n    // Persistence handlers\n    onInsert: async ({ transaction }) => {\n      const items = transaction.mutations.map((m) => m.modified)\n      await fetch(\"/api/todos\", {\n        method: \"POST\",\n        body: JSON.stringify(items),\n      })\n    },\n\n    onUpdate: async ({ transaction }) => {\n      await Promise.all(\n        transaction.mutations.map((m) =>\n          fetch(`/api/todos/${m.key}`, {\n            method: \"PATCH\",\n            body: JSON.stringify(m.changes),\n          })\n        )\n      )\n    },\n\n    onDelete: async ({ transaction }) => {\n      await Promise.all(\n        transaction.mutations.map((m) =>\n          fetch(`/api/todos/${m.key}`, { method: \"DELETE\" })\n        )\n      )\n    },\n  })\n)\n```\n\n### Electric Collection (Postgres Sync)\n\n```typescript\n// src/collections/todos.ts\nimport { createCollection } from \"@tanstack/react-db\"\nimport { electricCollectionOptions } from \"@tanstack/electric-db-collection\"\n\nexport const todosCollection = createCollection(\n  electricCollectionOptions({\n    id: \"todos\",\n    shapeOptions: {\n      url: \"/api/electric/todos\", // Proxy to Electric\n    },\n    getKey: (item) => item.id,\n\n    // Use transaction ID for sync confirmation\n    onInsert: async ({ transaction }) => {\n      const item = transaction.mutations[0].modified\n      const res = await fetch(\"/api/todos\", {\n        method: \"POST\",\n        body: JSON.stringify(item),\n      })\n      const { txid } = await res.json()\n      return { txid } // Electric waits for this txid\n    },\n\n    onUpdate: async ({ transaction }) => {\n      const { key, changes } = transaction.mutations[0]\n      const res = await fetch(`/api/todos/${key}`, {\n        method: \"PATCH\",\n        body: JSON.stringify(changes),\n      })\n      const { txid } = await res.json()\n      return { txid }\n    },\n\n    onDelete: async ({ transaction }) => {\n      const { key } = transaction.mutations[0]\n      const res = await fetch(`/api/todos/${key}`, { method: \"DELETE\" })\n      const { txid } = await res.json()\n      return { txid }\n    },\n  })\n)\n```\n\n### Sync Modes\n\n```typescript\n// Eager (default): Load all upfront - best for <10k rows\nelectricCollectionOptions({\n  sync: { mode: \"eager\" },\n  // ...\n})\n\n// On-demand: Load only what queries request - best for >50k rows\nelectricCollectionOptions({\n  sync: { mode: \"on-demand\" },\n  // ...\n})\n\n// Progressive: Instant query results + background full sync\nelectricCollectionOptions({\n  sync: { mode: \"progressive\" },\n  // ...\n})\n```\n\n## Live Queries\n\n### Basic Query\n\n```tsx\nimport { useLiveQuery } from \"@tanstack/react-db\"\nimport { todosCollection } from \"@/collections/todos\"\n\nfunction TodoList() {\n  const { data: todos, isLoading } = useLiveQuery((q) =>\n    q.from({ todo: todosCollection })\n  )\n\n  if (isLoading) return <div>Loading...</div>\n\n  return (\n    <ul>\n      {todos?.map((todo) => (\n        <li key={todo.id}>{todo.text}</li>\n      ))}\n    </ul>\n  )\n}\n```\n\n### Filtering with Where\n\n```typescript\nimport { eq, gt, and, or, like, inArray } from \"@tanstack/react-db\"\n\n// Simple equality\nuseLiveQuery((q) =>\n  q.from({ todo: todosCollection })\n   .where(({ todo }) => eq(todo.completed, false))\n)\n\n// Multiple conditions\nuseLiveQuery((q) =>\n  q.from({ todo: todosCollection })\n   .where(({ todo }) =>\n     and(\n       eq(todo.completed, false),\n       gt(todo.priority, 5)\n     )\n   )\n)\n\n// OR conditions\nuseLiveQuery((q) =>\n  q.from({ todo: todosCollection })\n   .where(({ todo }) =>\n     or(\n       eq(todo.status, \"urgent\"),\n       eq(todo.status, \"high\")\n     )\n   )\n)\n\n// String matching\nuseLiveQuery((q) =>\n  q.from({ todo: todosCollection })\n   .where(({ todo }) => like(todo.text, \"%meeting%\"))\n)\n\n// In array\nuseLiveQuery((q) =>\n  q.from({ todo: todosCollection })\n   .where(({ todo }) => inArray(todo.id, [\"1\", \"2\", \"3\"]))\n)\n```\n\n### Comparison Operators\n\n| Operator | Description |\n|----------|-------------|\n| `eq(a, b)` | Equal |\n| `gt(a, b)` | Greater than |\n| `gte(a, b)` | Greater than or equal |\n| `lt(a, b)` | Less than |\n| `lte(a, b)` | Less than or equal |\n| `like(a, pattern)` | Case-sensitive match |\n| `ilike(a, pattern)` | Case-insensitive match |\n| `inArray(a, arr)` | Value in array |\n| `isNull(a)` | Is null |\n| `isUndefined(a)` | Is undefined |\n\n### Sorting and Pagination\n\n```typescript\nuseLiveQuery((q) =>\n  q.from({ todo: todosCollection })\n   .orderBy(({ todo }) => todo.createdAt, \"desc\")\n   .limit(20)\n   .offset(0)\n)\n```\n\n### Select Projection\n\n```typescript\n// Select specific fields\nuseLiveQuery((q) =>\n  q.from({ todo: todosCollection })\n   .select(({ todo }) => ({\n     id: todo.id,\n     text: todo.text,\n     done: todo.completed,\n   }))\n)\n\n// Computed fields\nuseLiveQuery((q) =>\n  q.from({ todo: todosCollection })\n   .select(({ todo }) => ({\n     id: todo.id,\n     displayText: upper(todo.text),\n     isOverdue: lt(todo.dueDate, new Date().toISOString()),\n   }))\n)\n```\n\n### Joins\n\n```typescript\nimport { usersCollection } from \"@/collections/users\"\n\n// Inner join\nuseLiveQuery((q) =>\n  q.from({ todo: todosCollection })\n   .join(\n     { user: usersCollection },\n     ({ todo, user }) => eq(todo.userId, user.id),\n     \"inner\"\n   )\n   .select(({ todo, user }) => ({\n     id: todo.id,\n     text: todo.text,\n     assignee: user.name,\n   }))\n)\n\n// Left join (default)\nuseLiveQuery((q) =>\n  q.from({ todo: todosCollection })\n   .leftJoin(\n     { user: usersCollection },\n     ({ todo, user }) => eq(todo.userId, user.id)\n   )\n)\n```\n\n### Aggregations\n\n```typescript\n// Group by with aggregates\nuseLiveQuery((q) =>\n  q.from({ todo: todosCollection })\n   .groupBy(({ todo }) => todo.status)\n   .select(({ todo }) => ({\n     status: todo.status,\n     count: count(todo.id),\n     avgPriority: avg(todo.priority),\n   }))\n)\n\n// With having clause\nuseLiveQuery((q) =>\n  q.from({ order: ordersCollection })\n   .groupBy(({ order }) => order.customerId)\n   .select(({ order }) => ({\n     customerId: order.customerId,\n     totalSpent: sum(order.amount),\n   }))\n   .having(({ $selected }) => gt($selected.totalSpent, 1000))\n)\n```\n\n### Find Single Item\n\n```typescript\n// Returns T | undefined\nuseLiveQuery((q) =>\n  q.from({ todo: todosCollection })\n   .where(({ todo }) => eq(todo.id, todoId))\n   .findOne()\n)\n```\n\n### Reactive Dependencies\n\n```typescript\n// Re-run query when deps change\nconst [filter, setFilter] = useState(\"all\")\n\nuseLiveQuery(\n  (q) =>\n    q.from({ todo: todosCollection })\n     .where(({ todo }) =>\n       filter === \"all\" ? true : eq(todo.status, filter)\n     ),\n  [filter] // Dependency array\n)\n```\n\n## Mutations\n\n### Basic Operations\n\n```typescript\nconst { collection } = useLiveQuery((q) =>\n  q.from({ todo: todosCollection })\n)\n\n// Insert\ncollection.insert({\n  id: crypto.randomUUID(),\n  text: \"New todo\",\n  completed: false,\n  createdAt: new Date().toISOString(),\n})\n\n// Insert multiple\ncollection.insert([item1, item2, item3])\n\n// Update (immutable draft pattern)\ncollection.update(todoId, (draft) => {\n  draft.completed = true\n  draft.completedAt = new Date().toISOString()\n})\n\n// Update multiple\ncollection.update([id1, id2], (drafts) => {\n  drafts.forEach((d) => (d.completed = true))\n})\n\n// Delete\ncollection.delete(todoId)\n\n// Delete multiple\ncollection.delete([id1, id2, id3])\n```\n\n### Non-Optimistic Mutations\n\n```typescript\n// Skip optimistic update, wait for server\ncollection.insert(item, { optimistic: false })\ncollection.update(id, updater, { optimistic: false })\ncollection.delete(id, { optimistic: false })\n```\n\n### Custom Optimistic Actions\n\n```typescript\nimport { createOptimisticAction } from \"@tanstack/react-db\"\n\n// Multi-collection or complex mutations\nconst likePost = createOptimisticAction<string>({\n  onMutate: (postId) => {\n    postsCollection.update(postId, (draft) => {\n      draft.likeCount += 1\n      draft.likedByMe = true\n    })\n  },\n  mutationFn: async (postId) => {\n    await fetch(`/api/posts/${postId}/like`, { method: \"POST\" })\n    // Optionally refetch\n    await postsCollection.utils.refetch()\n  },\n})\n\n// Usage\nlikePost.mutate(postId)\n```\n\n### Manual Transactions\n\n```typescript\nimport { createTransaction } from \"@tanstack/react-db\"\n\nconst tx = createTransaction({\n  autoCommit: false,\n  mutationFn: async ({ transaction }) => {\n    // Batch all mutations in single request\n    await fetch(\"/api/batch\", {\n      method: \"POST\",\n      body: JSON.stringify(transaction.mutations),\n    })\n  },\n})\n\n// Queue mutations\ntx.mutate(() => {\n  todosCollection.insert(newTodo)\n  todosCollection.update(existingId, (d) => (d.status = \"active\"))\n  todosCollection.delete(oldId)\n})\n\n// Commit or rollback\nawait tx.commit()\n// or\ntx.rollback()\n```\n\n### Paced Mutations (Debounce/Throttle)\n\n```typescript\nimport { usePacedMutations, debounceStrategy } from \"@tanstack/react-db\"\n\n// Debounce rapid updates (e.g., text input)\nconst { mutate } = usePacedMutations({\n  onMutate: (value: string) => {\n    todosCollection.update(todoId, (d) => (d.text = value))\n  },\n  mutationFn: async ({ transaction }) => {\n    const changes = transaction.mutations[0].changes\n    await fetch(`/api/todos/${todoId}`, {\n      method: \"PATCH\",\n      body: JSON.stringify(changes),\n    })\n  },\n  strategy: debounceStrategy({ wait: 500 }),\n})\n\n// Usage in input\n<input onChange={(e) => mutate(e.target.value)} />\n```\n\n## Provider Setup\n\n```tsx\n// src/main.tsx\nimport { QueryClient, QueryClientProvider } from \"@tanstack/react-query\"\nimport { DBProvider } from \"@tanstack/react-db\"\n\nconst queryClient = new QueryClient()\n\nfunction App() {\n  return (\n    <QueryClientProvider client={queryClient}>\n      <DBProvider>\n        <Router />\n      </DBProvider>\n    </QueryClientProvider>\n  )\n}\n```\n\n## Electric Backend Setup\n\n### Server-Side Transaction ID\n\n```typescript\n// api/todos/route.ts (example with Drizzle)\nimport { db } from \"@/db\"\nimport { todos } from \"@/db/schema\"\nimport { sql } from \"drizzle-orm\"\n\nexport async function POST(req: Request) {\n  const data = await req.json()\n\n  const result = await db.transaction(async (tx) => {\n    // Insert the todo\n    const [todo] = await tx.insert(todos).values(data).returning()\n\n    // Get transaction ID in SAME transaction\n    const [{ txid }] = await tx.execute(\n      sql`SELECT pg_current_xact_id()::text as txid`\n    )\n\n    return { todo, txid: parseInt(txid, 10) }\n  })\n\n  return Response.json(result)\n}\n```\n\n### Electric Proxy Route\n\n```typescript\n// api/electric/[...path]/route.ts\nexport async function GET(req: Request) {\n  const url = new URL(req.url)\n  const electricUrl = `${process.env.ELECTRIC_URL}${url.pathname}${url.search}`\n\n  return fetch(electricUrl, {\n    headers: { Authorization: `Bearer ${process.env.ELECTRIC_TOKEN}` },\n  })\n}\n```\n\n## Utility Methods\n\n```typescript\n// Refetch collection data\nawait collection.utils.refetch()\n\n// Direct writes (bypass optimistic state)\ncollection.utils.writeInsert(item)\ncollection.utils.writeUpdate(item)\ncollection.utils.writeDelete(id)\ncollection.utils.writeUpsert(item)\n\n// Batch direct writes\ncollection.utils.writeBatch(() => {\n  collection.utils.writeInsert(item1)\n  collection.utils.writeDelete(id2)\n})\n\n// Wait for Electric sync (with txid)\nawait collection.utils.awaitTxId(txid, 30000)\n\n// Wait for custom match\nawait collection.utils.awaitMatch(\n  (msg) => msg.value.id === expectedId,\n  5000\n)\n```\n\n## Gotchas and Tips\n\n1. **Queries run client-side**: TanStack DB is NOT an ORM - queries run locally against collections, not against a database\n2. **Sub-millisecond updates**: Uses differential dataflow - only recalculates affected parts of queries\n3. **Transaction IDs matter**: With Electric, always get `pg_current_xact_id()` in the SAME transaction as mutations\n4. **Sync modes**: Use \"eager\" for small datasets, \"on-demand\" for large, \"progressive\" for collaborative apps\n5. **Optimistic by default**: All mutations apply instantly; use `{ optimistic: false }` for server-validated operations\n6. **Fine-grained reactivity**: Only components using changed data re-render\n7. **Mutation merging**: Rapid updates merge automatically (insert+update→insert, update+update→merged)\n8. **Collection = complete state**: Empty array from queryFn clears the collection\n\n## Common Patterns\n\n### Loading States\n\n```tsx\nfunction TodoList() {\n  const { data, isLoading, isPending } = useLiveQuery((q) =>\n    q.from({ todo: todosCollection })\n  )\n\n  if (isLoading) return <Skeleton />\n  if (!data?.length) return <EmptyState />\n\n  return <List items={data} />\n}\n```\n\n### Mutation with Feedback\n\n```tsx\nfunction TodoItem({ todo }: { todo: Todo }) {\n  const { collection } = useLiveQuery((q) =>\n    q.from({ todo: todosCollection })\n  )\n\n  const toggle = async () => {\n    const tx = collection.update(todo.id, (d) => {\n      d.completed = !d.completed\n    })\n\n    try {\n      await tx.isPersisted.promise\n      toast.success(\"Saved!\")\n    } catch (err) {\n      toast.error(\"Failed to save\")\n      // Optimistic update already rolled back\n    }\n  }\n\n  return <Checkbox checked={todo.completed} onChange={toggle} />\n}\n```\n\n### Derived/Computed Collections\n\n```tsx\n// Create a \"view\" with live query\nconst completedTodos = useLiveQuery((q) =>\n  q.from({ todo: todosCollection })\n   .where(({ todo }) => eq(todo.completed, true))\n   .orderBy(({ todo }) => todo.completedAt, \"desc\")\n)\n```\n"},"lastSynced":"2026-03-08T02:03:44.915Z","agentAnalysis":{"suitability":{"en":"Perfect for Real-Time Application Agents needing sub-millisecond queries and optimistic mutations with TanStack DB","zh":"适合需要亚毫秒查询和乐观变异的实时应用程序代理，搭配 TanStack DB","ja":"リアルタイムアプリケーションエージェントに適しています。サブミリ秒クエリと楽観的ミューテーションが必要です。TanStack DB を使用します","ko":"서브 밀리초 쿼리와 낙관적 변이 및 TanStack DB가 필요한 실시간 애플리케이션 에이전트에 적합합니다","es":"Perfecto para Agentes de Aplicación en Tiempo Real que necesitan consultas de submilisegundos y mutaciones optimistas con TanStack DB","fr":"Parfait pour les Agents d''Application en Temps Réel nécessitant des requêtes de sous-milliseconde et des mutations optimistes avec TanStack DB","de":"Perfekt für Echtzeit-Anwendungsagenten, die Abfragen im Submillisekundenbereich und optimistische Mutationen mit TanStack DB benötigen","pt":"Perfeito para Agentes de Aplicativos em Tempo Real que precisam de consultas de sub-milissegundos e mutações otimistas com TanStack DB","ru":"Идеально подходит для агентов приложений реального времени, которым необходимы запросы с задержкой менее миллисекунды и оптимистические мутации с TanStack DB","ar":"مثالي لعمليات الوكيل التطبيقية في الوقت الفعلي التي تحتاج إلى استفسارات أسرع من милли ثانية وتعديلات متفائلة مع TanStack DB"},"recommendation":{"en":"Empowers agents to build local-first apps with reactive client stores, leveraging live queries, optimistic mutations, and real-time sync using TanStack DB''s comprehensive features, including collections and live queries","zh":"赋予代理构建本地优先应用的能力，利用反应式客户端存储、实时查询、乐观变异和实时同步，使用 TanStack DB 的全面功能，包括集合和实时查询","ja":"エージェントがローカルファーストアプリを構築できるようにします。リアクティブクライアントストア、ライブクエリ、楽観的ミューテーション、リアルタイム同期を使用します。TanStack DB の包括的な機能を使用します。コレクションやライブクエリなど","ko":"에이전트가 로컬 우선 애플리케이션을 구축할 수 있도록 합니다. 반응형 클라이언트 저장소, 라이브 쿼리, 낙관적 변이 및 실시간 동기화를 사용합니다. TanStack DB의 포괄적인 기능을 사용합니다. 컬렉션 및 라이브 쿼리 등","es":"Habilita a los agentes a construir aplicaciones de primero local con almacenes de clientes reactivos, aprovechando consultas en vivo, mutaciones optimistas y sincronización en tiempo real utilizando las características integrales de TanStack DB, incluyendo colecciones y consultas en vivo","fr":"Permet aux agents de construire des applications locales en premier avec des magasins de clients réactifs, en exploitant les requêtes en direct, les mutations optimistes et la synchronisation en temps réel à l''aide des fonctionnalités complètes de TanStack DB, notamment les collections et les requêtes en direct","de":"Ermöglicht es Agenten, lokale Erstanwendungen mit reaktiven Client-Speichern zu erstellen, indem sie Live-Abfragen, optimistische Mutationen und Echtzeitsynchronisierung mit den umfassenden Funktionen von TanStack DB nutzen, einschließlich Sammlungen und Live-Abfragen","pt":"Habilita os agentes a construir aplicativos de primeiro nível local com lojas de clientes reativas, aproveitando consultas ao vivo, mutações otimistas e sincronização em tempo real usando os recursos abrangentes do TanStack DB, incluindo coleções e consultas ao vivo","ru":"Позволяет агентам создавать локально-ориентированные приложения с реактивными клиентскими хранилищами, используя живые запросы, оптимистические мутации и синхронизацию в реальном времени с помощью всесторонних функций TanStack DB, включая коллекции и живые запросы","ar":"تمكّن العميل من بناء تطبيقات أولية بمستوى محلي مع مخازن عميل تفاعلية، واستخدام استفسارات مباشرة، وتعديلات متفائلة، وتنسيق في الوقت الفعلي باستخدام ميزات شاملة من TanStack DB، بما في ذلك المجموعات والاستفسارات المباشرة"},"useCases":{"en":["Building real-time data visualizations with sub-millisecond queries","Implementing optimistic mutations for instant local writes","Syncing data in real-time across applications with TanStack DB"],"zh":["使用亚毫秒查询构建实时数据可视化","实现乐观变异以实现即时本地写入","使用 TanStack DB 实时跨应用程序同步数据"],"ja":["サブミリ秒クエリを使用したリアルタイムデータ視覚化の構築","即時ローカル書き込みのための楽観的ミューテーションの実装","TanStack DB を使用したリアルタイムでのアプリ間のデータ同期"],"ko":["서브 밀리초 쿼리를 사용한 실시간 데이터 시각화 구축","즉시 로컬 쓰기 위한 낙관적 변이 구현","TanStack DB를 사용한 실시간 애플리케이션 간 데이터 동기화"],"es":["Construir visualizaciones de datos en tiempo real con consultas de submilisegundos","Implementar mutaciones optimistas para escrituras locales instantáneas","Sincronizar datos en tiempo real entre aplicaciones con TanStack DB"],"fr":["Créer des visualisations de données en temps réel avec des requêtes de sous-milliseconde","Mettre en œuvre des mutations optimistes pour des écritures locales instantanées","Synchroniser des données en temps réel entre les applications avec TanStack DB"],"de":["Erstellen von Echtzeit-Datenvisualisierungen mit Abfragen im Submillisekundenbereich","Implementierung optimistischer Mutationen für instantane lokale Schreibvorgänge","Synchronisierung von Daten in Echtzeit zwischen Anwendungen mit TanStack DB"],"pt":["Construir visualizações de dados em tempo real com consultas de sub-milissegundos","Implementar mutações otimistas para gravações locais instantâneas","Sincronizar dados em tempo real entre aplicações com TanStack DB"],"ru":["Построение визуализаций данных реального времени с запросами менее миллисекунды","Реализация оптимистических мутаций для мгновенных локальных записей","Синхронизация данных в реальном времени между приложениями с TanStack DB"],"ar":["بناء تصورات بيانات في الوقت الفعلي باستفسارات أسرع من ملي ثانية","تطبيق تعديلات متفائلة للكتابة المحلية الفورية","تنسيق البيانات في الوقت الفعلي بين التطبيقات مع TanStack DB"]},"limitations":{"en":["Currently in BETA","Requires understanding of reactive client stores and local-first app development"],"zh":["目前处于 BETA 阶段","需要理解反应式客户端存储和本地优先应用开发"],"ja":["現在 BETA 段階にあります","リアクティブクライアントストアとローカルファーストアプリ開発の理解が必要"],"ko":["현재 베타 버전입니다","반응형 클라이언트 저장소 및 로컬 우선 애플리케이션 개발에 대한 이해가 필요합니다"],"es":["Actualmente en BETA","Requiere comprensión de almacenes de clientes reactivos y desarrollo de aplicaciones de primero local"],"fr":["Actuellement en BETA","Nécessite une compréhension des magasins de clients réactifs et du développement d''applications locales en premier"],"de":["Derzeit in BETA","Benötigt Verständnis für reaktive Client-Speicher und Entwicklung von lokalen Erstanwendungen"],"pt":["Atualmente em BETA","Exige compreensão de lojas de clientes reativas e desenvolvimento de aplicações de primeiro nível local"],"ru":["Находится в стадии BETA","Требует понимания реактивных клиентских хранилищ и разработки локально-ориентированных приложений"],"ar":["حاليًا في مرحلة بيتا","يتطلب فهم مخازن العميل التفاعلية وتطوير تطبيقات بمستوى محلي أولي"]},"version":4},"contentHash":"051a29660b70e0725850ebb970a1bbdcef2596d195a92d8ceb1111266d5a7849","qualityScore":42}');
