INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('zsxawerdu/gitexplorer/avalonia', 'avalonia', 'zsxawerdu', 'gitexplorer', 'community', 'avalonia zsxawerdu gitexplorer community Avalonia is a UI development skill that leverages modern C# and expert UI design to create beautiful, functional interfaces. It benefits developers who want to build data-driven applications with a focus on visual design and interaction. Avalonia UI是一个强大的跨平台UI框架，支持现代C#开发 Avalonia UIは、美しい＆機能的なインターフェースを作成するための優れたUIフレームワーク Avalonia UI는 데이터 흐름 및 프로시저 패턴을 지원하는 현대적인 UI 프레임워크 Avalonia es un framework de UI que permite a los desarrolladores crear interfaces funcionales y hermosas con C#. Aprenda a utilizarlo con nuestros recursos y tutoriales. Avalonia est un framework d''UI qui permet aux développeurs de créer des interfaces fonctionnelles et belles avec C#. Découvrez comment l''utiliser avec nos ressources et tutoriels. Avalonia ist ein UI-Framework, das es Entwicklern ermöglicht, funktionale und schöne Schnittstellen mit C# zu erstellen. Erfahren Sie, wie Sie es mit unseren Ressourcen und Tutorien verwenden können. Avalonia é uma ferramenta de desenvolvimento de UI que permite criar aplicativos de desktop cross-plataforma com C#. Aprenda a usar XAML, seletores, vinculações e modelos para criar interfaces de usuário personalizadas Avalonia - это инструмент для разработки пользовательских интерфейсов, который позволяет создавать кроссплатформенные桌товые приложения на C#. Узнайте, как использовать XAML, селекторы, привязки и шаблоны для создания настраиваемых интерфейсов Avalonia هي أداة لتطوير واجهات المستخدم التي تمكنك من إنشاء تطبيقات سطح المكتب متعددة المنصات باستخدام C#. تعلم كيفية استخدام XAML و المحselectors و الارتباطات و النماذج لإنشاء واجهات مستخدم مخصصة how to use avalonia avalonia vs WPF avalonia install guide what is avalonia UI avalonia alternative to Xamarin avalonia setup for C# developers avalonia UI design patterns avalonia XAML tutorial avalonia C# development best practices Avalonia UI开发 C#开发 XAML语法 ViewModels 交互设计 数据流 过程式模式 AIエージェント UI设计 Uses modern C# with a preference for records and value types Employs procedural patterns over heavy OOP for efficient development Supports XAML syntax, selectors, bindings, and templates for UI design Utilizes ViewModels and communication patterns for data flow management Enables creation of beautiful, functional interfaces with expert visual design and interaction design Avalonia is a C#-based UI development framework that utilizes records, value types, and procedural patterns to create modern, data-driven applications');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vinceh/recipe/vue-playwright-testing', 'community', 'vinceh', 'recipe', 'vinceh/recipe', 'vue-playwright-testing', 0, 0, 42, '2026-03-08T01:57:15.351Z', '2026-03-08T02:03:52.198Z', 'a5c2779e912b8e1403400e2b6137dd9ad5053ff2481f9416956829ec38a25756', '{"id":"vinceh/recipe/vue-playwright-testing","name":"vue-playwright-testing","description":{"en":"The vue-playwright-testing skill provides Vue-specific guidance for writing maintainable tests using Playwright, integrating with Vue''s reactivity system and Vite build pipeline. This skill benefits Vue 3 developers.","zh":"本技能提供 Vue 3 应用的 Playwright 测试指导，帮助开发者编写可维护的测试代码","ja":"このスキルは Vue 3 アプリケーションの Playwright テストのガイダンスを提供し、開発者がメンテナンス可能なテストコードを書くことを支援","ko":"이 스킬은 Vue 3 애플리케이션의 Playwright 테스트 가이드를 제공하여 개발자가 유지 보수 가능한 테스트 코드를 작성하도록 도와줍니다","es":"El skill vue-playwright-testing proporciona orientación específica de Vue para escribir pruebas mantenibles con Playwright, integrándose con el sistema de reactividad de Vue y Vite","fr":"Le skill vue-playwright-testing fournit des conseils spécifiques à Vue pour écrire des tests maintenables avec Playwright, en intégrant le système de réactivité de Vue et Vite","de":"Das Skill vue-playwright-testing bietet spezifische Anleitung für Vue, um mit Playwright wartbare Tests zu schreiben, integriert mit Vues Reaktionssystem und Vite","pt":"O Vue 3 + Playwright Testing permite a criação de testes confiáveis para aplicações Vue 3. Este skill fornece orientação específica para Vue.","ru":"Vue 3 + Playwright Testing позволяет создавать надёжные тесты для приложений Vue 3. Этот навык предоставляет специфические рекомендации для Vue.","ar":"يسمح Vue 3 + Playwright Testing بإنشاء اختبارات موثوقة للتطبيقات Vue 3. هذا المهارة يقدم إرشادات محددة لVue."},"seo":{"title":{"en":"vue-playwright-testing: End-to-End Testing Setup Guide | ...","zh":"Vue 3 Playwright 测试设置指南","ja":"Vue 3 Playwright テストベストプラクティス","ko":"Vue 3 Playwright 테스트 환경 설정 가이드","es":"Guía de configuración para pruebas de Vue 3 con Playwright","fr":"Configurer les tests Vue 3 avec Playwright - Meilleures p...","de":"Einrichten von Vue 3-Tests mit Playwright - Leitfaden","pt":"Guia de Configuração para Testes de Vue 3 com Playwright","ru":"ИИ Агенты: Руководство по настройке тестирования Vue 3 с ...","ar":"إعداد اختبارات Vue 3 مع Playwright: دليل الشروع"},"description":{"en":"Unlock reliable testing for Vue 3 apps with Playwright. Learn how to integrate and avoid common pitfalls. Get started with our setup guide and expert tips.","zh":"使用 Playwright 进行 Vue 3 应用的端到端测试和组件测试，实现可靠的测试环境","ja":"Vue 3 アプリケーションのエンドツーエンドテストとコンポーネントテストに Playwright を使用して、信頼性の高いテスト環境を実現","ko":"Playwright를 사용하여 Vue 3 애플리케이션의 엔드 투 엔드 테스트와 컴포넌트 테스트를进行하여 안정적인 테스트 환경을 구축","es":"Aprende a configurar pruebas de fin a fin y de componentes para aplicaciones Vue 3 con Playwright, evitando patrones anti-antipáticos de timeout","fr":"Découvrez comment configurer des tests de bout en bout et de composants pour les applications Vue 3 avec Playwright, tout en évitant les anti-modèles de timeout","de":"Erfahren Sie, wie Sie End-to-End- und Komponententests für Vue 3-Anwendungen mit Playwright konfigurieren und Timeout-Antimuster vermeiden","pt":"Aprenda a configurar testes de Vue 3 com Playwright. Este guia oferece dicas e práticas recomendadas para testes confiáveis.","ru":"Узнайте, как настроить тестирование Vue 3 с Playwright. Это руководство предоставляет советы и лучшие практики для надёжного тестирования.","ar":"تعلم كيفية إعداد اختبارات Vue 3 مع Playwright. هذا الدليل يقدم نصائح وأفضل الممارسات لاختبارات موثوقة."},"definition":{"en":"vue-playwright-testing is a skill that enables end-to-end testing for Vue 3 applications using Playwright, supporting seamless integration with Vue Router and Vite.","zh":"Vue 3 Playwright 测试是一种使用 Playwright 进行 Vue 3 应用的端到端测试和组件测试的方法","ja":"Vue 3 Playwright テストは、Playwright を使用して Vue 3 アプリケーションのエンドツーエンドテストとコンポーネントテストを実行する方法","ko":"Vue 3 Playwright 테스트는 Playwright를 사용하여 Vue 3 애플리케이션의 엔드 투 엔드 테스트와 컴포넌트 테스트를 진행하는 방법","es":"vue-playwright-testing es un skill que permite configurar pruebas de fin a fin y de componentes para aplicaciones Vue 3 con Playwright","fr":"vue-playwright-testing est un skill qui permet de configurer des tests de bout en bout et de composants pour les applications Vue 3 avec Playwright","de":"vue-playwright-testing ist ein Skill, der die Konfiguration von End-to-End- und Komponententests für Vue 3-Anwendungen mit Playwright ermöglicht","pt":"O que é Vue 3 + Playwright Testing? É uma abordagem para testes de Vue 3 que utiliza Playwright.","ru":"Что такое Vue 3 + Playwright Testing? Это подход к тестированию Vue 3, который использует Playwright.","ar":"ما هو Vue 3 + Playwright Testing? إنه نهج لاختبارات Vue 3 التي تستخدم Playwright."},"features":{"en":["Integrates with Vue''s reactivity system for reliable testing","Supports end-to-end testing and experimental component testing using Playwright","Works with Vue Router navigation for accurate testing scenarios","Compatible with Vite build pipeline for efficient testing workflows","Provides guidance on avoiding timeout anti-patterns for maintainable tests","Supports Playwright version 1.48+, Vue 3.5+, and Vite 6+"],"zh":["支持 Vue 3.5+ 和 Vite 6+","与 Vue 的响应式系统和 Vue Router 导航集成","提供可维护的测试代码编写指导","避免常见的超时反模式","支持 Playwright 1.48+"],"ja":["Vue 3.5+ と Vite 6+ のサポート","Vue のリアクティブシステムと Vue Router ナビゲーションの統合","メンテナンス可能なテストコードの書き方のガイダンスを提供","一般的なタイムアウト反パターンの回避","Playwright 1.48+ のサポート"],"ko":["Vue 3.5+ 및 Vite 6+ 지원","Vue의 리액티브 시스템과 Vue Router 네비게이션 통합","유지 보수 가능한 테스트 코드 작성 가이드 제공","일반적인 타임아웃 반패턴 회피","Playwright 1.48+ 지원"],"es":["Integración con el sistema de reactividad de Vue","Compatibilidad con Vue Router y Vite","Pruebas de fin a fin y de componentes con Playwright","Evitación de patrones anti-antipáticos de timeout","Compatibilidad con Playwright 1.48+ y Vue 3.5+"],"fr":["Intégration avec le système de réactivité de Vue","Compatibilité avec Vue Router et Vite","Tests de bout en bout et de composants avec Playwright","Évitement des anti-modèles de timeout","Compatibilité avec Playwright 1.48+ et Vue 3.5+"],"de":["Integration mit Vues Reaktionsystem","Kompatibilität mit Vue Router und Vite","End-to-End- und Komponententests mit Playwright","Vermeidung von Timeout-Antimustern","Kompatibilität mit Playwright 1.48+ und Vue 3.5+"],"pt":["Integração com o sistema de reatividade do Vue","Suporte à navegação do Vue Router","Compatibilidade com o pipeline de build do Vite","Evita padrões anti-timeout","Suporte às versões Playwright 1.48+, Vue 3.5+, Vite 6+"],"ru":["Интеграция с системой реактивности Vue","Поддержка навигации Vue Router","Совместимость с конвейером сборки Vite","Избежание анти-шаблонов таймаута","Поддержка версий Playwright 1.48+, Vue 3.5+, Vite 6+"],"ar":["التكامل مع نظام التفاعل في Vue","دعم التنقل في Vue Router","التوافق مع خط أنابيب بناء Vite","التغلب على أنماط التأخير","دعم الإصدارات Playwright 1.48+, Vue 3.5+, Vite 6+"]},"keywords":{"en":["how to use vue-playwright-testing","vue-playwright-testing setup guide","vue-playwright-testing vs Cypress","vue-playwright-testing install","what is vue-playwright-testing","vue-playwright-testing alternative","vue-playwright-testing tutorial","vue-playwright-testing best practices","vue-playwright-testing for AI agents"],"zh":["Vue 3 Playwright 测试","Vue 3 测试环境","Playwright 测试框架","Vue 3 应用测试","端到端测试","组件测试","AIエージェント","Vue 3 开发"],"ja":["Vue 3 Playwright テスト","Vue 3 テスト環境","Playwright テストフレームワーク","Vue 3 アプリケーションテスト","エンドツーエンドテスト","コンポーネントテスト","AIエージェント","Vue 3 開発"],"ko":["Vue 3 Playwright 테스트","Vue 3 테스트 환경","Playwright 테스트 프레임워크","Vue 3 애플리케이션 테스트","엔드 투 엔드 테스트","컴포넌트 테스트","AI 에이전트","Vue 3 개발"],"es":["pruebas de Vue 3","Playwright testing","Vue Router testing","Vite testing","pruebas de fin a fin","pruebas de componentes","evitar patrones anti-antipáticos de timeout","Herramientas de testing para Vue"],"fr":["tests Vue 3","Playwright testing","Vue Router testing","Vite testing","tests de bout en bout","tests de composants","éviter les anti-modèles de timeout","Outils de testing pour Vue"],"de":["Vue 3-Tests","Playwright-Testing","Vue Router-Testing","Vite-Testing","End-to-End-Tests","Komponententests","Vermeidung von Timeout-Antimustern","Testing-Tools für Vue"],"pt":["testes de Vue 3","Playwright","Vite","Vue Router","testes confiáveis","desenvolvimento de software","enguia de configuração","melhores práticas de testes"],"ru":["тестирование Vue 3","Playwright","Vite","Vue Router","надёжное тестирование","разработка программного обеспечения","руководство по настройке","лучшие практики тестирования"],"ar":["اختبارات Vue 3","Playwright","Vite","Vue Router","اختبارات موثوقة","تطوير البرمجيات","دليل الإعداد","أفضل الممارسات للاختبارات"]}},"owner":"vinceh","repo":"recipe","repoPath":"vinceh/recipe","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.351Z","topics":[],"category":"community","skillMd":{"name":"vue-playwright-testing","description":"Comprehensive guide for testing Vue 3 applications with Playwright (2025). This skill should be used when writing end-to-end tests or component tests for Vue apps, testing Vue Router navigation, reactive state changes, authentication flows, or setting up Playwright in Vue projects.","bodyPreview":"# Vue 3 + Playwright Testing\n\n## Overview\n\nTo build reliable tests for Vue 3 applications, use Playwright for both end-to-end testing and experimental component testing. Playwright integrates seamlessly with Vue''s reactivity system, Vue Router navigation, and Vite build pipeline. This skill provides Vue-specific guidance for writing maintainable tests while avoiding common pitfalls like timeout anti-patterns.\n\n**Current Versions:** Playwright 1.48+, Vue 3.5+, Vite 6+\n**Standard Approach:** Seman","body":"# Vue 3 + Playwright Testing\n\n## Overview\n\nTo build reliable tests for Vue 3 applications, use Playwright for both end-to-end testing and experimental component testing. Playwright integrates seamlessly with Vue''s reactivity system, Vue Router navigation, and Vite build pipeline. This skill provides Vue-specific guidance for writing maintainable tests while avoiding common pitfalls like timeout anti-patterns.\n\n**Current Versions:** Playwright 1.48+, Vue 3.5+, Vite 6+\n**Standard Approach:** Semantic locators, conditional waits, API mocking\n**Key Philosophy:** Never use arbitrary timeouts to fix flaky tests\n\n## Decision Tree: What Type of Test?\n\n```\nVue Test Request → What are you testing?\n    |\n    ├─ End-to-end user flow (login, forms, navigation)?\n    │   ├─ Single page interaction? → Use Quick Start: E2E Test\n    │   └─ Multi-page workflow? → Load references/e2e-patterns.md\n    │\n    ├─ Individual Vue component in isolation?\n    │   └─ Load references/component-testing.md\n    │\n    ├─ Vue Router navigation or page transitions?\n    │   └─ Load references/vue-specific-patterns.md → Router section\n    │\n    ├─ Reactive state changes or Pinia store?\n    │   └─ Load references/vue-specific-patterns.md → State Management\n    │\n    ├─ Authentication flow?\n    │   └─ Load references/vue-specific-patterns.md → Authentication\n    │\n    ├─ Test is failing intermittently/flaky?\n    │   └─ Load references/best-practices.md → Debugging Flaky Tests section\n    │\n    └─ Setting up Playwright in Vue project?\n        └─ Use Quick Start: Project Setup\n```\n\n## Quick Start: Project Setup\n\n### Initialize Playwright in Vue Project\n\n```bash\nnpm init playwright@latest -- --ct\n```\n\nThis command:\n- Installs `@playwright/test` and `@playwright/experimental-ct-vue`\n- Downloads browsers\n- Creates `playwright.config.ts`\n- Sets up test structure\n\nFor Vue projects with Vite, ensure `playwright.config.ts` includes:\n\n```typescript\nimport { defineConfig, devices } from ''@playwright/test'';\nimport react from ''@vitejs/plugin-react'';\nimport vue from ''@vitejs/plugin-vue'';\n\nexport default defineConfig({\n  testDir: ''./tests'',\n  fullyParallel: true,\n  forbidOnly: !!process.env.CI,\n  retries: process.env.CI ? 2 : 0,\n  workers: process.env.CI ? 1 : undefined,\n\n  use: {\n    baseURL: ''http://localhost:5173'',\n    trace: ''on-first-retry'',\n    screenshot: ''only-on-failure'',\n    video: ''retain-on-failure'',\n  },\n\n  webServer: {\n    command: ''npm run dev'',\n    url: ''http://localhost:5173'',\n    reuseExistingServer: !process.env.CI,\n  },\n\n  projects: [\n    { name: ''chromium'', use: { ...devices[''Desktop Chrome''] } },\n    { name: ''firefox'', use: { ...devices[''Desktop Firefox''] } },\n    { name: ''webkit'', use: { ...devices[''Desktop Safari''] } },\n  ],\n});\n```\n\n## Quick Start: E2E Test\n\n### Basic E2E Test Example\n\n```typescript\nimport { test, expect } from ''@playwright/test'';\n\ntest.describe(''Login Flow'', () => {\n  test.beforeEach(async ({ page }) => {\n    await page.goto(''/login'');\n  });\n\n  test(''user can login successfully'', async ({ page }) => {\n    // Use semantic locators (getByLabel, getByRole)\n    await page.getByLabel(''Email'').fill(''user@example.com'');\n    await page.getByLabel(''Password'').fill(''password123'');\n\n    // Click submit button\n    await page.getByRole(''button'', { name: ''Sign in'' }).click();\n\n    // Wait for URL change (condition-based, not timeout)\n    await expect(page).toHaveURL(''/dashboard'');\n\n    // Assert Vue app rendered correctly\n    await expect(page.getByRole(''heading'', { name: /Welcome/i })).toBeVisible();\n  });\n\n  test(''invalid credentials show error'', async ({ page }) => {\n    await page.getByLabel(''Email'').fill(''bad@email.com'');\n    await page.getByLabel(''Password'').fill(''wrong'');\n    await page.getByRole(''button'', { name: ''Sign in'' }).click();\n\n    // Wait for error message to appear\n    await expect(page.getByRole(''alert'')).toContainText(''Invalid credentials'');\n  });\n});\n```\n\n## Quick Start: Component Test\n\n### Testing Vue Component in Isolation\n\n```typescript\nimport { test, expect } from ''@playwright/experimental-ct-vue'';\nimport Button from ''./Button.vue'';\n\ntest(''button emits click event'', async ({ mount }) => {\n  const messages: string[] = [];\n\n  const component = await mount(Button, {\n    props: { label: ''Click me'' },\n    on: {\n      click: () => messages.push(''clicked'')\n    }\n  });\n\n  await component.getByRole(''button'').click();\n  expect(messages).toEqual([''clicked'']);\n});\n```\n\n## Core Vue 3 + Playwright Principles\n\n### 1. Never Use Arbitrary Timeouts to Fix Flaky Tests\n\n**❌ BAD: Masking the real issue**\n```typescript\n// This is a code smell - something is wrong\nawait page.waitForTimeout(3000);\nawait page.click(''button'');\n```\n\n**✅ GOOD: Wait for the specific condition**\n```typescript\n// Wait for button to be enabled\nawait page.locator(''button:not([disabled])'').waitFor();\nawait page.getByRole(''button'').click();\n\n// Or use Playwright''s auto-waiting\nawait page.getByRole(''button'', { name: ''Submit'' }).click();\n```\n\n**Why?** Arbitrary timeouts hide race conditions, selector problems, or network issues. When you see a flaky test, investigate the root cause:\n- Is the selector wrong? Use dev tools to verify\n- Is data loading? Wait for the API response\n- Is Vue not mounted yet? Check the condition\n- Is the element disabled? Wait for the disabled attribute to be removed\n\n### 2. Use Semantic Locators for Stability\n\nPriority order (most stable to least):\n\n```typescript\n// ✅ 1. User-facing text/roles (most stable)\nawait page.getByRole(''button'', { name: ''Save'' });\nawait page.getByLabel(''Email'');\nawait page.getByPlaceholder(''Search...'');\nawait page.getByText(''Welcome'');\n\n// ✅ 2. Test IDs (when semantic locators insufficient)\nawait page.getByTestId(''product-card'');\n\n// ❌ 3. CSS/XPath selectors (avoid - fragile)\nawait page.locator(''css=.dynamic-button'');\n```\n\n### 3. Test Vue-Specific Behavior\n\nWait for Vue app to be ready before interactions:\n\n```typescript\n// Wait for Vue app to mount\ntest(''app loads correctly'', async ({ page }) => {\n  await page.goto(''/'');\n\n  // Playwright auto-waits, but be explicit for Vue:\n  await page.waitForFunction(() => {\n    // Check Vue app is mounted\n    return !!(window as any).__VUE_DEVTOOLS_GLOBAL_HOOK__?.enabled;\n  });\n\n  // Now safe to interact\n  await page.getByRole(''button'').click();\n});\n```\n\n### 4. Test Reactive State Changes\n\nTest observable behavior from reactive updates:\n\n```typescript\ntest(''counter increments'', async ({ page }) => {\n  await page.goto(''/counter'');\n\n  // Initial state\n  await expect(page.getByText(''Count: 0'')).toBeVisible();\n\n  // Click increment\n  await page.getByRole(''button'', { name: ''Increment'' }).click();\n\n  // Reactive update (Playwright auto-waits for DOM change)\n  await expect(page.getByText(''Count: 1'')).toBeVisible();\n});\n```\n\n### 5. Mock Network Requests\n\nControl external APIs for consistent tests:\n\n```typescript\ntest(''fetches and displays data'', async ({ page }) => {\n  // Intercept API calls\n  await page.route(''**/api/users'', async (route) => {\n    await route.fulfill({\n      status: 200,\n      contentType: ''application/json'',\n      body: JSON.stringify([{ id: 1, name: ''Test User'' }])\n    });\n  });\n\n  await page.goto(''/users'');\n\n  // Assert mocked data is displayed\n  await expect(page.getByText(''Test User'')).toBeVisible();\n});\n```\n\n## Common Vue Testing Patterns\n\n### Pattern: Testing Vue Router Navigation\n\n```typescript\ntest(''navigates to product details'', async ({ page }) => {\n  await page.goto(''/products'');\n\n  // Click product link\n  await page.getByRole(''link'', { name: ''Product A'' }).click();\n\n  // Wait for URL change (conditional, not timeout)\n  await expect(page).toHaveURL(''/products/1'');\n\n  // Assert component mounted with correct data\n  await expect(page.getByRole(''heading'', { name: ''Product A'' })).toBeVisible();\n});\n```\n\n### Pattern: Testing Form Validation\n\n```typescript\ntest(''validates form before submit'', async ({ page }) => {\n  await page.goto(''/contact'');\n\n  // Leave required field empty\n  await page.getByLabel(''Email'').fill('''');\n  await page.getByLabel(''Message'').fill(''Hello'');\n\n  // Try to submit\n  await page.getByRole(''button'', { name: ''Send'' }).click();\n\n  // Error message should appear\n  await expect(page.getByText(''Email is required'')).toBeVisible();\n\n  // Form should not submit\n  await expect(page).toHaveURL(''/contact'');\n});\n```\n\n### Pattern: Testing Modal Dialogs\n\n```typescript\ntest(''modal closes on cancel'', async ({ page }) => {\n  await page.goto(''/'');\n\n  // Open modal\n  await page.getByRole(''button'', { name: ''Open Dialog'' }).click();\n  await expect(page.getByRole(''dialog'')).toBeVisible();\n\n  // Close modal\n  await page.getByRole(''button'', { name: ''Cancel'' }).click();\n\n  // Modal should disappear\n  await expect(page.getByRole(''dialog'')).not.toBeVisible();\n});\n```\n\n## When to Load Reference Files\n\nLoad these strategically to optimize context usage:\n\n### references/e2e-patterns.md\n- Building multi-page E2E workflows\n- Implementing Page Object Model for Vue tests\n- Testing complex user journeys\n- Multi-step authentication flows\n\n### references/component-testing.md\n- Testing Vue components in isolation\n- Setting up experimental component testing\n- Testing props, events, slots\n- Testing composables with components\n\n### references/vue-specific-patterns.md\n- Vue Router testing patterns\n- Pinia state management testing\n- Vue reactivity and computed properties\n- Authentication testing in Vue\n- Understanding wait patterns for Vue\n\n### references/best-practices.md\n- Debugging flaky tests (and why timeouts aren''t the answer)\n- Selector strategies and troubleshooting\n- API mocking patterns\n- CI/CD configuration\n- Performance optimization\n\n## Tips for Success\n\n1. **Start with semantic locators** - They''re more stable and maintainable\n2. **Never reach for timeouts first** - If tests are flaky, investigate the root cause\n3. **Test user behavior** - Not implementation details or Vue internals\n4. **Mock external APIs** - For consistency and speed\n5. **Run tests in parallel** - Playwright supports parallel execution by default\n6. **Use traces and videos** - For debugging failed tests\n7. **Review flaky tests immediately** - Don''t ignore intermittent failures\n8. **Keep tests focused** - One test should verify one behavior\n9. **Set up CI/CD early** - Use provided GitHub Actions workflow\n10. **Reference the Vue-specific patterns** - Understand how to wait for Vue correctly\n\n## File Structure\n\n```\nmy-vue-app/\n├── tests/\n│   ├── e2e/\n│   │   ├── login.spec.ts\n│   │   ├── products.spec.ts\n│   │   └── checkout.spec.ts\n│   ├── fixtures/\n│   │   ├── auth.ts\n│   │   └── data.ts\n│   └── pages/\n│       ├── LoginPage.ts\n│       ├── ProductsPage.ts\n│       └── CheckoutPage.ts\n├── playwright.config.ts\n└── package.json\n```\n\n## Resources\n\nThis skill includes references, templates, and scripts:\n\n### references/e2e-patterns.md\nComprehensive guide to E2E testing for Vue applications using Page Object Model and multi-page workflows.\n\n### references/component-testing.md\nGuide to testing Vue components in isolation using Playwright''s experimental component testing.\n\n### references/vue-specific-patterns.md\nVue-specific testing patterns including Router navigation, Pinia state management, reactivity testing, and proper wait strategies.\n\n### references/best-practices.md\nBest practices including timeout anti-patterns, debugging flaky tests, selector strategies, and CI/CD setup.\n\n### assets/playwright.config.template.ts\nProduction-ready Playwright configuration optimized for Vue with Vite.\n\n### assets/workflows/playwright-vue.yml\nGitHub Actions workflow for automated Playwright testing in CI/CD pipeline.\n\n### scripts/init-vue-playwright.ts\nSetup script to initialize Playwright in an existing Vue project with proper configuration.\n"},"lastSynced":"2026-03-08T02:03:52.198Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents specializing in Vue 3 development and needing advanced end-to-end testing capabilities with Playwright","zh":"适合专门从事Vue 3开发的前端代理，需要使用Playwright进行高级端到端测试的能力","ja":"Vue 3開発に特化したフロントエンドエージェントに適しています。Playwrightを使用した高度なエンドツーエンドテスト機能が必要です","ko":"Vue 3 개발에 특화된 프론트엔드 에이전트에게 적합합니다. Playwright를 사용한 고급 엔드투엔드 테스트 기능이 필요합니다","es":"Perfecto para Agentes Frontend especializados en desarrollo de Vue 3 y que necesitan capacidades de prueba de extremo a extremo avanzadas con Playwright","fr":"Parfait pour les agents Frontend spécialisés dans le développement Vue 3 et ayant besoin de capacités de test de bout en bout avancées avec Playwright","de":"Perfekt für Frontend-Agenten, die auf Vue 3-Entwicklung spezialisiert sind und erweiterte End-to-End-Testfunktionen mit Playwright benötigen","pt":"Perfeito para Agentes Frontend especializados em desenvolvimento Vue 3 e que necessitam de capacidades de teste de ponta a ponta avançadas com Playwright","ru":"Идеально подходит для агентов Frontend, специализирующихся на разработке Vue 3 и нуждающихся в расширенных возможностях тестирования от начала до конца с Playwright","ar":"مثالي لعميل واجهة المستخدم الأمامية المتخصص في تطوير Vue 3 والذي يحتاج إلى قدرات اختبار متقدمة من النهاية إلى النهاية مع Playwright"},"recommendation":{"en":"Empowers agents to write maintainable tests for Vue 3 applications by integrating Playwright with Vue''s reactivity system, Vue Router navigation, and Vite build pipeline, avoiding common pitfalls like timeout anti-patterns with Playwright 1.48+, Vue 3.5+, and Vite 6+","zh":"通过将Playwright与Vue的响应式系统、Vue Router导航和Vite构建流水线集成，赋予代理编写可维护的Vue 3应