INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vinceh/recipe/vue-playwright-testing', 'vue-playwright-testing', 'vinceh', 'recipe', 'community', 'vue-playwright-testing vinceh recipe community The vue-playwright-testing skill provides Vue-specific guidance for writing maintainable tests using Playwright, integrating with Vue''s reactivity system and Vite build pipeline. This skill benefits Vue 3 developers. 本技能提供 Vue 3 应用的 Playwright 测试指导，帮助开发者编写可维护的测试代码 このスキルは Vue 3 アプリケーションの Playwright テストのガイダンスを提供し、開発者がメンテナンス可能なテストコードを書くことを支援 이 스킬은 Vue 3 애플리케이션의 Playwright 테스트 가이드를 제공하여 개발자가 유지 보수 가능한 테스트 코드를 작성하도록 도와줍니다 El skill vue-playwright-testing proporciona orientación específica de Vue para escribir pruebas mantenibles con Playwright, integrándose con el sistema de reactividad de Vue y Vite Le skill vue-playwright-testing fournit des conseils spécifiques à Vue pour écrire des tests maintenables avec Playwright, en intégrant le système de réactivité de Vue et Vite Das Skill vue-playwright-testing bietet spezifische Anleitung für Vue, um mit Playwright wartbare Tests zu schreiben, integriert mit Vues Reaktionssystem und Vite O Vue 3 + Playwright Testing permite a criação de testes confiáveis para aplicações Vue 3. Este skill fornece orientação específica para Vue. Vue 3 + Playwright Testing позволяет создавать надёжные тесты для приложений Vue 3. Этот навык предоставляет специфические рекомендации для Vue. يسمح Vue 3 + Playwright Testing بإنشاء اختبارات موثوقة للتطبيقات Vue 3. هذا المهارة يقدم إرشادات محددة لVue. how to use vue-playwright-testing vue-playwright-testing setup guide vue-playwright-testing vs Cypress vue-playwright-testing install what is vue-playwright-testing vue-playwright-testing alternative vue-playwright-testing tutorial vue-playwright-testing best practices vue-playwright-testing for AI agents Vue 3 Playwright 测试 Vue 3 测试环境 Playwright 测试框架 Vue 3 应用测试 端到端测试 组件测试 AIエージェント Vue 3 开发 Integrates with Vue''s reactivity system for reliable testing Supports end-to-end testing and experimental component testing using Playwright Works with Vue Router navigation for accurate testing scenarios Compatible with Vite build pipeline for efficient testing workflows Provides guidance on avoiding timeout anti-patterns for maintainable tests Supports Playwright version 1.48+, Vue 3.5+, and Vite 6+ vue-playwright-testing is a skill that enables end-to-end testing for Vue 3 applications using Playwright, supporting seamless integration with Vue Router and Vite.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('shinpr/ai-coding-project-boilerplate/frontend/technical-spec', 'community', 'shinpr', 'ai-coding-project-boilerplate', 'shinpr/ai-coding-project-boilerplate', 'frontend/technical-spec', 0, 0, 42, '2026-03-08T01:57:15.357Z', '2026-03-08T02:04:05.071Z', '937e2cfdee77b770521c82244527ea42f982b06ccc15cd701b1bf52fbe8c4ed4', '{"id":"shinpr/ai-coding-project-boilerplate/frontend/technical-spec","name":"frontend/technical-spec","description":{"en":"The frontend/technical-spec skill provides a TypeScript-based React application implementation for AI agents, with features like environment variable management and security. It benefits developers working with Claude Code","zh":"本文介绍了前端技术规范的设置和最佳实践，使用TypeScript和React实现生产就绪的AI Agent","ja":"この記事では、フロントエンド技術仕様の設定とベストプラクティスについて説明し、TypeScriptとReactを使用して生産就緒のAIエージェントを実現します","ko":"이 문서는 프론트엔드 기술 사양의 설정과 최적의 방법에 대해 설명하며, TypeScript와 React를 사용하여 생산 준비가 된 AI 에이전트를 구현합니다","es":"El frontend/technical-spec proporciona un modelo de TypeScript listo para producción para Claude Code con agentes de AI especializados","fr":"Le frontend/technical-spec fournit un modèle de TypeScript prêt pour la production pour Claude Code avec des agents d''IA spécialisés","de":"Das frontend/technical-spec bietet ein produktionsreifes TypeScript-Modell für Claude Code mit spezialisierten KI-Agents","pt":"O frontend/technical-spec é um boilerplate TypeScript para Claude Code com agentes de IA especializados, projetado para melhorar a eficiência e escalabilidade dos aplicativos","ru":"Frontend/technical-spec - это производственный шаблон TypeScript для Claude Code с оснасткой ИИ, предназначенный для улучшения эффективности и масштабируемости приложений","ar":"بروتوكول frontend/technical-spec هو قالب أساسي TypeScript ل Claude Code مع وكلاء الذكاء الاصطناعي المتخصصين، مصمم لتحسين الكفاءة وال قابلية للتوسع لت