INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('shinpr/ai-coding-project-boilerplate/frontend/technical-spec', 'frontend/technical-spec', 'shinpr', 'ai-coding-project-boilerplate', 'community', 'frontend/technical-spec shinpr ai-coding-project-boilerplate community The frontend/technical-spec skill provides a TypeScript-based React application implementation for AI agents, with features like environment variable management and security. It benefits developers working with Claude Code 本文介绍了前端技术规范的设置和最佳实践，使用TypeScript和React实现生产就绪的AI Agent この記事では、フロントエンド技術仕様の設定とベストプラクティスについて説明し、TypeScriptとReactを使用して生産就緒のAIエージェントを実現します 이 문서는 프론트엔드 기술 사양의 설정과 최적의 방법에 대해 설명하며, TypeScript와 React를 사용하여 생산 준비가 된 AI 에이전트를 구현합니다 El frontend/technical-spec proporciona un modelo de TypeScript listo para producción para Claude Code con agentes de AI especializados Le frontend/technical-spec fournit un modèle de TypeScript prêt pour la production pour Claude Code avec des agents d''IA spécialisés Das frontend/technical-spec bietet ein produktionsreifes TypeScript-Modell für Claude Code mit spezialisierten KI-Agents O frontend/technical-spec é um boilerplate TypeScript para Claude Code com agentes de IA especializados, projetado para melhorar a eficiência e escalabilidade dos aplicativos Frontend/technical-spec - это производственный шаблон TypeScript для Claude Code с оснасткой ИИ, предназначенный для улучшения эффективности и масштабируемости приложений بروتوكول frontend/technical-spec هو قالب أساسي TypeScript ل Claude Code مع وكلاء الذكاء الاصطناعي المتخصصين، مصمم لتحسين الكفاءة وال قابلية للتوسع لتطبيقات how to use frontend/technical-spec frontend/technical-spec alternative TypeScript boilerplate for Claude Code frontend/technical-spec setup guide environment variable management in React frontend/technical-spec vs create-react-app TypeScript-based AI agent development Claude Code development best practices frontend/technical-spec install 前端技术规范 TypeScript AI Agent React应用程序 环境变量系统 类型安全 架构模式 AI开发 前端开发 TypeScript开发 TypeScript-based React application implementation Environment variable management through configuration layer Proper type safety with build tool''s environment variable system Centrally managed environment variables for security Architecture patterns selected according to project requirements and scale Support for `process.env` alternative in browser environments frontend/technical-spec is a production-ready TypeScript boilerplate for Claude Code with specialized AI agents, following technical design rules for frontend development');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Cornjebus/security-analyzer/security-analyzer', 'community', 'Cornjebus', 'security-analyzer', 'Cornjebus/security-analyzer', 'security-analyzer', 0, 0, 42, '2026-03-08T01:57:15.358Z', '2026-03-08T02:04:05.538Z', '1e6bc96431de082e80562bfc69d46466ebc0d5706f6104990f1ec539b4ce4ad5', '{"id":"Cornjebus/security-analyzer/security-analyzer","name":"security-analyzer","description":{"en":"The security-analyzer skill analyzes environments for vulnerabilities and generates phased remediation plans. It benefits developers and security teams by providing a comprehensive security scan.","zh":"Security Analyzer 是一个AIエージェント技能，用于分析环境漏洞，获取CVE数据，生成修复计划","ja":"Security Analyzer は、AIエージェントスキルで、環境の脆弱性を分析し、CVEデータを取得し、修復計画を生成します","ko":"Security Analyzer는 환경 취약점을 분석하고 CVE 데이터를 가져와서 복구 계획을 생성하는 AI 에이전트 스킬입니다","es":"El análisis de seguridad es una habilidad que analiza entornos para vulnerabilidades y genera planes de remediation con TDD","fr":"L''analyse de sécurité est une compétence qui analyse les environnements pour les vulnérabilités et génère des plans de remediation avec TDD","de":"Die Sicherheitsanalyse ist eine Fähigkeit, die Umgebungen auf Schwachstellen überprüft und Remediation-Pläne mit TDD generiert","pt":"O analisador de segurança é uma habilidade para Claude Code que analisa ambientes em busca de vulnerabilidades e gera planos de remediação","ru":"ИИ Агент Security Analyzer - это навык для Claude Code, который анализирует среды на наличие уязвимостей и генерирует планы по устранению","ar":"أداة تحليل الأمان هي مهارة لبرنامج Claude Code تقوم بتحليل البيئات لتحديد الثغرات وتوليد خطط الإصلاح"},"seo":{"title":{"en":"security-analyzer: Vulnerability Scanner Setup Guide | AI...","zh":"Security Analyzer Setup Guide - AIエージェント环境漏洞扫描","ja":"Security Analyzer ベストプラクティス - AIエージェント脆弱性診断","ko":"Security Analyzer 설정 가이드 - AI 에이전트 보안 분석","es":"Herramientas de Análisis de Seguridad: Guía de Configuración","fr":"Outil d''Analyse de Sécurité: Guide d''Installation","de":"Sicherheitsanalyse-Tool: Einrichtungsanleitung","pt":"Guia de Configuração do Analisador de Segurança para Dese...","ru":"Настройка ИИ Агента Security Analyzer: Руководство для Ра...","ar":"إعداد أداة تحليل الأمان للاستخدام مع Claude Code"},"description":{"en":"Discover how to setup security-analyzer for AI agents and protect your environments from vulnerabilities with our expert guide and tutorials.","zh":"使用Security Analyzer AIエージェント扫描环境漏洞，获取CVE数据，生成修复计划","ja":"Security Analyzer AIエージェントを使用して脆弱性を診断し、CVEデータを取得し、修復計画を生成する","ko":"Security Analyzer AI 에이전트를 사용하여 환경 취약점을 분석하고 CVE 데이터를 가져와서 복구 계획을 생성합니다","es":"Descubre cómo configurar el análisis de seguridad para identificar vulnerabilidades y generar planes de remediation con TDD","fr":"Découvrez comment configurer l''analyse de sécurité pour identifier les vulnérabilités et générer des plans de remediation avec TDD","de":"Erfahren Sie, wie Sie die Sicherheitsanalyse einrichten, um Schwachstellen zu identifizieren und Remediation-Pläne mit TDD zu generieren","pt":"Aprenda a configurar o analisador de segurança para identificar vulnerabilidades e gerar planos de remediação com validação TDD","ru":"Узнайте, как настроить ИИ Агент Security Analyzer для выявления уязвимостей и генерации планов по устранению с проверкой TDD","ar":"اكتشف كيفية إعداد أداة تحليل الأمان لتحديد الثغرات وتوليد خطط الإصلاح مع التحقق من TDD"},"definition":{"en":"security-analyzer is a skill that analyzes environments for vulnerabilities, fetches current CVE/exploit data, and generates phased remediation plans with TDD validation.","zh":"Security Analyzer 是一个用于环境漏洞分析和修复的AIエージェント技能","ja":"Security Analyzer は、環境の脆弱性を分析し、修復するためのAIエージェントスキルです","ko":"Security Analyzer는 환경 취약점을 분석하고 복구하기 위한 AI 에이전트 스킬입니다","es":"Análisis de seguridad es una herramienta que identifica vulnerabilidades y genera planes de remediation","fr":"L''analyse de sécurité est un outil qui identifie les vulnérabilités et génère des plans de remediation","de":"Sicherheitsanalyse ist ein Tool, das Schwachstellen identifiziert und Remediation-Pläne generiert","pt":"O que é um analisador de segurança? É uma ferramenta que identifica vulnerabilidades em ambientes e gera planos de remediação","ru":"Что такое ИИ Агент Security Analyzer? Это инструмент, который выявляет уязвимости в средах и генерирует планы по устранению","ar":"ما هي أداة تحليل الأمان؟ هي أداة تحدد الثغرات في البيئات وتوليد خطط الإصلاح"},"features":{"en":["Runs environment discovery using `python .claude/skills/security-analyzer/scripts/discover_env.py`","Saves output to `inventory.json` for further analysis","Performs vulnerability scan using `python .claude/skills/security-analyzer/scripts/fetch_vulns.py`","Generates phased remediation plans with TDD validation","Fetches current CVE/exploit data for accurate vulnerability assessment"],"zh":["环境发现和漏洞扫描","CVE数据获取和分析","生成修复计划和TDD验证","使用Python脚本运行环境发现和漏洞扫描","支持JSON格式的输出和输入"],"ja":["環境の発見と脆弱性のスキャン","CVEデータの取得と分析","修復計画の生成とTDD検証","Pythonスクリプトを使用して環境の発見と脆弱性のスキャンを実行","JSON形式の出力と入力をサポート"],"ko":["환경 발견과 취약점 분석","CVE 데이터 가져오기와 분석","복구 계획 생성과 TDD 검증","Python 스크립트를 사용하여 환경 발견과 취약점 분석을 실행","JSON 형식의 출력과 입력을 지원"],"es":["Análisis de entornos con Python","Identificación de vulnerabilidades con CVE","Generación de planes de remediation con TDD","Uso de scripts de descubrimiento de entornos","Análisis de resultados de escaneo con JSON"],"fr":["Analyse d''environnements avec Python","Identification de vulnérabilités avec CVE","Génération de plans de remediation avec TDD","Utilisation de scripts de découverte d''environnements","Analyse de résultats de scan avec JSON"],"de":["Analyse von Umgebungen mit Python","Identifizierung von Schwachstellen mit CVE","Generierung von Remediation-Plänen mit TDD","Verwendung von Umgebungs-Entdeckungs-Skripten","Analyse von Scan-Ergebnissen mit JSON"],"pt":["Análise de ambientes para identificar vulnerabilidades","Coleta de dados de CVE e exploração atuais","Geração de planos de remediação com validação TDD","Suporte a scripts em Python para automação","Saída em formato JSON para facilidade de integração"],"ru":["Анализ сред на наличие уязвимостей","Сбор данных о текущих уязвимостях и эксплуатациях","Генерация планов по устранению с проверкой TDD","Поддержка скриптов на Python для автоматизации","Выходные данные в формате JSON для легкой интеграции"],"ar":["تحليل البيئات لتحديد الثغرات","collecting البيانات الحالية عن الثغرات والاستغلال","توليد خطط الإصلاح مع التحقق من TDD","دعم سكريبتات Python للتحكم الآلي","إخراج البيانات بفورمت JSON لسهولة التكامل"]},"keywords":{"en":["how to use security-analyzer","security-analyzer setup guide","security-analyzer alternative","security-analyzer vs competitor","security-analyzer install","vulnerability scanner for AI agents","CVE exploit data analysis","TDD validation for security plans"],"zh":["Security Analyzer","AIエージェント","环境漏洞分析","CVE数据","修复计划","Python脚本","JSON格式","TDD验证"],"ja":["Security Analyzer","AIエージェント","環境の脆弱性診断","CVEデータ","修復計画","Pythonスクリプト","JSON形式","TDD検証"],"ko":["Security Analyzer","AI 에이전트","환경 취약점 분석","CVE 데이터","복구 계획","Python 스크립트","JSON 형식","TDD 검증"],"es":["análisis de seguridad","herramientas de seguridad","python seguridad","CVE","TDD","remediation","seguridad de código","análisis de vulnerabilidades","desarrollo seguro"],"fr":["analyse de sécurité","outils de sécurité","python sécurité","CVE","TDD","remediation","sécurité de code","analyse de vulnérabilités","développement sécurisé"],"de":["Sicherheitsanalyse","Sicherheitstools","Python Sicherheit","CVE","TDD","Remediation","Code-Sicherheit","Schwachstellen-Analyse","sichere Entwicklung"],"pt":["analisador de segurança","segurança de código","vulnerabilidades","planos de remediação","validação TDD","Python","CLI","desenvolvedores"],"ru":["ИИ Агент Security Analyzer","безопасность кода","уязвимости","планы по устранению","проверка TDD","Python","CLI","разработчики"],"ar":["أداة تحليل الأمان","أمان الكود","الثغرات","خطط الإصلاح","التحقق من TDD","Python","CLI","مطوري البرمجيات"]}},"owner":"Cornjebus","repo":"security-analyzer","repoPath":"Cornjebus/security-analyzer","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.358Z","topics":[],"category":"community","skillMd":{"name":"security-analyzer","description":"Comprehensive security vulnerability analysis for codebases and infrastructure. Scans dependencies (npm, pip, gem, go, cargo), containers (Docker, Kubernetes), cloud IaC (Terraform, CloudFormation), and detects secrets exposure. Fetches live CVE data from OSV.dev, calculates risk scores, and generates phased remediation plans with TDD validation tests. Use when users mention security scan, vulnerability, CVE, exploit, security audit, penetration test, OWASP, hardening, dependency audit, container security, or want to improve security posture.","bodyPreview":"# Security Analyzer\n\nAnalyze environments for vulnerabilities, fetch current CVE/exploit data, and generate phased remediation plans with TDD validation.\n\n## Quick Start\n\nWhen the user requests a security scan:\n\n1. Run environment discovery: `python .claude/skills/security-analyzer/scripts/discover_env.py .`\n2. Save output to `inventory.json`\n3. Run vulnerability scan: `python .claude/skills/security-analyzer/scripts/fetch_vulns.py inventory.json`\n4. Save output to `scan_results.json`\n5. Generat","body":"# Security Analyzer\n\nAnalyze environments for vulnerabilities, fetch current CVE/exploit data, and generate phased remediation plans with TDD validation.\n\n## Quick Start\n\nWhen the user requests a security scan:\n\n1. Run environment discovery: `python .claude/skills/security-analyzer/scripts/discover_env.py .`\n2. Save output to `inventory.json`\n3. Run vulnerability scan: `python .claude/skills/security-analyzer/scripts/fetch_vulns.py inventory.json`\n4. Save output to `scan_results.json`\n5. Generate reports: `python .claude/skills/security-analyzer/scripts/generate_report.py scan_results.json inventory.json`\n\n## Workflow\n\n### Phase 1: Environment Discovery\n\nScan working directory for:\n- **Dependencies**: `package.json`, `requirements.txt`, `Gemfile`, `go.mod`, `Cargo.toml`, `pom.xml`\n- **Containers**: `Dockerfile`, `docker-compose.yml`, `kubernetes/*.yaml`\n- **Cloud IaC**: `terraform/*.tf`, `cloudformation/*.yaml`, `*.bicep`\n- **Secrets**: `.env*` files (flag exposure risk, never log values)\n\nRun the discovery script:\n```bash\npython .claude/skills/security-analyzer/scripts/discover_env.py /path/to/project > inventory.json\n```\n\n### Phase 2: Vulnerability Intelligence\n\nFetch current threat data using the vulnerability scanner:\n\n```bash\npython .claude/skills/security-analyzer/scripts/fetch_vulns.py inventory.json > scan_results.json\n```\n\n| Source | Priority | Use For |\n|--------|----------|---------|\n| CISA KEV | 1 | Actively exploited vulns (use WebSearch) |\n| NVD | 2 | CVE details + CVSS scores (use WebSearch) |\n| GitHub Advisories | 3 | Package-specific vulns (use WebSearch) |\n| OSV.dev | 4 | Open source vulns (API in script) |\n\nFor CISA KEV and additional context, supplement with:\n```\nWebSearch: \"CVE-XXXX-YYYY CISA KEV exploit\"\n```\n\n### Phase 3: Risk Scoring\n\nThe scanner calculates risk scores using:\n\n```\nRisk = (CVSS * 0.3) + (Exploitability * 0.3) + (Criticality * 0.2) + (Exposure * 0.2)\n\nExploitability: 10=CISA KEV, 7=public exploit, 3=theoretical\nCriticality: 10=auth/payment, 5=core business, 2=logging\nExposure: 10=internet-facing, 5=internal, 2=air-gapped\n```\n\n### Phase 4: Phased Remediation\n\nGenerate reports with fix commands and validation tests:\n\n```bash\npython .claude/skills/security-analyzer/scripts/generate_report.py scan_results.json inventory.json\n```\n\nEach finding includes:\n1. Vulnerability details + risk score\n2. Actual fix code/patch (not just recommendations)\n3. Pre-fix test (proves vuln exists)\n4. Remediation unit tests (tests the fix code)\n5. Post-fix validation (proves vuln resolved)\n\n### Phase 5: Reports\n\nOutput two reports:\n- `security-report-technical.md` — Full details for engineers\n- `security-report-executive.md` — Summary for leadership\n\nSee `references/report-templates.md` for output structure.\n\n## TDD Pattern\n\nFor each vulnerability, generate three test types:\n\n```python\ndef test_vuln_exists():\n    \"\"\"PASS before fix, FAIL after\"\"\"\n    assert is_vulnerable(\"component\") == True\n\ndef test_fix_works():\n    \"\"\"Unit test for remediation code\"\"\"\n    result = apply_fix(vulnerable_config)\n    assert result.is_secure()\n\ndef test_vuln_resolved():\n    \"\"\"FAIL before fix, PASS after\"\"\"\n    assert is_vulnerable(\"component\") == False\n```\n\n## Fix Types by Finding\n\n| Finding | Output |\n|---------|--------|\n| Dependency CVE | Version bump command + lockfile update |\n| Container issue | Dockerfile patch |\n| IaC misconfiguration | Terraform/K8s fix |\n| Code vulnerability | Source patch + test |\n| Secret exposure | Rotation commands + `.gitignore` update |\n\n## Example Interaction\n\n**User:** \"Run a security scan on this project\"\n\n**Claude:**\n1. Discovers 47 npm dependencies, 3 Dockerfiles, 2 Terraform configs\n2. Fetches current CVE data from OSV.dev\n3. Identifies 12 vulnerabilities (2 critical, 4 high, 6 medium)\n4. Generates phased remediation plan with:\n   - Actual fix commands (`npm install lodash@4.17.21`)\n   - Code patches for IaC misconfigurations\n   - TDD tests proving each fix works\n5. Outputs technical and executive reports\n"},"lastSynced":"2026-03-08T02:04:05.538Z","agentAnalysis":{"suitability":{"en":"Ideal for Cybersecurity Agents requiring comprehensive vulnerability assessments and phased remediation planning.","zh":"适用于需要全面漏洞评估和分阶段补救计划的网络安全代理。","ja":"網絡セキュリティエージェントが包括的な脆弱性評価と段階的な修復計画を必要とする場合に最適です。","ko":"전반적인 취약점 평가 및 단계적 복구 계획이 필요한 사이버 보안 에이전트에 적합합니다.","es":"Ideal para Agentes de Ciberseguridad que requieren evaluaciones de vulnerabilidad exhaustivas y planificación de remediación por fases.","fr":"Idéal pour les agents de cybersécurité nécessitant des évaluations de vulnérabilité complètes et une planification de remédiation par phases.","de":"Ideal für Cyber-Sicherheitsagenten, die umfassende Schwachstellenevaluierungen und Phasen-Remediationplanung benötigen.","pt":"Ideal para Agentes de Cibersegurança que requerem avaliações de vulnerabilidade abrangentes e planejamento de remediação faseado.","ru":"Идеально для агентов кибербезопасности, требующих комплексных оценок уязвимостей и фазового планирования восстановления.","ar":"مثالي للوكلاء الأمنيين الذين يحتاجون إلى تقييمات شاملة للثغرات الأمنية وتخطيط الإصلاح المرحلي."},"recommendation":{"en":"Empowers agents to analyze environments for vulnerabilities, fetch current CVE and exploit data, and generate remediation plans with Test-Driven Development (TDD) validation using Python scripts and JSON output.","zh":"赋予代理分析环境中的漏洞，获取当前CVE和exploit数据，并使用Python脚本和JSON输出生成带有测试驱动开发（TDD）验证的修复计划。","ja":"エージェントが環境を脆弱性のあるものとして分析し、現在のCVEおよびexploitデータを取得し、PythonスクリプトおよびJSON出力を使用してテスト駆動開発（TDD）検証を伴う修復計画を生成できるようにします。","ko":"에이전트가 환경을 분석하여 취약점을 식별하고, 현재의 CVE 및 exploit 데이터를 가져와 Python 스크립트 및 JSON 출력을 사용하여 테스트 주도 개발(TDD) 검증을 통해 복구 계획을 생성할 수 있도록 합니다.","es":"Permite a los agentes analizar entornos en busca de vulnerabilidades, obtener datos actuales de CVE y explotación, y generar planes de remediación con validación de Desarrollo Dirigido por Pruebas (TDD) utilizando scripts de Python y salida JSON.","fr":"Permet aux agents d''analyser les environnements pour les vulnérabilités, de récupérer les données actuelles de CVE et d''exploitation, et de générer des plans de remédiation avec une validation de développement piloté par les tests (TDD) en utilisant des scripts Python et une sortie JSON.","de":"Ermöglicht es Agenten, Umgebungen auf Schwachstellen zu analysieren, aktuelle CVE- und Exploitedaten abzurufen und Remediationpläne mit Test-Driven Development (TDD)-Validierung unter Verwendung von Python-Skripten und JSON-Ausgabe zu generieren.","pt":"Habilita os agentes a analisar ambientes em busca de vulnerabilidades, obter dados atuais de CVE e exploração e gerar planos de remediação com validação de Desenvolvimento Dirigido por Testes (TDD) usando scripts Python e saída JSON.","ru":"Наделяет агентов возможностью анализировать среды для выявления уязвимостей, получать текущие данные CVE и эксплуатации, а также генерировать планы восстановления с валидацией Test-Driven Development (TDD) с использованием скриптов Python и вывода JSON.","ar":"يمنح الوكلاء القدرة على تحليل البيئات للبحث عن الثغرات الأمنية، والحصول على بيانات CVE والحيل الحالية، وتوليد خطط الإصلاح بالتحقق الموجه بالاختبار (TDD) باستخدام نصوص Python وخرج JSON."},"useCases":{"en":["Automating environment discovery for vulnerability scanning","Generating phased remediation plans for identified security threats","Fetching and analyzing current CVE and exploit data for risk assessment"],"zh":["自动执行环境发现以进行漏洞扫描","为已识别的安全威胁生成分阶段的修复计划","获取和分析当前CVE和exploit数据以进行风险评估"],"ja":["脆弱性スキャンのために環境の自動検出を実行する","特定されたセキュリティ脅威の段階的な修復計画を生成する","リスク評価のために現在のCVEおよびexploitデータを取得して分析する"],"ko":["취약점 스캔을 위한 환경 자동 탐색 실행","식별된 보안 위협에 대한 단계적 복구 계획 생성","위험 평가를 위한 현재 CVE 및 exploit 데이터 가져오기 및 분석"],"es":["Automatizar el descubrimiento de entornos para el análisis de vulnerabilidades","Generar planes de remediación por fases para las amenazas de seguridad identificadas","Recuperar y analizar los datos actuales de CVE y explotación para la evaluación de riesgos"],"fr":["Automatiser la découverte de l''environnement pour l''analyse des vulnérabilités","Générer des plans de remédiation par phases pour les menaces de sécurité identifiées","Récupérer et analyser les données actuelles de CVE et d''exploitation pour l''évaluation des risques"],"de":["Automatisieren der Umgebungs-Entdeckung für die Schwachstellen-Analyse","Generieren von phasenweisen Remediationplänen für identifizierte Sicherheitsbedrohungen","Abrufen und Analysieren der aktuellen CVE- und Exploitedaten für die Risikobewertung"],"pt":["Automatizar a descoberta de ambiente para varredura de vulnerabilidades","Gerar planos de remediação faseados para ameaças de segurança identificadas","Obter e analisar dados atuais de CVE e exploração para avaliação de risco"],"ru":["Автоматизировать обнаружение среды для сканирования уязвимостей","Генерировать поэтапные планы восстановления для выявленных угроз безопасности","Получать и анализировать текущие данные CVE и эксплуатации для оценки риска"],"ar":["توفير اكتشاف البيئة بشكل تلقائي لمسح الثغرات الأمنية","توليد خطط الإصلاح المرحلية للتهديدات الأمنية المحددة","الحصول على تحليل البيانات الحالية لCVE والحيل لتقييم المخاطر"]},"limitations":{"en":["Requires Python environment","Dependent on external CVE and exploit data sources","Output files require manual processing (e.g., inventory.json, scan_results.json)"],"zh":["需要Python环境","依赖于外部CVE和exploit数据源","输出文件需要手动处理（例如，inventory.json，scan_results.json）"],"ja":["Python環境が必要","外部のCVEおよびexploitデータソースに依存する","出力ファイルは手動で処理する必要がある（例：inventory.json、scan_results.json）"],"ko":["Python 환경 필요","외부 CVE 및 exploit 데이터 소스에 의존","출력 파일은 수동으로 처리해야 함(예: inventory.json, scan_results.json)"],"es":["Requiere un entorno de Python","Dependiente de fuentes de datos externas de CVE y explotación","Los archivos de salida requieren un procesamiento manual (por ejemplo, inventory.json, scan_results.json)"],"fr":["Nécessite un environnement Python","Dépendant des sources de données externes de CVE et d''exploitation","Les fichiers de sortie nécessitent un traitement manuel (par exemple, inventory.json, scan_results.json)"],"de":["Benötigt eine Python-Umgebung","Abhängig von externen Quellen für CVE- und Exploitedaten","Ausgabedateien erfordern manuelle Verarbeitung (z. B. inventory.json, scan_results.json)"],"pt":["Requer ambiente Python","Dependente de fontes de dados externas de CVE e exploração","Arquivos de saída requerem processamento manual (por exemplo, inventory.json, scan_results.json)"],"ru":["Требует среды Python","Зависит от внешних источников данных CVE и эксплуатации","Файлы вывода требуют ручной обработки (например, inventory.json, scan_results.json)"],"ar":["يتطلب بيئة Python","يعتمد على مصادر بيانات CVE والحيل الخارجية","تتطلب الملفات الناتجة معالجة يدوية (على سبيل المثال، inventory.json، scan_results.json)"]},"version":4},"contentHash":"1e6bc96431de082e80562bfc69d46466ebc0d5706f6104990f1ec539b4ce4ad5","qualityScore":42}');
