INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Cornjebus/security-analyzer/security-analyzer', 'security-analyzer', 'Cornjebus', 'security-analyzer', 'community', 'security-analyzer Cornjebus security-analyzer community The security-analyzer skill analyzes environments for vulnerabilities and generates phased remediation plans. It benefits developers and security teams by providing a comprehensive security scan. Security Analyzer 是一个AIエージェント技能，用于分析环境漏洞，获取CVE数据，生成修复计划 Security Analyzer は、AIエージェントスキルで、環境の脆弱性を分析し、CVEデータを取得し、修復計画を生成します Security Analyzer는 환경 취약점을 분석하고 CVE 데이터를 가져와서 복구 계획을 생성하는 AI 에이전트 스킬입니다 El análisis de seguridad es una habilidad que analiza entornos para vulnerabilidades y genera planes de remediation con TDD L''analyse de sécurité est une compétence qui analyse les environnements pour les vulnérabilités et génère des plans de remediation avec TDD Die Sicherheitsanalyse ist eine Fähigkeit, die Umgebungen auf Schwachstellen überprüft und Remediation-Pläne mit TDD generiert O analisador de segurança é uma habilidade para Claude Code que analisa ambientes em busca de vulnerabilidades e gera planos de remediação ИИ Агент Security Analyzer - это навык для Claude Code, который анализирует среды на наличие уязвимостей и генерирует планы по устранению أداة تحليل الأمان هي مهارة لبرنامج Claude Code تقوم بتحليل البيئات لتحديد الثغرات وتوليد خطط الإصلاح how to use security-analyzer security-analyzer setup guide security-analyzer alternative security-analyzer vs competitor security-analyzer install vulnerability scanner for AI agents CVE exploit data analysis TDD validation for security plans Security Analyzer AIエージェント 环境漏洞分析 CVE数据 修复计划 Python脚本 JSON格式 TDD验证 Runs environment discovery using `python .claude/skills/security-analyzer/scripts/discover_env.py` Saves output to `inventory.json` for further analysis Performs vulnerability scan using `python .claude/skills/security-analyzer/scripts/fetch_vulns.py` Generates phased remediation plans with TDD validation Fetches current CVE/exploit data for accurate vulnerability assessment security-analyzer is a skill that analyzes environments for vulnerabilities, fetches current CVE/exploit data, and generates phased remediation plans with TDD validation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('BWBama85/wp-migrate.sh/wp-migrate', 'community', 'BWBama85', 'wp-migrate.sh', 'BWBama85/wp-migrate.sh', 'wp-migrate', 0, 0, 42, '2026-03-08T01:57:15.358Z', '2026-03-08T02:04:06.890Z', 'ef1e5b04d63389b0a12ebe61d71cfddb33ba3831d8fb8c8ea9f77142dc915c92', '{"id":"BWBama85/wp-migrate.sh/wp-migrate","name":"wp-migrate","description":{"en":"The wp-migrate skill provides automated WordPress migration expertise, supporting SSH push and archive import modes for developers. It handles database updates, URL replacements, and wp-content syncing.","zh":"wp-migrate.sh是一种强大的WordPress迁移工具，支持SSH推送和归档导入两种模式","ja":"wp-migrate.shは、SSHプッシュとアーカイブインポートの2つのモードをサポートする包括的なWordPress移行ツールです","ko":"wp-migrate.sh는 SSH 푸시 및 아카이브 임포트의 2가지 모드를 지원하는 포괄적인 워드프레스 마이그레이션 툴입니다","es":"wp-migrate es una herramienta de migración de WordPress que admite SSH y modos de archivo con manejo de bases de datos automatizado","fr":"wp-migrate est un outil de migration de WordPress qui prend en charge SSH et les modes d''archive avec une gestion de base de données automatisée","de":"wp-migrate ist ein WordPress-Migrationstool, das SSH und Archivmodi mit automatisierter Datenbankverwaltung unterstützt","pt":"O wp-migrate é uma ferramenta de migração WordPress que suporta modos push e archive, com tratamento automático de banco de dados e substituição de URLs","ru":"wp-migrate - это инструмент для миграции WordPress, поддерживающий режимы push и archive, с автоматическим xử lý базы данных и заменой URL","ar":"wp-migrate هو أداة مهاجرة ووردبريس تدعم أوضاع دفع وارشيف، مع معالجة 자동ة لقاعدة البيانات واستبدال URLs"},"seo":{"title":{"en":"wp-migrate: Automated WordPress Migration Setup Guide | A...","zh":"wp-migrate.setup指南：SSH推送和归档导入","ja":"wp-migrateセットアップガイド：SSHプッシュとアーカイブインポート","ko":"wp-migrate 설정 가이드: SSH 푸시 및 아카이브 임포트","es":"Guía de configuración de wp-migrate para migración de Wor...","fr":"Guide d''installation de wp-migrate pour la migration de W...","de":"wp-migrate Einrichtungsleitfaden für WordPress-Migration","pt":"Guia de Configuração do wp-migrate para Migração de WordP...","ru":"Настройка wp-migrate: Инструмент для Миграции WordPress с...","ar":"دليل إعداد wp-migrate لمهاجرة مواقع ووردبريس"},"description":{"en":"Discover how to seamlessly migrate WordPress sites with wp-migrate''s SSH push and archive import modes - get started now and streamline your workflow!","zh":"使用wp-migrate.sh迁移WordPress站点，支持SSH推送和归档导入，自动处理数据库和URL替换","ja":"wp-migrate.shを使用してWordPressサイトを移行します。SSHプッシュとアーカイブインポートをサポートし、データベースとURLの置換を自動化します","ko":"wp-migrate.sh를 사용하여 워드프레스 사이트를 마이그레이션합니다. SSH 푸시 및 아카이브 임포트를 지원하며 데이터베이스 및 URL 교체를 자동화합니다","es":"Aprende a migrar sitios de WordPress con wp-migrate, una herramienta de migración que admite SSH y modos de archivo con manejo de bases de datos automatizado","fr":"Découvrez comment migrer des sites WordPress avec wp-migrate, un outil de migration qui prend en charge SSH et les modes d''archive avec une gestion de base d...","de":"Erfahren Sie, wie Sie WordPress-Seiten mit wp-migrate migrieren, einem Migrationstool, das SSH und Archivmodi mit automatisierter Datenbankverwaltung unterst...","pt":"Aprenda a migrar sites WordPress com facilidade usando o wp-migrate, com suporte a SSH e importação de arquivos de backup","ru":"Мигрируйте сайты WordPress с помощью wp-migrate, поддерживающего SSH и импорт архивов резервного копирования","ar":"استخدم wp-migrate لمهاجرة مواقع ووردبريس بسهولة، مع دعم SSH واستيراد أرشيفات النسخ الاحتياطي"},"definition":{"en":"wp-migrate is a WordPress migration tool that operates in push and archive modes, enabling automated database handling, URL replacement, and wp-content synchronization.","zh":"wp-migrate.sh是一种用于迁移WordPress站点的命令行工具","ja":"wp-migrate.shは、WordPressサイトを移行するためのコマンドラインツールです","ko":"wp-migrate.sh는 워드프레스 사이트를 마이그레이션하는 위한 명령줄 툴입니다","es":"wp-migrate es una herramienta de migración de WordPress que facilita la transferencia de sitios entre servidores","fr":"wp-migrate est un outil de migration de WordPress qui facilite le transfert de sites entre serveurs","de":"wp-migrate ist ein WordPress-Migrationstool, das den Transfer von Seiten zwischen Servern erleichtert","pt":"O wp-migrate é uma ferramenta de linha de comando para migrar sites WordPress","ru":"wp-migrate - это командная утилита для миграции сайтов WordPress","ar":"wp-migrate هو أداة سطر أوامر لمهاجرة مواقع ووردبريس"},"features":{"en":["Supports SSH push mode for migrating WordPress sites between servers","Enables archive import mode for importing WordPress backup archives from Duplicator, Jetpack Backup, and Solid Backups","Automates database handling for seamless migrations","Performs URL replacement for updated site URLs","Syncs wp-content for consistent site content","Utilizes git for version control and updates"],"zh":["SSH推送模式：支持WordPress站点之间的迁移","归档导入模式：支持Duplicator、Jetpack Backup和Solid Backups的备份归档","自动数据库处理：迁移过程中自动处理数据库","URL替换：自动替换URL以适应新环境","wp-content同步：同步wp-content目录以确保数据一致性"],"ja":["SSHプッシュモード：WordPressサイト間の移行をサポート","アーカイブインポートモード：Duplicator、Jetpack Backup、Solid Backupsのバックアップアーカイブをサポート","自動データベース処理：移行プロセス中に自動でデータベースを処理","URL置換：新しい環境に適応するためにURLを自動的に置換","wp-content同期：wp-contentディレクトリを同期してデータの一貫性を確保"],"ko":["SSH 푸시 모드: 워드프레스 사이트 간의 마이그레이션을 지원","아카이브 임포트 모드: Duplicator, Jetpack Backup, Solid Backups의 백업 아카이브를 지원","자동 데이터베이스 처리: 마이그레이션 프로세스 중에 자동으로 데이터베이스를 처리","URL 교체: 새로운 환경에 적응하기 위해 URL을 자동으로 교체","wp-content 동기화: wp-content 디렉토리를 동기화하여 데이터 일관성을 보장"],"es":["Modo push para migrar sitios de WordPress entre servidores via SSH","Modo de archivo para importar copias de seguridad de WordPress","Manejo de bases de datos automatizado","Reemplazo de URLs y sincronización de wp-content","Compatibilidad con Duplicator, Jetpack Backup y Solid Backups"],"fr":["Mode push pour migrer des sites WordPress entre serveurs via SSH","Mode d''archive pour importer des sauvegardes de WordPress","Gestion de base de données automatisée","Remplacement d''URL et synchronisation de wp-content","Compatibilité avec Duplicator, Jetpack Backup et Solid Backups"],"de":["Push-Modus für die Migration von WordPress-Seiten zwischen Servern über SSH","Archivmodus für die Importierung von WordPress-Sicherungskopien","Automatisierte Datenbankverwaltung","URL-Ersetzung und wp-content-Synchronisation","Kompatibilität mit Duplicator, Jetpack Backup und Solid Backups"],"pt":["Modo push para migração de sites via SSH","Modo archive para importação de arquivos de backup","Tratamento automático de banco de dados","Substituição de URLs","Sincronização de wp-content"],"ru":["Режим push для миграции сайтов через SSH","Режим archive для импорта архивов резервного копирования","Автоматическое xử lý базы данных","Замена URL","Синхронизация wp-content"],"ar":["وضع دفع لمهاجرة مواقع عبر SSH","وضع أرشيف لاستيراد أرشيفات النسخ الاحتياطي","معالجة 자동ة لقاعدة البيانات","استبدال URLs","مزامنة wp-content"]},"keywords":{"en":["how to use wp-migrate","wp-migrate setup guide","wp-migrate vs Duplicator","wp-migrate install","what is wp-migrate","wp-migrate alternative","WordPress migration tools","wp-migrate SSH push mode","wp-migrate archive import mode"],"zh":["wp-migrate","WordPress迁移","SSH推送","归档导入","自动数据库处理","URL替换","wp-content同步","AIエージェント","WordPress工具"],"ja":["wp-migrate","WordPress移行","SSHプッシュ","アーカイブインポート","自動データベース処理","URL置換","wp-content同期","AIエージェント","WordPressツール"],"ko":["wp-migrate","워드프레스 마이그레이션","SSH 푸시","아카이브 임포트","자동 데이터베이스 처리","URL 교체","wp-content 동기화","AI 에이전트","워드프레스 툴"],"es":["wp-migrate","migración de WordPress","herramienta de migración","SSH","modo de archivo","manejo de bases de datos","reemplazo de URLs","sincronización de wp-content"],"fr":["wp-migrate","migration de WordPress","outil de migration","SSH","mode d''archive","gestion de base de données","remplacement d''URL","synchronisation de wp-content"],"de":["wp-migrate","WordPress-Migration","Migrationstool","SSH","Archivmodus","Datenbankverwaltung","URL-Ersetzung","wp-content-Synchronisation"],"pt":["wp-migrate","migração wordpress","ssh","importação de arquivos de backup","tratamento de banco de dados","substituição de urls","sincronização de wp-content","ferramenta de linha de comando"],"ru":["wp-migrate","миграция wordpress","ssh","импорт архивов резервного копирования","обработка базы данных","замена url","синхронизация wp-content","командная утилита"],"ar":["wp-migrate","مهاجرة ووردبريس","ssh","استيراد أرشيفات النسخ الاحتياطي","معالجة قاعدة البيانات","استبدال urls","مزامنة wp-content","أداة سطر أوامر"]}},"owner":"BWBama85","repo":"wp-migrate.sh","repoPath":"BWBama85/wp-migrate.sh","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.358Z","topics":[],"category":"community","skillMd":{"name":"wp-migrate","description":"WordPress site migration and deployment using wp-migrate.sh. Use when migrating WordPress sites, syncing databases, managing backups, testing migrations, debugging migration issues, or working with WordPress deployment workflows including Duplicator, Jetpack Backup, and Solid Backups archives. Also use for code modifications, testing, git workflows, PR creation, and release management for this project.","bodyPreview":"# WordPress Migration Skill\n\nThis skill provides expertise for working with the wp-migrate.sh WordPress migration tool.\n\n## Project Overview\n\nwp-migrate.sh is a comprehensive WordPress migration tool that operates in two modes:\n\n1. **Push Mode**: Migrates WordPress sites between servers via SSH (source → destination)\n2. **Archive Mode**: Imports WordPress backup archives (Duplicator, Jetpack Backup, Solid Backups) on destination server\n\n**Current Version**: Check the latest release\n\n```bash\ngit","body":"# WordPress Migration Skill\n\nThis skill provides expertise for working with the wp-migrate.sh WordPress migration tool.\n\n## Project Overview\n\nwp-migrate.sh is a comprehensive WordPress migration tool that operates in two modes:\n\n1. **Push Mode**: Migrates WordPress sites between servers via SSH (source → destination)\n2. **Archive Mode**: Imports WordPress backup archives (Duplicator, Jetpack Backup, Solid Backups) on destination server\n\n**Current Version**: Check the latest release\n\n```bash\ngit describe --tags --abbrev=0  # Get current version from git\n```\n\n**Latest Release**: See [GitHub Releases](https://github.com/BWBama85/wp-migrate.sh/releases/latest)\n\n**Repository**: BWBama85/wp-migrate.sh\n\n**Main Branch**: main\n\n## Core Capabilities\n\n### Migration Modes\n\n#### Push Mode\n- Transfers wp-content and database from source to destination via SSH\n- Enables maintenance mode on both servers during migration\n- Creates timestamped backups before overwriting\n- Performs URL search-replace to align destination domain\n- Excludes object-cache.php to preserve destination caching infrastructure\n- Supports StellarSites managed hosting compatibility (--stellarsites flag)\n\n#### Archive Mode\n- Auto-detects archive format (Duplicator, Jetpack Backup, Solid Backups)\n- Extracts archives to temporary directory\n- Validates disk space (requires 3x archive size)\n- Creates backups of destination database and wp-content before import\n- Automatically aligns table prefixes if different from wp-config.php\n- Performs URL search-replace to align with destination URLs\n- Provides rollback instructions with exact commands\n\n### Key Features\n- **Migration preview with confirmation**: Pre-migration summary with detailed stats and confirmation prompt (v2.6.0)\n- **Rollback command**: Automatic restoration from backups with --rollback flag (v2.6.0)\n- **Progress indicators**: Real-time progress bars for long-running operations when pv is installed (v2.6.0)\n- **Dry-run mode**: Preview all operations without making changes (--dry-run)\n- **Verbose logging**: Show detailed diagnostic information (--verbose)\n- **Trace mode**: Show every command before execution (--trace)\n- **Plugin preservation**: Preserve destination plugins/themes not in source (--preserve-dest-plugins)\n- **StellarSites mode**: Managed hosting compatibility with mu-plugins exclusion (--stellarsites)\n- **Skip search-replace**: Fast migrations that only update home/siteurl options (--no-search-replace)\n- **Automation support**: Skip confirmation prompts with --yes flag for CI/CD (v2.6.0)\n- **Quiet mode**: Suppress progress indicators for non-interactive scripts with --quiet (v2.6.0)\n\n## Common Tasks\n\n### Running Migrations\n\n**Push Mode:**\n```bash\n./wp-migrate.sh --dest-host user@dest.example.com --dest-root /var/www/site\n```\n\n**Archive Mode:**\n```bash\n./wp-migrate.sh --archive /path/to/backup.zip\n./wp-migrate.sh --archive /path/to/backup.tar.gz --archive-type jetpack\n```\n\n**Dry Run:**\n```bash\n./wp-migrate.sh --dest-host user@dest --dest-root /var/www/site --dry-run --verbose\n```\n\n**Rollback (v2.6.0):**\n```bash\n./wp-migrate.sh --rollback  # Auto-detects latest backups\n./wp-migrate.sh --rollback --rollback-backup /path/to/specific/backup  # Specific backup\n./wp-migrate.sh --rollback --yes  # Skip confirmation for automation\n```\n\n**Automation-Friendly (v2.6.0):**\n```bash\n./wp-migrate.sh --archive /path/to/backup.zip --yes --quiet  # CI/CD: skip prompts, no progress bars\n```\n\n### Testing\n\n**Run all tests:**\n```bash\nmake test\n```\n\n**Run specific test:**\n```bash\n./test-wp-migrate.sh\n```\n\n**ShellCheck validation:**\n```bash\nshellcheck wp-migrate.sh\n```\n\n### Development Workflow\n\n#### Code Structure (v2+)\nThe project uses a modular source structure:\n\n```\nsrc/\n├── header.sh           # Shebang, defaults, variable declarations\n├── lib/\n│   ├── core.sh         # Core utilities (log, err, validate_url)\n│   ├── functions.sh    # All other functions\n│   └── adapters/       # Archive format adapters\n│       ├── README.md\n│       ├── duplicator.sh\n│       ├── jetpack.sh\n│       └── solidbackups.sh\n└── main.sh             # Argument parsing and main execution\n```\n\n**IMPORTANT**: Modifications should be made in `src/` files, NOT in `wp-migrate.sh` directly.\n\n#### Build Process\n\nAfter modifying source files:\n```bash\nmake build\n```\n\nThis will:\n1. Run shellcheck on concatenated source\n2. Concatenate src/ files into dist/wp-migrate.sh\n3. Copy to ./wp-migrate.sh (repo root)\n4. Generate SHA256 checksum\n\n#### Pre-commit Hook\nA pre-commit hook prevents committing source changes without rebuilding:\n```bash\nln -s ../../.githooks/pre-commit .git/hooks/pre-commit\n```\n\n### Git Workflow\n\n1. **Branching**: Create from main using descriptive names:\n   - `feature/<slug>` for enhancements\n   - `fix/<slug>` for bug fixes\n   - `docs/<slug>` for documentation\n   - `chore/<slug>` for maintenance\n\n2. **Commits**: Use .gitmessage template format:\n   ```\n   type: short imperative summary\n\n   Longer explanation if needed\n   ```\n\n   Types: feat, fix, docs, chore, refactor, test\n\n3. **Changelog**: Update CHANGELOG.md under [Unreleased] section with every feature or fix\n\n4. **Pull Requests**:\n   - Use .github/pull_request_template.md checklist\n   - Include comprehensive summary based on ALL commits (not just latest)\n   - Include test plan with verification steps\n   - Reference related issues\n\n5. **Merging**: Keep main release-ready with `git merge --no-ff` or squash after review\n\n6. **Releases**: Tag with semantic versioning (e.g., `git tag v2.7.0`)\n\n### Creating Pull Requests\n\nWhen creating PRs, ensure:\n- Review ALL commits in the branch (use `git log main..HEAD` and `git diff main...HEAD`)\n- Summary covers complete scope of changes\n- Test plan verifies all functionality\n- CHANGELOG.md is updated\n- ShellCheck passes\n- Tests pass (make test)\n\n### Common Files to Check\n\n- [wp-migrate.sh](wp-migrate.sh) - Main script (built artifact, don''t edit directly)\n- [src/](src/) - Modular source files (edit these)\n- [src/lib/adapters/](src/lib/adapters/) - Archive format adapters\n- [CHANGELOG.md](CHANGELOG.md) - Version history\n- [README.md](README.md) - User documentation\n- [Makefile](Makefile) - Build and test targets\n- [test-wp-migrate.sh](test-wp-migrate.sh) - Test script\n\n## Troubleshooting Guide\n\n### Common Issues\n\n**Permission Errors on Managed Hosts (StellarSites)**\n- Symptom: \"Permission denied\" when syncing wp-content\n- Solution: Use `--stellarsites` flag to exclude protected mu-plugins\n- Details: Managed hosts protect certain mu-plugins directories (e.g., `stellarsites-cloud`)\n\n**Database Import Fails**\n- Check table prefix alignment (script auto-detects and updates wp-config.php)\n- Verify sufficient disk space (3x archive size for archive mode)\n- Check MySQL max_allowed_packet size for large imports\n\n**URL Search-Replace Issues**\n- Use `--verbose` to see detected URLs\n- Override with `--dest-home-url` or `--dest-site-url` if detection fails\n- Use `--no-search-replace` for faster migrations that only need home/siteurl updated\n\n**Archive Detection Fails**\n- Use explicit `--archive-type` to specify format (duplicator, jetpack, solidbackups)\n- Verify archive structure matches adapter expectations (see src/lib/adapters/)\n- Check detailed validation errors with --verbose (v2.6.0+)\n\n**Non-Interactive Context Failures (v2.6.0)**\n- Symptom: Script exits with \"This script requires a TTY for confirmation prompts\"\n- Solution: Add `--yes` flag when running in CI/CD, cron, or pipeline contexts\n- Details: Migration preview and rollback require confirmation by default; use --yes to bypass\n\n**Rollback Issues (v2.6.0)**\n- Auto-detection looks for latest timestamped backups in db-backups/ and wp-content.backup-*\n- If backups aren''t found, use `--rollback-backup /path/to/backup` to specify explicitly\n- Rollback only works for archive mode migrations (restores from local backups)\n\n**SSH Connection Issues**\n- Add custom SSH options with `--ssh-opt` (can be repeated)\n- Examples: `--ssh-opt ''Port=2222''` or `--ssh-opt ''ProxyJump=bastion''`\n\n**ShellCheck Errors**\n- Install ShellCheck: `brew install shellcheck` (macOS) or see https://www.shellcheck.net/\n- Run: `shellcheck wp-migrate.sh`\n- All code must be ShellCheck-clean before merging\n\n### Debugging Commands\n\n**Show verbose migration preview:**\n```bash\n./wp-migrate.sh --dest-host user@dest --dest-root /var/www/site --dry-run --verbose\n```\n\n**Show every command (trace mode):**\n```bash\n./wp-migrate.sh --dest-host user@dest --dest-root /var/www/site --dry-run --trace\n```\n\n**Check archive structure:**\n```bash\nunzip -l /path/to/backup.zip | head -50\ntar -tzf /path/to/backup.tar.gz | head -50\n```\n\n**Verify wp-cli on destination:**\n```bash\nssh user@dest ''cd /var/www/site && wp core version''\n```\n\n## Archive Adapter System\n\nThe script uses an extensible adapter system for different backup formats.\n\n### Supported Formats\n\n1. **Duplicator**: ZIP archives with `dup-installer/dup-database__*.sql` structure\n2. **Jetpack Backup**: ZIP/TAR.GZ archives with `sql/*.sql` multi-file structure\n3. **Solid Backups**: ZIP archives with split SQL in `wp-content/uploads/backupbuddy_temp/{ID}/`\n\n### Adding New Adapters\n\nSee [src/lib/adapters/README.md](src/lib/adapters/README.md) for contributor guide.\n\nEach adapter must implement:\n- `validate_<adapter>()` - Check if file matches format\n- `extract_<adapter>()` - Extract archive to temp directory\n- `detect_db_<adapter>()` - Find database file(s)\n- `detect_wp_content_<adapter>()` - Find wp-content directory\n\n## Best Practices\n\n### When Assisting with Code Changes\n\n1. **Always check if source files need modification** (src/) not wp-migrate.sh directly\n2. **Run `make build` after any source changes** to regenerate wp-migrate.sh\n3. **Run ShellCheck validation** before committing\n4. **Update CHANGELOG.md** for all features and fixes\n5. **Use TodoWrite** to track multi-step tasks\n6. **Create focused PRs** addressing single concerns\n\n### When Testing Migrations\n\n1. **Always start with dry-run** to preview operations\n2. **Use verbose mode** for troubleshooting (--verbose or --trace)\n3. **Verify backups** before destructive operations\n4. **Test rollback procedures** in safe environments\n5. **Check logs** in logs/ directory after migrations\n\n### When Creating Releases\n\n1. **Update CHANGELOG.md** with version number and date\n2. **Create git tag** with semantic version (e.g., v2.7.0)\n3. **Generate GitHub release** with changelog excerpt\n4. **Verify tests pass** on clean checkout\n5. **Update README** if user-facing changes exist\n\n## Common Patterns\n\n### Searching Code\nUse Grep tool for code searches:\n```\npattern: \"function_name\"\noutput_mode: \"content\"\n-n: true (show line numbers)\n```\n\n### Reading Source Files\nUse Read tool for file contents:\n```\nfile_path: /Volumes/personal/codeprojects/bash/wp-migrate/src/lib/functions.sh\n```\n\n### Editing Code\nUse Edit tool for precise changes:\n```\nfile_path: /Volumes/personal/codeprojects/bash/wp-migrate/src/lib/functions.sh\nold_string: \"exact match from file\"\nnew_string: \"replacement text\"\n```\n\n### Running Git Commands\n```bash\ngit status\ngit diff main...HEAD  # See all changes in branch\ngit log main..HEAD    # See all commits in branch\n```\n\n## Critical Reminders\n\n- **NEVER edit wp-migrate.sh directly** - edit files in src/ instead\n- **ALWAYS run `make build`** after source changes\n- **ALWAYS update CHANGELOG.md** for features and fixes\n- **ALWAYS run ShellCheck** before committing (make test)\n- **ALWAYS commit both source AND built files** together\n- **ALWAYS review ALL commits** when creating PRs (not just latest commit)\n- **ALWAYS use TodoWrite** for multi-step tasks to track progress\n"},"lastSynced":"2026-03-08T02:04:06.890Z","agentAnalysis":{"suitability":{"en":"Ideal for WordPress Management Agents requiring seamless site migrations via SSH and archive imports.","zh":"适用于需要通过SSH和存档导入进行无缝站点迁移的WordPress管理代理。","ja":"SSHとアーカイブのインポートを介してシームレスなサイトの移行を必要とするWordPress管理エージェントに適しています。","ko":"SSH와 아카이브 가져오기를 통해 무중단 사이트 마이그레이션을 요구하는 워드프레스 관리 에이전트에 적합합니다.","es":"Ideal para agentes de administración de WordPress que requieren migraciones de sitios sin problemas a través de SSH y importaciones de archivos.","fr":"Idéal pour les agents de gestion de WordPress nécessitant des migrations de sites sans interruption via SSH et des importations d''archives.","de":"Ideal für WordPress-Management-Agenten, die eine reibungslose Migration von Websites über SSH und Archivimporte erfordern.","pt":"Ideal para Agentes de Gerenciamento do WordPress que exigem migrações de site sem interrupção via SSH e importações de arquivos.","ru":"Идеально подходит для агентов управления WordPress, требующих бесперебойных миграций сайтов через SSH и импорт архивов.","ar":"مثالي لعميل إدارة ووردبريس الذي يتطلب انتقالات موقع متواصلة عبر SSH واستيراد الأرشيف."},"recommendation":{"en":"Empowers agents to automate WordPress migrations using SSH push and archive import modes, handling database updates, URL replacements, and wp-content syncing via wp-migrate.sh, supporting formats like Duplicator, Jetpack Backup, and Solid Backups.","zh":"赋予代理自动执行WordPress迁移，使用SSH推送和存档导入模式，处理数据库更新、URL替换和wp-content同步，通过wp-migrate.sh支持Duplicator、Jetpack Backup和Solid Backups等格式。","ja":"エージェントにWordPressの移行を自動化する能力を提供します。SSHプッシュとアーカイブインポートモードを使用して、データベースの更新、URLの置換、wp-contentの同期を処理し、wp-migrate.shを介してDuplicator、Jetpack Backup、Solid Backupsなどの形式をサポートします。","ko":"에이전트가 워드프레스 마이그레이션을 자동화할 수 있도록 하는데, SSH 푸시 및 아카이브 가져오기 모드를 사용하여 데이터베이스 업데이트, URL 교체, wp-content 동기화를 처리하며, wp-migrate.sh를 통해 Duplicator, Jetpack Backup, Solid Backups 등의 형식을 지원합니다.","es":"Permite a los agentes automatizar las migraciones de WordPress utilizando los modos de push SSH y de importación de archivos, manejo de actualizaciones de bases de datos, reemplazos de URL y sincronización de wp-content a través de wp-migrate.sh, compatible con formatos como Duplicator, Jetpack Backup y Solid Backups.","fr":"Permet aux agents d''automatiser les migrations de WordPress en utilisant les modes push SSH et d''importation d''archives, en gérant les mises à jour de bases de données, les remplacements d''URL et la synchronisation de wp-content via wp-migrate.sh, prenant en charge des formats tels que Duplicator, Jetpack Backup et Solid Backups.","de":"Ermöglicht es den Agenten, WordPress-Migrationen mithilfe von SSH-Push- und Archivimportmodi zu automatisieren, wobei Datenbankaktualisierungen, URL-Ersetzungen und wp-content-Synchronisierung über wp-migrate.sh durchgeführt werden, und unterstützt Formate wie Duplicator, Jetpack Backup und Solid Backups.","pt":"Habilita os agentes a automatizar as migrações do WordPress usando os modos de push SSH e importação de arquivos, lidando com atualizações de banco de dados, substituições de URL e sincronização do wp-content via wp-migrate.sh, suportando formatos como Duplicator, Jetpack Backup e Solid Backups.","ru":"Позволяет агентам автоматизировать миграции WordPress, используя режимы push SSH и импорт архивов, обрабатывая обновления базы данных, замену URL и синхронизацию wp-content через wp-migrate.sh, поддерживая форматы, такие как Duplicator, Jetpack Backup и Solid Backups.","ar":"تمكّن الوكلاء من تutomatizar عمليات نقل ووردبريس باستخدام أوضاع دفع SSH واستيراد الأرشيف، وتتعامل مع تحديثات قاعدة البيانات واستبدال عناوين URL وتنسيق wp-content عبر wp-migrate.sh، ودعم تنسيقات مثل Duplicator و Jetpack Backup و Solid Backups."},"useCases":{"en":["Migrating WordPress sites between servers via SSH","Importing WordPress backup archives on destination servers","Automating database updates and URL replacements during migration"],"zh":["通过SSH在服务器之间迁移WordPress站点","在目标服务器上导入WordPress备份存档","在迁移期间自动执行数据库更新和URL替换"],"ja":["SSHを介してサーバー間でWordPressサイトを移行する","宛先サーバーでWordPressバックアップアーカイブをインポートする","移行中にデータベースの更新とURLの置換を自動化する"],"ko":["SSH를 통해 서버 간 워드프레스 사이트 마이그레이션","목적지 서버에서 워드프레스 백업 아카이브 가져오기","마이그레이션期间 데이터베이스 업데이트와 URL 교체 자동화"],"es":["Migrar sitios de WordPress entre servidores a través de SSH","Importar archivos de copia de seguridad de WordPress en servidores de destino","Automatizar actualizaciones de bases de datos y reemplazos de URL durante la migración"],"fr":["Migrer des sites WordPress entre des serveurs via SSH","Importer des archives de sauvegarde de WordPress sur des serveurs de destination","Automatiser les mises à jour de bases de données et les remplacements d''URL pendant la migration"],"de":["WordPress-Websites zwischen Servern über SSH migrieren","WordPress-Sicherungsdateien auf Zielservern importieren","Datenbankaktualisierungen und URL-Ersetzungen während der Migration automatisieren"],"pt":["Migrar sites do WordPress entre servidores via SSH","Importar arquivos de backup do WordPress em servidores de destino","Automatizar atualizações de banco de dados e substituições de URL durante a migração"],"ru":["Миграция сайтов WordPress между серверами через SSH","Импорт архивов резервного копирования WordPress на целевые серверы","Автоматизация обновлений базы данных и замены URL-адресов во время миграции"],"ar":["نقل مواقع ووردبريس بين الخوادم عبر SSH","استيراد أرشيفات النسخ الاحتياطي لوردبريس على خوادم الوجهة","توفير تحديثات قاعدة البيانات واستبدال عناوين URL أثناء النقل"]},"limitations":{"en":["Requires SSH access for push mode","Limited to WordPress migrations only","Dependent on wp-migrate.sh tool"],"zh":["需要SSH访问以进行推送模式","仅限WordPress迁移","依赖于wp-migrate.sh工具"],"ja":["プッシュモードにSSHアクセスが必要","WordPressの移行のみに限定される","wp-migrate.shツールに依存する"],"ko":["푸시 모드에 SSH 액세스가 필요","워드프레스 마이그레이션만 해당","wp-migrate.sh 툴에 의존"],"es":["Requiere acceso SSH para el modo push","Limitado a migraciones de WordPress solo","Dependiente de la herramienta wp-migrate.sh"],"fr":["Nécessite un accès SSH pour le mode push","Limité aux migrations de WordPress uniquement","Dépendant de l''outil wp-migrate.sh"],"de":["Benötigt SSH-Zugriff für den Push-Modus","Begrenzt auf WordPress-Migrationen nur","Abhängig vom Tool wp-migrate.sh"],"pt":["Exige acesso SSH para o modo de push","Limitado apenas às migrações do WordPress","Dependente da ferramenta wp-migrate.sh"],"ru":["Требует доступа SSH для режима push","Ограничен только миграциями WordPress","Зависит от инструмента wp-migrate.sh"],"ar":["يتطلب الوصول إلى SSH للوضع الدفع","محدود بنقل ووردبريس فقط","يعتمد على أداة wp-migrate.sh"]},"version":4},"contentHash":"ef1e5b04d63389b0a12ebe61d71cfddb33ba3831d8fb8c8ea9f77142dc915c92","qualityScore":42}');
