INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('BWBama85/wp-migrate.sh/wp-migrate', 'wp-migrate', 'BWBama85', 'wp-migrate.sh', 'community', 'wp-migrate BWBama85 wp-migrate.sh community The wp-migrate skill provides automated WordPress migration expertise, supporting SSH push and archive import modes for developers. It handles database updates, URL replacements, and wp-content syncing. wp-migrate.sh是一种强大的WordPress迁移工具，支持SSH推送和归档导入两种模式 wp-migrate.shは、SSHプッシュとアーカイブインポートの2つのモードをサポートする包括的なWordPress移行ツールです wp-migrate.sh는 SSH 푸시 및 아카이브 임포트의 2가지 모드를 지원하는 포괄적인 워드프레스 마이그레이션 툴입니다 wp-migrate es una herramienta de migración de WordPress que admite SSH y modos de archivo con manejo de bases de datos automatizado wp-migrate est un outil de migration de WordPress qui prend en charge SSH et les modes d''archive avec une gestion de base de données automatisée wp-migrate ist ein WordPress-Migrationstool, das SSH und Archivmodi mit automatisierter Datenbankverwaltung unterstützt O wp-migrate é uma ferramenta de migração WordPress que suporta modos push e archive, com tratamento automático de banco de dados e substituição de URLs wp-migrate - это инструмент для миграции WordPress, поддерживающий режимы push и archive, с автоматическим xử lý базы данных и заменой URL wp-migrate هو أداة مهاجرة ووردبريس تدعم أوضاع دفع وارشيف، مع معالجة 자동ة لقاعدة البيانات واستبدال URLs how to use wp-migrate wp-migrate setup guide wp-migrate vs Duplicator wp-migrate install what is wp-migrate wp-migrate alternative WordPress migration tools wp-migrate SSH push mode wp-migrate archive import mode wp-migrate WordPress迁移 SSH推送 归档导入 自动数据库处理 URL替换 wp-content同步 AIエージェント WordPress工具 Supports SSH push mode for migrating WordPress sites between servers Enables archive import mode for importing WordPress backup archives from Duplicator, Jetpack Backup, and Solid Backups Automates database handling for seamless migrations Performs URL replacement for updated site URLs Syncs wp-content for consistent site content Utilizes git for version control and updates wp-migrate is a WordPress migration tool that operates in push and archive modes, enabling automated database handling, URL replacement, and wp-content synchronization.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mave99a/ClaudeMobilePlayground/novel-creator', 'community', 'mave99a', 'ClaudeMobilePlayground', 'mave99a/ClaudeMobilePlayground', 'novel-creator', 0, 0, 42, '2026-03-08T01:57:15.361Z', '2026-03-08T02:04:15.997Z', '7e6bb05588a0ca66fd8eeaddfccd96bb9ff93b6ac8c0e74ebc605b2822cb5151', '{"id":"mave99a/ClaudeMobilePlayground/novel-creator","name":"novel-creator","description":{"en":"novel-creator transforms story ideas into complete novels with EPUB output through an interactive RPG-style workflow, benefiting writers and authors. It guides users from story concept to EPUB generation.","zh":"novel-creator 技术通过交互式 RPG 风格的工作流程，将故事创意转化为完整的小说，输出 EPUB 格式","ja":"novel-creator AIエージェントはインタラクティブな RPG スタイルのワークフローで小説を作成し、EPUB 出力する","ko":"novel-creator는 인터랙티브 워크플로우를 통해 EPUB 소설을 생성합니다","es":"Novel Creator es una herramienta que transforma ideas en novelas completas con salida EPUB a través de un flujo de trabajo interactivo de estilo RPG","fr":"Novel Creator est un outil qui transforme des idées en romans complets avec sortie EPUB via un workflow interactif de style RPG","de":"Novel Creator ist ein Tool, das Ideen in Romane mit EPUB-Ausgabe durch einen interaktiven RPG-Style-Workflow verwandelt","pt":"O Novel Creator é uma ferramenta que transforma ideias em romances completos com saída EPUB através de um fluxo de trabalho interativo de estilo RPG","ru":"ИИ Агент Novel Creator - это инструмент, который превращает идеи в романы с помощью интерактивного рабочего процесса в стиле RPG и выводом в формате EPUB","ar":"Novel Creator هو أداة تحول الأفكار إلى روايات كاملة مع إخراج EPUB من خلال تدفق عمل تفاعلي على غرار ألعاب RPG"},"seo":{"title":{"en":"novel-creator: Transform Story Ideas into EPUB Novels | A...","zh":"novel-creator 技术指南：将故事创意转化为 EPUB 小说","ja":"novel-creator AIエージェント：インタラクティブな RPG スタイルで小説を作成","ko":"novel-creator 개발자 가이드：EPUB 소설 생성을 위한 인터랙티브 워크플ロー","es":"Guía de Configuración de Novel Creator: Transforma Ideas ...","fr":"Guide de Configuration de Novel Creator: Créez des Romans...","de":"Einrichtungsleitfaden für Novel Creator: Verwandeln Sie I...","pt":"Guia de Configuração do Novel Creator: Transforme Ideias ...","ru":"ИИ Агент Novel Creator: Руководство по Созданию Романов","ar":"دليل إنشاء رواية مع Novel Creator: تحويل الأفكار إلى رواي..."},"description":{"en":"Unlock your creativity with novel-creator! Discover how to turn story ideas into complete novels with interactive RPG-style workflow and EPUB output. Get sta...","zh":"使用 novel-creator 技术将故事创意转化为完整的小说，输出 EPUB 格式，体验交互式 RPG 风格的写作流程","ja":"novel-creator AIエージェントを使用して、小説をインタラクティブな RPG スタイルで作成し、EPUB 出力が可能","ko":"novel-creator를 사용하여 EPUB 소설을 생성하는 인터랙티브 워크플ロー와 기술적인 세부사항을 알아보세요","es":"Aprende a utilizar Novel Creator para transformar ideas en novelas completas con salida EPUB a través de un flujo de trabajo interactivo de estilo RPG","fr":"Découvrez comment utiliser Novel Creator pour créer des romans complets avec sortie EPUB via un workflow interactif de style RPG","de":"Erfahren Sie, wie Sie Novel Creator verwenden, um Ideen in Romane mit EPUB-Ausgabe durch einen interaktiven RPG-Style-Workflow zu verwandeln","pt":"Aprenda a usar o Novel Creator para transformar ideias em romances completos com saída EPUB através de um fluxo de trabalho interativo de estilo RPG","ru":"Узнайте, как использовать ИИ Агент Novel Creator для создания романов с помощью интерактивного рабочего процесса в стиле RPG и выводом в формате EPUB","ar":"اكتشف كيفية استخدام Novel Creator لتحويل الأفكار إلى روايات كاملة مع إخراج EPUB من خلال تدفق عمل تفاعلي على غرار ألعاب RPG"},"definition":{"en":"novel-creator is an AI agent skill that transforms story ideas into complete novels with EPUB output through a phased workflow, including story setup, interactive RPG, writing plan, chapters, and EPUB generation.","zh":"novel-creator 是一种技术，通过交互式 RPG 风格的工作流程，将故事创意转化为完整的小说","ja":"novel-creator AIエージェントは、小説を作成するためのインタラクティブな RPG スタイルのワークフローを提供する","ko":"novel-creator는 EPUB 소설 생성을 위한 인터랙티브 워크플로우 기술입니다","es":"Novel Creator es una herramienta de creación de novelas que utiliza un flujo de trabajo interactivo de estilo RPG para generar historias","fr":"Novel Creator est un outil de création de romans qui utilise un workflow interactif de style RPG pour générer des histoires","de":"Novel Creator ist ein Tool zur Erstellung von Romanen, das einen interaktiven RPG-Style-Workflow zur Generierung von Geschichten verwendet","pt":"O que é Novel Creator? É uma ferramenta que ajuda a criar romances completos com saída EPUB","ru":"Что такое ИИ Агент Novel Creator? Это инструмент, который помогает создавать романы с помощью интерактивного рабочего процесса","ar":"ما هو Novel Creator؟ هو أداة تساعد على إنشاء روايات كاملة مع إخراج EPUB"},"features":{"en":["Utilizes AskUserQuestion tool to gather story elements such as genre and setting","Supports interactive RPG-style workflow for immersive story development","Generates writing plans and chapters based on user input","Produces EPUB output for easy sharing and publishing","Guides users through a phased workflow, from story concept to EPUB generation"],"zh":["交互式 RPG 风格的工作流程","支持多种类型的故事创意","输出 EPUB 格式的小说","使用 AskUserQuestion 工具收集故事元素","支持 Ancient palace 和 Modern 等多种场景设置"],"ja":["インタラクティブな RPG スタイルのワークフロー","多種のジャンルの物語創作をサポート","EPUB 出力に対応","AskUserQuestion ツールを使用して物語の要素を収集","Ancient palace や Modern などの複数のシーン設定をサポート"],"ko":["인터랙티브 워크플로우","다양한 장르의 소설 생성 지원","EPUB 출력 지원","AskUserQuestion 도구를 사용하여 소설 요소를 수집","Ancient palace 및 Modern 등의 여러 장면 설정 지원"],"es":["Flujo de trabajo interactivo de estilo RPG","Salida EPUB para novelas completas","Herramienta AskUserQuestion para recopilar información","Opciones de configuración para género y entorno","Generación de planes de escritura y capítulos"],"fr":["Workflow interactif de style RPG","Sortie EPUB pour des romans complets","Outil AskUserQuestion pour collecter des informations","Options de configuration pour le genre et l''environnement","Génération de plans d''écriture et de chapitres"],"de":["Interaktiver RPG-Style-Workflow","EPUB-Ausgabe für Romane","AskUserQuestion-Tool zur Informationsbeschaffung","Konfigurationsmöglichkeiten für Genre und Umgebung","Erstellung von Schreibplänen und Kapiteln"],"pt":["Fluxo de trabalho interativo de estilo RPG","Saída EPUB para romances completos","Ferramenta AskUserQuestion para coletar informações","Opções de gênero e configuração para personalizar a história","Criação de capítulos e planos de escrita"],"ru":["Интерактивный рабочий процесс в стиле RPG","Вывод в формате EPUB для романов","Инструмент AskUserQuestion для сбора информации","Варианты жанра и настройки для персонализации истории","Создание глав и планов написания"],"ar":["تدفق عمل تفاعلي على غرار ألعاب RPG","إخراج EPUB للروايات الكاملة","أداة AskUserQuestion لجمع المعلومات","خيارات للنوع والتصميم لتحديد القصة","إنشاء الفصول وخطط الكتابة"]},"keywords":{"en":["how to use novel-creator","novel-creator setup guide","novel-creator alternative","EPUB novel generation","interactive RPG-style workflow","story idea transformation","novel-creator install","novel-creator vs writing software","what is novel-creator"],"zh":["novel-creator 技术","交互式 RPG 风格","EPUB 小说生成","AskUserQuestion 工具","故事创意转化","小説創作","AI エージェント"],"ja":["novel-creator AIエージェント","インタラクティブな RPG スタイル","EPUB 小説生成","AskUserQuestion ツール","物語創作","小説作成","AI エージェント"],"ko":["novel-creator 기술","인터랙티브 워크플로우","EPUB 소설 생성","AskUserQuestion 도구","소설 생성","AI 에이전트","개발자 가이드"],"es":["herramientas de creación de novelas","Novel Creator","flujo de trabajo interactivo","salida EPUB","AskUserQuestion","creación de historias","desarrollo de novelas","Herramientas de escritura","agentes de IA para escritores"],"fr":["outils de création de romans","Novel Creator","workflow interactif","sortie EPUB","AskUserQuestion","création d''histoires","développement de romans","Outils d''écriture","agents IA pour écrivains"],"de":["Romangerätewerkzeuge","Novel Creator","interaktiver Workflow","EPUB-Ausgabe","AskUserQuestion","Geschichtenerstellung","Romanentwicklung","Schreibwerkzeuge","KI-Agenten für Schriftsteller"],"pt":["Novel Creator","criação de romances","ferramentas de escrita","fluxo de trabalho interativo","saída EPUB","AskUserQuestion","gênero e configuração","capítulos e planos de escrita"],"ru":["ИИ Агент Novel Creator","создание романов","инструменты для написания","интерактивный рабочий процесс","вывод в формате EPUB","AskUserQuestion","жанр и настройка","главы и планы написания"],"ar":["Novel Creator","إنشاء روايات","أدوات الكتابة","تدفق عمل تفاعلي","إخراج EPUB","AskUserQuestion","النوع والتصميم","الفصول وخطط الكتابة"]}},"owner":"mave99a","repo":"ClaudeMobilePlayground","repoPath":"mave99a/ClaudeMobilePlayground","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.361Z","topics":[],"category":"community","skillMd":{"name":"novel-creator","description":"|","bodyPreview":"# Novel Creator\n\nTransform story ideas into complete novels with EPUB output through an interactive RPG-style workflow.\n\n## Workflow\n\n```\n[Story Concept] → [Interactive RPG] → [Writing Plan] → [Chapters] → [EPUB]\n     Phase 1           Phase 2           Phase 3        Phase 4     Phase 5\n```\n\n## Phase 1: Story Setup\n\nUse `AskUserQuestion` tool to gather:\n\n| Element | Options | Default |\n|---------|---------|---------|\n| Genre | 穿越/Fantasy/Romance/Mystery | 穿越 |\n| Setting | Ancient palace/Modern/","body":"# Novel Creator\n\nTransform story ideas into complete novels with EPUB output through an interactive RPG-style workflow.\n\n## Workflow\n\n```\n[Story Concept] → [Interactive RPG] → [Writing Plan] → [Chapters] → [EPUB]\n     Phase 1           Phase 2           Phase 3        Phase 4     Phase 5\n```\n\n## Phase 1: Story Setup\n\nUse `AskUserQuestion` tool to gather:\n\n| Element | Options | Default |\n|---------|---------|---------|\n| Genre | 穿越/Fantasy/Romance/Mystery | 穿越 |\n| Setting | Ancient palace/Modern/Fantasy world | Palace |\n| Protagonist | Name, background, abilities | - |\n| Goal | What to achieve | Survive and thrive |\n| Length | Chapters × words | 10 × 5000 |\n\nLoad character personas from `references/personas.md` based on setting.\n\n## Phase 2: Interactive RPG\n\nRun 10-15 decision points where user makes choices via `AskUserQuestion`:\n\n```\n[Vivid scene description]\n↓\nAskUserQuestion with 3-4 meaningful choices\n↓\n[Consequence + next scene]\n```\n\n**Required elements to weave in:**\n- **Tech/Knowledge**: Modern knowledge as \"magic\" (phone→照妖镜, chemistry→炼丹)\n- **Fantasy**: Special abilities (灵觉), artifacts (蓄雷珠), prophecies\n- **Romance**: First meeting → mutual help → feelings → confession\n\n**Track throughout:**\n- Key plot points and decisions\n- Relationship development stages\n- Items and abilities acquired\n- Foreshadowing seeds planted\n\n## Phase 3: Writing Plan\n\nCreate `task_plan.md` with:\n\n```markdown\n# Writing Plan: [Title]\n\n## Characters\n| Name | Role | Traits | Arc |\n|------|------|--------|-----|\n\n## Foreshadowing Matrix\n| Element | Ch.1 Hint | Development | Payoff |\n|---------|-----------|-------------|--------|\n| Tech | [seed] | Ch.4 [use] | Ch.9 [climax] |\n| Fantasy | [seed] | Ch.6 [reveal] | Ch.9 [power] |\n| Romance | [meeting] | Ch.5 [feelings] | Ch.10 [love] |\n\n## Poetry Pairings (Chinese novels)\n| Ch | Ancient Poetry | Modern Lyrics | Theme |\n|----|----------------|---------------|-------|\nSee references/poetry_pairs.md for suggestions.\n\n## Chapter Outline\n- [ ] Ch.1: [title] - [key scenes, ~5000 words]\n...\n\n## Progress\n| Ch | Status | Words |\n|----|--------|-------|\n```\n\n## Phase 4: Chapter Writing\n\nWrite each chapter (~4000-5500 words) following this structure:\n\n```markdown\n# 第X章：[押韵标题]\n\n> *[Ancient poetry quote]*\n> *——[Author]《[Title]》*\n\n---\n\n## 一\n[Scene 1: Setting + action]\n\n## 二\n[Scene 2: Dialogue + conflict]\n\n## 三\n[Scene 3: Resolution + hook]\n\n---\n\n（第X章完）\n\n---\n\n> *\"[Modern lyrics quote]\"*\n> *——《[Song]》*\n```\n\n**Writing checklist:**\n- [ ] Vivid sensory descriptions (sight, sound, smell, touch)\n- [ ] Dialogue with subtext (what''s said vs. what''s meant)\n- [ ] Internal monologue showing modern perspective\n- [ ] Proper pacing (action → dialogue → reflection)\n- [ ] Foreshadowing elements per plan\n- [ ] Chapter-end hook\n\n**File naming:** `[##]_[章节标题].md` (e.g., `01_梦回千年惊鸿起.md`)\n\nUpdate `task_plan.md` progress after each chapter.\n\n## Phase 5: EPUB Generation\n\nRun:\n```bash\npython3 scripts/create_epub.py\n```\n\nScript auto-detects chapter files in current directory and generates:\n- Cover page with title/subtitle/author\n- Introduction page\n- All chapters with proper formatting\n- Table of contents\n- Chinese typography CSS\n\nOutput: `[书名].epub`\n\n## Quick Commands\n\n| User says | Action |\n|-----------|--------|\n| \"写一部穿越小说\" | Full workflow Phase 1-5 |\n| \"根据大纲写小说\" + outline | Phase 3-5 |\n| \"把章节转成epub\" | Phase 5 only |\n| \"继续写下一章\" | Resume Phase 4 |\n\n## Resources\n\n- `scripts/create_epub.py` - EPUB generator\n- `references/personas.md` - Character templates by setting\n- `references/poetry_pairs.md` - Poetry and lyrics pairings\n"},"lastSynced":"2026-03-08T02:04:15.997Z","agentAnalysis":{"suitability":{"en":"Perfect for Creative Writing Agents needing interactive storytelling and EPUB generation capabilities.","zh":"适合需要交互式讲故事和EPUB生成功能的创意写作代理。","ja":"インタラクティブな物語やEPUB生成機能を必要とするクリエイティブ・ライティング・エージェントに最適です。","ko":"대화형 스토리 텔링과 EPUB 생성 기능이 필요한 크리에이티브 글쓰기 에이전트에게 완벽합니다.","es":"Perfecto para agentes de escritura creativa que necesitan capacidades de narrativa interactiva y generación de EPUB.","fr":"Parfait pour les agents d''écriture créative ayant besoin de capacités de narration interactive et de génération d''EPUB.","de":"Perfekt für kreative Schreibagenten, die interaktive Erzählungen und EPUB-Generierungsfunktionen benötigen.","pt":"Perfeito para Agentes de Escrita Criativa que necessitam de capacidades de narrativa interativa e geração de EPUB.","ru":"Идеально для Креативных Литературных Агентов, которым необходимы интерактивные возможности рассказывания и генерации EPUB.","ar":"مثالي للوكلاء الكتابية الإبداعية الذين يحتاجون إلى khảيات السرد التفاعلي وتوليد EPUB."},"recommendation":{"en":"Empowers agents to transform story ideas into complete novels using an interactive RPG-style workflow, generating EPUB output and leveraging tools like AskUserQuestion for user input, supporting genres such as Fantasy, Romance, and Mystery.","zh":"赋予代理将故事创意转化为完整的小说，使用类似RPG的交互式工作流程，生成EPUB输出，并利用AskUserQuestion等工具获取用户输入，支持奇幻、浪漫、悬疑等类型。","ja":"エージェントが物語のアイデアを完全な小説に変えることができるようにし、インタラクティブなRPGスタイルのワークフローを使用してEPUB出力を生成し、AskUserQuestionなどのツールを使用してユーザーの入力をサポートし、ファンタジー、ロマンス、ミステリーなどのジャンルをサポートします。","ko":"에이전트가 스토리 아이디어를 완성된 소설로 변환할 수 있도록 강화하며, 대화형 RPG 스타일 워크플로우를 사용하여 EPUB 출력을 생성하고, AskUserQuestion과 같은 도구를 사용하여 사용자 입력을 지원하며, 판타지, 로맨스, 미스터리 등의 장르를 지원합니다.","es":"Habilita a los agentes a transformar ideas de historias en novelas completas utilizando un flujo de trabajo interactivo de estilo RPG, generando salida de EPUB y aprovechando herramientas como AskUserQuestion para la entrada del usuario, y admitiendo géneros como Fantasía, Romance y Misterio.","fr":"Permet aux agents de transformer des idées d''histoires en romans complets en utilisant un flux de travail interactif de style RPG, générant une sortie EPUB et exploitant des outils comme AskUserQuestion pour la saisie utilisateur, et prenant en charge des genres tels que Fantasy, Romance et Mystery.","de":"Ermächtigt Agenten, Storyideen in vollständige Romane mithilfe eines interaktiven RPG-Style-Arbeitsablaufs umzuwandeln, EPUB-Ausgaben zu generieren und Tools wie AskUserQuestion für die Benutzereingabe zu nutzen, und unterstützt Genres wie Fantasy, Romance und Mystery.","pt":"Habilita os agentes a transformar ideias de história em romances completos usando um fluxo de trabalho interativo de estilo RPG, gerando saída EPUB e aproveitando ferramentas como AskUserQuestion para entrada do usuário, suportando gêneros como Fantasia, Romance e Mistério.","ru":"Наделяет агентов возможностью превращать идеи историй в полноценные романы, используя интерактивный рабочий процесс в стиле RPG, генерируя выходные данные EPUB и используя инструменты, такие как AskUserQuestion, для ввода пользователя, поддерживая жанры, такие как Фэнтези, Роман и Детектив.","ar":"يمنح الوكلاء القدرة على تحويل أفكار القصة إلى روايات كاملة باستخدام تدفق عمل تفاعلي على غرار لعبة الأدوار، مع توليد مخرجات EPUB والاستفادة من أدوات مثل AskUserQuestion لإدخال المستخدم، ودعم الأنواع مثل الخيال والرومانسية والغموض."},"useCases":{"en":["Generating novels from story concepts","Creating interactive writing plans","Exporting finished novels in EPUB format"],"zh":["从故事概念生成小说","创建交互式写作计划","以EPUB格式导出完成的小说"],"ja":["物語のコンセプトから小説を生成する","インタラクティブなライティング・プランを作成する","完成した小説をEPUB形式でエクスポートする"],"ko":["스토리 개념에서 소설을 생성하는 것","대화형 글쓰기 계획을 만드는 것","完成된 소설을 EPUB 형식으로 내보내기"],"es":["Generación de novelas a partir de conceptos de historias","Creación de planes de escritura interactivos","Exportación de novelas terminadas en formato EPUB"],"fr":["Génération de romans à partir de concepts d''histoires","Création de plans d''écriture interactifs","Exportation de romans terminés au format EPUB"],"de":["Generierung von Romanen aus Storykonzepten","Erstellung interaktiver Schreibpläne","Export von fertigen Romanen im EPUB-Format"],"pt":["Geração de romances a partir de conceitos de histórias","Criação de planos de escrita interativos","Exportação de romances concluídos no formato EPUB"],"ru":["Генерация романов из концепций историй","Создание интерактивных планов написания","Экспорт завершенных романов в формате EPUB"],"ar":["توليد الروايات من مفاهيم القصة","إنشاء خطط كتابية تفاعلية","تصدير الروايات المنتهية في شكل EPUB"]},"limitations":{"en":["Requires user input for story setup","Limited to EPUB output format","Dependent on interactive RPG-style workflow for novel creation"],"zh":["需要用户输入来设置故事","仅限EPUB输出格式","依赖于交互式RPG风格的工作流程来创建小说"],"ja":["物語の設定にはユーザーの入力が必要","EPUB出力形式のみをサポート","小説の作成にはインタラクティブなRPGスタイルのワークフローに依存"],"ko":["스토리 설정을 위해 사용자 입력이 필요","EPUB 출력 형식만 지원","소설 생성을 위해 대화형 RPG 스타일 워크플로우에 의존"],"es":["Requiere entrada del usuario para la configuración de la historia","Limitado al formato de salida EPUB","Dependiente del flujo de trabajo interactivo de estilo RPG para la creación de novelas"],"fr":["Nécessite une saisie utilisateur pour la configuration de l''histoire","Limité au format de sortie EPUB","Dépendant du flux de travail interactif de style RPG pour la création de romans"],"de":["Benutzereingabe für die Storyeinrichtung erforderlich","Begrenzt auf das EPUB-Ausgabeformat","Abhängig vom interaktiven RPG-Style-Arbeitsablauf für die Romanerstellung"],"pt":["Requer entrada do usuário para configuração da história","Limitado ao formato de saída EPUB","Dependente do fluxo de trabalho interativo de estilo RPG para criação de romances"],"ru":["Требует ввода пользователя для настройки истории","Ограничен выходным форматом EPUB","Зависит от интерактивного рабочего процесса в стиле RPG для создания романов"],"ar":["يتطلب إدخال المستخدم لإعداد القصة","محدود بالتنسيق المخرج EPUB","يعتمد على تدفق العمل التفاعلي على غرار لعبة الأدوار لإنشاء الروايات"]},"version":4},"contentHash":"7e6bb05588a0ca66fd8eeaddfccd96bb9ff93b6ac8c0e74ebc605b2822cb5151","qualityScore":42}');
