INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mave99a/ClaudeMobilePlayground/novel-creator', 'novel-creator', 'mave99a', 'ClaudeMobilePlayground', 'community', 'novel-creator mave99a ClaudeMobilePlayground community novel-creator transforms story ideas into complete novels with EPUB output through an interactive RPG-style workflow, benefiting writers and authors. It guides users from story concept to EPUB generation. novel-creator 技术通过交互式 RPG 风格的工作流程，将故事创意转化为完整的小说，输出 EPUB 格式 novel-creator AIエージェントはインタラクティブな RPG スタイルのワークフローで小説を作成し、EPUB 出力する novel-creator는 인터랙티브 워크플로우를 통해 EPUB 소설을 생성합니다 Novel Creator es una herramienta que transforma ideas en novelas completas con salida EPUB a través de un flujo de trabajo interactivo de estilo RPG Novel Creator est un outil qui transforme des idées en romans complets avec sortie EPUB via un workflow interactif de style RPG Novel Creator ist ein Tool, das Ideen in Romane mit EPUB-Ausgabe durch einen interaktiven RPG-Style-Workflow verwandelt O Novel Creator é uma ferramenta que transforma ideias em romances completos com saída EPUB através de um fluxo de trabalho interativo de estilo RPG ИИ Агент Novel Creator - это инструмент, который превращает идеи в романы с помощью интерактивного рабочего процесса в стиле RPG и выводом в формате EPUB Novel Creator هو أداة تحول الأفكار إلى روايات كاملة مع إخراج EPUB من خلال تدفق عمل تفاعلي على غرار ألعاب RPG how to use novel-creator novel-creator setup guide novel-creator alternative EPUB novel generation interactive RPG-style workflow story idea transformation novel-creator install novel-creator vs writing software what is novel-creator novel-creator 技术 交互式 RPG 风格 EPUB 小说生成 AskUserQuestion 工具 故事创意转化 小説創作 AI エージェント Utilizes AskUserQuestion tool to gather story elements such as genre and setting Supports interactive RPG-style workflow for immersive story development Generates writing plans and chapters based on user input Produces EPUB output for easy sharing and publishing Guides users through a phased workflow, from story concept to EPUB generation novel-creator is an AI agent skill that transforms story ideas into complete novels with EPUB output through a phased workflow, including story setup, interactive RPG, writing plan, chapters, and EPUB generation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Intellifill/IntelliFill/zustand-store', 'community', 'Intellifill', 'IntelliFill', 'Intellifill/IntelliFill', 'zustand-store', 0, 0, 42, '2026-03-08T01:57:15.361Z', '2026-03-08T02:04:16.108Z', '450093c04cb9dc4873076a2ef26f9a72f11abe4be9919abc22714ee64b9571c2', '{"id":"Intellifill/IntelliFill/zustand-store","name":"zustand-store","description":{"en":"The zustand-store skill provides guidance for creating Zustand stores in the IntelliFill frontend, benefiting developers with comprehensive store architecture and automation capabilities.","zh":"Zustand Store是一种智能文档处理和表单自动化平台，提供综合的前端开发指导","ja":"Zustand Storeは、インテリフィルフロントエンドでZustandストアを作成するための包括的なガイダンスを提供する","ko":"Zustand Store는 지능형 문서 처리 및 형식 자동화 플랫폼으로, 전면 개발을 위한 포괄적인 가이드를 제공","es":"Zustand Store es una plataforma de procesamiento de documentos inteligentes y automatización de formularios para IntelliFill. Ofrece una arquitectura de tienda escalable y flexible.","fr":"Zustand Store est une plateforme de traitement de documents intelligents et d''automatisation de formulaires pour IntelliFill. Elle offre une architecture de magasin évolutible et flexible.","de":"Zustand Store ist eine Plattform für intelligente Dokumentenverarbeitung und Formularautomatisierung für IntelliFill. Sie bietet eine skalierbare und flexible Store-Architektur.","pt":"O Zustand Store é uma plataforma de processamento de documentos inteligentes e automação de formulários que fornece orientação abrangente para criar lojas Zustand","ru":"Zustand Store — это платформа интеллектуальной обработки документов и автоматизации форм, которая предоставляет всестороннее руководство по созданию магазинов Zustand","ar":"Zustand Store هو منصة لمعالجة الوثائق الذكية وآلية الاستمارة التي توفر إرشادات شاملة لإنشاء مخازن Zustand"},"seo":{"title":{"en":"zustand-store: Comprehensive Setup Guide for AI Agents","zh":"Zustand Store Setup Guide - AI智能工具","ja":"Zustand Store ベストプラクティス - AIエージェント","ko":"Zustand Store 개발 가이드 - AI 에이전트","es":"Guía de configuración de Zustand Store para IntelliFill","fr":"Guide de configuration de Zustand Store pour IntelliFill","de":"Zustand Store Einrichtungsleitfaden für IntelliFill","pt":"Guia de Configuração do Zustand Store para Desenvolvedores","ru":"ИИ Агенты: Настройка Zustand Store для Разработчиков","ar":"دليل إعداد Zustand Store لِمُطوِّري البرمجيات"},"description":{"en":"Unlock efficient document processing with zustand-store. Learn how to create scalable stores and automate forms with our expert guide and start building today!","zh":"了解Zustand Store的架构、模式和最佳实践，优化您的前端开发","ja":"Zustand Storeのアーキテクチャ、パターン、ミドルウェアスタックをマスターして、フロントエンド開発を最適化","ko":"Zustand Store의 구조, 패턴, 미들웨어 스택을 이해하고, 프론트엔드 개발을 최적화","es":"Aprende a crear tiendas Zustand en IntelliFill con nuestra guía paso a paso sobre arquitectura de tiendas, patrones básicos y más","fr":"Découvrez comment créer des magasins Zustand dans IntelliFill avec notre guide étape par étape sur l''architecture des magasins, les modèles de base et plus","de":"Erfahren Sie, wie Sie Zustand-Stores in IntelliFill erstellen, mit unserer Schritt-für-Schritt-Anleitung zu Store-Architektur, Grundmustern und mehr","pt":"Aprenda a criar lojas Zustand com arquitetura de armazenamento, padrões básicos e middleware para melhorar a eficiência do seu aplicativo","ru":"Узнайте, как создать магазины Zustand с архитектурой хранилища, базовыми шаблонами и стеком middleware для повышения эффективности вашего приложения","ar":"تعلم كيفية إنشاء مخازن Zustand مع هندسة التخزين والنماذج الأساسية وملحقات البرامج الوسيطة لتحسين كفاءة تطبيقك"},"definition":{"en":"zustand-store is an intelligent document processing and form automation platform for creating scalable Zustand stores","zh":"Zustand Store是一种提供Zustand存储创建指导的AI智能工具","ja":"Zustand Storeは、Zustandストアを作成するための包括的なガイダンスを提供するAIエージェント","ko":"Zustand Store는 Zustand 스토어 생성을 위한 포괄적인 가이드를 제공하는 AI 에이전트","es":"Zustand Store es una plataforma de procesamiento de documentos que utiliza una arquitectura de tienda para la automatización de formularios","fr":"Zustand Store est une plateforme de traitement de documents qui utilise une architecture de magasin pour l''automatisation de formulaires","de":"Zustand Store ist eine Plattform für Dokumentenverarbeitung, die eine Store-Architektur für die Formularautomatisierung nutzt","pt":"O que é Zustand Store? É uma plataforma de processamento de documentos que fornece orientação para criar lojas Zustand","ru":"Что такое Zustand Store? Это платформа обработки документов, которая предоставляет руководство по созданию магазинов Zustand","ar":"ما هو Zustand Store؟ هو منصة لمعالجة الوثائق التي توفر إرشادات لإنشاء مخازن Zustand"},"features":{"en":["Implements store architecture with basic store patterns and middleware stacks","Supports selectors and hooks for efficient data management","Enables async actions for seamless form automation","Provides persistence for reliable data storage","Allows testing stores for ensuring scalability and performance"],"zh":["Store Architecture","Basic Store Pattern","Middleware Stack","Selectors and Hooks","Async Actions","Persistence"],"ja":["ストアアーキテクチャ","ベーシックストアパターン","ミドルウェアスタック","セレクタとフック","非同期アクション","永続化"],"ko":["스토어 아키텍처","베이직 스토어 패턴","미들웨어 스택","셀렉터와 훅","비동기 액션","영속성"],"es":["Arquitectura de tienda escalable","Patrón de tienda básico","Pila de middleware","Selectores y hooks","Acciones asíncronas","Persistencia de datos"],"fr":["Architecture de magasin évolutible","Modèle de magasin de base","Pile de middleware","Sélecteurs et hooks","Actions asynchrones","Persistance des données"],"de":["Skalierbare Store-Architektur","Grundmuster für Stores","Middleware-Stack","Selektoren und Hooks","Asynchrone Aktionen","Datenpersistenz"],"pt":["Arquitetura de armazenamento","Padrões básicos de loja","Middleware para otimização","Seletor e ganchos para manipulação de dados","Ações assíncronas para processamento de tarefas","Persistência de dados para armazenamento seguro"],"ru":["Архитектура хранилища","Базовые шаблоны магазина","Стек middleware для оптимизации","Селекторы и крючки для манипуляции данными","Асинхронные действия для обработки задач","ПERSISTENCIA данных для безопасного хранения"],"ar":["هندسة التخزين","نماذج مخزن أساسية","ملحقات البرامج الوسيطة لتحسين الأداء","مختار وخطافات لتعامل البيانات","إجراءات متزامنة لمعالجة المهام","استمرارية البيانات لتخزين آمن"]},"keywords":{"en":["how to use zustand-store","zustand-store setup guide","zustand-store vs redux","zustand-store install","what is zustand-store","zustand-store alternative","zustand-store documentation","zustand-store tutorial","zustand-store example"],"zh":["Zustand Store","AI智能工具","前端开发","Store Architecture","Middleware Stack","Selectors and Hooks","Async Actions","Persistence"],"ja":["Zustand Store","AIエージェント","フロントエンド開発","ストアアーキテクチャ","ミドルウェアスタック","セレクタとフック","非同期アクション","永続化"],"ko":["Zustand Store","AI 에이전트","프론트엔드 개발","스토어 아키텍처","미들웨어 스택","셀렉터와 훅","비동기 액션","영속성"],"es":["zustand store","intellifill","procesamiento de documentos inteligentes","automatización de formularios","arquitectura de tienda","patrón de tienda básico","middleware","selectores y hooks","acciones asíncronas","persistencia de datos"],"fr":["zustand store","intellifill","traitement de documents intelligents","automatisation de formulaires","architecture de magasin","modèle de magasin de base","middleware","sélecteurs et hooks","actions asynchrones","persistance des données"],"de":["zustand store","intellifill","intelligente Dokumentenverarbeitung","Formularautomatisierung","Store-Architektur","Grundmuster für Stores","Middleware","Selektoren und Hooks","asynchrone Aktionen","Datenpersistenz"],"pt":["Zustand Store","desenvolvimento de lojas","arquitetura de armazenamento","padrões básicos de loja","middleware","seletor e ganchos","ações assíncronas","persistência de dados","processamento de documentos inteligentes"],"ru":["Zustand Store","создание магазинов","архитектура хранилища","базовые шаблоны магазина","стек middleware","селекторы и крючки","асинхронные действия","пERSISTENCIA данных","интеллектуальная обработка документов"],"ar":["Zustand Store","إنشاء مخازن","هندسة التخزين","نماذج مخزن أساسية","ملحقات البرامج الوسيطة","مختار وخطافات","إجراءات متزامنة","استمرارية البيانات","معالجة الوثائق الذكية"]}},"owner":"Intellifill","repo":"IntelliFill","repoPath":"Intellifill/IntelliFill","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.361Z","topics":[],"category":"community","skillMd":{"name":"zustand-store","description":"Create Zustand stores for IntelliFill with immer, persist, and devtools middleware. Use when adding state management for new features.","bodyPreview":"# Zustand Store Development Skill\n\nThis skill provides comprehensive guidance for creating Zustand stores in the IntelliFill frontend (`quikadmin-web/`).\n\n## Table of Contents\n\n1. [Store Architecture](#store-architecture)\n2. [Basic Store Pattern](#basic-store-pattern)\n3. [Middleware Stack](#middleware-stack)\n4. [Selectors and Hooks](#selectors-and-hooks)\n5. [Async Actions](#async-actions)\n6. [Persistence](#persistence)\n7. [Testing Stores](#testing-stores)\n8. [Best Practices](#best-practices)\n\n##","body":"# Zustand Store Development Skill\n\nThis skill provides comprehensive guidance for creating Zustand stores in the IntelliFill frontend (`quikadmin-web/`).\n\n## Table of Contents\n\n1. [Store Architecture](#store-architecture)\n2. [Basic Store Pattern](#basic-store-pattern)\n3. [Middleware Stack](#middleware-stack)\n4. [Selectors and Hooks](#selectors-and-hooks)\n5. [Async Actions](#async-actions)\n6. [Persistence](#persistence)\n7. [Testing Stores](#testing-stores)\n8. [Best Practices](#best-practices)\n\n## Store Architecture\n\nIntelliFill organizes Zustand stores by domain:\n\n```\nquikadmin-web/src/stores/\n├── authStore.ts              # Authentication state\n├── documentStore.ts          # Document management\n├── templateStore.ts          # Template management\n├── knowledgeStore.ts         # Knowledge base\n├── uiStore.ts                # UI state (modals, sidebar, etc.)\n└── __tests__/                # Store tests\n    ├── documentStore.test.ts\n    └── ...\n```\n\n## Basic Store Pattern\n\nIntelliFill uses a consistent pattern for all stores.\n\n### Simple Store Template\n\n```typescript\n// quikadmin-web/src/stores/[domain]Store.ts\nimport { create } from ''zustand'';\nimport { immer } from ''zustand/middleware/immer'';\nimport { devtools } from ''zustand/middleware'';\n\n// Types\ninterface Item {\n  id: string;\n  name: string;\n  createdAt: string;\n}\n\ninterface DomainState {\n  // Data\n  items: Item[];\n  selectedItem: Item | null;\n\n  // UI State\n  loading: boolean;\n  error: string | null;\n\n  // Actions\n  fetchItems: () => Promise<void>;\n  getItem: (id: string) => Promise<void>;\n  createItem: (data: Partial<Item>) => Promise<void>;\n  updateItem: (id: string, data: Partial<Item>) => Promise<void>;\n  deleteItem: (id: string) => Promise<void>;\n  setSelectedItem: (item: Item | null) => void;\n  clearError: () => void;\n}\n\n// Store\nexport const useDomainStore = create<DomainState>()(\n  devtools(\n    immer((set, get) => ({\n      // Initial state\n      items: [],\n      selectedItem: null,\n      loading: false,\n      error: null,\n\n      // Actions\n      fetchItems: async () => {\n        set({ loading: true, error: null });\n        try {\n          const response = await api.get(''/domain'');\n          set({ items: response.data, loading: false });\n        } catch (error) {\n          set({\n            error: ''Failed to fetch items'',\n            loading: false,\n          });\n        }\n      },\n\n      getItem: async (id: string) => {\n        set({ loading: true, error: null });\n        try {\n          const response = await api.get(`/domain/${id}`);\n          set({ selectedItem: response.data, loading: false });\n        } catch (error) {\n          set({\n            error: ''Failed to fetch item'',\n            loading: false,\n          });\n        }\n      },\n\n      createItem: async (data: Partial<Item>) => {\n        set({ loading: true, error: null });\n        try {\n          const response = await api.post(''/domain'', data);\n          set((state) => {\n            state.items.push(response.data);\n            state.loading = false;\n          });\n        } catch (error) {\n          set({\n            error: ''Failed to create item'',\n            loading: false,\n          });\n          throw error;\n        }\n      },\n\n      updateItem: async (id: string, data: Partial<Item>) => {\n        set({ loading: true, error: null });\n        try {\n          const response = await api.patch(`/domain/${id}`, data);\n          set((state) => {\n            const index = state.items.findIndex((item) => item.id === id);\n            if (index !== -1) {\n              state.items[index] = response.data;\n            }\n            if (state.selectedItem?.id === id) {\n              state.selectedItem = response.data;\n            }\n            state.loading = false;\n          });\n        } catch (error) {\n          set({\n            error: ''Failed to update item'',\n            loading: false,\n          });\n          throw error;\n        }\n      },\n\n      deleteItem: async (id: string) => {\n        set({ loading: true, error: null });\n        try {\n          await api.delete(`/domain/${id}`);\n          set((state) => {\n            state.items = state.items.filter((item) => item.id !== id);\n            if (state.selectedItem?.id === id) {\n              state.selectedItem = null;\n            }\n            state.loading = false;\n          });\n        } catch (error) {\n          set({\n            error: ''Failed to delete item'',\n            loading: false,\n          });\n          throw error;\n        }\n      },\n\n      setSelectedItem: (item: Item | null) => {\n        set({ selectedItem: item });\n      },\n\n      clearError: () => {\n        set({ error: null });\n      },\n    })),\n    { name: ''DomainStore'' }\n  )\n);\n```\n\n## Middleware Stack\n\nIntelliFill uses three middleware layers: immer, persist, and devtools.\n\n### Middleware Order\n\n```typescript\nimport { create } from ''zustand'';\nimport { immer } from ''zustand/middleware/immer'';\nimport { persist } from ''zustand/middleware'';\nimport { devtools } from ''zustand/middleware'';\n\n// Correct order: devtools(persist(immer(...)))\nexport const useStore = create<State>()(\n  devtools(\n    persist(\n      immer((set, get) => ({\n        // Store implementation\n      })),\n      {\n        name: ''store-name'',\n      }\n    ),\n    { name: ''StoreName'' }\n  )\n);\n```\n\n### Immer Middleware\n\nImmer allows direct state mutation (safely):\n\n```typescript\nimport { immer } from ''zustand/middleware/immer'';\n\nexport const useStore = create<State>()(\n  immer((set, get) => ({\n    items: [],\n\n    // WITHOUT immer (immutable updates)\n    addItemOld: (item) => {\n      set((state) => ({\n        items: [...state.items, item],\n      }));\n    },\n\n    // WITH immer (mutable style)\n    addItem: (item) => {\n      set((state) => {\n        state.items.push(item); // Direct mutation!\n      });\n    },\n\n    // Nested updates are easier\n    updateNested: (id, value) => {\n      set((state) => {\n        const item = state.items.find((i) => i.id === id);\n        if (item) {\n          item.nested.deeply.value = value; // Easy!\n        }\n      });\n    },\n  }))\n);\n```\n\n### Persist Middleware\n\nPersist store state to localStorage:\n\n```typescript\nimport { persist } from ''zustand/middleware'';\n\nexport const useStore = create<State>()(\n  persist(\n    immer((set, get) => ({\n      items: [],\n      preferences: {},\n    })),\n    {\n      name: ''domain-storage'', // localStorage key\n\n      // Partial persistence (only save specific fields)\n      partialPersist: {\n        preferences: true, // Save preferences\n        items: false, // Don''t save items\n      },\n\n      // Version for migrations\n      version: 1,\n\n      // Migration function\n      migrate: (persistedState: any, version: number) => {\n        if (version === 0) {\n          // Migrate from v0 to v1\n          persistedState.newField = ''default'';\n        }\n        return persistedState;\n      },\n    }\n  )\n);\n```\n\n### Devtools Middleware\n\nEnable Redux DevTools integration:\n\n```typescript\nimport { devtools } from ''zustand/middleware'';\n\nexport const useStore = create<State>()(\n  devtools(\n    immer((set, get) => ({\n      count: 0,\n\n      increment: () => {\n        set((state) => {\n          state.count++;\n        }, false, ''increment''); // Action name in devtools\n      },\n\n      decrement: () => {\n        set((state) => {\n          state.count--;\n        }, false, { type: ''decrement'', payload: -1 }); // Detailed action\n      },\n    })),\n    {\n      name: ''CounterStore'', // Store name in devtools\n      enabled: process.env.NODE_ENV === ''development'', // Only in dev\n    }\n  )\n);\n```\n\n## Selectors and Hooks\n\nOptimize re-renders with selectors.\n\n### Basic Selectors\n\n```typescript\n// Component re-renders only when items change\nfunction ItemList() {\n  const items = useDomainStore((state) => state.items);\n\n  return (\n    <ul>\n      {items.map((item) => (\n        <li key={item.id}>{item.name}</li>\n      ))}\n    </ul>\n  );\n}\n\n// Component re-renders only when loading changes\nfunction LoadingIndicator() {\n  const loading = useDomainStore((state) => state.loading);\n\n  if (!loading) return null;\n  return <Spinner />;\n}\n```\n\n### useShallow for Multiple Values\n\n```typescript\nimport { useShallow } from ''zustand/react/shallow'';\n\n// BAD: Re-renders when ANY store property changes\nfunction Component() {\n  const { items, loading, error } = useDomainStore();\n  // ...\n}\n\n// GOOD: Re-renders only when items, loading, or error change\nfunction Component() {\n  const { items, loading, error } = useDomainStore(\n    useShallow((state) => ({\n      items: state.items,\n      loading: state.loading,\n      error: state.error,\n    }))\n  );\n  // ...\n}\n```\n\n### Custom Selector Hooks\n\n```typescript\n// quikadmin-web/src/stores/domainStore.ts\n\n// Export selector hooks for common patterns\nexport const useDomainItems = () =>\n  useDomainStore((state) => state.items);\n\nexport const useDomainLoading = () =>\n  useDomainStore((state) => state.loading);\n\nexport const useDomainError = () =>\n  useDomainStore((state) => state.error);\n\nexport const useDomainActions = () =>\n  useDomainStore(\n    useShallow((state) => ({\n      fetchItems: state.fetchItems,\n      createItem: state.createItem,\n      updateItem: state.updateItem,\n      deleteItem: state.deleteItem,\n    }))\n  );\n\n// Usage in components\nfunction ItemList() {\n  const items = useDomainItems();\n  const { createItem, deleteItem } = useDomainActions();\n\n  // Component only re-renders when items or actions change\n}\n```\n\n### Derived State\n\n```typescript\nexport const useDomainStore = create<DomainState>()(\n  immer((set, get) => ({\n    items: [],\n    filter: '''',\n\n    // Computed/derived state\n    get filteredItems() {\n      const { items, filter } = get();\n      if (!filter) return items;\n      return items.filter((item) =>\n        item.name.toLowerCase().includes(filter.toLowerCase())\n      );\n    },\n\n    setFilter: (filter: string) => {\n      set({ filter });\n    },\n  }))\n);\n\n// Usage\nfunction FilteredList() {\n  const filteredItems = useDomainStore((state) => state.filteredItems);\n  return <ul>{filteredItems.map(...)}</ul>;\n}\n```\n\n## Async Actions\n\nHandle async operations with proper loading and error states.\n\n### Async Action Pattern\n\n```typescript\nexport const useDomainStore = create<DomainState>()(\n  immer((set, get) => ({\n    items: [],\n    loading: false,\n    error: null,\n\n    fetchItems: async () => {\n      // Set loading state\n      set({ loading: true, error: null });\n\n      try {\n        // API call\n        const response = await api.get(''/domain'');\n\n        // Update state on success\n        set({\n          items: response.data,\n          loading: false,\n        });\n      } catch (error) {\n        // Handle error\n        set({\n          error: error instanceof Error ? error.message : ''Unknown error'',\n          loading: false,\n        });\n\n        // Optionally rethrow for component handling\n        throw error;\n      }\n    },\n  }))\n);\n```\n\n### Optimistic Updates\n\n```typescript\nupdateItem: async (id: string, data: Partial<Item>) => {\n  // Save original state for rollback\n  const originalItems = get().items;\n\n  // Optimistic update\n  set((state) => {\n    const item = state.items.find((i) => i.id === id);\n    if (item) {\n      Object.assign(item, data);\n    }\n  });\n\n  try {\n    // API call\n    const response = await api.patch(`/domain/${id}`, data);\n\n    // Update with server response\n    set((state) => {\n      const item = state.items.find((i) => i.id === id);\n      if (item) {\n        Object.assign(item, response.data);\n      }\n    });\n  } catch (error) {\n    // Rollback on error\n    set({ items: originalItems, error: ''Failed to update item'' });\n    throw error;\n  }\n},\n```\n\n### Debounced Actions\n\n```typescript\nimport { debounce } from ''lodash-es'';\n\nexport const useDomainStore = create<DomainState>()(\n  immer((set, get) => ({\n    searchQuery: '''',\n    searchResults: [],\n\n    // Create debounced function outside of the store\n    searchItems: debounce(async (query: string) => {\n      if (!query) {\n        set({ searchResults: [] });\n        return;\n      }\n\n      set({ loading: true });\n      try {\n        const response = await api.get(''/domain/search'', { params: { q: query } });\n        set({ searchResults: response.data, loading: false });\n      } catch (error) {\n        set({ error: ''Search failed'', loading: false });\n      }\n    }, 300),\n\n    setSearchQuery: (query: string) => {\n      set({ searchQuery: query });\n      get().searchItems(query); // Trigger debounced search\n    },\n  }))\n);\n```\n\n## Persistence\n\nConfigure localStorage persistence for user preferences.\n\n### Persist Configuration\n\n```typescript\nimport { persist, createJSONStorage } from ''zustand/middleware'';\n\nexport const usePreferencesStore = create<PreferencesState>()(\n  persist(\n    immer((set) => ({\n      theme: ''light'',\n      language: ''en'',\n      sidebarCollapsed: false,\n\n      setTheme: (theme) => set({ theme }),\n      setLanguage: (language) => set({ language }),\n      toggleSidebar: () =>\n        set((state) => {\n          state.sidebarCollapsed = !state.sidebarCollapsed;\n        }),\n    })),\n    {\n      name: ''user-preferences'',\n      storage: createJSONStorage(() => localStorage),\n\n      // Only persist specific fields\n      partialPersist: {\n        theme: true,\n        language: true,\n        sidebarCollapsed: true,\n      },\n    }\n  )\n);\n```\n\n### Session Storage\n\n```typescript\nimport { createJSONStorage } from ''zustand/middleware'';\n\nexport const useSessionStore = create<SessionState>()(\n  persist(\n    immer((set) => ({\n      // Session-only data\n    })),\n    {\n      name: ''session-data'',\n      storage: createJSONStorage(() => sessionStorage), // Use sessionStorage\n    }\n  )\n);\n```\n\n### Migration Example\n\n```typescript\npersist(\n  immer((set) => ({\n    // Store implementation\n  })),\n  {\n    name: ''domain-storage'',\n    version: 2, // Current version\n\n    migrate: (persistedState: any, version: number) => {\n      // Migrate from v0 to v1\n      if (version === 0) {\n        persistedState.newField = ''default'';\n      }\n\n      // Migrate from v1 to v2\n      if (version === 1) {\n        persistedState.renamedField = persistedState.oldField;\n        delete persistedState.oldField;\n      }\n\n      return persistedState;\n    },\n  }\n);\n```\n\n## Testing Stores\n\nTest stores in isolation with mocked dependencies.\n\n### Basic Store Test\n\n```typescript\n// quikadmin-web/src/stores/__tests__/domainStore.test.ts\nimport { describe, it, expect, beforeEach, vi } from ''vitest'';\nimport { renderHook, act } from ''@testing-library/react'';\nimport { useDomainStore } from ''../domainStore'';\nimport * as api from ''@/services/api'';\n\n// Mock API\nvi.mock(''@/services/api'', () => ({\n  api: {\n    get: vi.fn(),\n    post: vi.fn(),\n    patch: vi.fn(),\n    delete: vi.fn(),\n  },\n}));\n\ndescribe(''useDomainStore'', () => {\n  beforeEach(() => {\n    // Reset store state before each test\n    useDomainStore.setState({\n      items: [],\n      loading: false,\n      error: null,\n    });\n    vi.clearAllMocks();\n  });\n\n  it(''fetches items successfully'', async () => {\n    const mockItems = [\n      { id: ''1'', name: ''Item 1'' },\n      { id: ''2'', name: ''Item 2'' },\n    ];\n\n    vi.mocked(api.api.get).mockResolvedValue({ data: mockItems });\n\n    const { result } = renderHook(() => useDomainStore());\n\n    await act(async () => {\n      await result.current.fetchItems();\n    });\n\n    expect(result.current.items).toEqual(mockItems);\n    expect(result.current.loading).toBe(false);\n    expect(result.current.error).toBeNull();\n  });\n\n  it(''handles fetch error'', async () => {\n    vi.mocked(api.api.get).mockRejectedValue(new Error(''Network error''));\n\n    const { result } = renderHook(() => useDomainStore());\n\n    await act(async () => {\n      try {\n        await result.current.fetchItems();\n      } catch (error) {\n        // Expected to throw\n      }\n    });\n\n    expect(result.current.items).toEqual([]);\n    expect(result.current.loading).toBe(false);\n    expect(result.current.error).toBeTruthy();\n  });\n\n  it(''creates item'', async () => {\n    const newItem = { id: ''1'', name: ''New Item'' };\n    vi.mocked(api.api.post).mockResolvedValue({ data: newItem });\n\n    const { result } = renderHook(() => useDomainStore());\n\n    await act(async () => {\n      await result.current.createItem({ name: ''New Item'' });\n    });\n\n    expect(result.current.items).toContainEqual(newItem);\n  });\n});\n```\n\n### Testing Selectors\n\n```typescript\nit(''returns filtered items'', () => {\n  const { result } = renderHook(() => useDomainStore());\n\n  act(() => {\n    useDomainStore.setState({\n      items: [\n        { id: ''1'', name: ''Apple'' },\n        { id: ''2'', name: ''Banana'' },\n        { id: ''3'', name: ''Apricot'' },\n      ],\n      filter: ''ap'',\n    });\n  });\n\n  expect(result.current.filteredItems).toHaveLength(2);\n  expect(result.current.filteredItems[0].name).toBe(''Apple'');\n  expect(result.current.filteredItems[1].name).toBe(''Apricot'');\n});\n```\n\n## Best Practices\n\n1. **Use TypeScript interfaces** - Type all store state and actions\n2. **Middleware order matters** - devtools → persist → immer\n3. **Use immer for nested updates** - Simplifies complex state updates\n4. **Select only what you need** - Use selectors to prevent unnecessary re-renders\n5. **Use useShallow for objects** - Shallow comparison for multiple values\n6. **Handle loading and errors** - Always track async operation states\n7. **Optimize with derived state** - Use getters for computed values\n8. **Test stores in isolation** - Mock API calls and dependencies\n9. **Persist user preferences only** - Don''t persist transient data\n10. **Use action naming** - Name actions for Redux DevTools\n\n## Common Patterns\n\n### Store Composition\n\n```typescript\n// Combine multiple stores in a component\nfunction Component() {\n  const documents = useDocumentStore((state) => state.documents);\n  const templates = useTemplateStore((state) => state.templates);\n  const { user } = useAuthStore();\n\n  // Use data from multiple stores\n}\n```\n\n### Store Subscription\n\n```typescript\nimport { useEffect } from ''react'';\n\nfunction Component() {\n  useEffect(() => {\n    // Subscribe to store changes\n    const unsubscribe = useDomainStore.subscribe(\n      (state) => state.items,\n      (items) => {\n        console.log(''Items changed:'', items);\n      }\n    );\n\n    return unsubscribe;\n  }, []);\n}\n```\n\n### Reset Store\n\n```typescript\nexport const useDomainStore = create<DomainState>()(\n  immer((set) => ({\n    items: [],\n    loading: false,\n\n    reset: () => {\n      set({\n        items: [],\n        loading: false,\n        error: null,\n      });\n    },\n  }))\n);\n```\n\n## References\n\n- [Zustand Documentation](https://github.com/pmndrs/zustand)\n- [Immer Documentation](https://immerjs.github.io/immer/)\n- [React Testing Library](https://testing-library.com/react)\n- [Vitest](https://vitest.dev/)\n"},"lastSynced":"2026-03-08T02:04:16.108Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents requiring advanced state management and automation capabilities in the IntelliFill frontend","zh":"适用于需要高级状态管理和自动化功能的前端代理，特别是在 IntelliFill 前端","ja":"フロントエンドエージェントに高度な状態管理と自動化機能が必要な場合に最適です。特に IntelliFill フロントエンドで","ko":"고급 상태 관리 및 자동화 기능이 필요한 프런트엔드 에이전트에 적합합니다. 특히 IntelliFill 프런트엔드에서","es":"Ideal para agentes de frontend que requieren administración de estado avanzada y capacidades de automatización en el frontend de IntelliFill","fr":"Idéal pour les agents Frontend nécessitant une gestion d''état avancée et des capacités d''automatisation dans le frontend d''IntelliFill","de":"Ideal für Frontend-Agents, die eine erweiterte Zustandsverwaltung und Automatisierungsfunktionen im IntelliFill-Frontend erfordern","pt":"Ideal para Agentes Frontend que exigem gerenciamento de estado avançado e capacidades de automação no frontend do IntelliFill","ru":"Идеально для Фронтенд-агентов, требующих продвинутого управления состоянием и возможностей автоматизации в фронтенде IntelliFill","ar":"مثالي للوكلاء الأماميين الذين يتطلبون إدارة состояние متقدمة وقدرات أتمتة في واجهة المستخدم الأمامية من IntelliFill"},"recommendation":{"en":"Empowers agents to create comprehensive Zustand stores with middleware stacks, selectors, and hooks, leveraging async actions and persistence for robust frontend development, utilizing selectors and hooks for efficient state access","zh":"赋予代理创建综合 Zustand 存储的能力，利用中间件栈、选择器和钩子，利用异步操作和持久性实现强大的前端开发，使用选择器和钩子实现高效的状态访问","ja":"エージェントがミドルウェアスタック、セレクター、フックを使用して包括的な Zustand ストアを作成できるようにし、非同期アクションと永続性を活用して強力なフロントエンド開発を行い、セレクターとフックを使用して効率的な状態アクセスを実現する","ko":"에이전트가 미들웨어 스택, 선택자 및 훅을 사용하여 포괄적인 Zustand 저장소를 생성할 수 있도록 하여 비동기 작업 및 지속성을 활용하여 강력한 프런트엔드 개발을 수행하고 선택자 및 훅을 사용하여 효율적인 상태 액세스를实现합니다","es":"Habilita a los agentes a crear almacenes de Zustand completos con pilas de middleware, selectores y ganchos, aprovechando acciones asíncronas y persistencia para un desarrollo de frontend robusto, utilizando selectores y ganchos para un acceso eficiente al estado","fr":"Permet aux agents de créer des magasins Zustand complets avec des piles de middleware, des sélecteurs et des crochets, en exploitant les actions asynchrones et la persistance pour un développement de frontend robuste, en utilisant des sélecteurs et des crochets pour un accès efficace à l''état","de":"Ermächtigt Agenten, umfassende Zustand-Speicher mit Middleware-Stacks, Selektoren und Haken zu erstellen, asynchrone Aktionen und Persistenz für eine robuste Frontend-Entwicklung nutzend, wobei Selektoren und Haken für einen effizienten Zugriff auf den Zustand verwendet werden","pt":"Habilita agentes a criar lojas Zustand abrangentes com pilhas de middleware, seletores e ganchos, aproveitando ações assíncronas e persistência para desenvolvimento de frontend robusto, utilizando seletores e ganchos para acesso eficiente ao estado","ru":"Наделяет агентов возможностью создавать всесторонние магазины Zustand с помощью стеков middleware, селекторов и хуков, используя асинхронные действия и персистентность для надежной разработки фронтенда, используя селекторы и хуки для эффективного доступа к состоянию","ar":"يتمكن الوكلاء من إنشاء مخازن Zustand شاملة مع هرمية من البرامج الوسيطة و المحددات و مشابك ، واستخدام الإجراءات غير المتزامنة و الثبات من أجل تطوير واجهة المستخدم الأمامية القوية، واستخدام المحددات و المشابك للوصول الفعال إلى الحالة"},"useCases":{"en":["Creating scalable store architectures","Implementing middleware stacks for enhanced store functionality","Developing async actions for seamless data synchronization"],"zh":["创建可扩展的存储架构","实现中间件栈以增强存储功能","开发异步操作以实现无缝数据同步"],"ja":["拡張可能なストアアーキテクチャを作成する","ストア機能を強化するためのミドルウェアスタックを実装する","シームレスなデータ同期のために非同期アクションを開発する"],"ko":["확장 가능한 저장소 아키텍처를 생성하는 것","저장소 기능을 강화하기 위한 미들웨어 스택을 구현하는 것","무결점 데이터 동기화를 위해 비동기 작업을 개발하는 것"],"es":["Creación de arquitecturas de almacenamiento escalables","Implementación de pilas de middleware para una funcionalidad de almacenamiento mejorada","Desarrollo de acciones asíncronas para una sincronización de datos sin problemas"],"fr":["Création d''architectures de magasin scalable","Mise en œuvre de piles de middleware pour une fonctionnalité de magasin améliorée","Développement d''actions asynchrones pour une synchronisation de données sans problème"],"de":["Erstellung von skalierbaren Speicherarchitekturen","Implementierung von Middleware-Stacks für eine verbesserte Speicherfunktionalität","Entwicklung asynchroner Aktionen für eine reibungslose Datensynchronisation"],"pt":["Criar arquiteturas de loja escaláveis","Implementar pilhas de middleware para funcionalidade de loja aprimorada","Desenvolver ações assíncronas para sincronização de dados sem interrupção"],"ru":["Создание масштабируемых архитектур хранилищ","Реализация стеков middleware для улучшения функциональности хранилища","Разработка асинхронных действий для бесперебойной синхронизации данных"],"ar":["إنشاء هياكل مخزن قابلة للتوسيع","تنفيذ هرمية من البرامج الوسيطة لتطوير وظيفة المخزن","تطوير الإجراءات غير المتزامنة من أجل مزامنة البيانات دون انقطاع"]},"limitations":{"en":["Requires IntelliFill frontend setup","Specific to Zustand store development"],"zh":["需要 IntelliFill 前端设置","特定于 Zustand 存储开发"],"ja":["IntelliFill フロントエンドの設定が必要","Zustand ストア開発に特化する"],"ko":["IntelliFill 프런트엔드 설정이 필요함","Zustand 저장소 개발에 특화됨"],"es":["Requiere configuración de frontend de IntelliFill","Específico para el desarrollo de almacenes de Zustand"],"fr":["Nécessite une configuration de frontend d''IntelliFill","Spécifique au développement de magasins Zustand"],"de":["Benötigt IntelliFill-Frontend-Setup","Spezifisch für die Entwicklung von Zustand-Speichern"],"pt":["Exige configuração do frontend do IntelliFill","Específico para desenvolvimento de loja Zustand"],"ru":["Требует настройки фронтенда IntelliFill","Специфичен для разработки магазина Zustand"],"ar":["يتطلب إعداد واجهة المستخدم الأمامية من IntelliFill","محدد لتطوير مخزن Zustand"]},"version":4},"contentHash":"450093c04cb9dc4873076a2ef26f9a72f11abe4be9919abc22714ee64b9571c2","qualityScore":42}');
