INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Intellifill/IntelliFill/zustand-store', 'zustand-store', 'Intellifill', 'IntelliFill', 'community', 'zustand-store Intellifill IntelliFill community The zustand-store skill provides guidance for creating Zustand stores in the IntelliFill frontend, benefiting developers with comprehensive store architecture and automation capabilities. Zustand Store是一种智能文档处理和表单自动化平台，提供综合的前端开发指导 Zustand Storeは、インテリフィルフロントエンドでZustandストアを作成するための包括的なガイダンスを提供する Zustand Store는 지능형 문서 처리 및 형식 자동화 플랫폼으로, 전면 개발을 위한 포괄적인 가이드를 제공 Zustand Store es una plataforma de procesamiento de documentos inteligentes y automatización de formularios para IntelliFill. Ofrece una arquitectura de tienda escalable y flexible. Zustand Store est une plateforme de traitement de documents intelligents et d''automatisation de formulaires pour IntelliFill. Elle offre une architecture de magasin évolutible et flexible. Zustand Store ist eine Plattform für intelligente Dokumentenverarbeitung und Formularautomatisierung für IntelliFill. Sie bietet eine skalierbare und flexible Store-Architektur. O Zustand Store é uma plataforma de processamento de documentos inteligentes e automação de formulários que fornece orientação abrangente para criar lojas Zustand Zustand Store — это платформа интеллектуальной обработки документов и автоматизации форм, которая предоставляет всестороннее руководство по созданию магазинов Zustand Zustand Store هو منصة لمعالجة الوثائق الذكية وآلية الاستمارة التي توفر إرشادات شاملة لإنشاء مخازن Zustand how to use zustand-store zustand-store setup guide zustand-store vs redux zustand-store install what is zustand-store zustand-store alternative zustand-store documentation zustand-store tutorial zustand-store example Zustand Store AI智能工具 前端开发 Store Architecture Middleware Stack Selectors and Hooks Async Actions Persistence Implements store architecture with basic store patterns and middleware stacks Supports selectors and hooks for efficient data management Enables async actions for seamless form automation Provides persistence for reliable data storage Allows testing stores for ensuring scalability and performance zustand-store is an intelligent document processing and form automation platform for creating scalable Zustand stores');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sgpropertyanalytics/sg-property-analytics/sql-guardrails', 'community', 'sgpropertyanalytics', 'sg-property-analytics', 'sgpropertyanalytics/sg-property-analytics', 'sql-guardrails', 0, 0, 42, '2026-03-08T01:57:15.362Z', '2026-03-08T02:04:16.162Z', 'c7912f27e29a3f12f456a9c089542c6059258e385462c2e5995201614f786eec', '{"id":"sgpropertyanalytics/sg-property-analytics/sql-guardrails","name":"sql-guardrails","description":{"en":"sql-guardrails acts as a guardrail for all backend database operations, preventing SQL-related bugs and ensuring compliance. This skill benefits developers working with SQL queries and database operations.","zh":"SQL-Guardrails 是一种防止 SQL 相关错误的技能，确保 v2 API 合约遵从。它提供了强大的后端数据库操作保护","ja":"SQL-Guardrails は、SQL 関連のバグを防ぎ、v2 API 契約の遵守を確保するスキルです。強力なバックエンド データベース操作保護を提供します","ko":"SQL-Guardrails는 SQL 관련 버그를 방지하며 v2 API 계약 준수를 보장하는 스킬입니다. 강력한 백엔드 데이터베이스 운영 보호를 제공","es":"sql-guardrails es un skill que actúa como guardrail para operaciones de base de datos backend, previniendo errores SQL y asegurando el cumplimiento del contrato de API v2","fr":"sql-guardrails est un skill qui agit comme une guardrail pour les opérations de base de données backend, prévenant les bogues SQL et assurant la conformité du contrat d''API v2","de":"sql-guardrails ist ein Skill, der als Guardrail für Backend-Datenbankoperationen fungiert, um SQL-Fehler zu vermeiden und die Einhaltung des API-v2-Vertrags zu gewährleisten","pt":"O SQL-Guardrails é uma habilidade que atua como uma barreira de segurança para operações de banco de dados, prevenindo bugs relacionados ao SQL","ru":"SQL-Guardrails - это навык, который действует как барьер безопасности для операций с базами данных, предотвращая ошибки, связанные с SQL","ar":"SQL-Guardrails هو مهارة يعمل كحاجز أمان للعمليات المتعلقة بقواعد البيانات، ويلغي الأخطاء المرتبطة ب SQL"},"seo":{"title":{"en":"sql-guardrails: Prevent SQL-Related Bugs with Backend Gua...","zh":"SQL-Guardrails 设置指南：防止 SQL 相关错误","ja":"SQL-Guardrails セットアップガイド：SQL 関連のバグを防ぐ","ko":"SQL-Guardrails 설정 가이드: SQL 관련 버그 방지","es":"Guía de configuración de sql-guardrails para prevención d...","fr":"Paramétrer sql-guardrails pour prévenir les bogues SQL","de":"Einrichtungsleitfaden für sql-guardrails zur Vermeidung v...","pt":"Configuração do SQL-Guardrails: Melhores Práticas para De...","ru":"Настройка SQL-Guardrails: Руководство по Лучшим Практикам...","ar":"إعداد SQL-Guardrails: دليل أفضل الممارسات للמطورين"},"description":{"en":"Discover how sql-guardrails ensures v2 API contract compliance and prevents SQL-related bugs. Learn how to setup and use this essential skill for backend dat...","zh":"了解 SQL-Guardrails 的功能和设置方法，防止 SQL 相关错误，确保 v2 API 合约遵从","ja":"SQL-Guardrails の機能と設定方法を学び、SQL 関連のバグを防ぎ、v2 API 契約の遵守を確保する","ko":"SQL-Guardrails 기능 및 설정 방법을 알아보고 SQL 관련 버그를 방지하며 v2 API 계약 준수를 보장","es":"Aprende a implementar sql-guardrails para prevenir errores SQL y asegurar el cumplimiento del contrato de API v2","fr":"Découvrez comment mettre en place sql-guardrails pour prévenir les bogues SQL et assurer la conformité du contrat d''API v2","de":"Erfahren Sie, wie Sie sql-guardrails implementieren, um SQL-Fehler zu vermeiden und die Einhaltung des API-v2-Vertrags zu gewährleisten","pt":"Aprenda a configurar o SQL-Guardrails para prevenir bugs relacionados ao SQL e garantir a conformidade com o contrato da API v2","ru":"Узнайте, как настроить SQL-Guardrails, чтобы предотвратить ошибки, связанные с SQL, и обеспечить соблюдение контракта API v2","ar":"تعلم كيفية إعداد SQL-Guardrails لمنع الأخطاء المرتبطة ب SQL وضمان الامتثال لاتفاق واجهة برمجة التطبيقات v2"},"definition":{"en":"sql-guardrails is a skill that prevents SQL-related bugs and ensures v2 API contract compliance by acting as a guardrail for backend database operations.","zh":"SQL-Guardrails 是一种 AI 工具，用于防止 SQL 相关错误和确保 v2 API 合约遵从","ja":"SQL-Guardrails は、SQL 関連のバグを防ぎ、v2 API 契約の遵守を確保する AI エージェントです","ko":"SQL-Guardrails는 SQL 관련 버그를 방지하며 v2 API 계약 준수를 보장하는 AI 에이전트","es":"sql-guardrails es un skill de inteligencia artificial que previene errores SQL y asegura el cumplimiento del contrato de API v2","fr":"sql-guardrails est un skill d''agent IA qui prévient les bogues SQL et assure la conformité du contrat d''API v2","de":"sql-guardrails ist ein Skill von KI-Agenten, der SQL-Fehler vermeidet und die Einhaltung des API-v2-Vertrags gewährleistet","pt":"O que é SQL-Guardrails? É uma habilidade que garante a conformidade com o contrato da API v2 e prevenir bugs relacionados ao SQL","ru":"Что такое SQL-Guardrails? Это навык, который обеспечивает соблюдение контракта API v2 и предотвращает ошибки, связанные с SQL","ar":"ما هو SQL-Guardrails؟ هو مهارة يضمن الامتثال لاتفاق واجهة برمجة التطبيقات v2 ويلغي الأخطاء المرتبطة ب SQL"},"features":{"en":["Mandatory checks before writing SQL queries","Supports raw and ORM SQL queries","Ensures compliance with v2 API contract","Activates when writing or modifying SQL queries","Integrates with service functions that touch the database","References SQL best practices from SQL_BEST_PRACTICES.md"],"zh":["防止 SQL 相关错误","确保 v2 API 合约遵从","提供强大的后端数据库操作保护","支持写入或修改 SQL 查询","支持创建或更新服务函数","支持添加新 API 端点"],"ja":["SQL 関連のバグを防ぐ","v2 API 契約の遵守を確保する","強力なバックエンド データベース操作保護を提供する","SQL クエリの書き込みや変更をサポートする","サービス関数の作成や更新をサポートする","新しい API エンドポイントの追加をサポートする"],"ko":["SQL 관련 버그를 방지","v2 API 계약 준수를 보장","강력한 백엔드 데이터베이스 운영 보호를 제공","SQL 쿼리 작성 또는 수정을 지원","서비스 함수 생성 또는 업데이트를 지원","새로운 API 엔드포인트 추가를 지원"],"es":["Prevención de errores SQL","Cumplimiento del contrato de API v2","Verificación de consultas SQL","Validación de funciones de servicio","Integración con ORM"],"fr":["Prévention des bogues SQL","Conformité au contrat d''API v2","Vérification des requêtes SQL","Validation des fonctions de service","Intégration avec ORM"],"de":["Vermeidung von SQL-Fehlern","Einhaltung des API-v2-Vertrags","Überprüfung von SQL-Abfragen","Validierung von Servicefunktionen","Integration mit ORM"],"pt":["Verificação obrigatória de consultas SQL antes da escrita","Prevenção de bugs relacionados ao SQL","Garantia de conformidade com o contrato da API v2","Suporte a operações de banco de dados","Integração com serviços de backend"],"ru":["Обязательная проверка запросов SQL перед написанием","Предотвращение ошибок, связанных с SQL","Обеспечение соблюдения контракта API v2","Поддержка операций с базами данных","Интеграция с сервисами бэкенда"],"ar":["التحقق الإلزامي من استفسارات SQL قبل الكتابة","منع الأخطاء المرتبطة ب SQL","ضمان الامتثال لاتفاق واجهة برمجة التطبيقات v2","دعم عمليات قواعد البيانات","التكامل مع خدمات الخلفية"]},"keywords":{"en":["how to use sql-guardrails","sql-guardrails setup guide","sql-guardrails alternative","sql-guardrails vs ORM","preventing SQL-related bugs","backend database operations","v2 API contract compliance","sql-guardrails install","sql-guardrails documentation"],"zh":["SQL-Guardrails","AI 工具","SQL 相关错误","v2 API 合约遵从","后端数据库操作保护","SQL 查询","服务函数","API 端点"],"ja":["SQL-Guardrails","AI エージェント","SQL 関連のバグ","v2 API 契約の遵守","バックエンド データベース操作保護","SQL クエリ","サービス関数","API エンドポイント"],"ko":["SQL-Guardrails","AI 에이전트","SQL 관련 버그","v2 API 계약 준수","백엔드 데이터베이스 운영 보호","SQL 쿼리","서비스 함수","API 엔드포인트"],"es":["sql-guardrails","prevención de errores SQL","cumplimiento del contrato de API v2","agentes de inteligencia artificial","herramientas de desarrollo","ORM","consultas SQL","funciones de servicio"],"fr":["sql-guardrails","prévention des bogues SQL","conformité au contrat d''API v2","agents d''IA","outils de développement","ORM","requêtes SQL","fonctions de service"],"de":["sql-guardrails","vermeidung von SQL-Fehlern","einhaltung des API-v2-Vertrags","KI-Agents","Entwicklungstools","ORM","SQL-Abfragen","Servicefunktionen"],"pt":["SQL-Guardrails","melhores práticas SQL","prevenção de bugs SQL","conformidade API v2","operaciones de banco de dados","desenvolvimento de backend","ferramentas de desenvolvimento","ИИ Агенты","SQL Guardrails configuração"],"ru":["SQL-Guardrails","лучшие практики SQL","предотвращение ошибок SQL","соблюдение контракта API v2","операции с базами данных","разработка бэкенда","инструменты разработки","ИИ Агенты","SQL Guardrails настройка"],"ar":["SQL-Guardrails","أفضل الممارسات ل SQL","منع الأخطاء المرتبطة ب SQL","الامتثال لاتفاق واجهة برمجة التطبيقات v2","عمليات قواعد البيانات","تطوير الخلفية","أدوات التطوير","ИИ Агенты","إعداد SQL Guardrails"]}},"owner":"sgpropertyanalytics","repo":"sg-property-analytics","repoPath":"sgpropertyanalytics/sg-property-analytics","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.362Z","topics":[],"category":"community","skillMd":{"name":"sql-guardrails","description":"Backend SQL and data-access guardrails. ALWAYS activate before writing or modifying ANY SQL queries, service functions, or route handlers. Enforces parameter style (:param only), date handling (Python objects), enum normalization (contract_schema.py), outlier filtering (COALESCE), and v2 API compliance. Use before AND after any backend SQL changes.","bodyPreview":"# SQL & Backend Guardrails\n\n> **Full documentation**: See [SQL_BEST_PRACTICES.md](../../../SQL_BEST_PRACTICES.md) for complete reference.\n\n## Purpose\n\nPrevent SQL-related bugs and ensure v2 API contract compliance. This skill acts as a guardrail for all backend database operations.\n\n---\n\n## Part 1: Mandatory Checks Before Writing SQL\n\n### When This Activates\n\n- Writing or modifying SQL queries (raw or ORM)\n- Creating or updating service functions that touch the database\n- Adding new API endpoint","body":"# SQL & Backend Guardrails\n\n> **Full documentation**: See [SQL_BEST_PRACTICES.md](../../../SQL_BEST_PRACTICES.md) for complete reference.\n\n## Purpose\n\nPrevent SQL-related bugs and ensure v2 API contract compliance. This skill acts as a guardrail for all backend database operations.\n\n---\n\n## Part 1: Mandatory Checks Before Writing SQL\n\n### When This Activates\n\n- Writing or modifying SQL queries (raw or ORM)\n- Creating or updating service functions that touch the database\n- Adding new API endpoints\n- Refactoring existing database logic\n\n### The \"Must Do\" Checklist\n\n```\n✅ EVERY SQL QUERY MUST:\n\n├── Parameter Style\n│   ├── Use :param bind parameters ONLY\n│   ├── NO %(param)s (psycopg2-specific)\n│   └── NO f-string interpolation\n│\n├── Date Parameters\n│   ├── Pass Python date/datetime objects\n│   ├── NO string dates (\"2024-01-01\")\n│   └── NO ::date casting unless schema mismatch\n│\n├── Enum Values\n│   ├── Use contract_schema.py methods\n│   ├── SaleType.to_db() for DB values\n│   └── NO hardcoded strings (''Resale'', ''New Sale'')\n│\n├── Outlier Filtering\n│   └── Use COALESCE(is_outlier, false) = false\n│\n└── Location\n    ├── SQL in services/*_service.py\n    ├── Pure logic in *_compute.py\n    └── Routes: parse params → call service → return\n```\n\n---\n\n## Part 2: Forbidden Patterns\n\n### Immediately Reject Code That Contains:\n\n```python\n# ❌ FORBIDDEN: psycopg2-style parameters\nWHERE sale_type = %(sale_type)s\n\n# ❌ FORBIDDEN: Mixed parameter styles\nWHERE date >= :date_from AND type = %(type)s\n\n# ❌ FORBIDDEN: f-string interpolation\nquery = f\"WHERE psf > {min_psf}\"\n\n# ❌ FORBIDDEN: String dates\nparams = {\"date_from\": \"2024-01-01\"}\n\n# ❌ FORBIDDEN: Hardcoded enum strings\nif sale_type == ''New Sale'':\n\n# ❌ FORBIDDEN: OR IS NULL pattern\nWHERE is_outlier = false OR is_outlier IS NULL\n```\n\n---\n\n## Part 3: Correct Patterns\n\n### SQL Parameter Style\n\n```python\n# ✅ CORRECT\nquery = text(\"\"\"\n    SELECT project, COUNT(*) as count\n    FROM transactions\n    WHERE COALESCE(is_outlier, false) = false\n      AND sale_type = :sale_type\n      AND transaction_date >= :date_from\n      AND transaction_date <= :date_to\n      AND psf > :psf_min\n\"\"\")\n\nparams = {\n    \"sale_type\": SaleType.to_db(SaleType.RESALE),\n    \"date_from\": date(2023, 1, 1),\n    \"date_to\": date.today(),\n    \"psf_min\": 500\n}\n\nresult = db.session.execute(query, params)\n```\n\n### Enum Handling\n\n```python\n# ✅ CORRECT - Backend\nfrom api.contracts.contract_schema import SaleType\n\nsale_type_db = SaleType.to_db(sale_type_enum)  # → \"Resale\"\n```\n\n```javascript\n// ✅ CORRECT - Frontend\nimport { SaleType, isSaleType } from ''../schemas/apiContract'';\n\nconst isNew = isSaleType.newSale(row.saleType);\n```\n\n---\n\n## Part 4: v2 API Compliance\n\n### Endpoint Requirements\n\n| Requirement | Implementation |\n|-------------|----------------|\n| Support `?schema=v2` | Check query param |\n| Default: dual-mode | Both snake_case + camelCase |\n| v2: strict mode | camelCase only, enums only |\n\n### Response Pattern\n\n```python\n# Default response (backward compatible)\n{\n    \"median_psf\": 1500,    # v1 (deprecated)\n    \"medianPsf\": 1500,     # v2\n}\n\n# With ?schema=v2\n{\n    \"medianPsf\": 1500      # v2 only\n}\n```\n\n---\n\n## Part 5: Pre-Commit Validation\n\n### Before Any Backend Change, Verify:\n\n1. **Parameter Style**: No `%(...)s` in any SQL\n2. **Date Types**: All date params are Python objects\n3. **Enum Usage**: No hardcoded DB strings\n4. **Outlier Filter**: Uses `COALESCE` pattern\n5. **File Location**: SQL in services, not routes\n6. **v2 Compliance**: New endpoints support `?schema=v2`\n\n---\n\n## Part 6: Placeholder/Param Validation\n\n### The Problem\n\nSQL placeholders (`:param`) are strings. Python dict keys are strings. No compiler catches mismatches.\n\n```python\n# BUG: SQL uses :max_date but params dict doesn''t have it\nsql = \"WHERE date < :max_date_exclusive AND date > :max_date - INTERVAL ''12 months''\"\nparams = {\"max_date_exclusive\": tomorrow}  # ❌ Missing max_date!\n```\n\n### The Fix: Validate Before Execute\n\n```python\nimport re\n\ndef validate_sql_params(sql: str, params: dict) -> None:\n    \"\"\"Fail fast if SQL placeholders don''t match params.\"\"\"\n    placeholders = set(re.findall(r'':([a-zA-Z_][a-zA-Z0-9_]*)'', sql))\n    param_keys = set(params.keys())\n\n    missing = placeholders - param_keys\n    if missing:\n        raise ValueError(f\"SQL placeholders missing from params: {missing}\")\n\n    unused = param_keys - placeholders\n    if unused:\n        # Warning only - unused params are safe but wasteful\n        logger.warning(f\"Unused params (not in SQL): {unused}\")\n```\n\n**Where to add:** In your DB helper so ALL queries benefit automatically.\n\n---\n\n## Part 6b: Common Mistakes Quick Reference\n\n| Anti-Pattern | Symptom | Grep to Find | Fix |\n|--------------|---------|--------------|-----|\n| `%(param)s` style | Works locally, breaks in prod | `grep -rn \"%(.*)\" backend/` | Use `:param` style |\n| String dates | Query returns wrong results | `grep -rn ''\"20[0-9][0-9]-'' backend/services/` | Use Python `date()` objects |\n| Hardcoded enums | Filter mismatches | `grep -rn \"''Resale''\\|''New Sale''\" backend/` | Use `SaleType.to_db()` |\n| Missing COALESCE | Outliers included | `grep -rn \"is_outlier = false\" backend/` | Use `COALESCE(is_outlier, false) = false` |\n| Mixed date params | Silent data gaps | `grep -rn \"max_date.*max_date_exclusive\" backend/` | Pick ONE convention per query |\n| SQL in routes | Scattered logic | `grep -rn \"text\\(\" backend/routes/` | Move to services/ |\n\n### Quick Audit Commands\n\n```bash\n# Find psycopg2-style params (FORBIDDEN)\ngrep -rn \"%(\" backend/services/ backend/routes/\n\n# Find hardcoded date strings\ngrep -rn ''\"20[0-9][0-9]-[0-9][0-9]'' backend/\n\n# Find hardcoded sale type strings\ngrep -rn \"''Resale''\\|''New Sale''\\|''Sub Sale''\" backend/\n\n# Find missing COALESCE on outliers\ngrep -rn \"is_outlier = false\" backend/ | grep -v COALESCE\n\n# Find f-string interpolation in SQL (DANGEROUS)\ngrep -rn ''f\".*WHERE\\|f\".*SELECT\\|f\".*FROM'' backend/\n```\n\n---\n\n## Part 7: Testing Requirements\n\n### Required Tests for SQL Changes\n\n```python\n# Unit test: Pure computation\ndef test_calculate_metrics():\n    result = calculate_metrics(sample_data)\n    assert result[''median''] == expected\n\n# Integration test: Valid query\ndef test_endpoint_returns_data():\n    response = client.get(''/api/endpoint'')\n    assert response.status_code == 200\n\n# Contract test: v2 shape\ndef test_v2_response_is_camel_case():\n    response = client.get(''/api/endpoint?schema=v2'')\n    data = response.json()\n    assert ''medianPsf'' in data\n    assert ''median_psf'' not in data\n```\n\n---\n\n## Part 8: SQL Correctness Patterns\n\n### Stable Keys for Joins\n\n```sql\n-- ❌ WRONG - display name changes break joins\nSELECT * FROM transactions t\nJOIN projects p ON t.project_name = p.project_name\n\n-- ✅ CORRECT - stable identifier\nSELECT * FROM transactions t\nJOIN projects p ON t.project_id = p.project_id\n```\n\n### Deterministic Aggregations\n\n```sql\n-- ❌ WRONG - non-deterministic (arbitrary tie-break)\nSELECT MODE() WITHIN GROUP (ORDER BY project_name) as canonical_name\n\n-- ❌ WRONG - unordered array\nSELECT array_agg(project_name) as names\n\n-- ✅ CORRECT - explicit ordering/tie-break\nSELECT project_name\nFROM projects\nORDER BY transaction_count DESC, project_id  -- id breaks ties\nLIMIT 1\n\n-- ✅ CORRECT - ordered array\nSELECT array_agg(project_name ORDER BY project_id) as names\n```\n\n### Two-Phase Pattern (Invariant Truth)\n\n```sql\n-- ❌ WRONG - filter changes the definition of launch_date\nWITH filtered AS (\n    SELECT * FROM transactions WHERE district = ''D01''\n)\nSELECT project_id, MIN(transaction_date) as launch_date\nFROM filtered\nGROUP BY project_id  -- Launch date shifts based on filter!\n\n-- ✅ CORRECT - compute globally, then filter membership\nWITH launch_dates AS (\n    -- Phase A: Compute truth globally (no filters)\n    SELECT project_id, MIN(transaction_date) as launch_date\n    FROM transactions\n    GROUP BY project_id\n),\nfiltered_projects AS (\n    -- Phase B: Filter is membership, not redefinition\n    SELECT DISTINCT project_id\n    FROM transactions\n    WHERE district = ''D01''\n)\nSELECT ld.*\nFROM launch_dates ld\nWHERE ld.project_id IN (SELECT project_id FROM filtered_projects)\n```\n\n### Static SQL with NULL Guards\n\n```sql\n-- ❌ FORBIDDEN - Dynamic string building in Python\nquery = \"SELECT * FROM txn WHERE 1=1\"\nif bedroom:\n    query += f\" AND bedroom = {bedroom}\"  -- Injection risk!\n\n-- ✅ CORRECT - Static SQL, all filters in one query\nSELECT * FROM transactions\nWHERE COALESCE(is_outlier, false) = false\n  AND (:bedroom IS NULL OR bedroom = :bedroom)\n  AND (:district IS NULL OR district = :district)\n  AND (:date_from IS NULL OR transaction_date >= :date_from)\n  AND (:date_to IS NULL OR transaction_date < :date_to)\n```\n\n### DB Does Set Work (No N+1)\n\n```python\n# ❌ WRONG - O(n²) Python loop\nproject_names = db.execute(\"SELECT DISTINCT project_name FROM txn\").fetchall()\nfor name in project_names:\n    units = db.execute(\"SELECT * FROM units WHERE project_name = :n\", {\"n\": name})\n    # N queries for N projects!\n\n# ✅ CORRECT - Single bulk join\nresult = db.execute(\"\"\"\n    SELECT t.project_name, u.unit_info\n    FROM (SELECT DISTINCT project_name FROM transactions) t\n    LEFT JOIN units u ON t.project_name = u.project_name\n\"\"\")\n```\n\n---\n\n## Quick Reference Card\n\n```\nSQL GUARDRAILS CHECKLIST\n\n[ ] :param style only (no %(param)s)\n[ ] Python date objects (no strings)\n[ ] Enums via contract_schema.py\n[ ] COALESCE(is_outlier, false) = false\n[ ] Parameterized numeric values\n[ ] SQL in service files\n[ ] Placeholders match params.keys()\n[ ] Exclusive bounds only (:max_date_exclusive, not :max_date)\n[ ] v2 endpoint support\n[ ] Tests for v1, v2, edge cases\n```\n\n---\n\n## Sign-Off Template\n\nBefore marking SQL work as complete:\n\n```markdown\n## SQL Change Sign-Off\n\n### Change Summary\n[Brief description]\n\n### Guardrail Compliance\n- [x] Parameter style: :param only\n- [x] Date handling: Python objects\n- [x] Enum handling: contract_schema.py\n- [x] Outlier filter: COALESCE pattern\n- [x] SQL location: services/ directory\n\n### v2 Compliance\n- [x] Supports ?schema=v2\n- [x] Returns camelCase in v2 mode\n- [x] Tests pass for both modes\n\nVerified by: [name]\nDate: [date]\n```\n"},"lastSynced":"2026-03-08T02:04:16.162Z","agentAnalysis":{"suitability":{"en":"Perfect for Backend Agents needing SQL-related bug prevention and v2 API contract compliance.","zh":"非常适合需要SQL相关错误预防和v2 API合同合规性的后端代理。","ja":"SQL関連のバグの防止とv2 API契約のコンプライアンスが必要なバックエンドエージェントに最適です。","ko":"SQL 관련 오류 예방 및 v2 API 계약 규정 준수가 필요한 백엔드 에이전트에 적합합니다.","es":"Perfecto para Agentes de Backend que necesitan prevención de errores relacionados con SQL y cumplimiento del contrato de API v2.","fr":"Parfait pour les agents Backend qui ont besoin d''une prévention de bogues liés à SQL et d''un respect du contrat d''API v2.","de":"Perfekt für Backend-Agents, die eine Verhinderung von SQL-bezogenen Fehlern und eine Einhaltung des API-Vertrags v2 benötigen.","pt":"Perfeito para Agentes Backend que necessitam de prevenção de bugs relacionados ao SQL e conformidade com o contrato da API v2.","ru":"Идеально подходит для агентов Backend, которым необходима предотвращение ошибок, связанных с SQL, и соблюдение соглашения API v2.","ar":"مثالي للوكلاء الخلفية الذين يحتاجون إلى منع أخطاء SQL والامتثال لاتفاق واجهة برمجة التطبيقات v2."},"recommendation":{"en":"Empowers agents to prevent SQL-related bugs and ensure compliance by acting as a guardrail for all backend database operations, utilizing SQL best practices and validating database interactions through mandatory checks before writing SQL queries.","zh":"赋予代理防止SQL相关错误和确保合规性的能力，通过对所有后端数据库操作作为护栏，利用SQL最佳实践并通过强制检查验证数据库交互在编写SQL查询之前。","ja":"エージェントがSQL関連のバグを防止し、コンプライアンスを確保できるようにすることで、バックエンドのデータベース操作すべてに対してガードレールとして機能し、SQLのベストプラクティスを利用し、SQLクエリを記述する前にデータベースの相互作用を必須のチェックによって検証します。","ko":"에이전트가 SQL 관련 오류를 예방하고 규정 준수를 보장할 수 있도록 하여 모든 백엔드 데이터베이스 운영에 대한 가드레일로 작동하고 SQL 최적의 관행을 사용하며 SQL 쿼리를 작성하기 전에 데이터베이스 상호 작용을 필수 확인을 통해 검증합니다.","es":"Habilita a los agentes a prevenir errores relacionados con SQL y garantizar el cumplimiento actuando como una barrera de seguridad para todas las operaciones de bases de datos de backend, utilizando las mejores prácticas de SQL y validando las interacciones con la base de datos a través de controles obligatorios antes de escribir consultas SQL.","fr":"Permet aux agents d''éviter les bogues liés à SQL et de garantir le respect en agissant comme une barrière de sécurité pour toutes les opérations de base de données de backend, en utilisant les meilleures pratiques de SQL et en validant les interactions avec la base de données via des vérifications obligatoires avant d''écrire des requêtes SQL.","de":"Ermächtigt die Agenten, SQL-bezogene Fehler zu verhindern und die Einhaltung sicherzustellen, indem sie als Schutzbarriere für alle Backend-Datenbankoperationen dienen, SQL-Best-Practices nutzen und Datenbankinteraktionen durch obligatorische Prüfungen vor dem Schreiben von SQL-Abfragen validieren.","pt":"Habilita os agentes a prevenir bugs relacionados ao SQL e garantir a conformidade, atuando como uma barreira de segurança para todas as operações de banco de dados backend, utilizando as melhores práticas de SQL e validando interações de banco de dados por meio de verificações obrigatórias antes de escrever consultas SQL.","ru":"Наделяет агентов возможностью предотвращать ошибки, связанные с SQL, и обеспечивать соблюдение требований, выступая в качестве ограничителя для всех операций с базами данных Backend, используя лучшие практики SQL и проверяя взаимодействия с базой данных через обязательные проверки перед написанием запросов SQL.","ar":"تمكن الوكلاء من منع أخطاء SQL وضمان الامتثال للاتفاقات من خلال العمل كمصدات أمان لجميع عمليات قاعدة البيانات الخلفية، واستخدام أفضل الممارسات لSQL و التحقق من التفاعلات مع قاعدة البيانات من خلال الفحوصات الإلزامية قبل كتابة استفسارات SQL."},"useCases":{"en":["Preventing SQL injection attacks","Validating SQL syntax for database operations","Ensuring v2 API contract compliance for backend services"],"zh":["防止SQL注入攻击","验证数据库操作的SQL语法","确保后端服务的v2 API合同合规性"],"ja":["SQLインジェクション攻撃の防止","データベース操作のSQL構文の検証","バックエンドサービスのv2 API契約のコンプライアンスの確保"],"ko":["SQL 주입 공격 예방","데이터베이스 운영의 SQL 구문 유효성 검사","백엔드 서비스의 v2 API 계약 규정 준수 보장"],"es":["Prevenir ataques de inyección SQL","Validar la sintaxis SQL para operaciones de base de datos","Garantizar el cumplimiento del contrato de API v2 para servicios de backend"],"fr":["Prévenir les attaques d''injection SQL","Valider la syntaxe SQL pour les opérations de base de données","Garantir le respect du contrat d''API v2 pour les services de backend"],"de":["Verhindern von SQL-Injection-Angriffen","Validieren der SQL-Syntax für Datenbankoperationen","Sicherstellen der Einhaltung des API-Vertrags v2 für Backend-Dienste"],"pt":["Prevenindo ataques de injeção de SQL","Validando a sintaxe de SQL para operações de banco de dados","Garantindo a conformidade com o contrato da API v2 para serviços backend"],"ru":["Предотвращение атак по внедрению SQL","Проверка синтаксиса SQL для операций с базой данных","Обеспечение соблюдения соглашения API v2 для сервисов Backend"],"ar":["منع هجمات حقن SQL","التحقق من بناء جملة SQL لعمليات قاعدة البيانات","ضمان امتثال اتفاق واجهة برمجة التطبيقات v2 لخدمات الخلفية"]},"limitations":{"en":["Requires integration with backend database operations","Limited to preventing SQL-related bugs and compliance checks"],"zh":["需要与后端数据库操作集成","仅限于防止SQL相关错误和合规性检查"],"ja":["バックエンドのデータベース操作との統合が必要","SQL関連のバグの防止とコンプライアンスチェックに限定される"],"ko":["백엔드 데이터베이스 운영과의 통합이 필요","SQL 관련 오류 예방 및 규정 준수 확인에만 제한됨"],"es":["Requiere integración con operaciones de base de datos de backend","Limitado a la prevención de errores relacionados con SQL y controles de cumplimiento"],"fr":["Nécessite une intégration avec les opérations de base de données de backend","Limité à la prévention des bogues liés à SQL et aux contrôles de respect"],"de":["Erfordert Integration mit Backend-Datenbankoperationen","Begrenzt auf die Verhinderung von SQL-bezogenen Fehlern und Einhaltungskontrollen"],"pt":["Requer integração com operações de banco de dados backend","Limitado à prevenção de bugs relacionados ao SQL e verificações de conformidade"],"ru":["Требует интеграции с операциями базы данных Backend","Ограничен предотвращением ошибок, связанных с SQL, и проверками на соответствие"],"ar":["يتطلب دمجًا مع عمليات قاعدة البيانات الخلفية","محدود بمنع أخطاء SQL والتحقق من الامتثال"]},"version":4},"contentHash":"c7912f27e29a3f12f456a9c089542c6059258e385462c2e5995201614f786eec","qualityScore":42}');
