INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sgpropertyanalytics/sg-property-analytics/sql-guardrails', 'sql-guardrails', 'sgpropertyanalytics', 'sg-property-analytics', 'community', 'sql-guardrails sgpropertyanalytics sg-property-analytics community sql-guardrails acts as a guardrail for all backend database operations, preventing SQL-related bugs and ensuring compliance. This skill benefits developers working with SQL queries and database operations. SQL-Guardrails 是一种防止 SQL 相关错误的技能，确保 v2 API 合约遵从。它提供了强大的后端数据库操作保护 SQL-Guardrails は、SQL 関連のバグを防ぎ、v2 API 契約の遵守を確保するスキルです。強力なバックエンド データベース操作保護を提供します SQL-Guardrails는 SQL 관련 버그를 방지하며 v2 API 계약 준수를 보장하는 스킬입니다. 강력한 백엔드 데이터베이스 운영 보호를 제공 sql-guardrails es un skill que actúa como guardrail para operaciones de base de datos backend, previniendo errores SQL y asegurando el cumplimiento del contrato de API v2 sql-guardrails est un skill qui agit comme une guardrail pour les opérations de base de données backend, prévenant les bogues SQL et assurant la conformité du contrat d''API v2 sql-guardrails ist ein Skill, der als Guardrail für Backend-Datenbankoperationen fungiert, um SQL-Fehler zu vermeiden und die Einhaltung des API-v2-Vertrags zu gewährleisten O SQL-Guardrails é uma habilidade que atua como uma barreira de segurança para operações de banco de dados, prevenindo bugs relacionados ao SQL SQL-Guardrails - это навык, который действует как барьер безопасности для операций с базами данных, предотвращая ошибки, связанные с SQL SQL-Guardrails هو مهارة يعمل كحاجز أمان للعمليات المتعلقة بقواعد البيانات، ويلغي الأخطاء المرتبطة ب SQL how to use sql-guardrails sql-guardrails setup guide sql-guardrails alternative sql-guardrails vs ORM preventing SQL-related bugs backend database operations v2 API contract compliance sql-guardrails install sql-guardrails documentation SQL-Guardrails AI 工具 SQL 相关错误 v2 API 合约遵从 后端数据库操作保护 SQL 查询 服务函数 API 端点 Mandatory checks before writing SQL queries Supports raw and ORM SQL queries Ensures compliance with v2 API contract Activates when writing or modifying SQL queries Integrates with service functions that touch the database References SQL best practices from SQL_BEST_PRACTICES.md sql-guardrails is a skill that prevents SQL-related bugs and ensures v2 API contract compliance by acting as a guardrail for backend database operations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('robinebers/openusage/tauri-development', 'community', 'robinebers', 'openusage', 'robinebers/openusage', 'tauri-development', 0, 0, 42, '2026-03-08T01:57:15.369Z', '2026-03-08T02:04:24.610Z', '45d43ef9223a6762ae5957ed99a9dad439bf7af5a9273ad27f4b4ac5738ae0f2', '{"id":"robinebers/openusage/tauri-development","name":"tauri-development","description":{"en":"Tauri-development enables experts in TypeScript and Rust to build cross-platform desktop applications. It benefits developers seeking efficient and maintainable code.","zh":"Tauri开发指南，涵盖TypeScript和Rust开发的最佳实践","ja":"Tauri開発のためのガイド，フロントエンドとバックエンドの開発方法を紹介","ko":"Tauri 개발을 위한 가이드，TypeScript와 Rust를 사용한 クロスプラットフォーム 데스크톱 애플리케이션 개발","es":"Tauri es un framework para desarrollo de aplicaciones de escritorio cross-plataforma. Utiliza TypeScript y Rust para crear aplicaciones de alta calidad.","fr":"Tauri est un framework pour le développement d''applications de bureau cross-plateforme. Il utilise TypeScript et Rust pour créer des applications de haute qualité.","de":"Tauri ist ein Framework für die Entwicklung von cross-plattformfähigen Desktop-Anwendungen. Es verwendet TypeScript und Rust, um hochwertige Anwendungen zu erstellen.","pt":"Desenvolva aplicativos de desktop cross-plataforma com Tauri, utilizando TypeScript e Rust. Siga as diretrizes para uma codificação limpa e eficiente.","ru":"Разрабатывайте кроссплатформенные настольные приложения с помощью Tauri, используя TypeScript и Rust. Следуйте руководящим принципам для чистого и эффективного кодирования ИИ Агентов.","ar":"تطوير تطبيقات سطح المكتب متعددة المنصات باستخدام Tauri، مع استخدام TypeScript و Rust. اتبع الإرشادات للحصول على ترميز نظيف وفعال مع أدوات الذكاء الاصطناعي."},"seo":{"title":{"en":"Tauri-Development: Cross-Platform Setup Guide | AI Agent ...","zh":"Tauri 开发最佳实践指南","ja":"Tauri開発セットアップガイド - AIエージェント","ko":"Tauri 개발 가이드: TypeScript와 Rust를 위한 최고의 프랙티스","es":"Guía de configuración de Tauri para desarrollo de aplicac...","fr":"Guide de démarrage rapide pour le développement Tauri d''a...","de":"Tauri-Entwicklung: Leitfaden für die Erstellung von Deskt...","pt":"Guia de Configuração Tauri para Desenvolvimento de Aplica...","ru":"Настройка Tauri для разработки кроссплатформенных приложе...","ar":"دليل إعداد توري لتنمية التطبيقات跨المنصات مع أدوات ذكاء اص..."},"description":{"en":"Unlock efficient cross-platform development with Tauri. Learn how to set up and optimize your workflow with our expert guide. Get started now!","zh":"了解Tauri开发的核心原则和技术栈，包括TypeScript、Rust、TailwindCSS和ShadCN-UI","ja":"Tauri開発のためのステップバイステップガイド - フロントエンドとバックエンドのベストプラクティス","ko":"Tauri 개발을 위한 클린 코드와 보안, 성능优化에 대한 정보","es":"Aprende a desarrollar aplicaciones de escritorio cross-plataforma con Tauri, utilizando TypeScript, Rust y TailwindCSS","fr":"Découvrez comment créer des applications de bureau cross-plateforme avec Tauri, en utilisant TypeScript, Rust et TailwindCSS","de":"Erfahren Sie, wie Sie cross-plattformfähige Desktop-Anwendungen mit Tauri, TypeScript, Rust und TailwindCSS entwickeln","pt":"Aprenda a desenvolver aplicativos de desktop cross-plataforma com Tauri, TypeScript e Rust. Confira as melhores práticas e dicas para começar.","ru":"Узнайте, как разрабатывать кроссплатформенные настольные приложения с помощью Tauri, TypeScript и Rust. Проверьте лучшие практики и советы для начала работы ...","ar":"تعلم كيفية تطوير تطبيقات سطح المكتب متعددة المنصات باستخدام Tauri و TypeScript و Rust. راجع أفضل الممارسات والنصائح للبدء في استخدام أدوات الذكاء الاصطناعي."},"definition":{"en":"Tauri-development is a set of guidelines for building cross-platform desktop applications using TypeScript, Rust, and Tauri APIs.","zh":"Tauri开发是一种使用TypeScript和Rust进行跨平台桌面应用开发的方法","ja":"Tauri開発とは，TypeScriptとRustを使用したクロスプラットフォームデスクトップアプリケーションの開発方法","ko":"Tauri 개발이란 TypeScript와 Rust를 사용하여 クロスプラットフォーム 데스크톱 애플리케이션을 개발하는 방법","es":"Tauri es un framework de código abierto para desarrollo de aplicaciones de escritorio","fr":"Tauri est un framework open source pour le développement d''applications de bureau","de":"Tauri ist ein Open-Source-Framework für die Entwicklung von Desktop-Anwendungen","pt":"Tauri é uma plataforma de desenvolvimento de aplicativos de desktop cross-plataforma que utiliza TypeScript e Rust.","ru":"Tauri - это платформа для разработки кроссплатформенных настольных приложений, использующая TypeScript и Rust для ИИ Агентов.","ar":"Tauri هو منصة لتنمية تطبيقات سطح المكتب متعددة المنصات التي تستخدم TypeScript و Rust لأدوات الذكاء الاصطناعي."},"features":{"en":["Writes clean, maintainable TypeScript and Rust code","Utilizes TailwindCSS and ShadCN-UI for styling","Follows step-by-step planning for complex features","Prioritizes code quality, security, and performance with Tauri APIs","Supports frontend development with React/Next.js","Enables backend development with Rust"],"zh":["使用TypeScript和Rust进行跨平台桌面应用开发","集成TailwindCSS和ShadCN-UI进行样式设计","遵循步骤式规划进行复杂功能开发","优先考虑代码质量、安全性和性能"],"ja":["TypeScriptとRustを使用したクロスプラットフォームデスクトップアプリケーションの開発","TailwindCSSとShadCN-UIを使用したスタイル設計","ステップバイステップの計画に従った複雑な機能の開発","コード品質、セキュリティ、パフォーマンスの優先化"],"ko":["TypeScript와 Rust를 사용한 クロスプラットフォーム 데스크톱 애플리케이션 개발","TailwindCSS와 ShadCN-UI를 사용한 스타일 디자인","단계별 계획에 따른 복잡한 기능 개발","코드 품질, 보안, 성능의 우선화"],"es":["Desarrollo de aplicaciones de escritorio cross-plataforma con TypeScript y Rust","Utilización de TailwindCSS y ShadCN-UI para el diseño de la interfaz de usuario","Seguimiento de principios de planificación para características complejas","Priorización de la calidad, seguridad y rendimiento del código","Uso de Tauri APIs para el desarrollo del backend","Compatibilidad con React y Next.js para el desarrollo del frontend"],"fr":["Développement d''applications de bureau cross-plateforme avec TypeScript et Rust","Utilisation de TailwindCSS et ShadCN-UI pour la conception de l''interface utilisateur","Suivi de principes de planification pour les fonctionnalités complexes","Priorisation de la qualité, de la sécurité et des performances du code","Utilisation de Tauri APIs pour le développement du backend","Compatibilité avec React et Next.js pour le développement du frontend"],"de":["Entwicklung von cross-plattformfähigen Desktop-Anwendungen mit TypeScript und Rust","Verwendung von TailwindCSS und ShadCN-UI für das Design der Benutzeroberfläche","Befolgen von Planungsprinzipien für komplexe Funktionen","Priorisierung von Codequalität, Sicherheit und Leistung","Verwendung von Tauri APIs für die Entwicklung des Backends","Kompatibilität mit React und Next.js für die Entwicklung des Frontends"],"pt":["Desenvolvimento de aplicativos com TypeScript e React/Next.js","Utilização de TailwindCSS e ShadCN-UI para estilização","Suporte a Rust para desenvolvimento de backend","Integração com Tauri APIs para funcionalidades avançadas","Priorização da qualidade, segurança e desempenho do código"],"ru":["Разработка приложений с помощью TypeScript и React/Next.js для ИИ Агентов","Использование TailwindCSS и ShadCN-UI для стилизации","Поддержка Rust для разработки бэкенда","Интеграция с Tauri APIs для расширенных функций","Приоритет качества, безопасности и производительности кода"],"ar":["تطوير التطبيقات باستخدام TypeScript و React/Next.js لأدوات الذكاء الاصطناعي","استخدام TailwindCSS و ShadCN-UI للتنسيق","دعم Rust لتنمية الخلفية","التكامل مع Tauri APIs لوظائف متقدمة","الاولوية لجودة وأمان واداء الكود"]},"keywords":{"en":["how to use tauri-development","tauri-development vs electron","tauri-development install","what is tauri-development","tauri-development alternative","tauri-development setup guide","tauri-development tutorial","tauri-development best practices","cross-platform development with tauri"],"zh":["Tauri开发","TypeScript开发","Rust开发","跨平台桌面应用","TailwindCSS","ShadCN-UI","代码质量","安全性","性能优化"],"ja":["Tauri開発","TypeScript開発","Rust開発","クロスプラットフォームデスクトップアプリケーション","TailwindCSS","ShadCN-UI","コード品質","セキュリティ","パフォーマンス最適化"],"ko":["Tauri 개발","TypeScript 개발","Rust 개발","クロスプラットフォーム 데스크톱 애플리케이션","TailwindCSS","ShadCN-UI","코드 품질","보안","성능 최적화"],"es":["desarrollo de aplicaciones de escritorio","Tauri","TypeScript","Rust","TailwindCSS","ShadCN-UI","React","Next.js","desarrollo cross-plataforma","framework de código abierto"],"fr":["développement d''applications de bureau","Tauri","TypeScript","Rust","TailwindCSS","ShadCN-UI","React","Next.js","développement cross-plateforme","framework open source"],"de":["Entwicklung von Desktop-Anwendungen","Tauri","TypeScript","Rust","TailwindCSS","ShadCN-UI","React","Next.js","cross-plattformfähige Entwicklung","Open-Source-Framework"],"pt":["Tauri desenvolvimento","aplicativos de desktop cross-plataforma","TypeScript","Rust","React/Next.js","TailwindCSS","ShadCN-UI","desenvolvimento de aplicativos"],"ru":["Tauri разработка","кроссплатформенные настольные приложения","TypeScript","Rust","React/Next.js","TailwindCSS","ShadCN-UI","ИИ Агенты","разработка приложений"],"ar":["توري تنمية","تطبيقات سطح المكتب متعددة المنصات","TypeScript","Rust","React/Next.js","TailwindCSS","ShadCN-UI","أدوات الذكاء الاصطناعي","تنمية التطبيقات"]}},"owner":"robinebers","repo":"openusage","repoPath":"robinebers/openusage","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.369Z","topics":[],"category":"community","skillMd":{"name":"tauri-development","description":"Tauri development guidelines for building cross-platform desktop applications with TypeScript, Rust, and modern web technologies","bodyPreview":"# Tauri Development Guidelines\n\nYou are an expert in TypeScript and Rust development for cross-platform desktop applications using Tauri.\n\n## Core Principles\n\n- Write clean, maintainable TypeScript and Rust code\n- Use TailwindCSS and ShadCN-UI for styling\n- Follow step-by-step planning for complex features\n- Prioritize code quality, security, and performance\n\n## Technology Stack\n\n- **Frontend**: TypeScript, React/Next.js, TailwindCSS, ShadCN-UI\n- **Backend**: Rust, Tauri APIs\n- **Build**: Tauri","body":"# Tauri Development Guidelines\n\nYou are an expert in TypeScript and Rust development for cross-platform desktop applications using Tauri.\n\n## Core Principles\n\n- Write clean, maintainable TypeScript and Rust code\n- Use TailwindCSS and ShadCN-UI for styling\n- Follow step-by-step planning for complex features\n- Prioritize code quality, security, and performance\n\n## Technology Stack\n\n- **Frontend**: TypeScript, React/Next.js, TailwindCSS, ShadCN-UI\n- **Backend**: Rust, Tauri APIs\n- **Build**: Tauri CLI, Vite/Webpack\n\n## Project Structure\n\n```\nsrc/\n├── app/                # Next.js app directory\n├── components/         # React components\n│   ├── ui/            # ShadCN-UI components\n│   └── features/      # Feature-specific components\n├── hooks/             # Custom React hooks\n├── lib/               # Utility functions\n├── styles/            # Global styles\nsrc-tauri/\n├── src/               # Rust source code\n│   ├── main.rs       # Entry point\n│   └── commands/     # Tauri commands\n├── Cargo.toml        # Rust dependencies\n└── tauri.conf.json   # Tauri configuration\n```\n\n## TypeScript Guidelines\n\n### Code Style\n- Use functional components with TypeScript\n- Define proper interfaces for all data structures\n- Use async/await for asynchronous operations\n- Implement proper error handling\n\n### Tauri Integration\n```typescript\nimport { invoke } from ''@tauri-apps/api/tauri'';\n\n// Call Rust commands from frontend\nconst result = await invoke<string>(''my_command'', { arg: ''value'' });\n\n// Listen to events from Rust\nimport { listen } from ''@tauri-apps/api/event'';\nawait listen(''event-name'', (event) => {\n  console.log(event.payload);\n});\n```\n\n## Rust Guidelines\n\n### Command Definitions\n```rust\n#[tauri::command]\nfn my_command(arg: String) -> Result<String, String> {\n    // Implementation\n    Ok(format!(\"Received: {}\", arg))\n}\n\nfn main() {\n    tauri::Builder::default()\n        .invoke_handler(tauri::generate_handler![my_command])\n        .run(tauri::generate_context!())\n        .expect(\"error while running tauri application\");\n}\n```\n\n### Error Handling\n- Use Result types for fallible operations\n- Define custom error types when needed\n- Propagate errors appropriately\n- Log errors for debugging\n\n### Security\n- Validate all inputs from the frontend\n- Use Tauri''s security features (CSP, allowlist)\n- Minimize permissions in tauri.conf.json\n- Sanitize file paths and user inputs\n\n## UI Development\n\n### TailwindCSS\n- Use utility-first approach\n- Implement responsive design\n- Use dark mode support\n- Follow consistent spacing and sizing\n\n### ShadCN-UI Components\n- Use pre-built accessible components\n- Customize with TailwindCSS\n- Maintain consistent theming\n- Follow accessibility best practices\n\n## State Management\n\n- Use React Context for global state\n- Consider Zustand for complex state\n- Keep state close to where it''s used\n- Implement proper state synchronization with Rust\n\n## File System Operations\n\n```rust\nuse std::fs;\nuse tauri::api::path::app_data_dir;\n\n#[tauri::command]\nfn read_file(path: String) -> Result<String, String> {\n    fs::read_to_string(&path)\n        .map_err(|e| e.to_string())\n}\n\n#[tauri::command]\nfn write_file(path: String, content: String) -> Result<(), String> {\n    fs::write(&path, content)\n        .map_err(|e| e.to_string())\n}\n```\n\n## Building and Distribution\n\n- Configure proper app metadata\n- Set up code signing for distribution\n- Use Tauri''s updater for auto-updates\n- Test on all target platforms\n\n## Performance\n\n- Minimize IPC calls between frontend and Rust\n- Use batch operations where possible\n- Implement proper caching\n- Profile and optimize hot paths\n\n## Testing\n\n- Write unit tests for Rust commands\n- Test frontend components\n- Implement integration tests\n- Test on all target platforms\n"},"lastSynced":"2026-03-08T02:04:24.610Z","agentAnalysis":{"suitability":{"en":"Perfect for Cross-Platform Agents needing efficient desktop application development with TypeScript and Rust.","zh":"适用于需要使用TypeScript和Rust进行高效桌面应用程序开发的跨平台Agent。","ja":"TypeScriptとRustを使用したデスクトップアプリケーション開発に効率的なクロスプラットフォームエージェントに最適。","ko":"TypeScript와 Rust를 사용한 효율적인 데스크톱 애플리케이션 개발이 필요한 크로스 플랫폼 에이전트에 적합합니다.","es":"Perfecto para agentes de plataforma cruzada que necesitan un desarrollo de aplicaciones de escritorio eficiente con TypeScript y Rust.","fr":"Parfait pour les agents de plateforme croisée nécessitant un développement d''applications de bureau efficace avec TypeScript et Rust.","de":"Perfekt für Cross-Platform-Agents, die ein effizientes Desktop-Anwendungs-Development mit TypeScript und Rust benötigen.","pt":"Perfeito para Agentes Cross-Platform que precisam de desenvolvimento de aplicativos de desktop eficientes com TypeScript e Rust.","ru":"Идеально подходит для агентов с кроссплатформенной поддержкой, которым необходим эффективный разработка настольных приложений с помощью TypeScript и Rust.","ar":" مثالي لويكلاء التطبيقات عبر المنصات التي تحتاج إلى تطوير تطبيقات سطح المكتب فعال مع TypeScript و Rust."},"recommendation":{"en":"Empowers agents to build maintainable and secure cross-platform desktop applications using Tauri, leveraging TypeScript, React/Next.js, and Rust, with styling capabilities from TailwindCSS and ShadCN-UI.","zh":"赋予代理构建可维护和安全的跨平台桌面应用程序的能力，利用Tauri，TypeScript，React/Next.js和Rust，并使用TailwindCSS和ShadCN-UI进行样式设置。","ja":"Tauri、TypeScript、React/Next.js、Rustを利用し、TailwindCSSとShadCN-UIによるスタイリング機能を使用して、メンテナンス性とセキュリティのあるクロスプラットフォームデスクトップアプリケーションを構築するエージェントをEmpowerする。","ko":"Tauri, TypeScript, React/Next.js, Rust를 사용하여 유지 보수와 보안이 가능한 크로스 플랫폼 데스크톱 애플리케이션을 구축할 수 있는 에이전트를 강화하며, TailwindCSS와 ShadCN-UI를 사용한 스타일링 기능도 제공합니다.","es":"Permite a los agentes crear aplicaciones de escritorio de plataforma cruzada mantenibles y seguras utilizando Tauri, aprovechando TypeScript, React/Next.js, y Rust, con capacidades de estilo de TailwindCSS y ShadCN-UI.","fr":"Permet aux agents de créer des applications de bureau croisées maintenables et sécurisées en utilisant Tauri, en exploitant TypeScript, React/Next.js, et Rust, avec des capacités de style de TailwindCSS et ShadCN-UI.","de":"Ermächtigt Agenten, wartbare und sichere Cross-Platform-Desktop-Anwendungen mit Tauri, TypeScript, React/Next.js und Rust zu erstellen, mit Styling-Fähigkeiten von TailwindCSS und ShadCN-UI.","pt":"Habilita os agentes a construir aplicações de desktop cross-platform mantidas e seguras usando Tauri, aproveitando TypeScript, React/Next.js e Rust, com capacidades de estilização do TailwindCSS e ShadCN-UI.","ru":"Наделяет агентов возможностью создавать поддерживаемые и безопасные кроссплатформенные настольные приложения, используя Tauri, с помощью TypeScript, React/Next.js и Rust, а также с возможностями стилизации от TailwindCSS и ShadCN-UI.","ar":"يمنح الوكلاء القدرة على بناء تطبيقات سطح المكتب المتوافقة عبر المنصات والمحتفظ بها وأمنة باستخدام Tauri، واستخدام TypeScript و React/Next.js و Rust، مع إمكانيات التنسيق من TailwindCSS و ShadCN-UI."},"useCases":{"en":["Building cross-platform desktop applications with TypeScript and Rust","Implementing responsive and customizable UI components using TailwindCSS and ShadCN-UI","Developing scalable and secure backend services with Tauri APIs and Rust"],"zh":["使用TypeScript和Rust构建跨平台桌面应用程序","使用TailwindCSS和ShadCN-UI实现响应式和可定制的UI组件","使用Tauri API和Rust开发可扩展和安全的后端服务"],"ja":["TypeScriptとRustを使用したクロスプラットフォームデスクトップアプリケーションの構築","TailwindCSSとShadCN-UIを使用したレスポンシブでカスタマイズ可能なUIコンポーネントの実装","Tauri APIとRustを使用したスケーラブルでセキュアなバックエンドサービスの開発"],"ko":["TypeScript와 Rust를 사용한 크로스 플랫폼 데스크톱 애플리케이션 구축","TailwindCSS와 ShadCN-UI를 사용한 반응형 및 사용자 지정 가능한 UI 컴포넌트 구현","Tauri API와 Rust를 사용한 확장 가능하고 보안이 가능한 백엔드 서비스 개발"],"es":["Construir aplicaciones de escritorio de plataforma cruzada con TypeScript y Rust","Implementar componentes de IU responsivos y personalizables con TailwindCSS y ShadCN-UI","Desarrollar servicios de backend escalables y seguros con APIs de Tauri y Rust"],"fr":["Créer des applications de bureau croisées avec TypeScript et Rust","Implémenter des composants d''interface utilisateur responsifs et personnalisables avec TailwindCSS et ShadCN-UI","Développer des services de backend évolutifs et sécurisés avec les API Tauri et Rust"],"de":["Erstellen von Cross-Platform-Desktop-Anwendungen mit TypeScript und Rust","Implementieren responsiver und anpassbarer Benutzeroberflächen-Komponenten mit TailwindCSS und ShadCN-UI","Entwickeln von skalierbaren und sicheren Backend-Diensten mit Tauri-APIs und Rust"],"pt":["Construir aplicações de desktop cross-platform com TypeScript e Rust","Implementar componentes de UI responsivos e personalizáveis usando TailwindCSS e ShadCN-UI","Desenvolver serviços de backend escaláveis e seguros com Tauri APIs e Rust"],"ru":["Создание кроссплатформенных настольных приложений с помощью TypeScript и Rust","Реализация отзывчивых и настраиваемых компонентов пользовательского интерфейса с помощью TailwindCSS и ShadCN-UI","Разработка масштабируемых и безопасных сервисов бэкенда с помощью Tauri API и Rust"],"ar":["بناء تطبيقات سطح المكتب المتوافقة عبر المنصات باستخدام TypeScript و Rust","تنفيذ مكونات واجهة المستخدم المنضبطة والقابلة للتعديل باستخدام TailwindCSS و ShadCN-UI","تطوير خدمات الخلفية القابلة للتطوير والأمن باستخدام Tauri APIs و Rust"]},"limitations":{"en":["Requires proficiency in TypeScript and Rust","Limited to desktop application development","Dependent on Tauri and its ecosystem for cross-platform compatibility"],"zh":["需要TypeScript和Rust的专业知识","仅限于桌面应用程序开发","依赖Tauri及其生态系统以实现跨平台兼容性"],"ja":["TypeScriptとRustの熟練度が必要","デスクトップアプリケーション開発に限定される","クロスプラットフォームの互換性を実現するためにTauriとそのエコシステムに依存する"],"ko":["TypeScript와 Rust의 전문 지식이 필요합니다","데스크톱 애플리케이션 개발에만 제한됩니다","크로스 플랫폼 호환성을 위해 Tauri와 그 생태계에 의존합니다"],"es":["Requiere conocimientos en TypeScript y Rust","Limitado al desarrollo de aplicaciones de escritorio","Dependiente de Tauri y su ecosistema para la compatibilidad de plataforma cruzada"],"fr":["Nécessite une maîtrise de TypeScript et Rust","Limité au développement d''applications de bureau","Dépendant de Tauri et de son écosystème pour la compatibilité croisée"],"de":["Benötigt Kenntnisse in TypeScript und Rust","Eingeschränkt auf die Entwicklung von Desktop-Anwendungen","Abhängig von Tauri und seinem Ökosystem für Cross-Platform-Kompatibilität"],"pt":["Exige proficiência em TypeScript e Rust","Limitado ao desenvolvimento de aplicações de desktop","Dependente do Tauri e seu ecossistema para compatibilidade cross-platform"],"ru":["Требует профессионализма в TypeScript и Rust","Ограничен разработкой настольных приложений","Зависит от Tauri и его экосистемы для кроссплатформенной совместимости"],"ar":["يتطلب إتقانًا في TypeScript و Rust","محدود بتطوير تطبيقات سطح المكتب","يعتمد على Tauri وبيئته لتوافق المنصات المتعددة"]},"version":4},"contentHash":"45d43ef9223a6762ae5957ed99a9dad439bf7af5a9273ad27f4b4ac5738ae0f2","qualityScore":42}');
