INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('robinebers/openusage/tauri-development', 'tauri-development', 'robinebers', 'openusage', 'community', 'tauri-development robinebers openusage community Tauri-development enables experts in TypeScript and Rust to build cross-platform desktop applications. It benefits developers seeking efficient and maintainable code. Tauri开发指南，涵盖TypeScript和Rust开发的最佳实践 Tauri開発のためのガイド，フロントエンドとバックエンドの開発方法を紹介 Tauri 개발을 위한 가이드，TypeScript와 Rust를 사용한 クロスプラットフォーム 데스크톱 애플리케이션 개발 Tauri es un framework para desarrollo de aplicaciones de escritorio cross-plataforma. Utiliza TypeScript y Rust para crear aplicaciones de alta calidad. Tauri est un framework pour le développement d''applications de bureau cross-plateforme. Il utilise TypeScript et Rust pour créer des applications de haute qualité. Tauri ist ein Framework für die Entwicklung von cross-plattformfähigen Desktop-Anwendungen. Es verwendet TypeScript und Rust, um hochwertige Anwendungen zu erstellen. Desenvolva aplicativos de desktop cross-plataforma com Tauri, utilizando TypeScript e Rust. Siga as diretrizes para uma codificação limpa e eficiente. Разрабатывайте кроссплатформенные настольные приложения с помощью Tauri, используя TypeScript и Rust. Следуйте руководящим принципам для чистого и эффективного кодирования ИИ Агентов. تطوير تطبيقات سطح المكتب متعددة المنصات باستخدام Tauri، مع استخدام TypeScript و Rust. اتبع الإرشادات للحصول على ترميز نظيف وفعال مع أدوات الذكاء الاصطناعي. how to use tauri-development tauri-development vs electron tauri-development install what is tauri-development tauri-development alternative tauri-development setup guide tauri-development tutorial tauri-development best practices cross-platform development with tauri Tauri开发 TypeScript开发 Rust开发 跨平台桌面应用 TailwindCSS ShadCN-UI 代码质量 安全性 性能优化 Writes clean, maintainable TypeScript and Rust code Utilizes TailwindCSS and ShadCN-UI for styling Follows step-by-step planning for complex features Prioritizes code quality, security, and performance with Tauri APIs Supports frontend development with React/Next.js Enables backend development with Rust Tauri-development is a set of guidelines for building cross-platform desktop applications using TypeScript, Rust, and Tauri APIs.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('invowk/invowk/cue', 'community', 'invowk', 'invowk', 'invowk/invowk', 'cue', 0, 0, 42, '2026-03-08T01:57:15.370Z', '2026-03-08T02:04:25.140Z', '24fc02815334f4c118772b43fe78a0102db363a62d2a2eadf581b9537ae2f2ab', '{"id":"invowk/invowk/cue","name":"cue","description":{"en":"The cue skill is designed for developers working with CUE schema files, providing a dynamically extensible command runner. It benefits those modifying parse functions or adding new CUE definitions.","zh":"CUE 是一种动态可扩展的命令运行器，支持 CUE 模式和 invowkfile 结构","ja":"CUE は、CUE スキーマと invowkfile 構造をサポートする動的可拡張コマンド実行器です","ko":"CUE는 동적 확장 명령 실행기로서 CUE 스키마 및 invowkfile 구조를 지원합니다","es":"Cue es un ejecutor de comandos dinámicamente extensible que trabaja con archivos de esquema CUE","fr":"Cue est un exécuteur de commandes dynamiquement extensible qui travaille avec des fichiers de schéma CUE","de":"Cue ist ein dynamisch erweiterbarer Befehlsausführer, der mit CUE-Schema-Dateien arbeitet","pt":"O Cue é um comando dinamicamente extensível, semelhante ao ''task'' e ''just'', mas com superpoderes próprios. Utilize-o para trabalhar com arquivos de esquema CUE","ru":"Cue - это динамически расширяемый командный запускам,类似 ''task'' и ''just'', но с собственными сверхспособностями. Используйте его для работы с файлами схемы CUE и ИИ Агентов","ar":"Cue هو تشغيل 命令 ديناميكي قابل للتوسيع، مشابه لـ ''task'' و ''just''، ولكن مع قوى خارقة خاصة. استخدمه للعمل مع ملفات مخطط CUE وأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"cue: Extensible Command Runner Setup Guide | AI Agent Skill","zh":"CUE 技术指南：动态可扩展命令运行器","ja":"CUE Setup Guide: AIエージェントによる動的コマンド実行","ko":"CUE 설정 가이드: 동적 확장 명령 실행기","es":"Guía de configuración de Cue: Patrones de esquema y valid...","fr":"Guide de démarrage de Cue : Modèles de schéma et validation","de":"Cue-Setup-Leitfaden: Schema-Muster und Validierung","pt":"Guia de Configuração do Cue: Melhores Práticas para Desen...","ru":"Настройка Cue: Руководство по лучшим практикам для разраб...","ar":"دليل إعداد Cue: أفضل الممارسات لمنطق التطوير مع أدوات الذ..."},"description":{"en":"Unlock the full potential of cue, a dynamically extensible command runner. Explore its superpowers and learn how to integrate it into your workflow today!","zh":"了解 CUE 技术的详细信息，包括 CUE 模式、invowkfile 和 invowkmod 结构等","ja":"CUE の詳細を学ぶ：CUE スキーマ、invowkfile、invowkmod 構造など","ko":"CUE 기술에 대한 자세한 정보: CUE 스키마, invowkfile 및 invowkmod 구조 등","es":"Aprende a utilizar Cue para trabajar con archivos de esquema CUE y validar errores de parseo","fr":"Découvrez comment utiliser Cue pour travailler avec des fichiers de schéma CUE et valider les erreurs de parse","de":"Erfahren Sie, wie Sie Cue verwenden, um mit CUE-Schema-Dateien zu arbeiten und Parse-Fehler zu validieren","pt":"Aprenda a configurar e utilizar o Cue de forma eficaz, incluindo padrões de esquema e localizações de esquema","ru":"Узнайте, как настроить и использовать Cue, включая схемы и местоположения схем для ИИ Агентов","ar":"تعلم كيفية إعداد واستخدام Cue بشكل فعال، بما في ذلك أنماط مخططات Cue ومواقع المخططات لأدوات الذكاء الاصطناعي"},"definition":{"en":"cue is a dynamically extensible command runner, similar to task and just, with its own set of superpowers for working with CUE schema files.","zh":"CUE 是一种命令运行器，支持动态可扩展的 CUE 模式","ja":"CUE は、動的可拡張の CUE スキーマをサポートするコマンド実行器です","ko":"CUE는 동적 확장 가능한 CUE 스키마를 지원하는 명령 실행기입니다","es":"Cue es un ejecutor de comandos que utiliza esquemas CUE para validar y parsear archivos","fr":"Cue est un exécuteur de commandes qui utilise des schémas CUE pour valider et parser des fichiers","de":"Cue ist ein Befehlsausführer, der CUE-Schemata verwendet, um Dateien zu validieren und zu parsen","pt":"O Cue é um comando que executa tarefas de forma dinâmica, utilizando esquemas CUE para definir estruturas","ru":"Cue - это команда, которая запускает задачи динамически, используя схемы CUE для определения структур для ИИ Агентов","ar":"Cue هو أمر ينفذ المهام بشكل ديناميكي، باستخدام مخططات CUE لتعريف الهياكل لأدوات الذكاء الاصطناعي"},"features":{"en":["Works with CUE schema files (*.cue) for flexible configuration","Modifies parse functions in pkg/invowkfile/, pkg/invowkmod/, or internal/config/ for customization","Adds new CUE definitions or corresponding Go struct fields for extensibility","Debugs CUE validation errors for efficient troubleshooting","Utilizes schema locations like pkg/invowkfile/invowkfile_schema.cue for invowkfile structure definition"],"zh":["支持 CUE 模式","invowkfile 和 invowkmod 结构","动态可扩展命令运行","CUE 验证错误调试","支持 pkg/invowkfile/invowkfile_schema.cue"],"ja":["CUE スキーマのサポート","invowkfile と invowkmod 構造","動的可拡張コマンド実行","CUE バリデーションエラーのデバッグ","pkg/invowkfile/invowkfile_schema.cue のサポート"],"ko":["CUE 스키마 지원","invowkfile 및 invowkmod 구조","동적 확장 명령 실행","CUE 검증 오류 디버깅","pkg/invowkfile/invowkfile_schema.cue 지원"],"es":["Trabaja con archivos de esquema CUE","Validación de errores de parseo","Compatibilidad con pkg/invowkfile y pkg/invowkmod","Definición de nuevos esquemas CUE","Soporte para campos de estructura Go"],"fr":["Travail avec des fichiers de schéma CUE","Validation des erreurs de parse","Compatibilité avec pkg/invowkfile et pkg/invowkmod","Définition de nouveaux schémas CUE","Prise en charge des champs de structure Go"],"de":["Arbeitet mit CUE-Schema-Dateien","Validierung von Parse-Fehlern","Kompatibilität mit pkg/invowkfile und pkg/invowkmod","Definition neuer CUE-Schemata","Unterstützung für Go-Struktur-Felder"],"pt":["Suporte a arquivos de esquema CUE","Definição de estruturas com invowkfile_schema.cue","Modificação de funções de parse em pkg/invowkfile e pkg/invowkmod","Adição de novas definições CUE e campos de estrutura Go","Depuração de erros de validação CUE"],"ru":["Поддержка файлов схемы CUE","Определение структур с помощью invowkfile_schema.cue для ИИ Агентов","Модификация функций парсинга в pkg/invowkfile и pkg/invowkmod","Добавление новых определений CUE и полей структуры Go","Отладка ошибок валидации CUE"],"ar":["دعم ملفات مخطط CUE","تحديد الهياكل باستخدام invowkfile_schema.cue لأدوات الذكاء الاصطناعي","تعديل وظائف التحليل في pkg/invowkfile و pkg/invowkmod","إضافة تعريفات CUE جديدة وحقول بنية Go","تصحيح أخطاء التحقق من مخطط CUE"]},"keywords":{"en":["how to use cue","cue alternative","cue vs task","cue install","cue setup guide","what is cue","cue schema patterns","cue validation errors"],"zh":["CUE 技术","动态可扩展命令运行器","CUE 模式","invowkfile 结构","invowkmod 结构","CUE 验证错误调试"],"ja":["CUE 技術","動的可拡張コマンド実行器","CUE スキーマ","invowkfile 構造","invowkmod 構造","CUE バリデーションエラーのデバッグ"],"ko":["CUE 기술","동적 확장 명령 실행기","CUE 스키마","invowkfile 구조","invowkmod 구조","CUE 검증 오류 디버깅"],"es":["Cue","esquemas CUE","validación de errores","parseo de archivos","pkg/invowkfile","pkg/invowkmod","campos de estructura Go","herramientas de desarrollo","Agente de inteligencia artificial"],"fr":["Cue","schémas CUE","validation des erreurs","parse des fichiers","pkg/invowkfile","pkg/invowkmod","champs de structure Go","outils de développement","Outil d''intelligence artificielle"],"de":["Cue","CUE-Schemata","Validierung von Fehlern","Parse von Dateien","pkg/invowkfile","pkg/invowkmod","Go-Struktur-Felder","Entwicklungstools","Künstliche Intelligenz-Tool"],"pt":["Cue","esquema CUE","invowkfile","invowkmod","configuração Cue","desenvolvimento com Cue","erros de validação CUE","padrões de esquema CUE"],"ru":["Cue","схема CUE","invowkfile","invowkmod","настройка Cue","разработка с Cue и ИИ Агентами","ошибки валидации CUE","шаблоны схемы CUE"],"ar":["Cue","مخطط CUE","invowkfile","invowkmod","إعداد Cue","التطوير مع Cue وأدوات الذكاء الاصطناعي","أخطاء التحقق من مخطط CUE","أنماط مخطط CUE"]}},"owner":"invowk","repo":"invowk","repoPath":"invowk/invowk","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.370Z","topics":[],"category":"community","skillMd":{"name":"cue","description":"CUE schema patterns for *.cue files, 3-step parsing flow, validation matrix, error formatting. Use when editing invowkfile_schema.cue, invowkmod_schema.cue, config_schema.cue, or working with cueutil parsing.","bodyPreview":"# CUE Schema Patterns\n\nUse this skill when:\n- Working with CUE schema files (`*.cue`)\n- Modifying parse functions in `pkg/invowkfile/`, `pkg/invowkmod/`, or `internal/config/`\n- Adding new CUE definitions or corresponding Go struct fields\n- Debugging CUE validation errors\n\n---\n\n## Schema Locations\n\n- `pkg/invowkfile/invowkfile_schema.cue` defines invowkfile structure.\n- `pkg/invowkmod/invowkmod_schema.cue` defines invowkmod structure.\n- `internal/config/config_schema.cue` defines config.\n\n## Sch","body":"# CUE Schema Patterns\n\nUse this skill when:\n- Working with CUE schema files (`*.cue`)\n- Modifying parse functions in `pkg/invowkfile/`, `pkg/invowkmod/`, or `internal/config/`\n- Adding new CUE definitions or corresponding Go struct fields\n- Debugging CUE validation errors\n\n---\n\n## Schema Locations\n\n- `pkg/invowkfile/invowkfile_schema.cue` defines invowkfile structure.\n- `pkg/invowkmod/invowkmod_schema.cue` defines invowkmod structure.\n- `internal/config/config_schema.cue` defines config.\n\n## Schema Compilation Pattern (3-Step Flow)\n\nAll CUE parsing in Invowk follows a consistent 3-step pattern:\n\n```go\n// Step 1: Compile the schema (embedded via //go:embed)\nctx := cuecontext.New()\nschemaValue := ctx.CompileString(embeddedSchema)\nif schemaValue.Err() != nil {\n    return nil, fmt.Errorf(\"internal error: failed to compile schema: %w\", schemaValue.Err())\n}\n\n// Step 2: Compile user data and unify with schema\nuserValue := ctx.CompileBytes(data, cue.Filename(path))\nif userValue.Err() != nil {\n    return nil, formatCUEError(userValue.Err(), path)\n}\n\nschema := schemaValue.LookupPath(cue.ParsePath(\"#DefinitionName\"))\nunified := schema.Unify(userValue)\nif err := unified.Validate(cue.Concrete(true)); err != nil {\n    return nil, formatCUEError(err, path)\n}\n\n// Step 3: Decode to Go struct\nvar result GoStructType\nif err := unified.Decode(&result); err != nil {\n    return nil, formatCUEError(err, path)\n}\n```\n\n**Key Points**:\n- Schema is embedded via `//go:embed` for single-binary distribution\n- Use `LookupPath()` to get the root definition (e.g., `#Invowkfile`, `#Config`)\n- Use `Validate(cue.Concrete(true))` to ensure all values are concrete\n- Use `cue.Concrete(false)` for config files where some fields may be optional\n- Always use `Decode()` for type-safe extraction (see Decode Usage Rules below)\n\n**Reference Implementations**:\n- `pkg/invowkfile/parse.go:ParseBytes()` - Invowkfile parsing\n- `pkg/invowkmod/invowkmod.go:ParseInvowkmodBytes()` - Invowkmod parsing\n- `internal/config/config.go:loadCUEIntoViper()` - Config loading\n\n## Validation Responsibility Matrix\n\nValidation is split between CUE and Go based on what each can handle:\n\n### CUE Handles (Declarative, Schema-Level)\n\n| Validation Type | CUE Construct | Example |\n|-----------------|---------------|---------|\n| Type checking | Native | `name: string` |\n| Field format (regex) | `=~` | `name: =~\"^[a-zA-Z][a-zA-Z0-9_-]*$\"` |\n| Enum values | Disjunction | `\"native\" \\| \"virtual\" \\| \"container\"` |\n| Length limits | `strings.MaxRunes()` | `& strings.MaxRunes(256)` |\n| Range constraints | Expressions | `>=0 & <=65535` |\n| Required fields | No `?` suffix | `name: string` (required) |\n| Optional fields | `?` suffix | `description?: string` (optional) |\n| Closed structs | `close({})` | Rejects unknown fields |\n| Mutual exclusivity | XOR constraints | See runtime config patterns |\n| Non-empty lists | Pattern | `[_, ...]` (at least one) |\n\n### Go Handles (Dynamic, Runtime-Level)\n\n| Validation Type | Why Go-Only | Example |\n|-----------------|-------------|---------|\n| ReDoS prevention | CUE cannot analyze regex complexity | `ValidateRegexPattern()` |\n| File existence | Requires filesystem access | `os.Stat()` |\n| Path traversal | Cross-platform normalization | `filepath.Clean()` checks |\n| Cross-field logic | Conditional requirements | Runtime-specific fields |\n| Command hierarchy | Requires tree analysis | Leaf-only args constraint |\n| Length limits (defense-in-depth) | Some limits enforced in Go too | `MaxNameLength` checks |\n\n### Justification Comments\n\nAll Go-only validations MUST include a `[GO-ONLY]` comment explaining why:\n\n```go\n// ValidateRegexPattern validates a user-provided regex pattern for safety.\n// [GO-ONLY] ReDoS (Regular Expression Denial of Service) prevention MUST be in Go.\n// CUE cannot analyze regex complexity or detect catastrophic backtracking patterns.\nfunc ValidateRegexPattern(pattern string) error { ... }\n```\n\n```go\n// validateEnvFilePath validates an env file path for security.\n// [GO-ONLY] Path traversal prevention and cross-platform path handling require Go.\n// CUE cannot perform filesystem operations or cross-platform path normalization.\nfunc validateEnvFilePath(path string) error { ... }\n```\n\n## Decode Usage Rules\n\n**ALWAYS use `value.Decode(&goStruct)` for type-safe extraction.**\n\n### Correct Pattern\n\n```go\nvar invowkfile Invowkfile\nif err := unified.Decode(&invowkfile); err != nil {\n    return nil, formatCUEError(err, path)\n}\n```\n\n### Why Not Manual Extraction?\n\nManual extraction methods (`String()`, `Int64()`, `Bool()`) are error-prone:\n- No compile-time type checking\n- Requires manual error handling for each field\n- Easy to forget optional field handling\n- Doesn''t leverage CUE''s type system\n\n**Exception**: Manual extraction is acceptable only for truly dynamic scenarios (e.g., extracting arbitrary user-defined keys). Document such cases.\n\n## Field Naming Convention\n\nCUE uses `snake_case`, Go uses `PascalCase`. The JSON tag bridges them:\n\n```cue\n// CUE Schema (snake_case)\n#Config: close({\n    container_engine: #ContainerEngine\n    includes:         [...#IncludeEntry]\n    default_runtime:  #RuntimeType\n})\n```\n\n```go\n// Go Struct (PascalCase with JSON tags)\ntype Config struct {\n    ContainerEngine ContainerEngine `json:\"container_engine\"`\n    Includes        []IncludeEntry  `json:\"includes\"`\n    DefaultRuntime  RuntimeMode     `json:\"default_runtime\"`\n}\n```\n\n**Rule**: Every CUE field name MUST have a matching JSON tag in the corresponding Go struct.\n\n**Verification**: Schema sync tests (in `*_sync_test.go` files) catch mismatches at CI time.\n\n## Error Formatting Requirements\n\nAll CUE errors MUST include JSON path prefixes for clear error messages:\n\n### Error Format\n\n```\n<file-path>: <json-path>: <message>\n```\n\nExamples:\n```\ninvowkfile.cue: cmds[0].implementations[2].script: value exceeds maximum length\nconfig.cue: container.auto_provision.enabled: expected bool, got string\n```\n\n### Implementation Pattern\n\nUse the `formatCUEError()` helper (available in each package):\n\n```go\nimport \"cuelang.org/go/cue/errors\"\n\nfunc formatCUEError(err error, filePath string) error {\n    if err == nil {\n        return nil\n    }\n\n    cueErrors := errors.Errors(err)\n    if len(cueErrors) == 0 {\n        return fmt.Errorf(\"%s: %w\", filePath, err)\n    }\n\n    var lines []string\n    for _, e := range cueErrors {\n        path := errors.Path(e)\n        pathStr := formatPath(path)  // Convert [\"cmds\", \"0\", \"script\"] to \"cmds[0].script\"\n        msg := e.Error()\n\n        if pathStr != \"\" {\n            lines = append(lines, fmt.Sprintf(\"%s: %s\", pathStr, msg))\n        } else {\n            lines = append(lines, msg)\n        }\n    }\n\n    if len(lines) == 1 {\n        return fmt.Errorf(\"%s: %s\", filePath, lines[0])\n    }\n    return fmt.Errorf(\"%s: validation failed:\\n  %s\", filePath, strings.Join(lines, \"\\n  \"))\n}\n```\n\n**Important**: Import `cuelang.org/go/cue/errors`, NOT the standard library `errors`. Only CUE''s error package provides `Errors()` and `Path()` functions.\n\n## CUE Library Version Pinning\n\n### Current Version\n\nCUE is pinned in `go.mod`:\n\n```\ncuelang.org/go v0.15.4\n```\n\n### Upgrade Process\n\nWhen upgrading the CUE library version:\n\n1. **Review Changelog**: Check for breaking changes in the CUE release notes\n2. **Run Full Test Suite**: `make test` including all schema sync tests\n3. **Check API Deprecations**: Search for deprecated function usage\n4. **Verify Error Formats**: Manually test that error messages still include paths\n5. **Update Documentation**: If CUE behavior changes, update this rules file\n6. **Test Cross-Platform**: Run CI on all platforms (Linux, macOS, Windows)\n\n### Known CUE Limitations\n\n- **No Encode API**: CUE can decode Go structs but has no production-ready encoder\n- **No Code Generation**: `gengotypes` is experimental; we use sync tests instead\n- **Context is Stateful**: Create a new `cuecontext.New()` for each parse operation\n\n## Rules\n\n- All CUE structs must be closed (use `close({ ... })`) so unknown fields cause validation errors.\n- When adding new CUE struct fields or definitions, always include appropriate validation constraints (e.g., `strings.MaxRunes()`, regex patterns with `=~`, range constraints like `>=0 & <=255`) - not just type declarations. This ensures defense-in-depth validation.\n- Schema sync tests MUST exist for every Go struct that corresponds to a CUE definition.\n- Go-only validations MUST have `[GO-ONLY]` comments explaining why CUE cannot handle them.\n\n## Schema Sync Tests\n\nSync tests verify Go struct JSON tags match CUE schema field names at CI time. They catch misalignments before they cause silent parsing failures.\n\n**Test Files**:\n- `pkg/invowkfile/sync_test.go` - Invowkfile, Command, Implementation, etc.\n- `pkg/invowkmod/sync_test.go` - Invowkmod, ModuleRequirement\n- `internal/config/sync_test.go` - Config, VirtualShellConfig, UIConfig, etc.\n\n**Pattern**:\n```go\nfunc TestStructNameSchemaSync(t *testing.T) {\n    schema, _ := getCUESchema(t)\n    cueFields := extractCUEFields(t, lookupDefinition(t, schema, \"#DefinitionName\"))\n    goFields := extractGoJSONTags(t, reflect.TypeFor[GoStructType]())\n\n    assertFieldsSync(t, \"StructName\", cueFields, goFields)\n}\n```\n\n**When to Add Sync Tests**:\n- Adding a new CUE definition with a corresponding Go struct\n- Adding new fields to existing CUE/Go types\n- Renaming fields (test will fail until both are updated)\n\n## Common Pitfalls\n\n### Unclosed CUE Structs\n\n**Problem**: Open structs allow arbitrary unknown fields, bypassing validation.\n\n```cue\n// WRONG: Open struct - unknown fields silently accepted\n#Config: {\n    name: string\n}\n\n// CORRECT: Closed struct - unknown fields rejected\n#Config: close({\n    name: string\n})\n```\n\n### Redundant Validation\n\n**Problem**: Same validation in both CUE and Go creates maintenance burden.\n\n**Rule**: Validation lives in ONE place. CUE handles format/type validation. Go handles security/filesystem/cross-field logic.\n\n**Anti-Pattern**:\n```go\n// WRONG: Duplicates CUE regex validation\nif !regexp.MustCompile(`^[a-zA-Z][a-zA-Z0-9_-]*$`).MatchString(name) {\n    return fmt.Errorf(\"invalid name format\")\n}\n```\n\n**Correct Pattern**:\n```go\n// CORRECT: CUE handles format; Go handles length (defense-in-depth)\n// [GO-ONLY] Length limit not in CUE for simplicity; checked here for defense-in-depth.\nif len(name) > MaxNameLength {\n    return fmt.Errorf(\"name too long (%d chars, max %d)\", len(name), MaxNameLength)\n}\n```\n\n### Missing JSON Tags\n\n**Problem**: Go struct field without JSON tag won''t be populated by `Decode()`.\n\n**Symptom**: Field is always zero value despite being in CUE file.\n\n**Fix**: Add JSON tag matching the CUE field name:\n```go\ntype Config struct {\n    Includes  []IncludeEntry `json:\"includes\"`  // Matches CUE field\n    CachePath string         // No JSON tag - will be empty!\n}\n```\n\n### Wrong Error Import\n\n**Problem**: Using standard library `errors` instead of CUE''s error package.\n\n```go\n// WRONG: Standard library - no Path() function\nimport \"errors\"\n\n// CORRECT: CUE error package with path extraction\nimport \"cuelang.org/go/cue/errors\"\n```\n\n### Stale Schema Sync Tests\n\n**Problem**: Sync test exclusions become outdated after refactoring.\n\n**Fix**: After any CUE/Go struct changes, run `make test` and verify sync tests pass. Remove obsolete exclusions.\n"},"lastSynced":"2026-03-08T02:04:25.140Z","agentAnalysis":{"suitability":{"en":"Ideal for Developer Agents working with CUE schema files, providing dynamic command execution and extensibility.","zh":"适合于处理 CUE 模式文件的开发者代理，提供动态命令执行和可扩展性。","ja":"CUE スキーマファイルを使用する Developer エージェントに適しています。動的なコマンド実行と拡張性を提供します。","ko":"CUE 스키마 파일을 처리하는 개발자 에이전트에 적합합니다. 동적 명령 실행 및 확장성을 제공합니다.","es":"Ideal para Agentes de Desarrollador que trabajan con archivos de esquema CUE, proporcionando ejecución de comandos dinámicos y extensibilidad.","fr":"Idéal pour les Agents de Développeur travaillant avec des fichiers de schéma CUE, offrant une exécution de commandes dynamique et une extensibilité.","de":"Ideal für Entwickleragenten, die mit CUE-Schemadateien arbeiten, bietet dynamische Befehlsausführung und Erweiterbarkeit.","pt":"Ideal para Agentes de Desenvolvedor que trabalham com arquivos de esquema CUE, fornecendo execução de comandos dinâmicos e extensibilidade.","ru":"Идеально подходит для агентов-разработчиков, работающих с файлами схемы CUE, обеспечивая динамическое выполнение команд и расширяемость.","ar":"مثالي لعميل المطور الذي يعمل مع ملفات مخطط CUE، ويوفر تنفيذ أوامر ديناميكي وتوسع."},"recommendation":{"en":"Empowers agents to dynamically extend command runners, modify parse functions, and add new CUE definitions, streamlining interactions with CUE schema files, such as *.cue, and debugging CUE validation errors using pkg/invowkfile/, pkg/invowkmod/, or internal/config/","zh":"赋予代理动态扩展命令运行器、修改解析函数、添加新的 CUE 定义的能力，简化与 CUE 模式文件（如 *.cue）的交互，并使用 pkg/invowkfile/、pkg/invowkmod/ 或 internal/config/ 调试 CUE 验证错误。","ja":"エージェントに、コマンドランナーを動的に拡張したり、解析関数を変更したり、新しい CUE 定義を追加したりする能力を与え、*.cue などの CUE スキーマファイルとのやり取りを簡素化し、pkg/invowkfile/、pkg/invowkmod/、または internal/config/ を使用して CUE 検証エラーをデバッグします。","ko":"에이전트에 동적으로 명령 실행기 확장, 구문 분석 함수 수정 및 새로운 CUE 정의 추가 기능을 제공하여 *.cue와 같은 CUE 스키마 파일과의 상호 작용을 간소화하고 pkg/invowkfile/, pkg/invowkmod/ 또는 internal/config/를 사용하여 CUE 유효성 검사 오류를 디버깅합니다.","es":"Permite a los agentes extender dinámicamente los ejecutores de comandos, modificar las funciones de análisis y agregar nuevas definiciones de CUE, simplificando las interacciones con los archivos de esquema CUE, como *.cue, y depurando errores de validación de CUE utilizando pkg/invowkfile/, pkg/invowkmod/ o internal/config/","fr":"Permet aux agents d''étendre dynamiquement les exécuteurs de commandes, de modifier les fonctions d''analyse et d''ajouter de nouvelles définitions de CUE, simplifiant les interactions avec les fichiers de schéma CUE, tels que *.cue, et déboguant les erreurs de validation de CUE en utilisant pkg/invowkfile/, pkg/invowkmod/ ou internal/config/","de":"Ermöglicht es Agenten, Befehlsausführer dynamisch zu erweitern, Parse-Funktionen zu modifizieren und neue CUE-Definitionen hinzuzufügen, wodurch die Interaktion mit CUE-Schemadateien wie *.cue vereinfacht wird und CUE-Validierungsfehler mithilfe von pkg/invowkfile/, pkg/invowkmod/ oder internal/config/ behoben werden können.","pt":"Habilita os agentes a estender dinamicamente os executores de comandos, modificar funções de análise e adicionar novas definições CUE, simplificando as interações com arquivos de esquema CUE, como *.cue, e depurando erros de validação CUE usando pkg/invowkfile/, pkg/invowkmod/, ou internal/config/","ru":"Наделяет агентов возможностью динамически расширять исполнителей команд, изменять функции парсинга и добавлять новые определения CUE, упрощая взаимодействие с файлами схемы CUE, такими как *.cue, и отладку ошибок проверки CUE с помощью pkg/invowkfile/, pkg/invowkmod/, или internal/config/","ar":"تمكين العميل من توسيع تشغيل الأوامر بشكل ديناميكي، وتعديل وظائف التحليل، وإضافة تعريفات CUE جديدة، وبذلك يُبسط التفاعل مع ملفات مخطط CUE، مثل *.cue، وتصحيح أخطاء التحقق من CUE باستخدام pkg/invowkfile/، pkg/invowkmod/، أو internal/config/"},"useCases":{"en":["Debugging CUE validation errors","Modifying parse functions in CUE schema files","Adding new CUE definitions and corresponding Go struct fields"],"zh":["调试 CUE 验证错误","修改 CUE 模式文件中的解析函数","添加新的 CUE 定义和对应的 Go 结构体字段"],"ja":["CUE 検証エラーのデバッグ","CUE スキーマファイルの解析関数の変更","新しい CUE 定義と対応する Go 構造体フィールドの追加"],"ko":["CUE 유효성 검사 오류 디버깅","CUE 스키마 파일의 구문 분석 함수 수정","새로운 CUE 정의 및 해당 Go 구조체 필드 추가"],"es":["Depuración de errores de validación de CUE","Modificación de funciones de análisis en archivos de esquema CUE","Adición de nuevas definiciones de CUE y campos de estructura de Go correspondientes"],"fr":["Débogage des erreurs de validation de CUE","Modification des fonctions d''analyse dans les fichiers de schéma CUE","Ajout de nouvelles définitions de CUE et de champs de structure de Go correspondants"],"de":["Behandlung von CUE-Validierungsfehlern","Modifizierung von Parse-Funktionen in CUE-Schemadateien","Hinzufügen neuer CUE-Definitionen und entsprechender Go-Strukturfelder"],"pt":["Depuração de erros de validação CUE","Modificação de funções de análise em arquivos de esquema CUE","Adição de novas definições CUE e campos de estrutura Go correspondentes"],"ru":["Отладка ошибок проверки CUE","Изменение функций парсинга в файлах схемы CUE","Добавление новых определений CUE и соответствующих полей структуры Go"],"ar":["تصحيح أخطاء التحقق من CUE","تعديل وظائف التحليل في ملفات مخطط CUE","إضافة تعريفات CUE جديدة وحقول بنية Go الموافقة"]},"limitations":{"en":["Requires CUE schema files","Limited to CUE definitions and Go struct fields"],"zh":["需要 CUE 模式文件","仅限于 CUE 定义和 Go 结构体字段"],"ja":["CUE スキーマファイルが必要","CUE 定義と Go 構造体フィールドのみ"],"ko":["CUE 스키마 파일이 필요","CUE 정의 및 Go 구조체 필드만"],"es":["Requiere archivos de esquema CUE","Limitado a definiciones de CUE y campos de estructura de Go"],"fr":["Nécessite des fichiers de schéma CUE","Limité aux définitions de CUE et aux champs de structure de Go"],"de":["Benötigt CUE-Schemadateien","Begrenzt auf CUE-Definitionen und Go-Strukturfelder"],"pt":["Requer arquivos de esquema CUE","Limitado a definições CUE e campos de estrutura Go"],"ru":["Требует файлов схемы CUE","Ограничен определениями CUE и полями структуры Go"],"ar":["يتطلب ملفات مخطط CUE","محدود بالتعريفات CUE وحقول بنية Go"]},"version":4},"contentHash":"24fc02815334f4c118772b43fe78a0102db363a62d2a2eadf581b9537ae2f2ab","qualityScore":42}');
