INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('invowk/invowk/cue', 'cue', 'invowk', 'invowk', 'community', 'cue invowk invowk community The cue skill is designed for developers working with CUE schema files, providing a dynamically extensible command runner. It benefits those modifying parse functions or adding new CUE definitions. CUE 是一种动态可扩展的命令运行器，支持 CUE 模式和 invowkfile 结构 CUE は、CUE スキーマと invowkfile 構造をサポートする動的可拡張コマンド実行器です CUE는 동적 확장 명령 실행기로서 CUE 스키마 및 invowkfile 구조를 지원합니다 Cue es un ejecutor de comandos dinámicamente extensible que trabaja con archivos de esquema CUE Cue est un exécuteur de commandes dynamiquement extensible qui travaille avec des fichiers de schéma CUE Cue ist ein dynamisch erweiterbarer Befehlsausführer, der mit CUE-Schema-Dateien arbeitet O Cue é um comando dinamicamente extensível, semelhante ao ''task'' e ''just'', mas com superpoderes próprios. Utilize-o para trabalhar com arquivos de esquema CUE Cue - это динамически расширяемый командный запускам,类似 ''task'' и ''just'', но с собственными сверхспособностями. Используйте его для работы с файлами схемы CUE и ИИ Агентов Cue هو تشغيل 命令 ديناميكي قابل للتوسيع، مشابه لـ ''task'' و ''just''، ولكن مع قوى خارقة خاصة. استخدمه للعمل مع ملفات مخطط CUE وأدوات الذكاء الاصطناعي how to use cue cue alternative cue vs task cue install cue setup guide what is cue cue schema patterns cue validation errors CUE 技术 动态可扩展命令运行器 CUE 模式 invowkfile 结构 invowkmod 结构 CUE 验证错误调试 Works with CUE schema files (*.cue) for flexible configuration Modifies parse functions in pkg/invowkfile/, pkg/invowkmod/, or internal/config/ for customization Adds new CUE definitions or corresponding Go struct fields for extensibility Debugs CUE validation errors for efficient troubleshooting Utilizes schema locations like pkg/invowkfile/invowkfile_schema.cue for invowkfile structure definition cue is a dynamically extensible command runner, similar to task and just, with its own set of superpowers for working with CUE schema files.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Tsunoda-s-FT/kindle-app/kindle-capture', 'community', 'Tsunoda-s-FT', 'kindle-app', 'Tsunoda-s-FT/kindle-app', 'kindle-capture', 0, 0, 42, '2026-03-08T01:57:15.389Z', '2026-03-08T02:06:00.228Z', 'b8ccc6c48938383181cb72eeff621bf6f7e014285f354f7da157d00841a1c876', '{"id":"Tsunoda-s-FT/kindle-app/kindle-capture","name":"kindle-capture","description":{"en":"The kindle-capture skill automates eBook screenshot capture and PDF generation from Kindle Web Reader and macOS apps. It benefits developers and users seeking efficient eBook processing.","zh":"Kindle Capture Skill 是一个自动获取 Kindle 书籍截图并生成 PDF 的工具，支持 Kindle Web Reader 和 macOS 应用","ja":"Kindle Capture Skill は、Kindle 書籍のスクリーンショットを自動取得し、PDF を生成するツールです。Kindle Web Reader と macOS アプリの両方に対応しています","ko":"Kindle Capture Skill은 Kindle 책의 스크린샷을 자동으로 캡처하고 PDF를 생성하는 툴입니다. Kindle Web Reader와 macOS 애플리케이션을 모두 지원합니다","es":"kindle-capture es una habilidad que automatiza la captura de screenshots de libros de Amazon Kindle Web Reader y macOS, utilizando Playwright y KindleRenderer API.","fr":"kindle-capture est une compétence qui automatise la capture d''écrans de livres sur Amazon Kindle Web Reader et macOS, en utilisant Playwright et KindleRenderer API.","de":"kindle-capture ist eine Fähigkeit, die die Automatisierung von Screenshots von Büchern in Amazon Kindle Web Reader und macOS ermöglicht, indem sie Playwright und KindleRenderer API verwendet.","pt":"O Kindle-Capture é uma ferramenta que captura telas de livros automaticamente com Playwright e KindleRenderer API. Ele suporta tanto a versão web quanto a aplicação macOS do Kindle.","ru":"ИИ Агент Kindle-Capture - это инструмент, который автоматически захватывает экраны книг с помощью Playwright и KindleRenderer API. Он поддерживает как веб-версию, так и macOS-приложение Kindle.","ar":"Kindle-Capture هو أداة تقوم بتقاط الشاشة التلقائي للكتب باستخدام Playwright و KindleRenderer API. يدعم كل من الإصدارات الويب وتطبيق macOS للكندل."},"seo":{"title":{"en":"kindle-capture: Automated eBook Screenshot Generation | A...","zh":"Kindle Capture Skill 自动获取设置指南","ja":"Kindle Capture Skill の自動取得設定ガイド","ko":"Kindle Capture Skill 자동 캡처 설정 가이드","es":"Guía de configuración de kindle-capture para desarrolladores","fr":"Configurer kindle-capture pour les développeurs : Meilleu...","de":"Einrichtungsanleitung für kindle-capture: Automatisierung...","pt":"Guia de Configuração do Kindle-Capture: Captura de Tela A...","ru":"ИИ Агент Kindle-Capture: Руководство по Настройке Автомат...","ar":"دليل إعداد Kindle-Capture: التقاط الشاشة التلقائي"},"description":{"en":"Discover how kindle-capture simplifies eBook screenshot capture and PDF generation. Learn how to automate your workflow with this AI agent skill.","zh":"了解如何使用 Kindle Capture Skill 自动获取 Kindle 书籍的截图并生成 PDF","ja":"Kindle Capture Skill を使用して Kindle 書籍のスクリーンショットを自動取得し、PDF を生成する方法を学びましょう","ko":"Kindle Capture Skill을 사용하여 Kindle 책의 스크린샷을 자동으로 캡처하고 PDF를 생성하는 방법에 대해 알아보세요","es":"Aprende a configurar kindle-capture para automatizar la captura de screenshots de libros de Amazon Kindle Web Reader y macOS","fr":"Découvrez comment configurer kindle-capture pour automatiser la capture d''écrans de livres sur Amazon Kindle Web Reader et macOS","de":"Erfahren Sie, wie Sie kindle-capture einrichten, um Screenshots von Amazon Kindle Web Reader- und macOS-Büchern zu automatisieren","pt":"Aprenda a configurar o Kindle-Capture para capturar telas de livros automaticamente com Playwright e KindleRenderer API","ru":"Узнайте, как настроить ИИ Агент Kindle-Capture для автоматической съемки экрана книг с помощью Playwright и KindleRenderer API","ar":"تعرف على كيفية إعداد Kindle-Capture لالتقاط الشاشة التلقائي للكتب باستخدام Playwright و KindleRenderer API"},"definition":{"en":"kindle-capture is an AI agent skill that automatically captures screenshots of eBooks from Kindle Web Reader and macOS apps, generating PDFs with titled book covers.","zh":"Kindle Capture Skill 是一种 AI 工具，用于自动获取 Kindle 书籍的截图","ja":"Kindle Capture Skill は、Kindle 書籍のスクリーンショットを自動取得する AI エージェントです","ko":"Kindle Capture Skill은 Kindle 책의 스크린샷을 자동으로 캡처하는 AI 에이전트입니다","es":"kindle-capture es una herramienta de captura de screenshots automatizada para libros de Amazon Kindle","fr":"kindle-capture est un outil de capture d''écrans automatisé pour les livres Amazon Kindle","de":"kindle-capture ist ein Tool für die automatisierte Erfassung von Screenshots von Amazon Kindle-Büchern","pt":"O Kindle-Capture é uma ferramenta de captura de tela automática para livros do Kindle","ru":"ИИ Агент Kindle-Capture - это инструмент автоматической съемки экрана для книг Kindle","ar":"Kindle-Capture هو أداة لتقاط الشاشة التلقائي للكتب في الكندل"},"features":{"en":["Automates screenshot capture using Playwright and KindleRenderer API","Supports both Kindle Web Reader and macOS apps for eBook processing","Uses AI to identify and title book covers when title retrieval fails","Executes with default settings unless user-specified instructions are provided","Utilizes `capture_cover.py --json` for title confirmation and retrieval"],"zh":["支持 Kindle Web Reader 和 macOS 应用","使用 Playwright 和 KindleRenderer API 自动获取截图","自动获取书籍标题，失败时使用 AI 识别","支持 PDF 生成","使用 CLI 命令进行操作"],"ja":["Kindle Web Reader と macOS アプリの両方に対応","Playwright と KindleRenderer API を使用してスクリーンショットを自動取得","書籍タイトルを自動取得し、失敗した場合は AI で識別","PDF 生成に対応","CLI コマンドを使用して操作"],"ko":["Kindle Web Reader와 macOS 애플리케이션을 모두 지원","Playwright와 KindleRenderer API를 사용하여 스크린샷을 자동으로 캡처","책 제목을 자동으로 캡처하고, 실패 시 AI로 식별","PDF 생성을 지원","CLI 명령어를 사용하여操作"],"es":["Automatización de la captura de screenshots utilizando Playwright","Compatibilidad con Amazon Kindle Web Reader y macOS","Uso de KindleRenderer API para la captura de screenshots","Reconocimiento de títulos de libros mediante inteligencia artificial","Generación de PDF a partir de screenshots"],"fr":["Automatisation de la capture d''écrans à l''aide de Playwright","Compatibilité avec Amazon Kindle Web Reader et macOS","Utilisation de KindleRenderer API pour la capture d''écrans","Reconnaissance de titres de livres par intelligence artificielle","Génération de PDF à partir d''écrans"],"de":["Automatisierung der Screenshots-Erfassung mit Playwright","Kompatibilität mit Amazon Kindle Web Reader und macOS","Verwendung von KindleRenderer API für die Screenshots-Erfassung","Titelerkennung von Büchern durch künstliche Intelligenz","Erzeugung von PDF aus Screenshots"],"pt":["Captura de tela automática com Playwright","Suporte a versão web e aplicação macOS do Kindle","Uso de KindleRenderer API para captura de tela","Capacidade de capturar capa do livro e usar AI para identificar o título","Execução com configurações padrão sem necessidade de confirmação adicional"],"ru":["Автоматическая съемка экрана с помощью Playwright","Поддержка веб-версии и macOS-приложения Kindle","Использование KindleRenderer API для съемки экрана","Возможность захватить обложку книги и использовать ИИ для определения названия","Выполнение с настройками по умолчанию без необходимости дополнительного подтверждения"],"ar":["التقاط التلقائي للشاشة باستخدام Playwright","دعم الإصدارات الويب وتطبيق macOS للكندل","استخدام KindleRenderer API لالتقاط الشاشة","القدرة على التقاط الغلاف والاستفادة من الذكاء الاصطناعي لتحديد العنوان","التشغيل بالاعتماد على الإعدادات الافتراضية دون الحاجة إلى تأكيد إضافي"]},"keywords":{"en":["how to use kindle-capture","kindle-capture setup guide","eBook screenshot capture","kindle-capture alternative","automated PDF generation","kindle-capture install","what is kindle-capture","kindle-capture vs other eBook tools","kindle-capture API integration"],"zh":["Kindle Capture Skill","AI 工具","Kindle 书籍截图","PDF 生成","Playwright","KindleRenderer API","CLI 命令","macOS 应用","自动获取截图"],"ja":["Kindle Capture Skill","AI エージェント","Kindle 書籍スクリーンショット","PDF 生成","Playwright","KindleRenderer API","CLI コマンド","macOS アプリ","自動取得"],"ko":["Kindle Capture Skill","AI 에이전트","Kindle 책 스크린샷","PDF 생성","Playwright","KindleRenderer API","CLI 명령어","macOS 애플리케이션","자동 캡처"],"es":["kindle-capture","automatización de screenshots","Amazon Kindle Web Reader","macOS","Playwright","KindleRenderer API","inteligencia artificial","PDF generación"],"fr":["kindle-capture","automatisation de la capture d''écrans","Amazon Kindle Web Reader","macOS","Playwright","KindleRenderer API","intelligence artificielle","génération de PDF"],"de":["kindle-capture","Automatisierung von Screenshots","Amazon Kindle Web Reader","macOS","Playwright","KindleRenderer API","künstliche Intelligenz","PDF-Erzeugung"],"pt":["Kindle-Capture","captura de tela automática","Playwright","KindleRenderer API","ferramenta de captura de tela","livros do Kindle","configuração do Kindle-Capture","guia de configuração"],"ru":["ИИ Агент Kindle-Capture","автоматическая съемка экрана","Playwright","KindleRenderer API","инструмент съемки экрана","книги Kindle","настройка ИИ Агента Kindle-Capture","руководство по настройке"],"ar":["Kindle-Capture","التقاط التلقائي للشاشة","Playwright","KindleRenderer API","أداة التقاط الشاشة","كتب الكندل","إعداد Kindle-Capture","دليل الإعداد"]}},"owner":"Tsunoda-s-FT","repo":"kindle-app","repoPath":"Tsunoda-s-FT/kindle-app","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.389Z","topics":[],"category":"community","skillMd":{"name":"kindle-capture","description":"Kindle Web Reader/Kindle macOSアプリからスクリーンショットをキャプチャしてPDF生成。書籍名やASIN指定でKindle本を自動PDF化。Kindleライブラリ検索、Playwrightでページ自動取得、PNG画像からPDF変換、レイアウト設定（single/double）、範囲指定、品質調整、リサイズに対応。タイトル取得に失敗した場合は表紙キャプチャをAIで視認して命名する。","bodyPreview":"# Kindle Capture Skill\n\nKindle Web Readerから書籍のスクリーンショットを自動取得し、PDFを生成します。\n\n## 概要\n\nこのSkillは、Amazon Kindle Web Reader（read.amazon.co.jp）とKindle macOSアプリの両方に対応します。WebはPlaywrightとKindleRenderer APIで自動キャプチャし、アプリはスクリーンショットで取得します。タイトル取得に失敗した場合は、表紙を1枚キャプチャしてAIが視認し、適切な書籍名で命名します。\n\n## エージェント運用ルール（必読）\n\n- ユーザーから指示がない限り、**すべてデフォルト設定で実行**する。不要な確認はしない。\n- ローカルmacOSアプリで取得する場合、ユーザーが書籍タイトルを指定しなくても**AIが自動取得**する。\n  - `capture_cover.py --json` → `view_image`で表紙タイトル確認 → 取得タイトルを `--book` に使用\n- 取得に失敗・判別不能な場合のみ、最小限の確認を行う。","body":"# Kindle Capture Skill\n\nKindle Web Readerから書籍のスクリーンショットを自動取得し、PDFを生成します。\n\n## 概要\n\nこのSkillは、Amazon Kindle Web Reader（read.amazon.co.jp）とKindle macOSアプリの両方に対応します。WebはPlaywrightとKindleRenderer APIで自動キャプチャし、アプリはスクリーンショットで取得します。タイトル取得に失敗した場合は、表紙を1枚キャプチャしてAIが視認し、適切な書籍名で命名します。\n\n## エージェント運用ルール（必読）\n\n- ユーザーから指示がない限り、**すべてデフォルト設定で実行**する。不要な確認はしない。\n- ローカルmacOSアプリで取得する場合、ユーザーが書籍タイトルを指定しなくても**AIが自動取得**する。\n  - `capture_cover.py --json` → `view_image`で表紙タイトル確認 → 取得タイトルを `--book` に使用\n- 取得に失敗・判別不能な場合のみ、最小限の確認を行う。\n- **ローカルキャプチャは再実行で上書きされるため、`capture_app.py` は必ず新しい出力先を指定する**（例: `--output ./kindle-captures/<BOOK_TITLE>__run_YYYYMMDD_HHMMSS`）。\n- **PDF生成前に、`src/dedupe_tail.py` で巻末末尾の重複ページを必ず検出・削除する**（末尾の連続ページで同一画像が続く場合は重複として除去する）。\n- **PDF生成後は、親フォルダを日本語の書籍タイトル名にし、その直下にPDFと画像フォルダを配置してGoogle Driveへ必ず移動する**（`/Users/tsunoda/Library/CloudStorage/GoogleDrive-tsunoda799@gmail.com/マイドライブ/Kindle`）。\n\n## タイムアウトの目安\n\n- 300ページ超の書籍は、一般的に約20分かかります。短いタイムアウト設定は避けてください。\n- **エージェントはキャプチャ系コマンドのツール実行タイムアウトを30分（1,800,000ms）に固定**する。  \n  例: `timeout_ms=1800000` を必ず指定して実行する。\n- さらに長い上限が必要な場合は、**ユーザー合意の上で**十分長い値に延長する。\n\n## 前提条件\n\n- **Google Chrome**: インストール済みで、Kindle Web Reader（https://read.amazon.co.jp）にログイン済みであること\n- **ブラウザ自動化拡張機能**（オプション）: 書籍名での自動検索を行う場合に必要\n  - 拡張機能未接続の場合は、ASINを手動で指定する必要があります\n- **Python**: 3.10以降\n- **依存パッケージ**: requirements.txtに記載のライブラリ\n- **Kindle macOSアプリ（ローカル時）**: 書籍を開いた状態で前面にする\n- **画面収録/アクセシビリティ許可（ローカル時）**: ターミナル（または実行元）に許可が必要\n\n## セットアップ\n\n```bash\ncd /Users/tsunoda/Development/kindle-app\n\n# 仮想環境を作成（初回のみ）\npython3 -m venv venv\n\n# 仮想環境を有効化\nsource venv/bin/activate\n\n# 依存パッケージをインストール\npip install -r requirements.txt\n\n# 注意: このツールはシステムのGoogle Chromeを使用します\n# Playwrightのブラウザインストールは不要です\n```\n\n## 基本的な使い方\n\n**重要**: トリミングは必須ステップです。UIが映り込んでいても無視し、本体ページの四隅（紙面の外枠）に合わせてトリミングします。\n\n### ステップ1: スクリーンショット取得\n\n```bash\nsource venv/bin/activate\npython src/capture.py --asin <ASIN> --layout double\n```\n\n書籍のASINコードを指定して、全ページのスクリーンショットを取得します。\nデフォルトはログイン済みの既存プロファイルを使用します。Chrome起動中でプロファイルロックが発生した場合は、自動的に `~/Library/Application Support/Google/Chrome-Kindle` にフォールバックします（初回ログインが必要）。\n\n### ステップ2: トリミング（必須）\n\n```bash\n# AIがサンプル画像（page_0001.png等）を確認してcrop_box値を決定\n# UIは無視し、本体ページの外枠（四隅）を基準に計測する\n# ここに数値の例は書かない（画像ごとに必ず計測する）\npython src/trim.py --input ./kindle-captures/<ASIN>/ --crop \"<left,top,right,bottom>\"\n```\n\nキャプチャ画像のうち、本体ページの外枠（紙面）に合わせてトリミングします。AIは複数ページを確認して最適なcrop_box値を決定します。\n詳細は「AIアシストトリミング ワークフロー」セクションを参照。\n\n### ステップ3: 巻末末尾の重複削除（必須 / スクリプト使用）\n\nPDF生成前に `src/dedupe_tail.py` を実行して末尾重複を削除します。\n\n### ステップ4: PDF生成\n\n```bash\nsource venv/bin/activate\npython src/dedupe_tail.py --input ./kindle-captures/<ASIN>/trimmed/\npython src/create_pdf.py --input ./kindle-captures/<ASIN>/trimmed/\n```\n\n### ステップ5: Google Driveへ移動（必須 / 親フォルダ=書籍タイトル）\n\n```bash\nmkdir -p \"/Users/tsunoda/Library/CloudStorage/GoogleDrive-tsunoda799@gmail.com/マイドライブ/Kindle/<BOOK_TITLE>\"\nmv \"<PDF_PATH>\" \"/Users/tsunoda/Library/CloudStorage/GoogleDrive-tsunoda799@gmail.com/マイドライブ/Kindle/<BOOK_TITLE>/<BOOK_TITLE>.pdf\"\nmv \"./kindle-captures/<CAPTURE_DIR>/\" \"/Users/tsunoda/Library/CloudStorage/GoogleDrive-tsunoda799@gmail.com/マイドライブ/Kindle/<BOOK_TITLE>/画像_<RUN_ID>\"\n```\n\nトリミング後の画像からPDFを生成します。**必ず `/trimmed/` ディレクトリを指定してください。**\n\n## ローカル（Kindle macOSアプリ）\n\n### 表紙1枚で命名（AI視認の標準フロー）\n\n```bash\nsource venv/bin/activate\npython src/capture_cover.py --json\n```\n\n1. `kindle-captures/<ASIN>/cover.png` を `view_image` で確認\n2. 表紙のタイトルを読み取り、適切な書籍名で命名する\n3. 必要なら出力ディレクトリ名と `metadata.json` の `book` を更新\n\n**注意**: 表紙が表示されている状態で実行すること（現在表示中のページを撮影）。\n\n### 全ページキャプチャ\n\n```bash\nsource venv/bin/activate\npython src/capture_app.py --book \"<BOOK_TITLE>\" --output \"./kindle-captures/<BOOK_TITLE>__run_YYYYMMDD_HHMMSS\"\n# 末尾の重複ページを削除してからPDF生成（スクリプト使用）\npython src/dedupe_tail.py --input \"./kindle-captures/<BOOK_TITLE>__run_YYYYMMDD_HHMMSS/\"\npython src/create_pdf.py --input \"./kindle-captures/<BOOK_TITLE>__run_YYYYMMDD_HHMMSS/\"\n# PDF生成後にGoogle Driveへ移動（PDF+画像フォルダ）\nmv \"./<BOOK_TITLE>__run_YYYYMMDD_HHMMSS.pdf\" \"/Users/tsunoda/Library/CloudStorage/GoogleDrive-tsunoda799@gmail.com/マイドライブ/Kindle/<BOOK_TITLE>/<BOOK_TITLE>.pdf\"\nmv \"./kindle-captures/<BOOK_TITLE>__run_YYYYMMDD_HHMMSS/\" \"/Users/tsunoda/Library/CloudStorage/GoogleDrive-tsunoda799@gmail.com/マイドライブ/Kindle/<BOOK_TITLE>/画像_YYYYMMDD_HHMMSS\"\n```\n\n## コマンドオプション\n\n### capture.py - スクリーンショット取得\n\n**必須オプション**:\n- `--asin <ASIN>`: 書籍のASINコード（Amazon商品識別子）\n\n**主要オプション**:\n- `--chrome-profile <パス>`: Chromeプロファイルパス（デフォルト: `~/Library/Application Support/Google/Chrome`）\n  - Chrome起動中でプロファイルロックが発生した場合は `~/Library/Application Support/Google/Chrome-Kindle` に自動フォールバック\n- `--layout <single|double>`: レイアウトモード（デフォルト: double）\n  - `single`: シングルページ表示\n  - `double`: 見開き（ダブルページ）表示\n- `--start <位置>`: キャプチャ開始位置（Kindleの位置番号）\n- `--end <位置>`: キャプチャ終了位置（Kindleの位置番号）\n- `--output <ディレクトリ>`: 出力先ディレクトリ（デフォルト: ./kindle-captures/{ASIN}/）\n- `--headless`: ヘッドレスモードで実行（デフォルト: false）\n- `--max-pages <数値>`: 取得ページ数の上限（デフォルト: 無制限）\n- `--viewport-width <数値>`: ブラウザのviewport幅（デフォルト: 3840）\n- `--viewport-height <数値>`: ブラウザのviewport高さ（デフォルト: 2160）\n\n### create_pdf.py - PDF生成\n\n**必須オプション**:\n- `--input <ディレクトリ>`: スクリーンショットが保存されているディレクトリ\n\n**主要オプション**:\n- `--output <ファイル名>`: 出力PDFファイル名（デフォルト: {ASIN}.pdf）\n- `--quality <1-100>`: JPEG品質（デフォルト: 85）\n- `--resize <0.1-1.0>`: リサイズ比率（デフォルト: 1.0 = リサイズなし）\n\n### capture_app.py - Kindle macOSアプリのスクリーンショット取得\n\n**必須オプション**:\n- `--book <タイトル>`: 書籍名/識別子\n\n**主要オプション**:\n- `--output <ディレクトリ>`: 出力先（デフォルト: `./kindle-captures/{book}`）\n- `--max-pages <数値>`: 取得ページ上限\n- `--region <x,y,w,h>`: キャプチャ領域指定\n- `--scale <倍率>`: 座標スケール（Retinaなら2.0）\n- `--wait <秒>`: ページ送り後の待機\n- `--next-key <right|left|space|pagedown>`: ページ送りキー\n\n### capture_cover.py - 表紙1枚キャプチャ\n\n**主要オプション**:\n- `--book <タイトル>`: 書籍名を直接指定（命名用）\n- `--asin <ASIN>`: ASIN指定（タイトル取得の補助）\n- `--online`: ローカルでタイトルが取れない場合にAmazonから補完\n- `--json`: スクリプト連携向けJSON出力\n\n## よくある使用パターン\n\n### パターン1: 完全キャプチャ＆PDF生成（標準ワークフロー）\n\n書籍全体をキャプチャしてPDF化する基本的なワークフローです。**トリミングは必須です。**\n\n```bash\nsource venv/bin/activate\n\n# 1. スクリーンショット取得\npython src/capture.py --asin B0DSKPTJM5 --layout double\n\n# 2. AIがサンプル画像を確認してcrop_box値を決定\n# （AIエージェントがpage_0001.png等を読み、本体ページの外枠に合わせて判断）\n\n# 3. トリミング実行（画像から測定した値を使用）\npython src/trim.py --input ./kindle-captures/B0DSKPTJM5/ --crop \"<left,top,right,bottom>\"\n\n# 4. AIがトリミング結果を複数ページで確認\n# （本体外枠のバランス、コンテンツ切れがないか確認）\n\n# 5. 巻末末尾の重複削除（トリミング後の画像で末尾重複を除去 / スクリプト使用）\npython src/dedupe_tail.py --input ./kindle-captures/B0DSKPTJM5/trimmed/\n\n# 6. PDF生成（トリミング後の画像から）\npython src/create_pdf.py --input ./kindle-captures/B0DSKPTJM5/trimmed/\n\n# 7. Google Driveへ移動（日本語ディレクトリ名・ファイル名）\nmkdir -p \"/Users/tsunoda/Library/CloudStorage/GoogleDrive-tsunoda799@gmail.com/マイドライブ/Kindle/<BOOK_TITLE>\"\nmv \"./<BOOK_TITLE>.pdf\" \"/Users/tsunoda/Library/CloudStorage/GoogleDrive-tsunoda799@gmail.com/マイドライブ/Kindle/<BOOK_TITLE>/<BOOK_TITLE>.pdf\"\nmv \"./kindle-captures/<BOOK_TITLE>/\" \"/Users/tsunoda/Library/CloudStorage/GoogleDrive-tsunoda799@gmail.com/マイドライブ/Kindle/<BOOK_TITLE>/画像_<RUN_ID>\"\n```\n\n### パターン2: 部分キャプチャ（範囲指定）\n\n特定の範囲のみをキャプチャする場合に使用します。**トリミングは必須です。**\n\n```bash\nsource venv/bin/activate\n\n# 1. 位置1000から5000までをキャプチャ\npython src/capture.py --asin B0DSKPTJM5 --start 1000 --end 5000 --layout double\n\n# 2. トリミング（画像から測定した値を使用）\npython src/trim.py --input ./kindle-captures/B0DSKPTJM5/ --crop \"<left,top,right,bottom>\"\n\n# 3. PDF生成\npython src/create_pdf.py --input ./kindle-captures/B0DSKPTJM5/trimmed/\n```\n\n### パターン3: ページ数指定キャプチャ\n\n指定したページ数だけキャプチャする場合に使用します。**トリミングは必須です。**\n\n```bash\nsource venv/bin/activate\n\n# 1. 最初の15ページをキャプチャ\npython src/capture.py --asin B0DSKPTJM5 --max-pages 15 --layout double\n\n# 2. トリミング（画像から測定した値を使用）\npython src/trim.py --input ./kindle-captures/B0DSKPTJM5/ --crop \"<left,top,right,bottom>\"\n\n# 3. PDF生成\npython src/create_pdf.py --input ./kindle-captures/B0DSKPTJM5/trimmed/\n```\n\n### パターン4: モバイル最適化PDF\n\nモバイルデバイス用にファイルサイズを最適化する場合に使用します。**トリミングは必須です。**\n\n```bash\nsource venv/bin/activate\n\n# 1. キャプチャ\npython src/capture.py --asin B0DSKPTJM5 --layout double\n\n# 2. トリミング（画像から測定した値を使用）\npython src/trim.py --input ./kindle-captures/B0DSKPTJM5/ --crop \"<left,top,right,bottom>\"\n\n# 3. リサイズ＆圧縮してPDF生成\npython src/create_pdf.py --input ./kindle-captures/B0DSKPTJM5/trimmed/ --resize 0.7 --quality 80\n```\n\n## AIアシストトリミング ワークフロー\n\nAIエージェントが視覚的にキャプチャ画像を確認し、最適なトリミング範囲を決定するワークフローです。\n\n### ワークフロー概要\n\n```\ncapture.py\n    ↓\n[AI: 中程から3-5ページ選択（例: 5,8,10,12）]\n    ↓\nmark.py --pages \"5,8,10,12\" --crop \"...\" (元画像にマーカー描画)\n    ↓\n[AI: マーカー付き画像を確認] → 位置調整が必要？ → crop値調整して mark.py 再実行\n    ↓ 位置OK                          ↑ (2-3回繰り返し)\ntrim.py --crop \"...\" (全ページトリミング)\n    ↓\ncreate_pdf.py\n```\n\n**⚠️ 重要: マーカーで視覚的に位置を確認してからトリミングを実行します。**\n\n- **mark.py で元画像にマーカーを描画**して位置を視覚的に確認\n- マーカーが本体ページの四隅に合っているか確認\n- 位置が決まったら trim.py で一発でトリミング実行\n\n### サンプルページ選択ガイドライン\n\n**原則**:\n- 1-3ページ目は表紙・扉なので**避ける**（レイアウトが本文と異なる）\n- 中程から3-5ページをサンプリング\n- ページ総数の20%、50%、80%付近を目安に選ぶ\n\n**例**:\n- 15ページの場合: `--pages \"5,8,10,12\"`\n- 50ページの場合: `--pages \"10,20,30,40\"`\n- 100ページの場合: `--pages \"20,40,60,80\"`\n\n### AIによるcrop_box決定ガイドライン\n\nAIは以下の要素を確認してトリミング範囲を決定します：\n\n1. **上部境界**: 本体ページ（紙面）の上端\n2. **下部境界**: 本体ページ（紙面）の下端\n3. **左右境界**: 本体ページ（紙面）の左右端\n   - 見開きページの場合、左ページ外枠の左端と右ページ外枠の右端を揃える\n   - 左右のバランスを確認（右側だけ外枠が削られやすい）\n4. **UIは無視**: ヘッダー/Location/ナビ矢印などは判断材料にしない\n\n**コマンド例（テンプレート）**:\n```bash\npython src/trim.py --input ./kindle-captures/<ASIN>/ --crop \"<left,top,right,bottom>\"\n```\n\n**注意**: 数値の例は記載しません。必ず対象画像を見て測定し、他書籍や過去の値を流用しないこと。\n\n**判断手順**:\n1. **複数ページを確認**（表紙、目次、本文2-3ページ）\n2. 本体ページの外枠（紙面）を確認して上下面を決定\n3. 見開きの場合、左右の外枠を揃えて決定\n4. 本体外枠が切れていないかを確認\n5. crop_box値を `\"left,top,right,bottom\"` 形式で決定（数値は画像から測定）\n\n### トリミング結果の確認（最重要ステップ）\n\n**⚠️ このステップが最も重要です。一発でOKになることは稀なので、厳しい目でチェックしてください。**\n\nトリミング後、AIは**サンプルページ**を確認します（1ページだけで判断しない）：\n\n**確認すべきページ（中程から3-5ページ）**:\n- **本文ページ（中程）** - page_0005以降から3-5ページ\n- 表紙や扉（page_0001-0003）はレイアウトが異なるため参考にしない\n- 見開きページの余白バランスを重視\n\n**確認チェックリスト**:\n- [ ] **右側の余白**: 本体ページの右端に不要な余白が残っていないか **←最も見落としやすい**\n- [ ] **下側の余白**: 本体ページの下端に不要な余白が残っていないか **←最も見落としやすい**\n- [ ] **左側の余白**: 本体ページの左端に不要な余白が残っていないか\n- [ ] **上側の余白**: 本体ページの上端に不要な余白が残っていないか\n- [ ] **コンテンツ切れ**: 本文やイラストが切れていないか\n- [ ] **左右バランス**: 見開きの左右ページの余白が均等か\n\n**🔴 余白が少しでも残っている場合は、即座に再トリミングを実行してください。**\n\n基準: 本体ページ（紙面）の端がトリミング後の画像の端にほぼ一致していること。グレーや白の余白が目立つ場合はNGです。\n\n**⚠️ 重要な注意事項**:\n- 1ページだけ確認して「OK」と判断しないこと\n- 必ず複数ページを並列で読み取り、余白のバランスを確認する\n- **ユーザーに「これでOKですか？」と聞く前に、自分で余白を厳しくチェックする**\n- **2〜3回のトリミング反復を標準として想定する**\n- 「まあこれくらいなら」と妥協しない\n\n**再トリミングの手順**:\n元画像は保持されているため、新しいcrop_box値で`trim.py`を再実行するだけでOKです。\n```bash\n# 例: 右側と下側の余白を詰める場合\n# right値を小さく、bottom値を小さくして再実行\npython src/trim.py --input ./kindle-captures/<ASIN>/ --crop \"<left,top,新しいright,新しいbottom>\"\n```\n\n### mark.py - トリミング位置プレビュー（マーカー描画）\n\n元画像にトリミング位置を示すマーカー（赤い枠線とL字コーナー）を描画します。\n**各ページにつき5つの画像を生成**：全体画像 + 4辺の拡大画像で、位置を精密に確認できます。\n\n**生成される画像**:\n- `{page}_marked.png`: 全体画像（マーカー付き）\n- `{page}_top.png`: 上辺の拡大画像\n- `{page}_bottom.png`: 下辺の拡大画像\n- `{page}_left.png`: 左辺の拡大画像\n- `{page}_right.png`: 右辺の拡大画像\n\n**必須オプション**:\n- `--input <ディレクトリ>`: 元画像ディレクトリ\n- `--crop \"left,top,right,bottom\"`: マーカー位置（絶対座標）\n\n**オプション**:\n- `--pages \"5,8,10,12\"`: 指定ページのみマーカー描画\n- `--output <ディレクトリ>`: 出力先（デフォルト: `{input}/marked/`）\n- `--color <色>`: マーカーの色（デフォルト: red）\n- `--width <数値>`: 線の太さ（デフォルト: 4）\n- `--margin <数値>`: 拡大画像のマージン（デフォルト: 150px）\n\n**マーカー→確認→トリミングの手順**:\n```bash\n# 1. サンプルページにマーカーを描画（5画像×ページ数 生成）\npython src/mark.py --input ./kindle-captures/<ASIN>/ --crop \"305,115,3280,1955\" --pages \"5,8,10,12\"\n\n# 2. 各辺の拡大画像と全体像を確認（5画像）\n# - page_0005_top.png: 上辺のマーカー位置を確認\n# - page_0005_bottom.png: 下辺のマーカー位置を確認\n# - page_0005_left.png: 左辺のマーカー位置を確認\n# - page_0005_right.png: 右辺のマーカー位置を確認\n# - page_0005_marked.png: 全体画像で四隅のバランスを確認\n\n# 3. 位置調整が必要なら crop値を変更して再実行\npython src/mark.py --input ./kindle-captures/<ASIN>/ --crop \"310,120,3270,1950\" --pages \"5,8,10,12\"\n\n# 4. 位置がOKなら全ページをトリミング\npython src/trim.py --input ./kindle-captures/<ASIN>/ --crop \"310,120,3270,1950\"\n```\n\n### trim.py - 画像トリミング\n\n**必須オプション**:\n- `--input <ディレクトリ>`: 元画像ディレクトリ\n- `--crop \"left,top,right,bottom\"`: トリミング範囲（絶対座標）\n\n**オプション**:\n- `--pages \"5,8,10,12\"`: 指定ページのみトリミング（省略時は全ページ）\n- `--output <ディレクトリ>`: 出力先（デフォルト: `{input}/trimmed/`）\n- `--note <テキスト>`: メタデータに記録するメモ\n\n## ブラウザ自動化によるASIN検索\n\nこのスキルはブラウザ自動化ツールを使用してKindleライブラリから書籍を検索できます。使用するエージェントに応じて適切なツールを使用してください。\n\n### 抽象的なフロー（全エージェント共通）\n\n1. Kindleライブラリ（https://read.amazon.co.jp/kindle-library）にアクセス\n2. ログイン状態を確認（未ログインならユーザーに依頼）\n3. 検索バーにキーワードを入力\n4. 検索結果から書籍を選択\n5. URLからASINを抽出（例: `https://read.amazon.co.jp/?asin=B0DSKPTJM5`）\n6. `source venv/bin/activate && python src/capture.py --asin <ASIN> --layout double` を実行\n7. **【必須】マーカーでトリミング位置を決定**:\n   - 中程から3-5ページ選択（例: 5,8,10,12）\n   - `python src/mark.py --input ./kindle-captures/<ASIN>/ --crop \"<値>\" --pages \"5,8,10,12\"` でマーカー描画\n   - マーカー付き画像（marked/ディレクトリ）を確認 → 位置調整が必要なら再実行（2-3回繰り返し）\n8. **全ページトリミング**: 位置が決まったら `python src/trim.py --input ./kindle-captures/<ASIN>/ --crop \"<値>\"` で全ページトリミング\n9. `source venv/bin/activate && python src/create_pdf.py --input ./kindle-captures/<ASIN>/trimmed/` を実行\n10. 完了報告\n\n### Claude Code\n\nブラウザ自動化ツール: `mcp__claude-in-chrome__*`\n\n| 操作 | ツール |\n|------|--------|\n| タブ確認/作成 | `tabs_context_mcp`, `tabs_create_mcp` |\n| ナビゲート | `navigate` |\n| 要素検索 | `find` |\n| フォーム入力 | `form_input` |\n| クリック/操作 | `computer` |\n| ページ読み取り | `read_page` |\n\n**前提条件**: Claude in Chrome エクステンション（https://claude.ai/chrome）\n\n**実装例**:\n1. `mcp__claude-in-chrome__tabs_context_mcp` でブラウザ接続を確認\n2. `mcp__claude-in-chrome__navigate` でKindleライブラリにアクセス\n3. `mcp__claude-in-chrome__find` で検索バーを特定\n4. `mcp__claude-in-chrome__form_input` でキーワードを入力\n5. `mcp__claude-in-chrome__computer` で検索を実行\n6. `mcp__claude-in-chrome__read_page` で検索結果を取得\n\n### Codex CLI\n\nブラウザ自動化ツール: `mcp__chrome-devtools__*`\n\n| 操作 | ツール |\n|------|--------|\n| 新規ページ | `new_page` |\n| ナビゲート | `navigate_page` |\n| スナップショット | `take_snapshot` |\n| フォーム入力 | `fill` |\n| キー入力 | `press_key` |\n| クリック | `click` |\n| スクリプト実行 | `evaluate_script` |\n\n**実装例**:\n1. `mcp__chrome-devtools__new_page` でKindleライブラリにアクセス\n2. ログイン画面が表示されていれば、ユーザーにログインを依頼\n3. `mcp__chrome-devtools__take_snapshot` で検索バーを特定\n4. `mcp__chrome-devtools__fill` でキーワードを入力\n5. `mcp__chrome-devtools__press_key`（Enter）で検索実行\n6. `mcp__chrome-devtools__take_snapshot` で検索結果を取得\n\n### 他のエージェント\n\n上記に該当しないエージェントを使用している場合：\n\n1. エージェントのブラウザ自動化ツールを確認\n2. 「抽象的なフロー」に従って同等の操作を実行\n3. ブラウザ自動化が利用できない場合は、ユーザーに手動でASINを確認してもらう\n\n**手動確認の案内**:\n1. ユーザーにKindleライブラリ（https://read.amazon.co.jp/kindle-library）へのアクセスを依頼\n2. 検索バーでキーワード検索を実行してもらう\n3. 該当書籍のURLまたはASINを教えてもらう\n4. 提供されたASINでキャプチャを実行\n\n### ASINの確認方法\n\n- **Kindle Web Reader URL**: `https://read.amazon.co.jp/?asin=B0DSKPTJM5` → ASIN: `B0DSKPTJM5`\n- **Amazon商品URL**: `https://www.amazon.co.jp/dp/B0DSKPTJM5/` → ASIN: `B0DSKPTJM5`（`/dp/`の後の英数字）\n\n## ユーザーリクエストの解釈と対応\n\n**「githubの本をPDF化して」（書籍名が曖昧な場合）**:\n1. ブラウザ自動化ツールでKindleライブラリを検索\n2. 複数の候補がある場合はリスト表示してユーザーに確認\n3. 選択された書籍のASINでキャプチャを実行\n\n**「アプリで（ローカルで）PDF化して」**:\n1. Kindleアプリで対象書籍を前面表示\n2. 書籍名が不明なら `python src/capture_cover.py --json` で表紙を取得\n3. `view_image` で表紙を読み取り、適切な書籍名で命名\n4. `python src/capture_app.py --book \"<BOOK_TITLE>\" --output \"./kindle-captures/<BOOK_TITLE>__run_YYYYMMDD_HHMMSS\"` を実行\n5. `python src/create_pdf.py --input \"./kindle-captures/<BOOK_TITLE>__run_YYYYMMDD_HHMMSS/\"` を実行\n\n**「この本の100ページ目から200ページ目までPDF化」**:\n1. ページ番号とKindleの位置番号の違いを説明（必要に応じて）\n2. `--start` と `--end` オプションで範囲指定\n\n**「見開きでキャプチャして」**:\n1. `--layout double` オプションを使用\n\n**「モバイル用に軽量化してPDF化」**:\n1. `--resize 0.7 --quality 80` オプションを使用\n\n## トラブルシューティング\n\n### ブラウザ自動化が利用できない\n\n**症状**: ブラウザ自動化ツールが接続されていない\n\n**対処法**:\n1. 手動でKindleライブラリから書籍のASINを確認\n2. `source venv/bin/activate && python src/capture.py --asin <ASIN>` で直接実行\n\n### タイトルが取得できない（ローカル）\n\n**対処法**:\n1. `python src/capture_cover.py --json` を実行\n2. `view_image` で `cover.png` を確認して書籍名を決める\n3. `--book` にその書籍名を使って再実行\n\n### セッション切れエラー\n\n**症状**: `Session invalid. Please log in to Kindle in Chrome and retry.`\n\n**原因**: Kindle Web Readerのログインセッションが切れている\n\n**対処法**:\n1. Google Chromeを開く\n2. https://read.amazon.co.jp にアクセス\n3. Amazonアカウントでログイン\n4. スクリプトを再実行\n\n### Chromeプロファイルがロックされているエラー\n\n**症状**: `Failed to launch browser` または `Chrome profile is locked`\n\n**原因**: 既にChromeが起動中で、デフォルトのプロファイルが使用されている\n\n**対処法**（推奨）:\n一時的なプロファイルを使用してプロファイル競合を回避します。この方法を使えば、通常のChromeを起動したままでもキャプチャできます。\n```bash\nsource venv/bin/activate\npython src/capture.py --asin <ASIN> --chrome-profile /tmp/kindle-test-profile\n```\n\n**補足**: 自動フォールバック後は初回ログインが必要です。\n\n**代替対処法**:\n1. 起動中のGoogle Chromeをすべて終了\n2. スクリプトを再実行\n\n### ページ読み込みタイムアウト\n\n**症状**: キャプチャが途中で進まなくなる、または遅い\n\n**原因**: ネットワーク速度が遅い、またはページ読み込み検知のタイムアウトが短すぎる\n\n**対処法**:\n1. ネットワーク接続を確認\n2. `config.yaml` の `wait_timeout` を増やす（例: `3.0` → `5.0`）\n3. スクリプトを再実行\n\n```yaml\n# config.yaml\ncapture:\n  wait_timeout: 5.0  # 3.0から5.0に変更\n```\n\n### スクリーンショットが見つからないエラー\n\n**症状**: `No screenshots found in {directory}`\n\n**原因**: capture.pyを実行せずにcreate_pdf.pyを実行した、またはディレクトリパスが間違っている\n\n**対処法**:\n1. 先に `source venv/bin/activate && python src/capture.py --asin <ASIN>` を実行（フォールバック時は初回ログイン）\n2. 正しい入力ディレクトリパスを指定（`--input ./kindle-captures/<ASIN>/`）\n\n### 中断後の再実行で上書きされる\n\n**症状**: 再実行すると `page_0001.png` などが既存データを上書きする\n\n**原因**: `capture_app.py` はページ番号を固定名で保存するため、同じ出力先に再実行すると上書きされる\n\n**対処法**:\n1. **必ず新しい出力先を指定**して再実行する  \n   例: `--output \"./kindle-captures/<BOOK_TITLE>__run_YYYYMMDD_HHMMSS\"`\n2. 既存データを残したい場合は、再実行前にディレクトリを退避（リネーム）する\n\n## 出力ファイル\n\n### ディレクトリ構造\n\n```\nkindle-captures/\n└── {ASIN}/\n    ├── page_0001.png          # 元画像\n    ├── page_0002.png\n    ├── page_0003.png\n    ├── ...\n    ├── metadata.json          # キャプチャメタデータ\n    ├── marked/                # マーカー付き画像（mark.py実行時）\n    │   ├── page_0005_marked.png  # 全体画像\n    │   ├── page_0005_top.png     # 上辺拡大\n    │   ├── page_0005_bottom.png  # 下辺拡大\n    │   ├── page_0005_left.png    # 左辺拡大\n    │   ├── page_0005_right.png   # 右辺拡大\n    │   └── ...\n    └── trimmed/               # トリミング後（trim.py実行時）\n        ├── page_0001.png\n        ├── page_0002.png\n        ├── ...\n        └── trim_metadata.json # トリミング設定・履歴\n```\n\n### metadata.json\n\n各キャプチャセッションの詳細情報を記録します：\n- ASIN\n- レイアウト設定（single/double）\n- キャプチャページ数\n- 位置範囲（最小・最大）\n- 各ページの位置情報とタイムスタンプ\n\n### 生成されるPDF\n\n- **デフォルト**: カレントディレクトリに `{ASIN}.pdf`\n- **カスタム**: `--output` オプションで指定したファイル名\n\n## 注意事項\n\nこのツールは**私的利用のみ**を目的としています。以下の点を遵守してください：\n\n- 日本の著作権法を遵守してください\n- Amazon Kindleの利用規約に従ってください\n- 商業利用や第三者への再配布は禁止されています\n- 生成したPDFは個人的な利用のみに使用してください\n- ページ数が多い書籍（300ページ超）はキャプチャ完了まで20〜30分かかることがあります。**外部タイムアウトは設定しない**（必要ならユーザー合意の上で長めに設定）。\n\n## 技術情報\n\n### 使用ライブラリ\n\n- **Playwright**: ブラウザ自動化（Chrome制御）\n- **img2pdf**: PNG→PDF変換（ロスレス圧縮）\n- **Pillow**: 画像処理（リサイズ、JPEG変換）\n- **PyYAML**: 設定ファイル管理\n- **tqdm**: 進捗表示\n\n### KindleRenderer API\n\nKindle Web ReaderのJavaScript APIを利用：\n- `getMinimumPosition()` / `getMaximumPosition()`: 書籍の位置範囲取得\n- `gotoPosition(position)`: 指定位置へ移動\n- `hasNextScreen()`: 次ページの有無確認\n- `nextScreen()`: 次ページへ移動\n\n## 詳細情報\n\n- **詳細なオプション説明**: [REFERENCE.md](REFERENCE.md) を参照\n- **より多くの使用例**: [EXAMPLES.md](EXAMPLES.md) を参照\n"},"lastSynced":"2026-03-08T02:06:00.228Z","agentAnalysis":{"suitability":{"en":"Perfect for eBook Processing Agents needing automated Kindle content capture and PDF generation.","zh":"非常适合需要自动捕获Kindle内容和生成PDF的电子书处理代理。","ja":"Kindleコンテンツの自動キャプチャとPDF生成が必要な電子書籍処理エージェントに最適です。","ko":"Kindle 콘텐츠 자동 캡처 및 PDF 생성이 필요한 전자책 처리 에이전트에 적합합니다.","es":"Perfecto para Agentes de Procesamiento de eBooks que necesitan captura automática de contenido de Kindle y generación de PDF.","fr":"Parfait pour les Agents de Traitement de eBooks nécessitant une capture automatisée de contenu Kindle et une génération de PDF.","de":"Perfekt für eBook-Verarbeitungsagenten, die eine automatisierte Kindle-Inhaltsaufnahme und PDF-Generierung benötigen.","pt":"Perfeito para Agentes de Processamento de eBooks que necessitam de captura automática de conteúdo do Kindle e geração de PDF.","ru":"Идеально подходит для агентов обработки электронных книг, которым требуется автоматизированная захват контента Kindle и генерация PDF.","ar":"مثالي لعميل معالجة الكتب الإلكترونية الذي يحتاج إلى التقاط المحتوى التلقائي للكندل وتوليد PDF."},"recommendation":{"en":"Empowers agents to automate eBook screenshot capture and PDF generation from Kindle Web Reader and macOS apps using Playwright and KindleRenderer API, with AI-driven title detection and naming.","zh":"赋予代理自动化电子书截图捕获和从Kindle Web Reader和macOS应用程序生成PDF的能力，使用Playwright和KindleRenderer API，并具有AI驱动的标题检测和命名。","ja":"PlaywrightとKindleRenderer APIを使用して、Kindle Web ReaderとmacOSアプリケーションから電子書籍のスクリーンショットをキャプチャし、PDFを生成する機能をエージェントに自動化します。AI駆動のタイトル検出と命名も含まれます。","ko":"Playwright와 KindleRenderer API를 사용하여 Kindle Web Reader와 macOS 애플리케이션에서 전자책 스크린샷을 캡처하고 PDF를 생성하는 기능을 에이전트에 자동화합니다. AI 구동 제목 감지 및命名도 포함됩니다.","es":"Habilita a los agentes a automatizar la captura de pantallas de eBooks y la generación de PDF desde Kindle Web Reader y aplicaciones de macOS utilizando Playwright y KindleRenderer API, con detección y nominación de títulos impulsadas por IA.","fr":"Permet aux agents d''automatiser la capture d''écran de eBooks et la génération de PDF à partir de Kindle Web Reader et d''applications macOS en utilisant Playwright et KindleRenderer API, avec une détection et une nomination de titres propulsées par l''IA.","de":"Ermächtigt Agenten, die Erfassung von eBook-Bildschirmen und die Generierung von PDFs aus Kindle Web Reader und macOS-Apps mithilfe von Playwright und KindleRenderer API zu automatisieren, mit künstlich intelligenter Titelerkennung und Benennung.","pt":"Habilita os agentes a automatizar a captura de telas de eBooks e geração de PDF a partir do Kindle Web Reader e aplicativos macOS usando Playwright e API KindleRenderer, com detecção de título impulsionada por IA e nomeação.","ru":"Предоставляет агентам возможность автоматизировать захват экрана электронных книг и генерацию PDF из Kindle Web Reader и приложений macOS с помощью Playwright и API KindleRenderer, с обнаружением названия, управляемым ИИ, и именованием.","ar":"يمنح الوكيل القدرة على توفير لقطة شاشة للكتب الإلكترونية وتوليد PDF من قارئ الويب الكندل وتطبيقات macOS باستخدام Playwright وواجهة برمجة تطبيقات KindleRenderer ، مع كشف العنوان القائم على الذكاء الاصطناعي والتسمية."},"useCases":{"en":["Automating eBook content processing for developers and users","Generating PDFs from Kindle Web Reader and macOS apps","Capturing eBook screenshots with AI-driven title detection"],"zh":["为开发人员和用户自动化电子书内容处理","从Kindle Web Reader和macOS应用程序生成PDF","使用AI驱动的标题检测捕获电子书截图"],"ja":["開発者とユーザー向けの電子書籍コンテンツ処理の自動化","Kindle Web ReaderとmacOSアプリケーションからPDFを生成","AI駆動のタイトル検出を使用した電子書籍スクリーンショットのキャプチャ"],"ko":["개발자와 사용자를 위한 전자책 콘텐츠 처리 자동화","Kindle Web Reader와 macOS 애플리케이션에서 PDF 생성","AI 구동 제목 감지를 사용한 전자책 스크린샷 캡처"],"es":["Automatizar el procesamiento de contenido de eBook para desarrolladores y usuarios","Generar PDF desde Kindle Web Reader y aplicaciones de macOS","Capturar pantallas de eBook con detección de títulos impulsada por IA"],"fr":["Automatiser le traitement de contenu de eBook pour les développeurs et les utilisateurs","Générer des PDF à partir de Kindle Web Reader et d''applications macOS","Capturer des écrans de eBook avec une détection de titres propulsée par l''IA"],"de":["Automatisieren des eBook-Inhaltsverarbeitungsprozesses für Entwickler und Benutzer","Generieren von PDFs aus Kindle Web Reader und macOS-Apps","Erfassen von eBook-Bildschirmen mit künstlich intelligenter Titelerkennung"],"pt":["Automatizar o processamento de conteúdo de eBooks para desenvolvedores e usuários","Gerar PDFs a partir do Kindle Web Reader e aplicativos macOS","Capturar telas de eBooks com detecção de título impulsionada por IA"],"ru":["Автоматизировать обработку контента электронных книг для разработчиков и пользователей","Генерировать PDF из Kindle Web Reader и приложений macOS","Захватывать экран электронных книг с обнаружением названия, управляемым ИИ"],"ar":["توفير معالجة المحتوى التلقائي للكتب الإلكترونية للمطورين والمستخدمين","توليد PDF من قارئ الويب الكندل وتطبيقات macOS","التقاط شاشة الكتب الإلكترونية مع كشف العنوان القائم على الذكاء الاصطناعي"]},"limitations":{"en":["Requires macOS for app-based capture","Limited to Kindle Web Reader and macOS apps","May require user intervention for title detection failures"],"zh":["需要macOS进行基于应用程序的捕获","仅限Kindle Web Reader和macOS应用程序","标题检测失败可能需要用户干预"],"ja":["アプリベースのキャプチャにはmacOSが必要","Kindle Web ReaderとmacOSアプリケーションに限定","タイトル検出の失敗はユーザーの介入を必要とする場合がある"],"ko":["애플리케이션 기반 캡처에는 macOS가 필요합니다.","Kindle Web Reader 및 macOS 애플리케이션으로 제한됨","제목 감지 실패는 사용자 개입이 필요할 수 있음"],"es":["Requiere macOS para la captura basada en aplicaciones","Limitado a Kindle Web Reader y aplicaciones de macOS","Puede requerir intervención del usuario para fallos en la detección de títulos"],"fr":["Nécessite macOS pour la capture basée sur les applications","Limité à Kindle Web Reader et aux applications macOS","Peut nécessiter une intervention utilisateur pour les défaillances de détection de titres"],"de":["Benötigt macOS für die app-basierte Erfassung","Begrenzt auf Kindle Web Reader und macOS-Apps","Kann Benutzereingriff für Fehlschläge bei der Titelerkennung erfordern"],"pt":["Requer macOS para captura baseada em aplicativos","Limitado ao Kindle Web Reader e aplicativos macOS","Pode requerer intervenção do usuário em caso de falhas na detecção de título"],"ru":["Требует macOS для захвата на основе приложений","Ограничен Kindle Web Reader и приложениями macOS","Может потребовать вмешательства пользователя в случае неудачи обнаружения названия"],"ar":["يتطلب macOS للتقاط القائم على التطبيق","محدود لقارئ الويب الكندل وتطبيقات macOS","يمكن أن يتطلب تدخل المستخدم في حالات فشل كشف العنوان"]},"version":4},"contentHash":"b8ccc6c48938383181cb72eeff621bf6f7e014285f354f7da157d00841a1c876","qualityScore":42}');
