INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Tsunoda-s-FT/kindle-app/kindle-capture', 'kindle-capture', 'Tsunoda-s-FT', 'kindle-app', 'community', 'kindle-capture Tsunoda-s-FT kindle-app community The kindle-capture skill automates eBook screenshot capture and PDF generation from Kindle Web Reader and macOS apps. It benefits developers and users seeking efficient eBook processing. Kindle Capture Skill 是一个自动获取 Kindle 书籍截图并生成 PDF 的工具，支持 Kindle Web Reader 和 macOS 应用 Kindle Capture Skill は、Kindle 書籍のスクリーンショットを自動取得し、PDF を生成するツールです。Kindle Web Reader と macOS アプリの両方に対応しています Kindle Capture Skill은 Kindle 책의 스크린샷을 자동으로 캡처하고 PDF를 생성하는 툴입니다. Kindle Web Reader와 macOS 애플리케이션을 모두 지원합니다 kindle-capture es una habilidad que automatiza la captura de screenshots de libros de Amazon Kindle Web Reader y macOS, utilizando Playwright y KindleRenderer API. kindle-capture est une compétence qui automatise la capture d''écrans de livres sur Amazon Kindle Web Reader et macOS, en utilisant Playwright et KindleRenderer API. kindle-capture ist eine Fähigkeit, die die Automatisierung von Screenshots von Büchern in Amazon Kindle Web Reader und macOS ermöglicht, indem sie Playwright und KindleRenderer API verwendet. O Kindle-Capture é uma ferramenta que captura telas de livros automaticamente com Playwright e KindleRenderer API. Ele suporta tanto a versão web quanto a aplicação macOS do Kindle. ИИ Агент Kindle-Capture - это инструмент, который автоматически захватывает экраны книг с помощью Playwright и KindleRenderer API. Он поддерживает как веб-версию, так и macOS-приложение Kindle. Kindle-Capture هو أداة تقوم بتقاط الشاشة التلقائي للكتب باستخدام Playwright و KindleRenderer API. يدعم كل من الإصدارات الويب وتطبيق macOS للكندل. how to use kindle-capture kindle-capture setup guide eBook screenshot capture kindle-capture alternative automated PDF generation kindle-capture install what is kindle-capture kindle-capture vs other eBook tools kindle-capture API integration Kindle Capture Skill AI 工具 Kindle 书籍截图 PDF 生成 Playwright KindleRenderer API CLI 命令 macOS 应用 自动获取截图 Automates screenshot capture using Playwright and KindleRenderer API Supports both Kindle Web Reader and macOS apps for eBook processing Uses AI to identify and title book covers when title retrieval fails Executes with default settings unless user-specified instructions are provided Utilizes `capture_cover.py --json` for title confirmation and retrieval kindle-capture is an AI agent skill that automatically captures screenshots of eBooks from Kindle Web Reader and macOS apps, generating PDFs with titled book covers.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jackspace/ClaudeSkillz/rdkit', 'community', 'jackspace', 'ClaudeSkillz', 'jackspace/ClaudeSkillz', 'rdkit', 0, 0, 42, '2026-03-08T01:57:15.402Z', '2026-03-08T02:06:47.058Z', 'cf451fd778f2baaf2e7afe9415a08ce4ea2293e1bc7d6c196a8b985fcfaeef22', '{"id":"jackspace/ClaudeSkillz/rdkit","name":"rdkit","description":{"en":"rdkit is a comprehensive cheminformatics library providing Python APIs for molecular analysis and manipulation, ideal for drug discovery and computational chemistry research tasks.","zh":"RDKit 是一个用于分子分析和操作的综合化学信息学库，提供 Python API 用于读写分子结构、计算描述符和指纹识别等任务","ja":"RDKit は、分子分析と操作用の包括的なケミカルインフォマティクスライブラリです。Python API を使用して分子構造の読み書き、記述子計算、指紋検索などのタスクを実行します","ko":"RDKit은 분자 분석 및 조작을 위한 종합적인 케미컬 인포매티크스 라이브러리입니다. Python API를 사용하여 분자 구조 읽기/쓰기, 설명자 계산 및 지문 검색 등을 수행합니다","es":"RDKit es una biblioteca de cheminformatics que proporciona APIs de Python para análisis y manipulación molecular. Utilice esta habilidad para tareas de investigación en descubrimiento de fármacos y química computacional.","fr":"RDKit est une bibliothèque de chimie informatique qui fournit des API Python pour l''analyse et la manipulation moléculaire. Utilisez cette compétence pour les tâches de recherche en découverte de médicaments et en chimie informatique.","de":"RDKit ist eine Bibliothek für Chemieinformatik, die Python-APIs für Molekülanalyse und -manipulation bereitstellt. Nutzen Sie diese Fähigkeit für Forschungsaufgaben im Bereich Arzneimittelentdeckung und computergestützte Chemie.","pt":"O RDKit é uma biblioteca de química computacional que fornece APIs Python para análise molecular. Use-o para tarefas de descoberta de fármacos e pesquisa em química computacional.","ru":"RDKit - это библиотека химической информатики, предоставляющая Python API для молекулярного анализа. Используйте его для задач по открытию лекарств и исследований в области химической информатики.","ar":"RDKit هي مكتبة كيميائية حاسوبية توفر واجهات برمجة تطبيقات Python لتحليل الجزيئات. استخدمها لمهام اكتشاف الأدوية والبحث في الكيمياء الحاسوبية"},"seo":{"title":{"en":"rdkit: Molecular Analysis and Manipulation Setup Guide | ...","zh":"RDKit 分子分析工具箱 Setup Guide","ja":"RDKit 分子分析 AIエージェント のベストプラクティス","ko":"RDKit 분자 분석 도구 Setup 및 사용법","es":"Guía de configuración de RDKit para análisis molecular","fr":"Guide de démarrage rapide pour RDKit et la chimie informa...","de":"RDKit-Setup-Anleitung für Molekülanalyse und -manipulation","pt":"Guia de Configuração do RDKit para Análise Molecular","ru":"Настройка RDKit для химической информатики и ИИ Агентов","ar":"دليل إعداد RDKit للكيمياء الحاسوبية والأدوات الذكية"},"description":{"en":"Unlock the power of cheminformatics with rdkit. Discover how to read/write molecular structures, calculate descriptors, and more. Get started with rdkit today!","zh":"RDKit 是一个综合的化学信息学库，提供 Python API 用于分子分析和操作。了解如何使用 RDKit 进行分子结构读写、描述符计算和指纹识别等任务","ja":"RDKit は、分子分析と操作用の Python API を提供する包括的なケミカルインフォマティクスライブラリです。RDKit を使用して分子構造の読み書き、記述子計算、指紋検索などのタスクを実行する方法を学びましょう","ko":"RDKit은 분자 분석 및 조작을 위한 Python API를 제공하는 종합적인 케미컬 인포매티크스 라이브러리입니다. RDKit을 사용하여 분자 구조 읽기/쓰기, 설명자 계산 및 지문 검색 등을 수행하는 방법을 알아보세요","es":"Aprende a utilizar RDKit para análisis molecular y descubrimiento de fármacos con nuestra guía de configuración y mejores prácticas","fr":"Découvrez comment utiliser RDKit pour l''analyse moléculaire et la recherche en chimie informatique avec notre guide de démarrage rapide","de":"Erfahren Sie, wie Sie RDKit für Molekülanalyse und -manipulation einrichten und nutzen können, mit unserer umfassenden Anleitung","pt":"Aprenda a utilizar o RDKit para análise molecular e descubra como aplicar suas capacidades em projetos de química computacional","ru":"Изучите возможности RDKit для химической информатики и узнайте, как использовать его в проектах ИИ Агентов","ar":"استكشف كيفية استخدام RDKit في الكيمياء الحاسوبية وتطوير الأدوات الذكية لتحليل الجزيئات"},"definition":{"en":"rdkit is a cheminformatics library providing Python APIs for molecular analysis and manipulation, including reading/writing molecular structures and calculating descriptors.","zh":"RDKit 是一个综合的化学信息学库，用于分子分析和操作","ja":"RDKit は、分子分析と操作用の包括的なケミカルインフォマティクスライブラリです","ko":"RDKit은 분자 분석 및 조작을 위한 종합적인 케미컬 인포매티크스 라이브러리입니다","es":"RDKit es una biblioteca de cheminformatics que proporciona herramientas para análisis y manipulación molecular","fr":"RDKit est une bibliothèque de chimie informatique qui fournit des outils pour l''analyse et la manipulation moléculaire","de":"RDKit ist eine Bibliothek für Chemieinformatik, die Werkzeuge für Molekülanalyse und -manipulation bereitstellt","pt":"O que é RDKit? É uma biblioteca de química computacional que fornece APIs Python para análise molecular e manipulação.","ru":"Что такое RDKit? Это библиотека химической информатики, предоставляющая Python API для молекулярного анализа и манипуляций.","ar":"ما هو RDKit؟ هو مكتبة كيميائية حاسوبية توفر واجهات برمجة تطبيقات Python لتحليل الجزيئات والتعامل معها"},"features":{"en":["Reading and writing molecular structures","Calculating descriptors and fingerprinting","Substructure searching and chemical reactions","2D/3D coordinate generation and molecular visualization","Support for drug discovery and computational chemistry research tasks"],"zh":["分子结构读写","描述符计算","指纹识别","子结构搜索","化学反应","2D/3D 坐标生成"],"ja":["分子構造の読み書き","記述子計算","指紋検索","部分構造検索","化学反応","2D/3D 座標生成"],"ko":["분자 구조 읽기/쓰기","설명자 계산","지문 검색","부분 구조 검색","화학 반응","2D/3D 좌표 생성"],"es":["Lectura y escritura de estructuras moleculares","Cálculo de descriptores moleculares","Búsqueda de subestructuras","Generación de coordenadas 2D/3D","Visualización molecular"],"fr":["Lecture et écriture de structures moléculaires","Calcul de descripteurs moléculaires","Recherche de sous-structures","Génération de coordonnées 2D/3D","Visualisation moléculaire"],"de":["Lesen und Schreiben von Molekülstrukturen","Berechnung von Molekülbeschreibungen","Suche nach Substrukturen","Generierung von 2D/3D-Koordinaten","Molekülvisualisierung"],"pt":["Leitura e escrita de estruturas moleculares","Cálculo de descritores moleculares","Pesquisa de subestruturas","Geração de coordenadas 2D/3D","Visualização molecular"],"ru":["Чтение и запись молекулярных структур","Расчет молекулярных дескрипторов","Поиск подструктур","Генерация координат 2D/3D","Молекулярная визуализация"],"ar":["قراءة وكتابة الهياكل الجزيئية","حساب الموصفات الجزيئية","بحث الهياكل الفرعية","توليد إحداثيات 2D/3D","تجسير الجزيئات"]},"keywords":{"en":["how to use rdkit","rdkit alternative","rdkit install","rdkit setup guide","rdkit vs cheminformatics libraries","what is rdkit","rdkit for drug discovery","rdkit molecular analysis"],"zh":["RDKit","化学信息学","分子分析","Python API","分子结构读写","描述符计算","指纹识别","子结构搜索","化学反应"],"ja":["RDKit","ケミカルインフォマティクス","分子分析","Python API","分子構造の読み書き","記述子計算","指紋検索","部分構造検索","化学反応"],"ko":["RDKit","케미컬 인포매티크스","분자 분석","Python API","분자 구조 읽기/쓰기","설명자 계산","지문 검색","부분 구조 검색","화학 반응"],"es":["RDKit","análisis molecular","descubrimiento de fármacos","química computacional","cheminformatics","Python","APIs de Python","lectura de estructuras moleculares","cálculo de descriptores moleculares"],"fr":["RDKit","analyse moléculaire","découverte de médicaments","chimie informatique","chimie informatique","Python","API Python","lecture de structures moléculaires","calcul de descripteurs moléculaires"],"de":["RDKit","Molekülanalyse","Arzneimittelentdeckung","computergestützte Chemie","Chemieinformatik","Python","Python-APIs","Lesen von Molekülstrukturen","Berechnung von Molekülbeschreibungen"],"pt":["RDKit","química computacional","análise molecular","API Python","descoberta de fármacos","pesquisa em química","biblioteca de química","manipulação molecular","visualização molecular"],"ru":["RDKit","химическая информатика","молекулярный анализ","Python API","открытие лекарств","исследования в области химической информатики","библиотека химической информатики","манипуляция молекулами","молекулярная визуализация"],"ar":["RDKit","الكيمياء الحاسوبية","تحليل الجزيئات","واجهة برمجة تطبيقات Python","اكتشاف الأدوية","البحث في الكيمياء","مكتبة الكيمياء الحاسوبية","التعامل مع الجزيئات","تجسير الجزيئات"]}},"owner":"jackspace","repo":"ClaudeSkillz","repoPath":"jackspace/ClaudeSkillz","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.402Z","topics":[],"category":"community","skillMd":{"name":"rdkit","description":"Cheminformatics toolkit for fine-grained molecular control. SMILES/SDF parsing, descriptors (MW, LogP, TPSA), fingerprints, substructure search, 2D/3D generation, similarity, reactions. For standard workflows with simpler interface, use datamol (wrapper around RDKit). Use rdkit for advanced control, custom sanitization, specialized algorithms.","bodyPreview":"# RDKit Cheminformatics Toolkit\n\n## Overview\n\nRDKit is a comprehensive cheminformatics library providing Python APIs for molecular analysis and manipulation. This skill provides guidance for reading/writing molecular structures, calculating descriptors, fingerprinting, substructure searching, chemical reactions, 2D/3D coordinate generation, and molecular visualization. Use this skill for drug discovery, computational chemistry, and cheminformatics research tasks.\n\n## Core Capabilities\n\n### 1. Mo","body":"# RDKit Cheminformatics Toolkit\n\n## Overview\n\nRDKit is a comprehensive cheminformatics library providing Python APIs for molecular analysis and manipulation. This skill provides guidance for reading/writing molecular structures, calculating descriptors, fingerprinting, substructure searching, chemical reactions, 2D/3D coordinate generation, and molecular visualization. Use this skill for drug discovery, computational chemistry, and cheminformatics research tasks.\n\n## Core Capabilities\n\n### 1. Molecular I/O and Creation\n\n**Reading Molecules:**\n\nRead molecular structures from various formats:\n\n```python\nfrom rdkit import Chem\n\n# From SMILES strings\nmol = Chem.MolFromSmiles(''Cc1ccccc1'')  # Returns Mol object or None\n\n# From MOL files\nmol = Chem.MolFromMolFile(''path/to/file.mol'')\n\n# From MOL blocks (string data)\nmol = Chem.MolFromMolBlock(mol_block_string)\n\n# From InChI\nmol = Chem.MolFromInchi(''InChI=1S/C6H6/c1-2-4-6-5-3-1/h1-6H'')\n```\n\n**Writing Molecules:**\n\nConvert molecules to text representations:\n\n```python\n# To canonical SMILES\nsmiles = Chem.MolToSmiles(mol)\n\n# To MOL block\nmol_block = Chem.MolToMolBlock(mol)\n\n# To InChI\ninchi = Chem.MolToInchi(mol)\n```\n\n**Batch Processing:**\n\nFor processing multiple molecules, use Supplier/Writer objects:\n\n```python\n# Read SDF files\nsuppl = Chem.SDMolSupplier(''molecules.sdf'')\nfor mol in suppl:\n    if mol is not None:  # Check for parsing errors\n        # Process molecule\n        pass\n\n# Read SMILES files\nsuppl = Chem.SmilesMolSupplier(''molecules.smi'', titleLine=False)\n\n# For large files or compressed data\nwith gzip.open(''molecules.sdf.gz'') as f:\n    suppl = Chem.ForwardSDMolSupplier(f)\n    for mol in suppl:\n        # Process molecule\n        pass\n\n# Multithreaded processing for large datasets\nsuppl = Chem.MultithreadedSDMolSupplier(''molecules.sdf'')\n\n# Write molecules to SDF\nwriter = Chem.SDWriter(''output.sdf'')\nfor mol in molecules:\n    writer.write(mol)\nwriter.close()\n```\n\n**Important Notes:**\n- All `MolFrom*` functions return `None` on failure with error messages\n- Always check for `None` before processing molecules\n- Molecules are automatically sanitized on import (validates valence, perceives aromaticity)\n\n### 2. Molecular Sanitization and Validation\n\nRDKit automatically sanitizes molecules during parsing, executing 13 steps including valence checking, aromaticity perception, and chirality assignment.\n\n**Sanitization Control:**\n\n```python\n# Disable automatic sanitization\nmol = Chem.MolFromSmiles(''C1=CC=CC=C1'', sanitize=False)\n\n# Manual sanitization\nChem.SanitizeMol(mol)\n\n# Detect problems before sanitization\nproblems = Chem.DetectChemistryProblems(mol)\nfor problem in problems:\n    print(problem.GetType(), problem.Message())\n\n# Partial sanitization (skip specific steps)\nfrom rdkit.Chem import rdMolStandardize\nChem.SanitizeMol(mol, sanitizeOps=Chem.SANITIZE_ALL ^ Chem.SANITIZE_PROPERTIES)\n```\n\n**Common Sanitization Issues:**\n- Atoms with explicit valence exceeding maximum allowed will raise exceptions\n- Invalid aromatic rings will cause kekulization errors\n- Radical electrons may not be properly assigned without explicit specification\n\n### 3. Molecular Analysis and Properties\n\n**Accessing Molecular Structure:**\n\n```python\n# Iterate atoms and bonds\nfor atom in mol.GetAtoms():\n    print(atom.GetSymbol(), atom.GetIdx(), atom.GetDegree())\n\nfor bond in mol.GetBonds():\n    print(bond.GetBeginAtomIdx(), bond.GetEndAtomIdx(), bond.GetBondType())\n\n# Ring information\nring_info = mol.GetRingInfo()\nring_info.NumRings()\nring_info.AtomRings()  # Returns tuples of atom indices\n\n# Check if atom is in ring\natom = mol.GetAtomWithIdx(0)\natom.IsInRing()\natom.IsInRingSize(6)  # Check for 6-membered rings\n\n# Find smallest set of smallest rings (SSSR)\nfrom rdkit.Chem import GetSymmSSSR\nrings = GetSymmSSSR(mol)\n```\n\n**Stereochemistry:**\n\n```python\n# Find chiral centers\nfrom rdkit.Chem import FindMolChiralCenters\nchiral_centers = FindMolChiralCenters(mol, includeUnassigned=True)\n# Returns list of (atom_idx, chirality) tuples\n\n# Assign stereochemistry from 3D coordinates\nfrom rdkit.Chem import AssignStereochemistryFrom3D\nAssignStereochemistryFrom3D(mol)\n\n# Check bond stereochemistry\nbond = mol.GetBondWithIdx(0)\nstereo = bond.GetStereo()  # STEREONONE, STEREOZ, STEREOE, etc.\n```\n\n**Fragment Analysis:**\n\n```python\n# Get disconnected fragments\nfrags = Chem.GetMolFrags(mol, asMols=True)\n\n# Fragment on specific bonds\nfrom rdkit.Chem import FragmentOnBonds\nfrag_mol = FragmentOnBonds(mol, [bond_idx1, bond_idx2])\n\n# Count ring systems\nfrom rdkit.Chem.Scaffolds import MurckoScaffold\nscaffold = MurckoScaffold.GetScaffoldForMol(mol)\n```\n\n### 4. Molecular Descriptors and Properties\n\n**Basic Descriptors:**\n\n```python\nfrom rdkit.Chem import Descriptors\n\n# Molecular weight\nmw = Descriptors.MolWt(mol)\nexact_mw = Descriptors.ExactMolWt(mol)\n\n# LogP (lipophilicity)\nlogp = Descriptors.MolLogP(mol)\n\n# Topological polar surface area\ntpsa = Descriptors.TPSA(mol)\n\n# Number of hydrogen bond donors/acceptors\nhbd = Descriptors.NumHDonors(mol)\nhba = Descriptors.NumHAcceptors(mol)\n\n# Number of rotatable bonds\nrot_bonds = Descriptors.NumRotatableBonds(mol)\n\n# Number of aromatic rings\naromatic_rings = Descriptors.NumAromaticRings(mol)\n```\n\n**Batch Descriptor Calculation:**\n\n```python\n# Calculate all descriptors at once\nall_descriptors = Descriptors.CalcMolDescriptors(mol)\n# Returns dictionary: {''MolWt'': 180.16, ''MolLogP'': 1.23, ...}\n\n# Get list of available descriptor names\ndescriptor_names = [desc[0] for desc in Descriptors._descList]\n```\n\n**Lipinski''s Rule of Five:**\n\n```python\n# Check drug-likeness\nmw = Descriptors.MolWt(mol) <= 500\nlogp = Descriptors.MolLogP(mol) <= 5\nhbd = Descriptors.NumHDonors(mol) <= 5\nhba = Descriptors.NumHAcceptors(mol) <= 10\n\nis_drug_like = mw and logp and hbd and hba\n```\n\n### 5. Fingerprints and Molecular Similarity\n\n**Fingerprint Types:**\n\n```python\nfrom rdkit.Chem import AllChem, RDKFingerprint\nfrom rdkit.Chem.AtomPairs import Pairs, Torsions\nfrom rdkit.Chem import MACCSkeys\n\n# RDKit topological fingerprint\nfp = Chem.RDKFingerprint(mol)\n\n# Morgan fingerprints (circular fingerprints, similar to ECFP)\nfp = AllChem.GetMorganFingerprint(mol, radius=2)\nfp_bits = AllChem.GetMorganFingerprintAsBitVect(mol, radius=2, nBits=2048)\n\n# MACCS keys (166-bit structural key)\nfp = MACCSkeys.GenMACCSKeys(mol)\n\n# Atom pair fingerprints\nfp = Pairs.GetAtomPairFingerprint(mol)\n\n# Topological torsion fingerprints\nfp = Torsions.GetTopologicalTorsionFingerprint(mol)\n\n# Avalon fingerprints (if available)\nfrom rdkit.Avalon import pyAvalonTools\nfp = pyAvalonTools.GetAvalonFP(mol)\n```\n\n**Similarity Calculation:**\n\n```python\nfrom rdkit import DataStructs\n\n# Calculate Tanimoto similarity\nfp1 = AllChem.GetMorganFingerprintAsBitVect(mol1, radius=2)\nfp2 = AllChem.GetMorganFingerprintAsBitVect(mol2, radius=2)\nsimilarity = DataStructs.TanimotoSimilarity(fp1, fp2)\n\n# Calculate similarity for multiple molecules\nsimilarities = DataStructs.BulkTanimotoSimilarity(fp1, [fp2, fp3, fp4])\n\n# Other similarity metrics\ndice = DataStructs.DiceSimilarity(fp1, fp2)\ncosine = DataStructs.CosineSimilarity(fp1, fp2)\n```\n\n**Clustering and Diversity:**\n\n```python\n# Butina clustering based on fingerprint similarity\nfrom rdkit.ML.Cluster import Butina\n\n# Calculate distance matrix\ndists = []\nfps = [AllChem.GetMorganFingerprintAsBitVect(mol, 2) for mol in mols]\nfor i in range(len(fps)):\n    sims = DataStructs.BulkTanimotoSimilarity(fps[i], fps[:i])\n    dists.extend([1-sim for sim in sims])\n\n# Cluster with distance cutoff\nclusters = Butina.ClusterData(dists, len(fps), distThresh=0.3, isDistData=True)\n```\n\n### 6. Substructure Searching and SMARTS\n\n**Basic Substructure Matching:**\n\n```python\n# Define query using SMARTS\nquery = Chem.MolFromSmarts(''[#6]1:[#6]:[#6]:[#6]:[#6]:[#6]:1'')  # Benzene ring\n\n# Check if molecule contains substructure\nhas_match = mol.HasSubstructMatch(query)\n\n# Get all matches (returns tuple of tuples with atom indices)\nmatches = mol.GetSubstructMatches(query)\n\n# Get only first match\nmatch = mol.GetSubstructMatch(query)\n```\n\n**Common SMARTS Patterns:**\n\n```python\n# Primary alcohols\nprimary_alcohol = Chem.MolFromSmarts(''[CH2][OH1]'')\n\n# Carboxylic acids\ncarboxylic_acid = Chem.MolFromSmarts(''C(=O)[OH]'')\n\n# Amides\namide = Chem.MolFromSmarts(''C(=O)N'')\n\n# Aromatic heterocycles\naromatic_n = Chem.MolFromSmarts(''[nR]'')  # Aromatic nitrogen in ring\n\n# Macrocycles (rings > 12 atoms)\nmacrocycle = Chem.MolFromSmarts(''[r{12-}]'')\n```\n\n**Matching Rules:**\n- Unspecified properties in query match any value in target\n- Hydrogens are ignored unless explicitly specified\n- Charged query atom won''t match uncharged target atom\n- Aromatic query atom won''t match aliphatic target atom (unless query is generic)\n\n### 7. Chemical Reactions\n\n**Reaction SMARTS:**\n\n```python\nfrom rdkit.Chem import AllChem\n\n# Define reaction using SMARTS: reactants >> products\nrxn = AllChem.ReactionFromSmarts(''[C:1]=[O:2]>>[C:1][O:2]'')  # Ketone reduction\n\n# Apply reaction to molecules\nreactants = (mol1,)\nproducts = rxn.RunReactants(reactants)\n\n# Products is tuple of tuples (one tuple per product set)\nfor product_set in products:\n    for product in product_set:\n        # Sanitize product\n        Chem.SanitizeMol(product)\n```\n\n**Reaction Features:**\n- Atom mapping preserves specific atoms between reactants and products\n- Dummy atoms in products are replaced by corresponding reactant atoms\n- \"Any\" bonds inherit bond order from reactants\n- Chirality preserved unless explicitly changed\n\n**Reaction Similarity:**\n\n```python\n# Generate reaction fingerprints\nfp = AllChem.CreateDifferenceFingerprintForReaction(rxn)\n\n# Compare reactions\nsimilarity = DataStructs.TanimotoSimilarity(fp1, fp2)\n```\n\n### 8. 2D and 3D Coordinate Generation\n\n**2D Coordinate Generation:**\n\n```python\nfrom rdkit.Chem import AllChem\n\n# Generate 2D coordinates for depiction\nAllChem.Compute2DCoords(mol)\n\n# Align molecule to template structure\ntemplate = Chem.MolFromSmiles(''c1ccccc1'')\nAllChem.Compute2DCoords(template)\nAllChem.GenerateDepictionMatching2DStructure(mol, template)\n```\n\n**3D Coordinate Generation and Conformers:**\n\n```python\n# Generate single 3D conformer using ETKDG\nAllChem.EmbedMolecule(mol, randomSeed=42)\n\n# Generate multiple conformers\nconf_ids = AllChem.EmbedMultipleConfs(mol, numConfs=10, randomSeed=42)\n\n# Optimize geometry with force field\nAllChem.UFFOptimizeMolecule(mol)  # UFF force field\nAllChem.MMFFOptimizeMolecule(mol)  # MMFF94 force field\n\n# Optimize all conformers\nfor conf_id in conf_ids:\n    AllChem.MMFFOptimizeMolecule(mol, confId=conf_id)\n\n# Calculate RMSD between conformers\nfrom rdkit.Chem import AllChem\nrms = AllChem.GetConformerRMS(mol, conf_id1, conf_id2)\n\n# Align molecules\nAllChem.AlignMol(probe_mol, ref_mol)\n```\n\n**Constrained Embedding:**\n\n```python\n# Embed with part of molecule constrained to specific coordinates\nAllChem.ConstrainedEmbed(mol, core_mol)\n```\n\n### 9. Molecular Visualization\n\n**Basic Drawing:**\n\n```python\nfrom rdkit.Chem import Draw\n\n# Draw single molecule to PIL image\nimg = Draw.MolToImage(mol, size=(300, 300))\nimg.save(''molecule.png'')\n\n# Draw to file directly\nDraw.MolToFile(mol, ''molecule.png'')\n\n# Draw multiple molecules in grid\nmols = [mol1, mol2, mol3, mol4]\nimg = Draw.MolsToGridImage(mols, molsPerRow=2, subImgSize=(200, 200))\n```\n\n**Highlighting Substructures:**\n\n```python\n# Highlight substructure match\nquery = Chem.MolFromSmarts(''c1ccccc1'')\nmatch = mol.GetSubstructMatch(query)\n\nimg = Draw.MolToImage(mol, highlightAtoms=match)\n\n# Custom highlight colors\nhighlight_colors = {atom_idx: (1, 0, 0) for atom_idx in match}  # Red\nimg = Draw.MolToImage(mol, highlightAtoms=match,\n                      highlightAtomColors=highlight_colors)\n```\n\n**Customizing Visualization:**\n\n```python\nfrom rdkit.Chem.Draw import rdMolDraw2D\n\n# Create drawer with custom options\ndrawer = rdMolDraw2D.MolDraw2DCairo(300, 300)\nopts = drawer.drawOptions()\n\n# Customize options\nopts.addAtomIndices = True\nopts.addStereoAnnotation = True\nopts.bondLineWidth = 2\n\n# Draw molecule\ndrawer.DrawMolecule(mol)\ndrawer.FinishDrawing()\n\n# Save to file\nwith open(''molecule.png'', ''wb'') as f:\n    f.write(drawer.GetDrawingText())\n```\n\n**Jupyter Notebook Integration:**\n\n```python\n# Enable inline display in Jupyter\nfrom rdkit.Chem.Draw import IPythonConsole\n\n# Customize default display\nIPythonConsole.ipython_useSVG = True  # Use SVG instead of PNG\nIPythonConsole.molSize = (300, 300)   # Default size\n\n# Molecules now display automatically\nmol  # Shows molecule image\n```\n\n**Visualizing Fingerprint Bits:**\n\n```python\n# Show what molecular features a fingerprint bit represents\nfrom rdkit.Chem import Draw\n\n# For Morgan fingerprints\nbit_info = {}\nfp = AllChem.GetMorganFingerprintAsBitVect(mol, radius=2, bitInfo=bit_info)\n\n# Draw environment for specific bit\nimg = Draw.DrawMorganBit(mol, bit_id, bit_info)\n```\n\n### 10. Molecular Modification\n\n**Adding/Removing Hydrogens:**\n\n```python\n# Add explicit hydrogens\nmol_h = Chem.AddHs(mol)\n\n# Remove explicit hydrogens\nmol = Chem.RemoveHs(mol_h)\n```\n\n**Kekulization and Aromaticity:**\n\n```python\n# Convert aromatic bonds to alternating single/double\nChem.Kekulize(mol)\n\n# Set aromaticity\nChem.SetAromaticity(mol)\n```\n\n**Replacing Substructures:**\n\n```python\n# Replace substructure with another structure\nquery = Chem.MolFromSmarts(''c1ccccc1'')  # Benzene\nreplacement = Chem.MolFromSmiles(''C1CCCCC1'')  # Cyclohexane\n\nnew_mol = Chem.ReplaceSubstructs(mol, query, replacement)[0]\n```\n\n**Neutralizing Charges:**\n\n```python\n# Remove formal charges by adding/removing hydrogens\nfrom rdkit.Chem.MolStandardize import rdMolStandardize\n\n# Using Uncharger\nuncharger = rdMolStandardize.Uncharger()\nmol_neutral = uncharger.uncharge(mol)\n```\n\n### 11. Working with Molecular Hashes and Standardization\n\n**Molecular Hashing:**\n\n```python\nfrom rdkit.Chem import rdMolHash\n\n# Generate Murcko scaffold hash\nscaffold_hash = rdMolHash.MolHash(mol, rdMolHash.HashFunction.MurckoScaffold)\n\n# Canonical SMILES hash\ncanonical_hash = rdMolHash.MolHash(mol, rdMolHash.HashFunction.CanonicalSmiles)\n\n# Regioisomer hash (ignores stereochemistry)\nregio_hash = rdMolHash.MolHash(mol, rdMolHash.HashFunction.Regioisomer)\n```\n\n**Randomized SMILES:**\n\n```python\n# Generate random SMILES representations (for data augmentation)\nfrom rdkit.Chem import MolToRandomSmilesVect\n\nrandom_smiles = MolToRandomSmilesVect(mol, numSmiles=10, randomSeed=42)\n```\n\n### 12. Pharmacophore and 3D Features\n\n**Pharmacophore Features:**\n\n```python\nfrom rdkit.Chem import ChemicalFeatures\nfrom rdkit import RDConfig\nimport os\n\n# Load feature factory\nfdef_path = os.path.join(RDConfig.RDDataDir, ''BaseFeatures.fdef'')\nfactory = ChemicalFeatures.BuildFeatureFactory(fdef_path)\n\n# Get pharmacophore features\nfeatures = factory.GetFeaturesForMol(mol)\n\nfor feat in features:\n    print(feat.GetFamily(), feat.GetType(), feat.GetAtomIds())\n```\n\n## Common Workflows\n\n### Drug-likeness Analysis\n\n```python\nfrom rdkit import Chem\nfrom rdkit.Chem import Descriptors\n\ndef analyze_druglikeness(smiles):\n    mol = Chem.MolFromSmiles(smiles)\n    if mol is None:\n        return None\n\n    # Calculate Lipinski descriptors\n    results = {\n        ''MW'': Descriptors.MolWt(mol),\n        ''LogP'': Descriptors.MolLogP(mol),\n        ''HBD'': Descriptors.NumHDonors(mol),\n        ''HBA'': Descriptors.NumHAcceptors(mol),\n        ''TPSA'': Descriptors.TPSA(mol),\n        ''RotBonds'': Descriptors.NumRotatableBonds(mol)\n    }\n\n    # Check Lipinski''s Rule of Five\n    results[''Lipinski''] = (\n        results[''MW''] <= 500 and\n        results[''LogP''] <= 5 and\n        results[''HBD''] <= 5 and\n        results[''HBA''] <= 10\n    )\n\n    return results\n```\n\n### Similarity Screening\n\n```python\nfrom rdkit import Chem\nfrom rdkit.Chem import AllChem\nfrom rdkit import DataStructs\n\ndef similarity_screen(query_smiles, database_smiles, threshold=0.7):\n    query_mol = Chem.MolFromSmiles(query_smiles)\n    query_fp = AllChem.GetMorganFingerprintAsBitVect(query_mol, 2)\n\n    hits = []\n    for idx, smiles in enumerate(database_smiles):\n        mol = Chem.MolFromSmiles(smiles)\n        if mol:\n            fp = AllChem.GetMorganFingerprintAsBitVect(mol, 2)\n            sim = DataStructs.TanimotoSimilarity(query_fp, fp)\n            if sim >= threshold:\n                hits.append((idx, smiles, sim))\n\n    return sorted(hits, key=lambda x: x[2], reverse=True)\n```\n\n### Substructure Filtering\n\n```python\nfrom rdkit import Chem\n\ndef filter_by_substructure(smiles_list, pattern_smarts):\n    query = Chem.MolFromSmarts(pattern_smarts)\n\n    hits = []\n    for smiles in smiles_list:\n        mol = Chem.MolFromSmiles(smiles)\n        if mol and mol.HasSubstructMatch(query):\n            hits.append(smiles)\n\n    return hits\n```\n\n## Best Practices\n\n### Error Handling\n\nAlways check for `None` when parsing molecules:\n\n```python\nmol = Chem.MolFromSmiles(smiles)\nif mol is None:\n    print(f\"Failed to parse: {smiles}\")\n    continue\n```\n\n### Performance Optimization\n\n**Use binary formats for storage:**\n\n```python\nimport pickle\n\n# Pickle molecules for fast loading\nwith open(''molecules.pkl'', ''wb'') as f:\n    pickle.dump(mols, f)\n\n# Load pickled molecules (much faster than reparsing)\nwith open(''molecules.pkl'', ''rb'') as f:\n    mols = pickle.load(f)\n```\n\n**Use bulk operations:**\n\n```python\n# Calculate fingerprints for all molecules at once\nfps = [AllChem.GetMorganFingerprintAsBitVect(mol, 2) for mol in mols]\n\n# Use bulk similarity calculations\nsimilarities = DataStructs.BulkTanimotoSimilarity(fps[0], fps[1:])\n```\n\n### Thread Safety\n\nRDKit operations are generally thread-safe for:\n- Molecule I/O (SMILES, mol blocks)\n- Coordinate generation\n- Fingerprinting and descriptors\n- Substructure searching\n- Reactions\n- Drawing\n\n**Not thread-safe:** MolSuppliers when accessed concurrently.\n\n### Memory Management\n\nFor large datasets:\n\n```python\n# Use ForwardSDMolSupplier to avoid loading entire file\nwith open(''large.sdf'') as f:\n    suppl = Chem.ForwardSDMolSupplier(f)\n    for mol in suppl:\n        # Process one molecule at a time\n        pass\n\n# Use MultithreadedSDMolSupplier for parallel processing\nsuppl = Chem.MultithreadedSDMolSupplier(''large.sdf'', numWriterThreads=4)\n```\n\n## Common Pitfalls\n\n1. **Forgetting to check for None:** Always validate molecules after parsing\n2. **Sanitization failures:** Use `DetectChemistryProblems()` to debug\n3. **Missing hydrogens:** Use `AddHs()` when calculating properties that depend on hydrogen\n4. **2D vs 3D:** Generate appropriate coordinates before visualization or 3D analysis\n5. **SMARTS matching rules:** Remember that unspecified properties match anything\n6. **Thread safety with MolSuppliers:** Don''t share supplier objects across threads\n\n## Resources\n\n### references/\n\nThis skill includes detailed API reference documentation:\n\n- `api_reference.md` - Comprehensive listing of RDKit modules, functions, and classes organized by functionality\n- `descriptors_reference.md` - Complete list of available molecular descriptors with descriptions\n- `smarts_patterns.md` - Common SMARTS patterns for functional groups and structural features\n\nLoad these references when needing specific API details, parameter information, or pattern examples.\n\n### scripts/\n\nExample scripts for common RDKit workflows:\n\n- `molecular_properties.py` - Calculate comprehensive molecular properties and descriptors\n- `similarity_search.py` - Perform fingerprint-based similarity screening\n- `substructure_filter.py` - Filter molecules by substructure patterns\n\nThese scripts can be executed directly or used as templates for custom workflows.\n"},"lastSynced":"2026-03-08T02:06:47.058Z","agentAnalysis":{"suitability":{"en":"Perfect for Cheminformatics Agents needing advanced molecular analysis and manipulation capabilities.","zh":"非常适合需要高级分子分析和操作能力的化学生物信息学代理。","ja":"高度な分子分析および操作機能を必要とする化学生物情報学エージェントに最適です。","ko":"고급 분자 분석 및 조작 기능이 필요한 화학 생물 정보학 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Quimioinformática que necesitan capacidades de análisis y manipulación molecular avanzadas.","fr":"Parfait pour les Agents de Chemo-informatique ayant besoin de capacités d''analyse et de manipulation moléculaire avancées.","de":"Perfekt für Chemoinformatik-Agenten, die erweiterte molekulare Analyse- und Manipulationsfunktionen benötigen.","pt":"Perfeito para Agentes de Quimioinformática que necessitam de capacidades avançadas de análise e manipulação molecular.","ru":"Идеально подходит для агентов хемоинформатики, которым требуются продвинутые возможности анализа и манипулирования молекулами.","ar":"مثالي لوكلاء الكيمياء الحاسوبية الذين يحتاجون إلى قدرات تحليلและการ مаниع جزيئية متقدمة."},"recommendation":{"en":"Empowers agents to perform molecular structure analysis, calculate descriptors, and generate 2D/3D coordinates using RDKit''s Python APIs, ideal for drug discovery and computational chemistry research tasks involving molecular fingerprinting, substructure searching, and chemical reactions.","zh":"赋予代理执行分子结构分析、计算描述符、使用RDKit的Python APIs生成2D/3D坐标的能力，非常适合药物发现和计算化学研究任务，涉及分子指纹、子结构搜索和化学反应。","ja":"エージェントに分子構造分析、記述子の計算、RDKitのPython APIを使用した2D/3D座標の生成を実行する能力を付与し、薬物発見と計算化学研究タスクに最適です。分子指紋、サブ構造検索、化学反応が含まれます。","ko":"에이전트가 분자 구조 분석, 설명자 계산 및 RDKit의 Python API를 사용한 2D/3D 좌표 생성을 수행할 수 있도록 하며, 분자 지문, 서브구조 검색 및 화학 반응을 포함한 약물 발견 및 계산 화학 연구 작업에 적합합니다.","es":"Habilita a los agentes a realizar análisis de estructura molecular, calcular descriptores y generar coordenadas 2D/3D utilizando las API de Python de RDKit, ideal para tareas de investigación de descubrimiento de fármacos y química computacional que involucran la identificación de huellas moleculares, la búsqueda de subestructuras y las reacciones químicas.","fr":"Permet aux agents de réaliser l''analyse de structure moléculaire, de calculer des descripteurs et de générer des coordonnées 2D/3D en utilisant les API Python de RDKit, idéal pour les tâches de recherche de découverte de médicaments et de chimie computationnelle impliquant l''empreinte moléculaire, la recherche de sous-structures et les réactions chimiques.","de":"Ermöglicht es Agenten, molekulare Strukturanalysen durchzuführen, Deskriptoren zu berechnen und 2D/3D-Koordinaten mit RDKit''s Python-APIs zu generieren, ideal für Arbeiten zum Wirkstoffdesign und zur computergestützten Chemieforschung, die die molekulare Fingerprinting, die Substruktursuche und chemische Reaktionen umfassen.","pt":"Habilita agentes a realizar análise de estrutura molecular, calcular descritores e gerar coordenadas 2D/3D usando as APIs Python do RDKit, ideal para tarefas de pesquisa de descoberta de drogas e química computacional que envolvem impressão digital molecular, pesquisa de subestrutura e reações químicas.","ru":"Наделяет агентов возможностью выполнять анализ молекулярной структуры, вычислять дескрипторы и генерировать координаты 2D/3D с использованием Python API RDKit, идеально подходит для задач исследований открытия лекарств и вычислительной химии, включающих молекулярное фингер-printing, поиск подструктуры и химические реакции.","ar":"يُمنح الوكلاء القدرة على أداء تحليل الهيكل الجزيئي وحساب الموصفات وتوليد إحداثيات 2D/3D باستخدام APIs بايثون RDKit، مثالي لمهام أبحاث اكتشاف الأدوية والكيمياء الحاسوبية التي تتضمن البصمة الجزيئية وعمليات البحث عن الهيكل الفرعي والتفاعلات الكيميائية."},"useCases":{"en":["Automating molecular structure visualization","Generating molecular descriptors for drug discovery","Performing substructure searching for chemical reactions"],"zh":["自动化分子结构可视化","为药物发现生成分子描述符","执行化学反应的子结构搜索"],"ja":["分子構造の可視化を自動化する","薬物発見のための分子記述子の生成","化学反応のサブ構造検索を実行する"],"ko":["분자 구조 시각화 자동화","약물 발견을 위한 분자 설명자 생성","화학 반응을 위한 서브구조 검색 수행"],"es":["Automatizar la visualización de estructuras moleculares","Generar descriptores moleculares para el descubrimiento de fármacos","Realizar búsquedas de subestructuras para reacciones químicas"],"fr":["Automatiser la visualisation de structures moléculaires","Générer des descripteurs moléculaires pour la découverte de médicaments","Réalisser des recherches de sous-structures pour les réactions chimiques"],"de":["Automatisieren der Visualisierung molekularer Strukturen","Generieren molekularer Deskriptoren für die Wirkstofffindung","Durchführen von Substruktursuchen für chemische Reaktionen"],"pt":["Automatizar visualização de estrutura molecular","Gerar descritores moleculares para descoberta de drogas","Realizar pesquisa de subestrutura para reações químicas"],"ru":["Автоматизация визуализации молекулярной структуры","Генерация молекулярных дескрипторов для открытия лекарств","Выполнение поиска подструктуры для химических реакций"],"ar":["تأتمتة تصور الهيكل الجزيئي","إنتاج موصفات جزيئية لاكتشاف الأدوية"," Performing عمليات البحث عن الهيكل الفرعي للتفاعلات الكيميائية"]},"limitations":{"en":["Requires Python environment","Limited to cheminformatics and computational chemistry tasks"],"zh":["需要Python环境","仅限于化学生物信息学和计算化学任务"],"ja":["Python環境が必要","化学生物情報学と計算化学タスクのみに限定される"],"ko":["Python 환경이 필요함","화학 생물 정보학 및 계산 화학 작업에만 제한됨"],"es":["Requiere entorno de Python","Limitado a tareas de quimioinformática y química computacional"],"fr":["Nécessite un environnement Python","Limité aux tâches de chemo-informatique et de chimie computationnelle"],"de":["Benötigt eine Python-Umgebung","Eingeschränkt auf Aufgaben der Chemoinformatik und computergestützten Chemie"],"pt":["Requer ambiente Python","Limitado a tarefas de quimioinformática e química computacional"],"ru":["Требуется среда Python","Ограничен задачами хемоинформатики и вычислительной химии"],"ar":["يتطلب بيئة بايثون","محدود بمهام الكيمياء الحاسوبية والكيمياء الحاسوبية"]},"version":4},"contentHash":"cf451fd778f2baaf2e7afe9415a08ce4ea2293e1bc7d6c196a8b985fcfaeef22","qualityScore":42}');
