INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('alexknowshtml/cord/cord', 'cord', 'alexknowshtml', 'cord', 'community', 'cord alexknowshtml cord community Cord is a skill that enables interaction with Discord through Claude Code, allowing developers to send messages, embeds, files, and interactive buttons. It benefits developers who want to integrate Discord functionality into their applications. Cord 是一个 Discord 到 Claude Code 的桥接，允许开发者通过 Discord 与 Claude Code 进行交互 Cord は Discord から Claude Code へのブリッジであり、開発者が Discord を介して Claude Code と対話できるようにします Cord는 Discord에서 Claude Code로의桥接로, 개발자가 Discord를 통해 Claude Code와 상호 작용할 수 있게 합니다 Cord es un puente entre Discord y Claude Code que permite interactuar con Discord a través de comandos CLI. Esta habilidad enseña a Claude Code a enviar mensajes, archivos y botones interactivos. Cord est un pont entre Discord et Claude Code qui permet d''interagir avec Discord via des commandes CLI. Cette compétence enseigne à Claude Code à envoyer des messages, des fichiers et des boutons interactifs. Cord ist eine Brücke zwischen Discord und Claude Code, die es ermöglicht, mit Discord über CLI-Befehle zu interagieren. Diese Fähigkeit lehrt Claude Code, Nachrichten, Dateien und interaktive Schaltflächen zu senden. O Cord é uma ponte entre o Discord e o Claude Code, permitindo interagir com o Discord através de comandos CLI. Ele ensina o Claude Code a enviar mensagens, anexos e botões interativos. Cord является мостом между Discord и Claude Code, позволяющим взаимодействовать с Discord через CLI-команды. Он учит Claude Code отправке сообщений, вложений и интерактивных кнопок для ИИ Агентов Cord هو جسر بين Discord و Claude Code ، مما يسمح بالتفاعل مع Discord من خلال أوامر CLI. يعلّم Claude Code إرسال الرسائل والمرفقات والأزرار التفاعلية للوكلاء الذكيين how to use cord cord discord bridge cord setup guide cord alternative cord vs discord bot cord install what is cord cord cli commands cord github repository Cord 技术 Discord 与 Claude Code 桥接 AI 工具 CLI 命令 Discord 机器人 Claude Code 集成 AIエージェント Discord API Sends text messages to channels or threads via the `send` CLI command Supports embedding files and interactive buttons Verifies connection status via `curl` requests to `http://localhost:2643/health` Runs on a local server, accessible via `http://localhost:2643` Utilizes a CLI-based interface for easy interaction Provides a health check endpoint for monitoring connection status Cord is a Discord to Claude Code bridge that enables developers to interact with Discord through CLI commands, allowing for seamless integration of Discord functionality into their applications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('martinholovsky/claude-skills-generator/python', 'community', 'martinholovsky', 'claude-skills-generator', 'martinholovsky/claude-skills-generator', 'python', 0, 0, 42, '2026-03-08T01:57:15.404Z', '2026-03-08T02:06:51.682Z', '7911f285f6070fd7ed9cb45bc5d17ed72d51bc485fba0b493dbbf7d70ec2b3f5', '{"id":"martinholovsky/claude-skills-generator/python","name":"python","description":{"en":"The Python skill provides advanced backend development capabilities, benefiting developers with secure and optimized code. It utilizes a split structure for high-risk requirements.","zh":"Python 后端开发技能涉及文件组织、安全模式和高级优化技术","ja":"Python バックエンド開発スキルにはファイル組織、セキュリティパターン、高度な最適化が含まれる","ko":"파이썬 백엔드 개발 스킬은 파일 조직, 보안 패턴, 고급 최적화를 포함한다","es":"Python es un lenguaje de programación versátil para desarrollo backend, con patrones de seguridad y optimización avanzados","fr":"Python est un langage de programmation polyvalent pour le développement backend, avec des modèles de sécurité et d''optimisation avancés","de":"Python ist eine vielseitige Programmiersprache für die Backend-Entwicklung, mit Sicherheits- und Optimierungsmustern","pt":"O Python é uma linguagem de programação versátil para desenvolvimento de backend. Aprenda a configurá-lo com segurança e padrões avançados.","ru":"Python - это универсальный язык программирования для разработки бэкенда. Узнайте, как настроить его с безопасностью и продвинутыми шаблонами","ar":"بايثون هي لغة برمجة متعددة الاستخدامات لتطوير الـbackend. تعلم كيفية إعدادها بأمان ونمط متقدم"},"seo":{"title":{"en":"Python: Advanced Backend Development Setup Guide | AI Age...","zh":"Python 后端开发最佳实践指南","ja":"Python バックエンド開発セットアップガイド","ko":"파이썬 백엔드 개발 가이드","es":"Guía de configuración de Python para desarrollo backend","fr":"Guide de configuration Python pour le développement backend","de":"Python-Backend-Entwicklung: Einrichtungsleitfaden","pt":"Guia de Configuração Python para Desenvolvimento de Backend","ru":"Настройка Python для разработки бэкенда: ИИ Агенты","ar":"دليل إعداد بايثون للbackend مع أدوات الذكاء الاصطناعي"},"description":{"en":"Unlock expert-level Python backend development with this AI agent skill, featuring advanced security patterns and optimization techniques - get started now!","zh":"了解 Python 后端开发的核心原则、安全模式和高级优化技术","ja":"Python バックエンド開発の基本原則、セキュリティパターン、高度な最適化を学ぶ","ko":"파이썬 백엔드 개발의 핵심 원칙, 보안 패턴, 고급 최적화 기술을 배우다","es":"Aprende a configurar Python para desarrollo backend con nuestras mejores prácticas y patrones de seguridad","fr":"Découvrez comment configurer Python pour le développement backend avec nos meilleures pratiques et modèles de sécurité","de":"Erfahren Sie, wie Sie Python für die Backend-Entwicklung konfigurieren, mit unseren Best Practices und Sicherheitsmustern","pt":"Aprenda a configurar o Python para desenvolvimento de backend com segurança e padrões avançados. Descubra como melhorar sua estrutura de projeto","ru":"Узнайте, как настроить Python для разработки бэкенда с безопасностью и продвинутыми шаблонами. Улучшите свою структуру проекта с ИИ Агентами","ar":"تعلم كيفية إعداد بايثون لتطوير الـbackend بأمان ونمط متقدم. استكشف كيفية تحسين هيكل مشروعك مع أدوات الذكاء الاصطناعي"},"definition":{"en":"Python is a high-level programming language used for backend development, emphasizing security and optimization through advanced patterns and threat modeling.","zh":"Python 后端开发是指使用 Python 编程语言构建服务器端应用程序","ja":"Python バックエンド開発とは Python プログラミング言語を使用してサーバーサイドアプリケーションを構築すること","ko":"파이썬 백엔드 개발은 파이썬 프로그래밍 언어를 사용하여 서버 측 애플리케이션을 구축하는 것을 의미한다","es":"Python es un lenguaje de programación de alto nivel para desarrollo backend","fr":"Python est un langage de programmation de haut niveau pour le développement backend","de":"Python ist eine hochrangige Programmiersprache für die Backend-Entwicklung","pt":"O que é Python? É uma linguagem de programação de alto nível para