INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('masuP9/a11y-specialist-skills/planning-wcag-audit', 'planning-wcag-audit', 'masuP9', 'a11y-specialist-skills', 'community', 'planning-wcag-audit masuP9 a11y-specialist-skills community The planning-wcag-audit skill helps accessibility specialists plan WCAG audits by organizing scope, page selection, and test environments. It benefits developers and auditors by streamlining the audit process. planning-wcag-audit AI智能审计工具，帮助开发者按照WAIC测试指南，组织审计范围、页面选择和测试环境，生成审计计划文档 WCAGオーディット計画AIエージェントは、開発者がWAICテストガイドラインに基づいてスコープ、ページ選択、テスト環境を整理し、オーディット計画書を生成するのに役立ちます planning-wcag-audit AI 에이전트는 개발자가 WAIC 테스트 가이드라인에 따라 감사 범위, 페이지 선택 및 테스트 환경을 구성하고 감사 계획서를 생성하는 데 도움이 됩니다 Planifica auditorías WCAG de manera efectiva con nuestro plugin de habilidades para especialistas en accesibilidad, que sigue las directrices de prueba de WAIC Planifiez des audits WCAG de manière efficace avec notre plugin de compétences pour les spécialistes de l''accessibilité, basé sur les directives de test WAIC Planen Sie WCAG-Audits effektiv mit unserem Skill-Plugin für Accessibility-Spezialisten, das auf den WAIC-Testrichtlinien basiert O plugin de habilidades de especialista em acessibilidade para Claude Code ajuda a planejar auditorias WCAG, incluindo coleta de informações do site e geração de documentos de plano de auditoria Плагин навыков специалиста по доступности для Claude Code помогает планировать аудиты WCAG, включая сбор информации о сайте и генерацию плана аудита مكون الإضافة لمهارات chuyênية في الوصول لبرنامج Claude Code يساعد في تنظيم تدقيق WCAG، بما في ذلك جمع معلومات الموقع وإنشاء مستند خطة التدقيق how to plan a WCAG audit what is planning-wcag-audit WCAG audit planning guide planning-wcag-audit vs accessibility audit tools planning-wcag-audit setup guide planning-wcag-audit install for AI agents WCAG audit best practices accessibility specialist skills WAIC test guidelines for WCAG audit WCAG审计 AI智能审计 WAIC测试指南 审计范围 页面选择 测试环境 审计计划文档 开发者工具 Organizes scope and page selection based on WAIC test guidelines Confirms test environment for WCAG audit Generates audit plan documents Captures site information at a high level Selects test methods according to WAIC guidelines Produces a comprehensive audit plan planning-wcag-audit is a skill that assists in planning WCAG audits based on WAIC test guidelines, covering site information gathering, test method selection, and audit plan document generation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('plosson/siteio/logo-creator', 'community', 'plosson', 'siteio', 'plosson/siteio', 'logo-creator', 0, 0, 42, '2026-03-08T01:57:15.409Z', '2026-03-08T02:07:01.208Z', '1c5e690f473156aea542656272fc97e6459c2b46d68bcd675b254605e0f9bd57', '{"id":"plosson/siteio/logo-creator","name":"logo-creator","description":{"en":"The logo-creator skill generates professional logos through AI image generation with an iterative design process, benefiting developers and designers. It utilizes required API keys from Google AI Studio, remove.bg, and recraft.ai.","zh":"Logo Creator Skill是一个基于AI图像生成的Logo设计工具，需要GEMINI_API_KEY、REMOVE_BG_API_KEY和RECRAFT_API_KEY","ja":"Logo Creator SkillはAIエージェントを使用したロゴ作成ツールで、GEMINI_API_KEY、REMOVE_BG_API_KEY、RECRAFT_API_KEYが必要","ko":"Logo Creator Skill은 AI 도구를 사용한 로고 생성 도구로, GEMINI_API_KEY, REMOVE_BG_API_KEY, RECRAFT_API_KEY가 필요합니다","es":"El skill Logo Creator utiliza tecnologías de AI como Gemini 3 Pro Image para generar logotipos profesionales. Requiere claves API de Gemini, Remove.bg y Recraft.ai.","fr":"Le skill Logo Creator utilise des technologies d''IA comme Gemini 3 Pro Image pour créer des logos professionnels. Il nécessite des clés API de Gemini, Remove.bg et Recraft.ai.","de":"Das Logo Creator-Skill verwendet KI-Technologien wie Gemini 3 Pro Image, um professionelle Logos zu erstellen. Es erfordert API-Schlüssel von Gemini, Remove.bg und Recraft.ai.","pt":"O Logo Creator é uma ferramenta de IA que cria logos profissionais com processos de design iterativos, utilizando APIs como Gemini e Remove.bg","ru":"ИИ Агент Logo Creator - это инструмент, создающий профессиональные логотипы с помощью итеративного процесса дизайна, используя API Gemini и Remove.bg","ar":"Logo Creator هو أداة ذكاء اصطناعي لإنشاء شعارات احترافية باستخدام عمليات تصميم متكررة، وتستخدم واجهات برمجة التطبيقات مثل Gemini و Remove.bg"},"seo":{"title":{"en":"logo-creator: AI-Powered Logo Generation Setup Guide | AI...","zh":"Logo Creator 设置指南 - 基于 AI 图像生成的Logo设计","ja":"Logo Creator のベストプラクティス - AIエージェントによるロゴ作成","ko":"Logo Creator 사용 가이드 - AI 도구를 사용한 로고 생성","es":"Guía de configuración de Logo Creator: generación de logo...","fr":"Guide de mise en place de Logo Creator: création de logos...","de":"Logo Creator Einrichtungsleitfaden: Logos mit KI erstellen","pt":"Guia de Configuração do Logo Creator - Crie Logos Profiss...","ru":"Настройка ИИ Агента Logo Creator - Создание Профессиональ...","ar":"دليل إعداد Logo Creator - إنشاء الشعارات الاحترافية باستخ..."},"description":{"en":"Unlock professional logo design with logo-creator! Get started with our AI image generation skill, featuring Gemini 3 Pro Image and remove.bg API integration...","zh":"了解如何使用Logo Creator Skill通过AI图像生成创建专业的Logo，包括必要的API密钥和技能","ja":"Logo Creator Skillの使い方を学び、AIエージェントを使用してプロフェッショナルなロゴを作成する","ko":"Logo Creator Skill을 사용하여 AI 도구를 통해 전문적인 로고를 생성하는 방법을 알아보세요","es":"Aprende a configurar el skill Logo Creator para generar logotipos profesionales con tecnologías de AI como Gemini 3 Pro Image","fr":"Découvrez comment configurer le skill Logo Creator pour créer des logos professionnels avec des technologies d''IA comme Gemini 3 Pro Image","de":"Erfahren Sie, wie Sie das Logo Creator-Skill konfigurieren, um professionelle Logos mit KI-Technologien wie Gemini 3 Pro Image zu erstellen","pt":"Aprenda a configurar o Logo Creator, uma ferramenta de IA para criar logos profissionais com processos de design iterativos","ru":"Узнайте, как настроить ИИ Агент Logo Creator для создания профессиональных логотипов с помощью итеративного процесса дизайна","ar":"تعرف على كيفية إعداد Logo Creator، أداة ذكاء اصطناعي لإنشاء شعارات احترافية باستخدام عمليات تصميم متكررة"},"definition":{"en":"logo-creator is an AI-powered skill that generates professional logos through AI image generation with an iterative design process, utilizing Gemini 3 Pro Image and remove.bg API integration.","zh":"Logo Creator Skill是一种AI图像生成工具，用于创建专业的Logo","ja":"Logo Creator SkillはAIエージェントを使用したロゴ作成ツール","ko":"Logo Creator Skill은 AI 도구를 사용한 로고 생성 도구입니다","es":"Logo Creator es un skill que utiliza AI para generar logotipos profesionales a través de un proceso de diseño iterativo","fr":"Logo Creator est un skill qui utilise l''IA pour créer des logos professionnels à travers un processus de conception itératif","de":"Logo Creator ist ein Skill, der KI nutzt, um professionelle Logos durch einen iterativen Designprozess zu erstellen","pt":"O que é Logo Creator? É uma ferramenta de IA que cria logos profissionais com processos de design iterativos","ru":"Что такое ИИ Агент Logo Creator? Это инструмент, создающий профессиональные логотипы с помощью итеративного процесса дизайна","ar":"ما هو Logo Creator؟ هو أداة ذكاء اصطناعي لإنشاء شعارات احترافية باستخدام عمليات تصميم متكررة"},"features":{"en":["Utilizes Gemini 3 Pro Image for AI image generation","Integrates with remove.bg API for background removal","Requires RECRAFT_API_KEY for recraft.ai services","Supports iterative design process for customized logos","Needs GEMINI_API_KEY from Google AI Studio for setup","Outputs files in a designated location"],"zh":["基于AI图像生成的Logo设计","需要GEMINI_API_KEY、REMOVE_BG_API_KEY和RECRAFT_API_KEY","支持nanobanana AI图像生成","可以创建专业的Logo","使用Gemini 3 Pro Image进行图像生成","支持迭代设计过程"],"ja":["AIエージェントを使用したロゴ作成","GEMINI_API_KEY、REMOVE_BG_API_KEY、RECRAFT_API_KEYが必要","nanobanana AI图像生成をサポート","プロフェッショナルなロゴを作成可能","Gemini 3 Pro Imageを使用した图像生成","イテレーティブデザインプロセスをサポート"],"ko":["AI 도구를 사용한 로고 생성","GEMINI_API_KEY, REMOVE_BG_API_KEY, RECRAFT_API_KEY가 필요","nanobanana AI图像 생성을 지원","전문적인 로고를 생성할 수 있습니다","Gemini 3 Pro Image를 사용한 이미지 생성","반복적 설계 프로세스를 지원"],"es":["Generación de logotipos con AI utilizando Gemini 3 Pro Image","Proceso de diseño iterativo para logotipos personalizados","Requiere claves API de Gemini, Remove.bg y Recraft.ai","Compatibilidad con tecnologías de AI de vanguardia","Diseño de logotipos profesionales con resultados de alta calidad"],"fr":["Création de logos avec l''IA à l''aide de Gemini 3 Pro Image","Processus de conception itératif pour des logos sur mesure","Nécessite des clés API de Gemini, Remove.bg et Recraft.ai","Compatibilité avec les technologies d''IA de pointe","Conception de logos professionnels avec des résultats de haute qualité"],"de":["Erstellung von Logos mit KI unter Verwendung von Gemini 3 Pro Image","Iterativer Designprozess für individuelle Logos","Benötigt API-Schlüssel von Gemini, Remove.bg und Recraft.ai","Kompatibilität mit modernen KI-Technologien","Erstellung von professionellen Logos mit hochwertigen Ergebnissen"],"pt":["Geração de imagens de IA com Gemini 3 Pro Image","Processo de design iterativo para criar logos personalizados","Integração com APIs como Remove.bg e Recraft.ai","Suporte a chaves de API para Gemina, Remove.bg e Recraft.ai","Saída de arquivos de logo em formatos variados"],"ru":["Генерация изображений с помощью ИИ с Gemini 3 Pro Image","Итеративный процесс дизайна для создания индивидуальных логотипов","Интеграция с API seperti Remove.bg и Recraft.ai","Поддержка ключей API для Gemina, Remove.bg и Recraft.ai","Выходные файлы логотипов в различных форматах"],"ar":["إنشاء صور ذكاء اصطناعي باستخدام Gemini 3 Pro Image","عملية تصميم متكررة لإنشاء شعارات مخصصة","التكامل مع واجهات برمجة التطبيقات مثل Remove.bg و Recraft.ai","دعم مفاتيح واجهة برمجة التطبيقات ل Gemina و Remove.bg و Recraft.ai","مخرجات ملفات الشعارات في صيغ متعددة"]},"keywords":{"en":["how to use logo-creator","logo-creator setup guide","AI-powered logo generation","logo-creator alternative","logo-creator vs Adobe Illustrator","logo-creator install","what is logo-creator","logo-creator tutorial","logo-creator API integration","logo-creator design process"],"zh":["Logo Creator Skill","AI图像生成","Logo设计","GEMINI_API_KEY","REMOVE_BG_API_KEY","RECRAFT_API_KEY","nanobanana","Gemini 3 Pro Image","AI工具","Logo创建"],"ja":["Logo Creator Skill","AIエージェント","ロゴ作成","GEMINI_API_KEY","REMOVE_BG_API_KEY","RECRAFT_API_KEY","nanobanana","Gemini 3 Pro Image","AIツール","ロゴ生成"],"ko":["Logo Creator Skill","AI 도구","로고 생성","GEMINI_API_KEY","REMOVE_BG_API_KEY","RECRAFT_API_KEY","nanobanana","Gemini 3 Pro Image","AI 툴","로고 디자인"],"es":["Logo Creator","generación de logotipos con AI","Gemini 3 Pro Image","diseño de logotipos","tecnologías de AI","creación de logos","skill de logo","herramientas de diseño gráfico","logotipos profesionales"],"fr":["Logo Creator","création de logos avec l''IA","Gemini 3 Pro Image","conception de logos","technologies d''IA","création de logos","compétence de logo","outils de conception graphique","logos professionnels"],"de":["Logo Creator","Erstellung von Logos mit KI","Gemini 3 Pro Image","Logodesign","KI-Technologien","Logoerstellung","Logo-Skill","Grafikdesign-Tools","professionelle Logos"],"pt":["logo creator","ia para design","gemini 3 pro image","remove.bg api","recraft.ai api","desenvolvimento de logos","ferramentas de ia para design","design de logos profissionais"],"ru":["ИИ Агент Logo Creator","ИИ для дизайна","Gemini 3 Pro Image","API Remove.bg","API Recraft.ai","Разработка логотипов","ИИ инструменты для дизайна","Дизайн профессиональных логотипов"],"ar":["Logo Creator","ذكاء اصطناعي للتصميم","Gemini 3 Pro Image","واجهة برمجة التطبيقات Remove.bg","واجهة برمجة التطبيقات Recraft.ai","تطوير الشعارات","أدوات ذكاء اصطناعي للتصميم","تصميم شعارات احترافية"]}},"owner":"plosson","repo":"siteio","repoPath":"plosson/siteio","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.409Z","topics":[],"category":"community","skillMd":{"name":"logo-creator","description":"Create logos using AI image generation. Discuss style/ratio, generate variations, iterate with user feedback, crop, remove background, and export as SVG. Use when user wants to create a logo, icon, favicon, or brand mark.","bodyPreview":"# Logo Creator Skill\n\nCreate professional logos through AI image generation with an iterative design process.\n\n## Prerequisites\n\n**Required API Keys (set in environment):**\n- `GEMINI_API_KEY` - Get from [Google AI Studio](https://aistudio.google.com/apikey)\n- `REMOVE_BG_API_KEY` - Get from [remove.bg](https://www.remove.bg/api)\n- `RECRAFT_API_KEY` - Get from [recraft.ai](https://www.recraft.ai/)\n\n**Required Skills:**\n- `nanobanana` - AI image generation (Gemini 3 Pro Image)\n\n\n\n## File Output Loc","body":"# Logo Creator Skill\n\nCreate professional logos through AI image generation with an iterative design process.\n\n## Prerequisites\n\n**Required API Keys (set in environment):**\n- `GEMINI_API_KEY` - Get from [Google AI Studio](https://aistudio.google.com/apikey)\n- `REMOVE_BG_API_KEY` - Get from [remove.bg](https://www.remove.bg/api)\n- `RECRAFT_API_KEY` - Get from [recraft.ai](https://www.recraft.ai/)\n\n**Required Skills:**\n- `nanobanana` - AI image generation (Gemini 3 Pro Image)\n\n\n\n## File Output Location\n\nAll generated files should be saved to the `.skill-archive` directory:\n\n```\n.skill-archive/logo-creator/<yyyy-mm-dd-summaryname>/\n```\n\n**Example:**\n```\n.skill-archive/logo-creator/2026-01-18-opc-logo/\n  logo-01.png\n  logo-02.png\n  ...\n  logo-09-cropped.png\n  logo-09-nobg.png\n  logo-09.svg\n  preview.html\n```\n\n**Guidelines:**\n- Use current date in format `yyyy-mm-dd`\n- Add short summary name (project/brand name, kebab-case)\n- Create directory before generating first logo\n- Keep all variations and iterations in same folder\n- Final approved logo should be copied to user''s desired location\n\n## Workflow\n\n### Step 1: Discovery & Requirements\n\nBefore generating, gather requirements from user:\n\n**Ask about:**\n1. **Project/Brand name** - What is the logo for?\n2. **Style preference** - See [references/styles.md](./references/styles.md) for options:\n   - Pixel art / 8-bit retro\n   - Minimalist / flat design\n   - 3D / isometric\n   - Hand-drawn / sketch\n   - Mascot / character\n   - Monogram / lettermark\n   - Abstract / geometric\n\n3. **Aspect ratio** - Default is 1:1 (square), options:\n   - `1:1` - Square (favicons, app icons)\n   - `16:9` - Wide (headers, banners)\n   - `4:3` - Standard\n   - `2:3` - Portrait\n\n4. **Color preferences**:\n   - Monochrome (black & white)\n   - Specific brand colors\n   - Let AI decide\n\n5. **Reference images** - Any existing logos or styles to reference?\n\n**Wait for user confirmation before proceeding!**\n\n### Step 2: Generate Logo Variations\n\nGenerate 20 logo variations (default) using the `nanobanana` skill:\n\n```bash\n# Generate single logo\npython3 <nanobanana_skill_dir>/scripts/generate.py \"{style} logo for {brand}, {description}, {colors}\" \\\n  --ratio 1:1 -o .skill-archive/logo-creator/<date-name>/logo-01.png\n\n# Batch generate 20 logos\npython3 <nanobanana_skill_dir>/scripts/batch_generate.py \"{style} logo for {brand}, {description}, {colors}\" \\\n  -n 20 --ratio 1:1 -d .skill-archive/logo-creator/<date-name> -p logo\n```\n\n**Guidelines:**\n- Use batch_generate.py for multiple variations (includes auto-delay)\n- Save to `.skill-archive/logo-creator/<yyyy-mm-dd-summaryname>/` directory\n- Use sequential naming: `logo-01.png`, `logo-02.png`, etc.\n\n**Prompt Tips:**\n- Include style keywords: \"pixel art\", \"minimalist\", \"8-bit\", \"flat design\"\n- Specify colors: \"black on white\", \"monochrome\", \"blue gradient\"\n- Add context: \"tech startup\", \"food brand\", \"gaming company\"\n- Request format: \"icon\", \"emblem\", \"mascot\", \"lettermark\"\n\n### Step 3: Create HTML Preview\n\nCopy the preview template and open in browser:\n\n```bash\ncp <skill_dir>/templates/preview.html .skill-archive/logo-creator/<yyyy-mm-dd-summaryname>/preview.html\n```\n\nThen open in default browser:\n\n```bash\nopen .skill-archive/logo-creator/<yyyy-mm-dd-summaryname>/preview.html\n```\n\n**IMPORTANT:** Update the HTML to include the correct number of logos generated.\n\n### Step 4: Iterate with User\n\nAsk user which logos they prefer:\n- \"Which logos do you like? (e.g., #5, #12, #18)\"\n- \"What do you like about them?\"\n- \"Any changes you''d want?\"\n\nBased on feedback:\n1. Generate 10-20 more variations of favorite styles\n2. Use naming: `logo-{original}-v{n}.png` (e.g., `logo-05-v1.png`)\n3. Update HTML preview\n4. Repeat until user selects final logo\n\n### Step 5: Finalize Logo\n\nOnce user approves a logo, process it:\n\n**5a. Crop whitespace (make 1:1 with no margins):**\n```bash\npython3 <skill_dir>/scripts/crop_logo.py {input.png} {output-cropped.png}\n```\n\n**5b. Remove background:**\n```bash\npython3 <skill_dir>/scripts/remove_bg.py {input.png} {output-nobg.png}\n```\n\n**5c. Convert to SVG:**\n```bash\npython3 <skill_dir>/scripts/vectorize.py {input.png} {output.svg}\n```\n\n### Step 6: Deliver Final Assets\n\nPresent final deliverables:\n\n```\n## Final Logo Assets\n\n| File | Description | Size |\n|------|-------------|------|\n| logo.png | Original | 1024x1024 |\n| logo-cropped.png | No margins, 1:1 | ~800x800 |\n| logo-nobg.png | Transparent background | ~800x800 |\n| logo.svg | Vector (scalable) | ~20KB |\n\nAll files saved to: `.skill-archive/logo-creator/<yyyy-mm-dd-summaryname>/`\nCopy final logo to user''s desired location.\n```\n\n## Quick Reference\n\n### Common Prompt Patterns\n\n**Pixel Art:**\n```\nPixel art {subject} logo, 8-bit retro style, black pixels on white background, {size}x{size} grid, minimalist icon\n```\n\n**Minimalist:**\n```\nMinimalist {subject} logo, flat design, clean lines, {color} on white, simple geometric shapes\n```\n\n**Mascot:**\n```\nCute {animal/character} mascot logo, friendly expression, {style} style, {colors}, suitable for brand icon\n```\n\n**Lettermark:**\n```\nLetter \"{letter}\" logo, modern typography, {style} design, {colors}, clean professional look\n```\n\n### Supported Aspect Ratios\n\n- `1:1` - Square (default for logos)\n- `2:3`, `3:2` - Portrait/Landscape\n- `3:4`, `4:3` - Standard\n- `4:5`, `5:4` - Photo\n- `9:16`, `16:9` - Wide\n- `21:9` - Ultra-wide\n\n## References\n\n- [references/styles.md](./references/styles.md) - Logo style guide with prompt examples\n- [examples/opc-logo-creation.md](./examples/opc-logo-creation.md) - Full example conversation\n"},"lastSynced":"2026-03-08T02:07:01.208Z","agentAnalysis":{"suitability":{"en":"Ideal for Creative Agents needing advanced logo generation capabilities through AI image generation with Google AI Studio and recraft.ai","zh":"适合需要通过Google AI Studio和recraft.ai实现高级logo生成能力的创意代理","ja":"Google AI Studioおよびrecraft.aiを使用して高度なロゴ生成機能を必要とするクリエイティブエージェントに適しています","ko":"Google AI Studio와 recraft.ai를 통해 고급 로고 생성 기능을 필요한 창의적인 에이전트에 적합합니다","es":"Ideal para Agentes Creativos que necesitan capacidades avanzadas de generación de logotipos a través de la generación de imágenes de inteligencia artificial con Google AI Studio y recraft.ai","fr":"Idéal pour les agents créatifs ayant besoin de capacités avancées de génération de logos grâce à la génération d''images par intelligence artificielle avec Google AI Studio et recraft.ai","de":"Ideal für kreative Agenten, die erweiterte Logo-Erstellungsfunktionen durch künstliche Intelligenz-Bildgenerierung mit Google AI Studio und recraft.ai benötigen","pt":"Ideal para Agentes Criativos que necessitam de capacidades avançadas de geração de logotipos por meio da geração de imagens de IA com Google AI Studio e recraft.ai","ru":"Идеально для Креативных Агентов, которым требуются продвинутые возможности генерации логотипов с помощью генерации изображений ИИ в Google AI Studio и recraft.ai","ar":"مثالي للوكلاء الإبداعيين الذين يحتاجون إلى قدرات متقدمة لإنشاء الشعارات من خلال إنشاء صورة إيه آي مع استوديو إيه آي جوجل و recraft.ai"},"recommendation":{"en":"Empowers agents to create professional logos using iterative design processes, leveraging API keys from Google AI Studio, remove.bg, and recraft.ai for seamless image generation and editing, producing high-quality logos in various formats","zh":"使代理能够使用迭代设计过程创建专业的logo，利用Google AI Studio、remove.bg和recraft.ai的API密钥实现无缝的图像生成和编辑，生产各种格式的高质量logo","ja":"エージェントがGoogle AI Studio、remove.bg、recraft.aiのAPIキーを使用して反復設計プロセスでプロフェッショナルなロゴを作成できるようにし、シームレスな画像生成と編集を実現し、高品質のロゴをさまざまな形式で生成します","ko":"에이전트가 반복적인 설계 프로세스를 통해 전문적인 로고를 생성할 수 있도록 하며, Google AI Studio, remove.bg, recraft.ai의 API 키를 사용하여 무결점의 이미지 생성 및 편집을 구현하고, 다양한 형식의 고품질 로고를 생성합니다","es":"Permite a los agentes crear logotipos profesionales utilizando procesos de diseño iterativos, aprovechando las claves de API de Google AI Studio, remove.bg y recraft.ai para una generación y edición de imágenes sin problemas, produciendo logotipos de alta calidad en varios formatos","fr":"Permet aux agents de créer des logos professionnels en utilisant des processus de conception itératifs, en exploitant les clés d''API de Google AI Studio, remove.bg et recraft.ai pour une génération et une édition d''images sans interruption, produisant des logos de haute qualité dans divers formats","de":"Ermöglicht es Agenten, professionelle Logos mit iterativen Designprozessen zu erstellen, indem sie API-Schlüssel von Google AI Studio, remove.bg und recraft.ai für eine nahtlose Bildgenerierung und -bearbeitung nutzen, um Logos in verschiedenen Formaten in hoher Qualität zu produzieren","pt":"Habilita os agentes a criarem logotipos profissionais usando processos de design iterativos, aproveitando chaves de API do Google AI Studio, remove.bg e recraft.ai para geração e edição de imagens sem interrupções, produzindo logotipos de alta qualidade em vários formatos","ru":"Наделяет агентов возможностью создавать профессиональные логотипы с помощью итеративных процессов дизайна, используя ключи API от Google AI Studio, remove.bg и recraft.ai для бесшовной генерации и редактирования изображений, производя логотипы высокого качества в различных форматах","ar":"يمنح الوكلاء القدرة على إنشاء شعارات احترافية باستخدام عمليات التصميم التكرارية، و利用 مفاتيح واجهة برمجة التطبيقات من استوديو إيه آي جوجل و remove.bg و recraft.ai من أجل توليد وتصحيح الصور بسلاسة، وإنتاج شعارات عالية الجودة في صيغ متعددة"},"useCases":{"en":["Generating custom logos for businesses","Automating logo design iterations with nanobanana AI image generation","Creating professional logos with transparent backgrounds using remove.bg API"],"zh":["为企业生成自定义logo","使用nanobanana AI图像生成自动化logo设计迭代","使用remove.bg API生成透明背景的专业logo"],"ja":["企業向けのカスタムロゴを生成する","nanobanana AI画像生成を使用してロゴデザインのイテレーションを自動化する","remove.bg APIを使用して透明背景のプロフェッショナルロゴを作成する"],"ko":["기업을 위한 맞춤형 로고 생성","nanobanana AI 이미지 생성을 사용하여 로고 디자인 반복을 자동화","remove.bg API를 사용하여 투명 배경의 전문적인 로고 생성"],"es":["Generar logotipos personalizados para empresas","Automatizar iteraciones de diseño de logotipos con la generación de imágenes de inteligencia artificial de nanobanana","Crear logotipos profesionales con fondos transparentes utilizando la API de remove.bg"],"fr":["Générer des logos personnalisés pour les entreprises","Automatiser les itérations de conception de logos avec la génération d''images par intelligence artificielle de nanobanana","Créer des logos professionnels avec des arrières-plans transparents en utilisant l''API de remove.bg"],"de":["Erstellen von benutzerdefinierten Logos für Unternehmen","Automatisieren von Logo-Design-Iterationen mit der künstlichen Intelligenz-Bildgenerierung von nanobanana","Erstellen von professionellen Logos mit transparentem Hintergrund unter Verwendung der remove.bg-API"],"pt":["Geração de logotipos personalizados para empresas","Automação de iterações de design de logotipos com geração de imagens de IA nanobanana","Criação de logotipos profissionais com fundos transparentes usando API remove.bg"],"ru":["Генерация индивидуальных логотипов для бизнеса","Автоматизация итераций дизайна логотипов с помощью генерации изображений ИИ nanobanana","Создание профессиональных логотипов с прозрачными фонами с использованием API remove.bg"],"ar":["إنشاء شعارات مخصصة للشركات","التحكم الآلي في تكرار تصميم الشعارات باستخدام إنشاء صورة إيه آي نانوبانانا","إنشاء شعارات احترافية مع خلفيات شفافة باستخدام واجهة برمجة التطبيقات remove.bg"]},"limitations":{"en":["Requires Google AI Studio, remove.bg, and recraft.ai API keys","Dependent on nanobanana AI image generation skill","Environment variables must be set for API keys"],"zh":["需要Google AI Studio、remove.bg和recraft.ai的API密钥","依赖于nanobanana AI图像生成技能","环境变量必须设置为API密钥"],"ja":["Google AI Studio、remove.bg、recraft.aiのAPIキーが必要","nanobanana AI画像生成スキルに依存する","APIキーの環境変数を設定する必要がある"],"ko":["Google AI Studio, remove.bg, recraft.ai의 API 키가 필요합니다","nanobanana AI 이미지 생성 기술에 의존합니다","API 키를 위한 환경 변수를 설정해야 합니다"],"es":["Requiere claves de API de Google AI Studio, remove.bg y recraft.ai","Dependiente de la habilidad de generación de imágenes de inteligencia artificial de nanobanana","Las variables de entorno deben establecerse para las claves de API"],"fr":["Nécessite des clés d''API de Google AI Studio, remove.bg et recraft.ai","Dépend de la compétence de génération d''images par intelligence artificielle de nanobanana","Les variables d''environnement doivent être définies pour les clés d''API"],"de":["Benötigt API-Schlüssel von Google AI Studio, remove.bg und recraft.ai","Abhängig von der Fähigkeit zur künstlichen Intelligenz-Bildgenerierung von nanobanana","Umgebungsvariablen müssen für API-Schlüssel festgelegt werden"],"pt":["Exige chaves de API do Google AI Studio, remove.bg e recraft.ai","Dependente da habilidade de geração de imagens de IA nanobanana","Variáveis de ambiente devem ser definidas para chaves de API"],"ru":["Требует ключей API от Google AI Studio, remove.bg и recraft.ai","Зависит от навыка генерации изображений ИИ nanobanana","Переменные окружения должны быть установлены для ключей API"],"ar":["يتطلب مفاتيح واجهة برمجة التطبيقات من استوديو إيه آي جوجل و remove.bg و recraft.ai","يعتمد على مهارة إنشاء صورة إيه آي نانوبانانا","يجب تعيين متغيرات البيئة لمفاتيح واجهة برمجة التطبيقات"]},"version":4},"contentHash":"1c5e690f473156aea542656272fc97e6459c2b46d68bcd675b254605e0f9