INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('miethe/skillmeat/design-principles', 'design-principles', 'miethe', 'skillmeat', 'community', 'design-principles miethe skillmeat community The design-principles skill enforces precise design for enterprise software, SaaS dashboards, and web applications, ensuring polished interfaces with intentional personality. This skill benefits developers and designers seeking to create context-specific interfaces. 设计原则是一种技能管理器，用于为企业软件、SaaS仪表板、管理界面和Web应用程序实现精准设计 デザイン原則は、企業ソフトウェア、SaaSダッシュボード、管理インターフェース、Webアプリケーションの精密設計を実現するスキルマネージャー 디자인 원칙은 기업 소프트웨어, SaaS 대시보드, 관리 인터페이스, 웹 애플리케이션의 정밀한 설계를 구현하는 스킬 매니저 El skill de principios de diseño garantiza una interfaz de usuario pulida y personalizada para cada contexto específico Le skill de principes de conception garantit une interface utilisateur polie et personnalisée pour chaque contexte spécifique Das Designprinzipien-Skill sorgt für eine polierte und personalisierte Benutzeroberfläche für jeden spezifischen Kontext O skill de design-principles para Claude aplica princípios de design precisos em software de empresa e interfaces web Навык design-principles для Claude применяет точные принципы дизайна в корпоративном программном обеспечении и веб-интерфейсах مهارة design-principles لـ Claude تطبق مبادئ التصميم الدقيقة في برامج الشركات والواجهات الإلكترونية how to use design-principles what is design-principles design-principles alternative design-principles vs material design design-principles install design-principles setup guide enterprise software design principles SaaS dashboard design best practices intentional interface design 设计原则 AI工具 精准设计 企业软件设计 SaaS仪表板设计 管理界面设计 Web应用程序设计 Jony Ive设计 设计方向 Enforces precise design with intentional personality Crafts interfaces for specific contexts Requires commitment to a design direction before writing code Considers context and product needs for tailored design Aims for Jony Ive-level precision in interface design Supports design for enterprise software, SaaS dashboards, and web applications design-principles is a skill that enforces precise, crafted design for enterprise software, SaaS dashboards, admin interfaces, and web applications with Jony Ive-level precision.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('neovateai/neovate-code/add-nodebridge-handler', 'community', 'neovateai', 'neovate-code', 'neovateai/neovate-code', 'add-nodebridge-handler', 0, 0, 42, '2026-03-08T01:57:15.411Z', '2026-03-08T02:07:04.565Z', '344bb3080885a5297fd49c39d3995e884ec562f74c582a6235fec55e26fc3926', '{"id":"neovateai/neovate-code/add-nodebridge-handler","name":"add-nodebridge-handler","description":{"en":"The add-nodebridge-handler skill enables developers to add new message handlers to the NodeBridge system, enhancing communication between the UI layer and Node.js backend. This skill benefits developers working with NodeBridge and Node.js.","zh":"本文介绍如何添加NodeBridge处理程序，实现UI层和Node.js后端之间的通信","ja":"NodeBridgeハンドラーを追加してUI層とNode.jsバックエンドの通信を実現する方法を説明します","ko":"NodeBridge 핸들러를 추가하여 UI 계층과 Node.js 백엔드 간의 통신을 구현하는 방법을 설명합니다","es":"Add-nodebridge-handler es una habilidad que permite agregar un nuevo controlador de mensajes a NodeBridge, mejorando la comunicación entre la capa de UI y el backend de Node.js.","fr":"Add-nodebridge-handler est une compétence qui permet d''ajouter un nouveau gestionnaire de messages à NodeBridge, améliorant la communication entre la couche UI et le backend Node.js.","de":"Add-nodebridge-handler ist eine Fähigkeit, die es ermöglicht, einen neuen Nachrichtenhandler zu NodeBridge hinzuzufügen, um die Kommunikation zwischen der UI-Schicht und dem Node.js-Backend zu verbessern.","pt":"O Add NodeBridge Handler é uma habilidade que permite adicionar manipuladores de mensagens personalizados ao sistema NodeBridge","ru":"Add NodeBridge Handler - это навык, который позволяет добавлять пользовательские обработчики сообщений в систему NodeBridge","ar":"معالج إضافة NodeBridge هو مهارة تسمح بإضافة معالجات رسائل مخصصة إلى نظام NodeBridge"},"seo":{"title":{"en":"add-nodebridge-handler: NodeBridge Setup Guide | AI Agent...","