INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('neovateai/neovate-code/add-nodebridge-handler', 'add-nodebridge-handler', 'neovateai', 'neovate-code', 'community', 'add-nodebridge-handler neovateai neovate-code community The add-nodebridge-handler skill enables developers to add new message handlers to the NodeBridge system, enhancing communication between the UI layer and Node.js backend. This skill benefits developers working with NodeBridge and Node.js. 本文介绍如何添加NodeBridge处理程序，实现UI层和Node.js后端之间的通信 NodeBridgeハンドラーを追加してUI層とNode.jsバックエンドの通信を実現する方法を説明します NodeBridge 핸들러를 추가하여 UI 계층과 Node.js 백엔드 간의 통신을 구현하는 방법을 설명합니다 Add-nodebridge-handler es una habilidad que permite agregar un nuevo controlador de mensajes a NodeBridge, mejorando la comunicación entre la capa de UI y el backend de Node.js. Add-nodebridge-handler est une compétence qui permet d''ajouter un nouveau gestionnaire de messages à NodeBridge, améliorant la communication entre la couche UI et le backend Node.js. Add-nodebridge-handler ist eine Fähigkeit, die es ermöglicht, einen neuen Nachrichtenhandler zu NodeBridge hinzuzufügen, um die Kommunikation zwischen der UI-Schicht und dem Node.js-Backend zu verbessern. O Add NodeBridge Handler é uma habilidade que permite adicionar manipuladores de mensagens personalizados ao sistema NodeBridge Add NodeBridge Handler - это навык, который позволяет добавлять пользовательские обработчики сообщений в систему NodeBridge معالج إضافة NodeBridge هو مهارة تسمح بإضافة معالجات رسائل مخصصة إلى نظام NodeBridge how to use add-nodebridge-handler add-nodebridge-handler setup guide NodeBridge message handler add-nodebridge-handler alternative Node.js backend communication add-nodebridge-handler install what is add-nodebridge-handler NodeBridge UI layer communication add-nodebridge-handler vs other handlers NodeBridge处理程序 添加处理程序 UI层和Node.js后端通信 messageBus.registerHandler() 异步处理 Node.js开发 AI工具 代码生成 Adds handler implementation in src/nodeBridge.ts Registers handlers using the registerHandlers() method in NodeHandlerRegistry class Supports message handling between UI layer and Node.js backend Utilizes the messageBus.registerHandler() function for handler registration Enables communication between UI and backend using NodeBridge add-nodebridge-handler is a skill that guides the process of adding a new message handler to the NodeBridge system, enabling communication between the UI layer and the Node.js backend.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('abyssparanoia/rapid-go/crud-implementation', 'community', 'abyssparanoia', 'rapid-go', 'abyssparanoia/rapid-go', 'crud-implementation', 0, 0, 42, '2026-03-08T01:57:15.412Z', '2026-03-08T02:07:05.061Z', 'de23f2eeb4a3ee05d534df81e8316994cbd048eb6f227205675aa1e18ad78c0b', '{"id":"abyssparanoia/rapid-go/crud-implementation","name":"crud-implementation","description":{"en":"The crud-implementation skill enables developers to quickly start developing great APIs with full CRUD operations using rapid-go. It benefits developers by providing a workflow for implementing new entities.","zh":"使用 Rapid-Go 实现 CRUD 操作，包括添加数据库表、域实体和 API 端点，快速开发 API","ja":"Rapid-Go を使用して CRUD 操作を実装し、データベーステーブル、ドメインエンティティ、API エンドポイントを追加して API 開発を迅速化","ko":"Rapid-Go를 사용하여 CRUD 연산을 구현하고 데이터베이스 테이블, 도메인 엔티티, API 엔드포인트를 추가하여 API 개발을 가속화","es":"La implementación CRUD con Rapid-Go permite desarrollar APIs de manera rápida y eficiente","fr":"L''implémentation CRUD avec Rapid-Go permet de développer des API de manière rapide et efficace","de":"Die CRUD-Implementierung mit Rapid-Go ermöglicht die schnelle und effiziente Entwicklung von APIs","pt":"A implementação CRUD com Rapid-Go permite desenvolver APIs de forma rápida e eficiente. Aprenda a criar entidades com operações de criação, leitura, atualização e exclusão.","ru":"Реализация CRUD с помощью Rapid-Go позволяет быстро и эффективно разрабатывать API. Узнайте, как создавать сущности с операциями создания, чтения, обновления и удаления.","ar":"تنفيذ CRUD باستخدام Rapid-Go يسمح بتطوير واجهات برمجة التطبيقات بسرعة وفعالية. تعلم كيفية إنشاء كيانات مع عمليات إنشاء وقراءة وتحديث وحذف."},"seo":{"title":{"en":"crud-implementation: API Development Setup Guide | AI Age...","zh":"CRUD 实现快速指南 - 使用 Rapid-Go 搭建 API","ja":"CRUD 実装セットアップガイド - Rapid-Go を使用した API 開発","ko":"CRUD 구현 설정 가이드 - Rapid-Go로 API 개발하기","es":"Guía de implementación CRUD con Rapid-Go","fr":"Guide d''implémentation CRUD avec Rapid-Go","de":"CRUD-Implementierungsleitfaden mit Rapid-Go","pt":"Guia de Implementação CRUD com Rapid-Go","ru":"Руководство по реализации CRUD с помощью Rapid-Go и ИИ Аг...","ar":"دليل تنفيذ CRUD باستخدام Rapid-Go ووكيلات الذكاء الاصطناعي"},"description":{"en":"Unlock rapid API development with crud-implementation. Discover how to implement full CRUD operations and streamline your workflow. Get started now!","zh":"了解如何使用 Rapid-Go 快速实现 CRUD 操作，包括添加数据库表、域实体和 API 端点","ja":"Rapid-Go を使用して CRUD 操作を迅速に実装する方法について学びます。データベーステーブルの追加、ドメインエンティティ、API エンドポイントなど","ko":"Rapid-Go를 사용하여 CRUD 연산을 빠르게 구현하는 방법을 알아보세요. 데이터베이스 테이블 추가, 도메인 엔티티, API 엔드포인트 등","es":"Aprende a implementar operaciones CRUD con Rapid-Go y mejora tu desarrollo de API","fr":"Découvrez comment implémenter des opérations CRUD avec Rapid-Go et améliorez votre développement d''API","de":"Erfahren Sie, wie Sie CRUD-Operationen mit Rapid-Go implementieren und verbessern Sie Ihre API-Entwicklung","pt":"Aprenda a implementar operações CRUD com Rapid-Go e melhore a produtividade do seu desenvolvimento de API","ru":"Узнайте, как реализовать операции CRUD с помощью Rapid-Go и ИИ Агентов, чтобы повысить производительность разработки вашего API","ar":"تعلم كيفية تنفيذ عمليات CRUD باستخدام Rapid-Go ووكيلات الذكاء الاصطناعي لتحسين إنتاجية تطوير واجهة برمجة التطبيقات"},"definition":{"en":"crud-implementation is a workflow for implementing new entities with full CRUD operations, involving add-database-table, add-domain-entity, and add-api-endpoint steps.","zh":"CRUD 实现是使用 Rapid-Go 快速开发 API 的一种方法，包括添加数据库表、域实体和 API 端点","ja":"CRUD 実装は、Rapid-Go を使用して API を迅速に開発する方法の一つで、データベーステーブルの追加、ドメインエンティティ、API エンドポイントなど","ko":"CRUD 구현은 Rapid-Go를 사용하여 API를 빠르게 개발하는 방법 중 하나로 데이터베이스 테이블 추가, 도메인 엔티티, API 엔드포인트 등","es":"La implementación CRUD es un patrón de diseño que permite crear, leer, actualizar y eliminar entidades en una base de datos","fr":"L''implémentation CRUD est un patron de conception qui permet de créer, lire, mettre à jour et supprimer des entités dans une base de données","de":"Die CRUD-Implementierung ist ein Entwurfsmuster, das die Erstellung, das Lesen, die Aktualisierung und das Löschen von Entitäten in einer Datenbank ermöglicht","pt":"Implementação CRUD é um fluxo de trabalho que permite criar entidades com operações de criação, leitura, atualização e exclusão.","ru":"Реализация CRUD - это рабочий процесс, который позволяет создавать сущности с операциями создания, чтения, обновления и удаления.","ar":"تنفيذ CRUD هو عملية عمل تتيح إنشاء كيانات مع عمليات إنشاء وقراءة وتحديث وحذف."},"features":{"en":["Implements CRUD operations using rapid-go","Generates migration SQL for database tables","Creates domain models and repositories","Supports usecase implementation for API endpoints","Includes constant tables for data consistency","Streamlines workflow with a structured entry point"],"zh":["使用 Migration SQL 添加数据库表","创建域模型和 Repository","使用 Usecase 添加 API 端点","支持 Constant tables","快速开发 API"],"ja":["Migration SQL を使用してデータベーステーブルを追加","ドメインモデルと Repository を作成","Usecase を使用して API エンドポイントを追加","Constant tables をサポート","API 開発を迅速化"],"ko":["마이그레이션 SQL을 사용하여 데이터베이스 테이블 추가","도메인 모델과 Repository 생성","Usecase를 사용하여 API 엔드포인트 추가","상수 테이블 지원","API 개발 가속화"],"es":["Implementación de operaciones CRUD con Rapid-Go","Creación de tablas de base de datos con Migration SQL","Definición de modelos de dominio y repositorios","Implementación de casos de uso y puntos de conexión de API","Uso de constantes de tabla para mejorar la eficiencia","Integración con frameworks y bibliotecas de desarrollo de API"],"fr":["Implémentation d''opérations CRUD avec Rapid-Go","Création de tables de base de données avec Migration SQL","Définition de modèles de domaine et de répertoires","Implémentation de cas d''utilisation et de points de terminaison d''API","Utilisation de constantes de tableau pour améliorer l''efficacité","Intégration avec des frameworks et des bibliothèques de développement d''API"],"de":["Implementierung von CRUD-Operationen mit Rapid-Go","Erstellung von Datenbanktabellen mit Migration SQL","Definition von Domänenmodellen und Repositorien","Implementierung von Anwendungsfällen und API-Endpunkten","Verwendung von Konstantentabellen zur Verbesserung der Effizienz","Integration mit Frameworks und Bibliotheken für die API-Entwicklung"],"pt":["Criação de tabelas de banco de dados com Migration SQL","Desenvolvimento de modelos de domínio com Domain Model","Criação de endpoints de API com Usecase","Suporte a constantes de tabela com Constant tables","Integração com repositórios com Repository"],"ru":["Создание таблиц базы данных с помощью Migration SQL","Разработка моделей домена с помощью Domain Model","Создание конечных точек API с помощью Usecase","Поддержка констант таблиц с помощью Constant tables","Интеграция с хранилищами с помощью Repository"],"ar":["إنشاء جداول قاعدة البيانات مع Migration SQL","تطوير نماذج المجال مع Domain Model","إنشاء نقاط نهاية واجهة برمجة التطبيقات مع Usecase","دعم ثوابت الجدول مع Constant tables","التكامل مع مستودعات البيانات مع Repository"]},"keywords":{"en":["how to use crud-implementation","crud-implementation setup guide","crud-implementation vs rapid-go","crud-implementation install","what is crud-implementation","crud-implementation alternative","crud-implementation tutorial","crud-implementation workflow","crud-implementation api development"],"zh":["CRUD 实现","Rapid-Go","API 开发","数据库表添加","域实体","API 端点","Migration SQL","Constant tables"],"ja":["CRUD 実装","Rapid-Go","API 開発","データベーステーブル追加","ドメインエンティティ","API エンドポイント","Migration SQL","Constant tables"],"ko":["CRUD 구현","Rapid-Go","API 개발","데이터베이스 테이블 추가","도메인 엔티티","API 엔드포인트","마이그레이션 SQL","상수 테이블"],"es":["implementación CRUD","Rapid-Go","desarrollo de API","operaciones CRUD","bases de datos","Migration SQL","modelos de dominio","repositorios","casos de uso","puntos de conexión de API"],"fr":["implémentation CRUD","Rapid-Go","développement d''API","opérations CRUD","bases de données","Migration SQL","modèles de domaine","répertoires","cas d''utilisation","points de terminaison d''API"],"de":["CRUD-Implementierung","Rapid-Go","API-Entwicklung","CRUD-Operationen","Datenbanken","Migration SQL","Domänenmodelle","Repositorien","Anwendungsfälle","API-Endpunkte"],"pt":["implementação crud","rapid-go","desenvolvimento de api","criação de entidades","operações de criação","leitura","atualização","exclusão","migration sql","domain model"],"ru":["реализация crud","rapid-go","разработка api","создание сущностей","операции создания","чтения","обновления","удаления","migration sql","domain model","ии агенты"],"ar":["تنفيذ crud","rapid-go","تطوير واجهة برمجة التطبيقات","إنشاء كيانات","عمليات إنشاء","قراءة","تحديث","حذف","migration sql","domain model","وكيلات الذكاء الاصطناعي"]}},"owner":"abyssparanoia","repo":"rapid-go","repoPath":"abyssparanoia/rapid-go","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.412Z","topics":[],"category":"community","skillMd":{"name":"crud-implementation","description":"Complete workflow guide for implementing new CRUD entities. Use when adding a new resource, implementing full CRUD operations, or needing an overview of the database-to-API flow. Triggers: new entity, add resource, implement CRUD, create table and API. Orchestrates add-database-table, add-domain-entity, and add-api-endpoint skills.","bodyPreview":"# CRUD Implementation Workflow\n\nEntry point for implementing a new entity with full CRUD operations.\n\n## Workflow Overview\n\n```\n┌─────────────────────┐     ┌─────────────────────┐     ┌─────────────────────┐\n│  add-database-table │ --> │  add-domain-entity  │ --> │  add-api-endpoint   │\n│                     │     │                     │     │                     │\n│  - Migration SQL    │     │  - Domain model     │     │  - Usecase          │\n│  - Constant tables  │     │  - Repository       │","body":"# CRUD Implementation Workflow\n\nEntry point for implementing a new entity with full CRUD operations.\n\n## Workflow Overview\n\n```\n┌─────────────────────┐     ┌─────────────────────┐     ┌─────────────────────┐\n│  add-database-table │ --> │  add-domain-entity  │ --> │  add-api-endpoint   │\n│                     │     │                     │     │                     │\n│  - Migration SQL    │     │  - Domain model     │     │  - Usecase          │\n│  - Constant tables  │     │  - Repository       │     │  - Proto definition │\n│  - SQLBoiler gen    │     │  - Marshaller       │     │  - gRPC handler     │\n└─────────────────────┘     └─────────────────────┘     └─────────────────────┘\n```\n\n## Quick Start\n\n| Step | Skill | Key Command |\n|------|-------|-------------|\n| 1 | **add-database-table** | `make migrate.create` then `make migrate.up` |\n| 2 | **add-domain-entity** | `make generate.mock` |\n| 3 | **add-api-endpoint** | `make generate.buf` |\n\n## Before You Start\n\n1. Know the entity name and its fields\n2. Identify relationships to existing entities\n3. Determine which API actor (admin/public/debug)\n\n## Step-by-Step\n\n### Step 1: Database Layer\n\nUse the **add-database-table** skill for:\n- Creating migration file with table DDL\n- Adding indexes and foreign keys\n- Creating constant tables for enum fields\n- Running `make migrate.up` to generate SQLBoiler\n\n### Step 2: Domain Layer\n\nUse the **add-domain-entity** skill for:\n- Domain model with constructor and update methods\n- Repository interface with query structs\n- Marshaller (DB model <-> domain model)\n- Repository implementation\n\n### Step 3: API Layer\n\nUse the **add-api-endpoint** skill for:\n- Usecase input/output structs\n- Interactor interface and implementation\n- Protocol Buffers messages and RPCs\n- gRPC handler and marshaller\n- DI registration\n\n## Final Verification\n\n```bash\nmake lint.go && make test\n```\n\n## Related Skills\n\n- **code-investigation** - Analyze existing patterns before implementation\n- **review-pr** - Self-review before creating PR\n- **create-pull-request** - PR creation with proper format\n"},"lastSynced":"2026-03-08T02:07:05.061Z","agentAnalysis":{"suitability":{"en":"Perfect for API Development Agents needing rapid CRUD operation implementation using rapid-go.","zh":"适合需要使用 rapid-go 实现快速 CRUD 操作的 API 开发代理","ja":"rapid-go を使用して迅速な CRUD 操作を実装する必要がある API 開発エージェントに最適","ko":"rapid-go를 사용하여 빠른 CRUD 연산을 구현해야 하는 API 개발 에이전트에게 적합","es":"Perfecto para agentes de desarrollo de API que necesitan implementar operaciones CRUD rápidas utilizando rapid-go.","fr":"Parfait pour les agents de développement d''API ayant besoin d''une mise en œuvre rapide des opérations CRUD à l''aide de rapid-go.","de":"Perfekt für API-Entwicklungsagenten, die eine schnelle Implementierung von CRUD-Operationen mit rapid-go benötigen.","pt":"Perfeito para Agentes de Desenvolvimento de API que precisam de implementação rápida de operações CRUD usando rapid-go.","ru":"Идеально подходит для агентов разработки API, которым требуется быстрая реализация операций CRUD с использованием rapid-go.","ar":"مثالي لعميل تطوير واجهة برمجة التطبيقات الذي يحتاج إلى تنفيذ سريع لعمليات CRUD باستخدام rapid-go."},"recommendation":{"en":"Empowers agents to quickly implement new entities with full CRUD operations, utilizing migration SQL, domain models, and repository patterns, streamlining API development with rapid-go.","zh":"赋予代理快速实现新实体的能力，具有完整的 CRUD 操作，利用迁移 SQL、域模型和仓库模式，简化 API 开发流程，并使用 rapid-go","ja":"エージェントが新しいエンティティを迅速に実装できるようにし、完全な CRUD 操作を利用し、移行 SQL、ドメイン モデル、リポジトリ パターンを使用し、API 開発を簡素化し、rapid-go を使用","ko":"에이전트가 새로운 엔티티를 빠르게 구현할 수 있는 능력을 부여하며, 완전한 CRUD 연산을 사용하며, 마이그레이션 SQL, 도메인 모델 및 리포지토리 패턴을 활용하여 API 개발을 간소화하며, rapid-go를 사용","es":"Habilita a los agentes a implementar rápidamente nuevas entidades con operaciones CRUD completas, utilizando SQL de migración, modelos de dominio y patrones de repositorio, simplificando el desarrollo de API con rapid-go.","fr":"Permet aux agents de mettre en œuvre rapidement de nouvelles entités avec des opérations CRUD complètes, en utilisant le SQL de migration, les modèles de domaine et les modèles de répository, simplifiant ainsi le développement d''API avec rapid-go.","de":"Ermächtigt Agenten, neue Entitäten mit vollständigen CRUD-Operationen schnell zu implementieren, indem sie Migration-SQL, Domänenmodelle und Repository-Muster verwenden, um die API-Entwicklung mit rapid-go zu rationalisieren.","pt":"Habilita os agentes a implementar rapidamente novas entidades com operações CRUD completas, utilizando SQL de migração, modelos de domínio e padrões de repositório, simplificando o desenvolvimento de API com rapid-go.","ru":"Наделяет агентов возможностью быстро реализовывать новые сущности с полными операциями CRUD, используя SQL-миграцию, модели домена и шаблоны репозитория, упрощая разработку API с rapid-go.","ar":"يمنح العميل القدرة على تنفيذ كيانات جديدة بسرعة مع عمليات CRUD كاملة، باستخدام SQL للهجرة، ونماذج المجال، وأنماط المستودع، مبسطًا تطوير واجهة برمجة التطبيقات مع rapid-go."},"useCases":{"en":["Implementing new database tables with migration SQL","Generating domain entities with repository patterns","Creating API endpoints with usecase-driven development"],"zh":["使用迁移 SQL 实现新的数据库表","使用仓库模式生成域实体","使用用例驱动开发创建 API 端点"],"ja":["移行 SQL を使用して新しいデータベース テーブルを実装","リポジトリ パターンを使用してドメイン エンティティを生成","ユースケース駆動開発を使用して API エンドポイントを作成"],"ko":["마이그레이션 SQL을 사용하여 새로운 데이터베이스 테이블을 구현","리포지토리 패턴을 사용하여 도메인 엔티티를 생성","유스케이스 주도 개발을 사용하여 API 엔드포인트를 생성"],"es":["Implementar nuevas tablas de base de datos con SQL de migración","Generar entidades de dominio con patrones de repositorio","Crear puntos de conexión de API con desarrollo dirigido por casos de uso"],"fr":["Mettre en œuvre de nouvelles tables de base de données avec le SQL de migration","Générer des entités de domaine avec des modèles de répository","Créer des points de terminaison d''API avec un développement dirigé par les cas d''utilisation"],"de":["Implementierung neuer Datenbanktabellen mit Migration-SQL","Erzeugen von Domänenentitäten mit Repository-Mustern","Erstellen von API-Endpunkten mit usecase-orientierter Entwicklung"],"pt":["Implementar novas tabelas de banco de dados com SQL de migração","Gerar entidades de domínio com padrões de repositório","Criar pontos de extremidade de API com desenvolvimento orientado a caso de uso"],"ru":["Реализация новых таблиц базы данных с помощью SQL-миграции","Генерация сущностей домена с помощью шаблонов репозитория","Создание конечных точек API с разработкой, ориентированной на случай использования"],"ar":["تنفيذ جداول قاعدة بيانات جديدة باستخدام SQL للهجرة","генерация كيانات المجال مع أنماط المستودع","إنشاء نقاط نهاية واجهة برمجة التطبيقات مع تطوير موجه لاستخدام الحالة"]},"limitations":{"en":["Requires rapid-go setup","Limited to CRUD operations"],"zh":["需要 rapid-go 设置","仅限 CRUD 操作"],"ja":["rapid-go の設定が必要","CRUD 操作のみ"],"ko":["rapid-go 설정이 필요","CRUD 연산만 가능"],"es":["Requiere configuración de rapid-go","Limitado a operaciones CRUD"],"fr":["Nécessite une configuration de rapid-go","Limité aux opérations CRUD"],"de":["Benötigt rapid-go-Setup","Begrenzt auf CRUD-Operationen"],"pt":["Requer configuração do rapid-go","Limitado a operações CRUD"],"ru":["Требует настройки rapid-go","Ограничен операциями CRUD"],"ar":["يتطلب إعداد rapid-go","محدود لعمليات CRUD"]},"version":4},"contentHash":"de23f2eeb4a3ee05d534df81e8316994cbd048eb6f227205675aa1e18ad78c0b","qualityScore":42}');
